/**
 * Payroll readiness / config admin helpers (F08).
 */

export function resolvePayrollCheckFix(check) {
  if (!check) {
    return { path: "/payroll/groups", label: "Open payroll groups" };
  }
  if (check.fixPath) {
    return { path: check.fixPath, label: check.fixLabel || "Fix now" };
  }
  const id = String(check.id || "").toLowerCase();
  const label = String(check.label || "").toLowerCase();

  if (id.includes("paycheck") || label.includes("paycheck")) {
    return { path: "/admin/appconfig", label: "Open application config" };
  }
  if (id.includes("structure") || label.includes("salary structure")) {
    return { path: "/payroll/salary-structures", label: "Configure salary structures" };
  }
  if (id.includes("deduction") || label.includes("deduction")) {
    return { path: "/payroll/deductions", label: "Open deductions" };
  }
  if (id.includes("leave") || label.includes("leave")) {
    return { path: "/workspace/approvals", label: "Clear leave approvals" };
  }
  if (id.includes("timesheet") || label.includes("timesheet")) {
    return { path: "/workspace/approvals", label: "Clear timesheet approvals" };
  }
  if (id.includes("attendance") || label.includes("attendance")) {
    return { path: "/workspace/approvals", label: "Clear attendance approvals" };
  }
  if (id.includes("group") || id.includes("frequency") || label.includes("payroll group") || label.includes("pay frequency")) {
    return { path: "/payroll/groups", label: "Configure payroll groups" };
  }
  return { path: "/payroll/runs", label: "Open payroll runs" };
}

export function enrichPayrollConfigPayload(raw) {
  const payload = raw && typeof raw === "object" ? raw : {};
  const groups = Array.isArray(payload.groups) ? payload.groups : [];
  const checks = Array.isArray(payload.mandatoryChecks) ? payload.mandatoryChecks : [];
  const passed = checks.filter((c) => c && c.passed).length;
  const total = checks.length;
  const score = total > 0 ? Math.round((passed / total) * 100) : 0;

  return {
    ...payload,
    groups,
    mandatoryChecks: checks,
    deductionScheduleCount: payload.deductionScheduleCount != null ? payload.deductionScheduleCount : 0,
    structureCount: payload.structureCount != null ? payload.structureCount : null,
    paychecksEnabled: payload.paychecksEnabled === true,
    readinessScore: score,
    checksPassed: passed,
    checksTotal: total,
    readyToRun: total > 0 && passed === total,
  };
}

export function buildClientPayrollMandatoryChecks({
  groups = [],
  paychecksEnabled = false,
  structureCount = 0,
}) {
  return [
    {
      id: "payroll_groups",
      passed: groups.length > 0,
      label: "At least one payroll group configured",
      fixPath: "/payroll/groups",
      fixLabel: "Configure groups",
    },
    {
      id: "pay_frequency",
      passed: groups.some((g) => g && g.payFrequency),
      label: "Pay frequency defined on payroll groups",
      fixPath: "/payroll/groups",
      fixLabel: "Set pay frequency",
    },
    {
      id: "paychecks_module",
      passed: paychecksEnabled === true,
      label: "Paychecks module enabled for publishing",
      fixPath: "/admin/appconfig",
      fixLabel: "Enable in app config",
    },
    {
      id: "salary_structures",
      passed: structureCount > 0,
      label: "At least one salary structure configured",
      fixPath: "/payroll/salary-structures",
      fixLabel: "Add structure",
    },
    {
      id: "leave_cleared",
      passed: true,
      label: "Leave approvals cleared for current period",
      fixPath: "/workspace/approvals",
      fixLabel: "Review approvals",
    },
    {
      id: "timesheet_cleared",
      passed: true,
      label: "Timesheet approvals cleared for current period",
      fixPath: "/workspace/approvals",
      fixLabel: "Review approvals",
    },
    {
      id: "attendance_cleared",
      passed: true,
      label: "Attendance approvals cleared for current period",
      fixPath: "/workspace/approvals",
      fixLabel: "Review approvals",
    },
  ];
}
