import React from "react";
import classNames from "classnames/bind";
import { WorkflowLuxPanel, WorkflowRunStatusBadge } from "views/automation/components/WorkflowLuxShared";

function formatDuration(ms) {
  if (!ms) {
    return "—";
  }
  if (ms < 1000) {
    return `${ms}ms`;
  }
  return `${(ms / 1000).toFixed(1)}s`;
}

export default function WorkflowRunHistoryPanel({ runs, loading, selectedRunId, onSelect }) {
  const list = runs || [];

  return (
    <WorkflowLuxPanel title="Run history" meta="Debug log and step trace" icon="fe fe-terminal" accent="slate">
      {loading ? (
        <div className="lux-wf-skeleton lux-wf-skeleton--panel" />
      ) : !list.length ? (
        <div className="lux-wf-empty">No runs recorded yet.</div>
      ) : (
        <div className="lux-wf-run-history">
          <ul className="lux-wf-run-list">
            {list.map((run) => (
              <li key={run.id}>
                <button
                  type="button"
                  className={classNames("lux-wf-run-row", run.tone && `is-${run.tone}`, selectedRunId === run.id && "is-selected")}
                  onClick={() => onSelect && onSelect(run)}
                >
                  <div className="lux-wf-run-row__main">
                    <span className="lux-wf-run-row__rule">{run.ruleName}</span>
                    <span className="lux-wf-run-row__time">{run.startedAt}</span>
                  </div>
                  <div className="lux-wf-run-row__meta">
                    <WorkflowRunStatusBadge status={run.status} />
                    <span>{formatDuration(run.durationMs)}</span>
                    <span>{run.stepsExecuted} steps</span>
                  </div>
                </button>
              </li>
            ))}
          </ul>
          {selectedRunId ? (
            <div className="lux-wf-run-debug">
              <h4>Debug log</h4>
              <ul>
                {((list.find((r) => r.id === selectedRunId) || {}).debugLog || []).map((line, index) => (
                  <li key={index}>{line}</li>
                ))}
              </ul>
              {(list.find((r) => r.id === selectedRunId) || {}).errorMessage ? (
                <p className="lux-wf-run-debug__error">{(list.find((r) => r.id === selectedRunId) || {}).errorMessage}</p>
              ) : null}
            </div>
          ) : null}
        </div>
      )}
    </WorkflowLuxPanel>
  );
}
