import React from "react";
import classNames from "classnames/bind";
import { enrichWorkItemDetail } from "../plannerHourly.utils";
import PlannerAssignHorizonEmptyState from "./PlannerAssignHorizonEmptyState";

export default function PlannerAssignAllocatedList({ context }) {
  if (!context) {
    return (
      <aside className="lux-planner-assign-alloc lux-planner-assign-alloc--empty">
        <PlannerAssignHorizonEmptyState variant="select-member" />
      </aside>
    );
  }

  const { assignments } = context;

  return (
    <aside className="lux-planner-assign-alloc lux-planner-assign-lux__alloc" aria-label="Tasks in horizon">
      <div className="lux-planner-assign-alloc__head lux-planner-assign-lux__alloc-head">
        <div className="lux-planner-assign-lux__alloc-copy">
          <span className="lux-planner-assign-lux__alloc-kicker">
            <i className="fe fe-layers" aria-hidden="true" />
            Horizon queue
          </span>
          <h4>Tasks in range</h4>
        </div>
        <div className="lux-planner-assign-lux__alloc-aside">
          <span className={classNames("lux-planner-assign-lux__util-chip", `is-${context.tone}`)}>
            {context.horizonUtilization}%
          </span>
          <span className="lux-planner-assign-lux__count">{assignments.length}</span>
        </div>
      </div>
      {assignments.length === 0 ? (
        <PlannerAssignHorizonEmptyState variant="no-tasks" context={context} />
      ) : (
        <ul className="lux-planner-assign-alloc__list">
          {assignments.map((entry) => {
            const { item, minutes, dayBreakdown, horizonDateLabel, hoursLabel, scheduleRangeLabel } = entry;
            const d = enrichWorkItemDetail(item, minutes);
            return (
              <li key={item.id} className="lux-planner-assign-task">
                <span className="lux-planner-assign-task__dot" style={{ background: d.statusColor }} />
                <div className="lux-planner-assign-task__main">
                  <strong>{d.item.name || d.item.taskActCategory || "Work item"}</strong>
                  <span className="lux-planner-assign-task__context">
                    {[d.projectName, d.taskName, d.statusMeta.label].filter(Boolean).join(" · ")}
                  </span>
                  <div className="lux-planner-assign-task__schedule">
                    <span className="lux-planner-assign-task__pill is-date" title="Days with planned time in this horizon">
                      <i className="fe fe-calendar" aria-hidden />
                      {horizonDateLabel}
                    </span>
                    <span className="lux-planner-assign-task__pill is-hours" title="Total hours in this horizon">
                      <i className="fe fe-clock" aria-hidden />
                      {hoursLabel}
                    </span>
                  </div>
                  {scheduleRangeLabel && scheduleRangeLabel !== horizonDateLabel && (
                    <span className="lux-planner-assign-task__full-range">
                      Scheduled {scheduleRangeLabel}
                    </span>
                  )}
                  {dayBreakdown && dayBreakdown.length > 1 && (
                    <ul className="lux-planner-assign-task__days">
                      {dayBreakdown.map((day) => (
                        <li key={day.dayKey}>
                          <span>{day.weekday}</span>
                          <span>{day.dateLabel}</span>
                          <strong>{day.hoursLabel}</strong>
                        </li>
                      ))}
                    </ul>
                  )}
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </aside>
  );
}
