import React, { useMemo, useState } from "react";
import classNames from "classnames/bind";
import ImageUpload from "./ImageUpload";
import { writeSummaryExpanded, getSummaryToggleLabel } from "_helpers/summaryExpandedStorage";
import {
  PROFILE_HERO_STORAGE_KEY,
  buildProfileHeroContextLine,
  buildProfileHeroKpis,
  collectSkillChips,
  formatProfileDate,
  getEmployeeStatusMeta,
  readProfileHeroExpanded,
} from "./profile/profilePage.utils";
import { resolveEmployeeAvatarUrl } from "./profile/profilePhoto.storage";
import ProfilePageHeroSkeleton from "./profile/ProfilePageHeroSkeleton";

const HeroDateItem = ({ label, value, tone }) => (
  <div className={classNames("profile-hero__date", tone && `is-${tone}`)}>
    <span className="profile-hero__date-label">{label}</span>
    <strong className="profile-hero__date-value">{value || "—"}</strong>
  </div>
);

const HeroChipList = ({ items, emptyLabel }) => {
  if (!items || !items.length) {
    return <span className="profile-hero__glance-empty">{emptyLabel || "None"}</span>;
  }
  return (
    <div className="profile-chip-list profile-hero__chip-list">
      {items.map((item) => (
        <span key={item} className="profile-chip">
          {item}
        </span>
      ))}
    </div>
  );
};

function ProfilePageHero({ employee, readOnly, loading }) {
  const [expanded, setExpanded] = useState(readProfileHeroExpanded);

  const status = useMemo(() => getEmployeeStatusMeta(employee), [employee]);
  const contextLine = useMemo(() => buildProfileHeroContextLine(employee), [employee]);
  const kpis = useMemo(() => buildProfileHeroKpis(employee), [employee]);
  const skillChips = useMemo(() => collectSkillChips(employee), [employee]);
  const additionalSkillLabels = useMemo(
    () => skillChips.filter((chip) => chip.tier === "additional").map((chip) => chip.label),
    [skillChips]
  );
  const rankedSkillChips = useMemo(
    () => skillChips.filter((chip) => chip.tier !== "additional"),
    [skillChips]
  );

  if (loading && !employee) return <ProfilePageHeroSkeleton />;
  if (!employee) return null;

  const hasDates =
    employee.dateOfJoin || employee.dateOfBirth || employee.exitDate;
  const hasSkills = rankedSkillChips.length > 0 || additionalSkillLabels.length > 0;

  const imageUrl = resolveEmployeeAvatarUrl(employee);
  const teamName = employee.defaultUserTeamDetails && employee.defaultUserTeamDetails.name;
  const roleName = employee.userAccessDetails && employee.userAccessDetails.name;

  const toggleExpanded = () => {
    setExpanded((prev) => {
      const next = !prev;
      writeSummaryExpanded(PROFILE_HERO_STORAGE_KEY, next);
      return next;
    });
  };

  return (
    <header
      className={classNames("pd-hero profile-hero", {
        "profile-hero--collapsed": !expanded,
      })}
      aria-label="Employee summary"
    >
      <div className="pd-hero__glow" aria-hidden="true" />

      <div className="profile-hero__shell">
        <div className="lux-emp-summary__header-bar profile-hero__header-bar">
          <div className="profile-hero__lead lux-emp-summary__header-main">
            <div className="profile-hero__avatar-wrap">
              <ImageUpload
                employeeId={employee.id}
                imageUrl={imageUrl}
                readOnly={readOnly}
              />
            </div>

            <div className="profile-hero__identity-block">
              <div className="pd-hero__identity">
                <div className="profile-hero__eyebrow">
                  <i className="fe fe-user" aria-hidden="true" />
                  Employee profile
                </div>
                <div className="profile-hero__meta-row">
                  {teamName && <span className="pd-hero__badge">{teamName}</span>}
                  {employee.empCode && <span className="pd-hero__id">{employee.empCode}</span>}
                  <span
                    className={classNames(
                      "profile-hero__status",
                      "profile-hero__status--inline",
                      `is-${status.tone}`
                    )}
                  >
                    {status.label}
                  </span>
                </div>
                <h1 className="pd-hero__title">{employee.name}</h1>
                <div className="pd-hero__chips">
                  {employee.designation && (
                    <span className="pd-chip pd-chip--soft">
                      <i className="fe fe-briefcase" /> {employee.designation}
                    </span>
                  )}
                  {roleName && <span className="pd-chip pd-chip--accent">{roleName}</span>}
                  {employee.empType && (
                    <span className="pd-chip pd-chip--soft">
                      <i className="fe fe-user" /> {employee.empType}
                    </span>
                  )}
                </div>
                {!expanded && contextLine && (
                  <p className="profile-hero__collapsed-line">{contextLine}</p>
                )}
              </div>

              {expanded && (hasDates || hasSkills) && (
                <div className="profile-hero__rail">
                  {hasDates && (
                    <section className="profile-hero__rail-panel" aria-label="Key dates">
                      <h3 className="profile-hero__glance-title">
                        <i className="fe fe-calendar" aria-hidden="true" />
                        Key dates
                      </h3>
                      <div className="profile-hero__dates profile-hero__dates--rail">
                        {employee.dateOfJoin && (
                          <HeroDateItem
                            label="Joined"
                            value={formatProfileDate(employee.dateOfJoin)}
                            tone="green"
                          />
                        )}
                        {employee.dateOfBirth && (
                          <HeroDateItem
                            label="Date of birth"
                            value={formatProfileDate(employee.dateOfBirth)}
                          />
                        )}
                        {employee.exitDate && (
                          <HeroDateItem
                            label="Exit date"
                            value={formatProfileDate(employee.exitDate)}
                            tone="rose"
                          />
                        )}
                      </div>
                    </section>
                  )}

                  {hasSkills && (
                    <section className="profile-hero__rail-panel" aria-label="Skills">
                      <h3 className="profile-hero__glance-title">
                        <i className="fe fe-award" aria-hidden="true" />
                        Skills
                      </h3>
                      {rankedSkillChips.length > 0 && (
                        <div className="profile-skill-chips profile-hero__skill-chips">
                          {rankedSkillChips.map((chip) => (
                            <span
                              key={chip.key}
                              className={classNames("profile-skill-chip", `is-${chip.tier}`)}
                            >
                              {chip.label}
                            </span>
                          ))}
                        </div>
                      )}
                      <div className="profile-hero__glance-sub">
                        <span className="profile-hero__glance-sub-label">Additional</span>
                        <HeroChipList
                          items={additionalSkillLabels}
                          emptyLabel="None"
                        />
                      </div>
                    </section>
                  )}
                </div>
              )}
            </div>
          </div>

          <div className="profile-hero__header-actions">
            {employee.email && (
              <a
                className="lux-emp-summary__toggle lux-summary-toggle--icon"
                href={`mailto:${employee.email}`}
                title={employee.email}
                aria-label={`Email ${employee.email}`}
              >
                <i className="fe fe-mail" aria-hidden="true" />
              </a>
            )}
            {employee.mobileNumber && (
              <a
                className="lux-emp-summary__toggle lux-summary-toggle--icon"
                href={`tel:${employee.mobileNumber}`}
                title={employee.mobileNumber}
                aria-label={`Call ${employee.mobileNumber}`}
              >
                <i className="fe fe-phone" aria-hidden="true" />
              </a>
            )}
            <button
              type="button"
              className="lux-emp-summary__toggle"
              onClick={toggleExpanded}
              aria-expanded={expanded}
              title={expanded ? "Collapse summary" : "Insights"}
            >
              <span>{getSummaryToggleLabel(expanded)}</span>
              <i className="fe fe-chevron-down lux-summary-toggle__chevron" aria-hidden="true" />
            </button>
          </div>
        </div>

        {expanded && kpis.length > 0 && (
          <section className="profile-hero__glance" aria-label="At-a-glance metrics" aria-hidden={!expanded}>
            <header className="profile-hero__glance-head">
              <div className="profile-hero__glance-head-main">
                <span className="profile-hero__glance-kicker">
                  <i className="fe fe-sliders" aria-hidden="true" />
                  At-a-glance
                </span>
                <p className="profile-hero__glance-hint">
                  Full records are in Personal information below
                </p>
              </div>
            </header>
            <div className="profile-hero__glance-stats" role="list">
              {kpis.map((item) => (
                <article
                  key={item.key}
                  role="listitem"
                  className={classNames("profile-hero__stat", item.tone && `is-${item.tone}`)}
                >
                  <span className="profile-hero__stat-glow" aria-hidden="true" />
                  <span className="profile-hero__stat-icon">
                    <i className={item.icon} aria-hidden="true" />
                  </span>
                  <div className="profile-hero__stat-copy">
                    <span className="profile-hero__stat-label">{item.label}</span>
                    <strong className="profile-hero__stat-value">{item.value}</strong>
                    {item.hint && <span className="profile-hero__stat-hint">{item.hint}</span>}
                  </div>
                </article>
              ))}
            </div>
          </section>
        )}
      </div>
    </header>
  );
}

export default ProfilePageHero;
