export function getIntegrationCenterShellPageTitle(routePath) {
  if (!routePath) {
    return "Integration hub";
  }
  if (routePath.startsWith(INTEGRATION_CENTER_ROUTES.SYNC_HEALTH)) {
    return "Sync monitor";
  }
  if (routePath.startsWith(INTEGRATION_CENTER_ROUTES.MAPPING)) {
    return "Data mapping";
  }
  if (routePath.startsWith(INTEGRATION_CENTER_ROUTES.JOBS)) {
    return "Import/export jobs";
  }
  if (routePath.startsWith(INTEGRATION_CENTER_ROUTES.LOGS)) {
    return "Integration logs";
  }
  if (routePath.startsWith(INTEGRATION_CENTER_ROUTES.ADAPTERS)) {
    return "Connector adapters";
  }
  return "Integration hub";
}
