import React from "react";
import classNames from "classnames/bind";

/**
 * Primary create / add action for LuxModuleIntro (page hero).
 * Same visual language as the former lux-page-header__create-btn.
 */
export default function PageCreateButton({
  onClick,
  children = "Create",
  icon = "fe-plus",
  testId,
  className,
  disabled = false,
  createLink = false,
  title,
}) {
  const iconClass = icon.startsWith("fe ") ? icon : `fe ${icon}`;

  return (
    <button
      type="button"
      className={classNames(
        "lux-page-header__create-btn",
        "lux-module-hero__create-btn",
        createLink && "create-link",
        disabled && "is-busy",
        className
      )}
      onClick={onClick}
      disabled={disabled}
      data-testid={testId || undefined}
      title={title}
    >
      <i className={iconClass} aria-hidden="true" />
      <span>{children}</span>
    </button>
  );
}
