import React, { Component } from "react";
import classNames from "classnames/bind";
import { getScheduleStatusMeta } from "../settings/settingsTab.utils";

class ScheduleListRow extends Component {
  constructor(props) {
    super(props);
    this.state = { confirmRemove: false };
  }

  setEnabled = (nextEnabled) => {
    if (this.props.item.deleted) return;
    if (this.props.item.enabled === nextEnabled) return;
    this.props.onEnable(nextEnabled);
  };

  handleRemove = () => {
    if (this.state.confirmRemove) {
      this.props.onRemove();
      this.setState({ confirmRemove: false });
    } else {
      this.setState({ confirmRemove: true });
    }
  };

  render() {
    const { item, rowIndex } = this.props;
    const meta = getScheduleStatusMeta(item);
    const isDeleted = item.deleted === true;

    return (
      <article
        className={classNames("lux-schedule-row", {
          "is-deleted": isDeleted,
          "is-disabled": !item.enabled && !isDeleted,
        })}
        role="listitem"
      >
        <span className="lux-schedule-row__index">{rowIndex}</span>
        <span className={classNames("lux-schedule-row__status", `is-${meta.tone}`)}>
          <i className={meta.icon} aria-hidden="true" />
          {meta.label}
        </span>
        <div className="lux-schedule-row__main">
          <div className="lux-schedule-row__title-row">
            <span className="lux-schedule-row__id">#{item.id}</span>
            <h4 className={classNames("lux-schedule-row__name", { "is-struck": isDeleted })} title={item.name}>
              {item.name}
            </h4>
            {item.scheduleType && (
              <span className="lux-schedule-row__type">{item.scheduleType}</span>
            )}
          </div>
          {item.cronString && (
            <code className="lux-schedule-row__cron" title="Cron expression">
              {item.cronString}
            </code>
          )}
        </div>
        <div className="lux-schedule-row__runs">
          <div className="lux-schedule-row__run">
            <span className="lux-schedule-row__run-label">Last run</span>
            <strong>{item.lastRun || "—"}</strong>
          </div>
          <div className="lux-schedule-row__run">
            <span className="lux-schedule-row__run-label">Next run</span>
            <strong className={classNames({ "is-live": item.enabled && !isDeleted })}>
              {item.enabled && !isDeleted && <i className="fe fe-clock" aria-hidden="true" />}
              {item.nextRun || "—"}
            </strong>
          </div>
        </div>
        <div className="lux-schedule-row__actions">
          <div
            className={classNames("lux-schedule-power", {
              "is-active": item.enabled && !isDeleted,
              "is-paused": !item.enabled && !isDeleted,
              "is-disabled": isDeleted,
            })}
            role="group"
            aria-label={`Scheduler ${item.name} power`}
          >
            <button
              type="button"
              className={classNames("lux-schedule-power__btn", {
                "is-selected": !item.enabled,
              })}
              disabled={isDeleted}
              onClick={() => this.setEnabled(false)}
              aria-pressed={!item.enabled}
            >
              <i className="fe fe-pause-circle" aria-hidden="true" />
              <span>Paused</span>
            </button>
            <button
              type="button"
              className={classNames("lux-schedule-power__btn", {
                "is-selected": !!item.enabled,
              })}
              disabled={isDeleted}
              onClick={() => this.setEnabled(true)}
              aria-pressed={!!item.enabled}
            >
              <i className="fe fe-play-circle" aria-hidden="true" />
              <span>Active</span>
            </button>
          </div>
          <button
            type="button"
            className={classNames("lux-schedule-row__remove", { "is-confirm": this.state.confirmRemove })}
            onClick={this.handleRemove}
            disabled={isDeleted}
            title={this.state.confirmRemove ? "Confirm remove" : "Remove scheduler"}
            aria-label={this.state.confirmRemove ? "Confirm remove" : "Remove scheduler"}
          >
            <i className={this.state.confirmRemove ? "fe fe-check" : "fe fe-trash-2"} aria-hidden="true" />
          </button>
        </div>
      </article>
    );
  }
}

export default ScheduleListRow;
