import React from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";

function SummaryCard({ label, value, hint, tone, icon, onClick, filterLabel, active }) {
  const interactive = typeof onClick === "function";
  const Tag = interactive ? "button" : "article";

  return (
    <Tag
      type={interactive ? "button" : undefined}
      className={classNames("lux-hrms-dash__kpi lux-appr-kpi", `is-${tone}`, {
        "is-interactive": interactive,
        "is-active": interactive && active,
      })}
      role={interactive ? undefined : "listitem"}
      onClick={onClick}
      aria-pressed={interactive ? Boolean(active) : undefined}
      aria-label={
        interactive
          ? active
            ? `Clear ${label} filter`
            : filterLabel || `Filter by ${label}`
          : undefined
      }
    >
      <div className="lux-hrms-dash__kpi-top">
        <span className="lux-hrms-dash__kpi-label">{label}</span>
        {icon && (
          <span className="lux-hrms-dash__kpi-icon" aria-hidden="true">
            <i className={`fe ${icon}`} />
          </span>
        )}
      </div>
      <strong className="lux-hrms-dash__kpi-value">
        <CountUp end={Number(value) || 0} duration={0.7} separator="," />
      </strong>
      {hint && <span className="lux-hrms-dash__kpi-hint">{hint}</span>}
    </Tag>
  );
}

function UniversalApprovalSummary({ metrics, loading, onFilter, filters }) {
  const pending = loading ? 0 : metrics.pending || 0;
  const highPriority = loading ? 0 : metrics.highPriority || 0;
  const domainCount = loading ? 0 : metrics.domainCount || 0;
  const delegateCount = loading ? 0 : metrics.delegateCount || 0;
  const status = (filters && filters.status) || "PENDING";
  const priority = (filters && filters.priority) || "ALL";
  const pendingActive = status === "PENDING" && priority === "ALL";
  const highPriorityActive = status === "PENDING" && priority === "HIGH";

  const applyOrClear = (patch, isActive) => {
    if (!onFilter) return;
    if (isActive) {
      onFilter({ status: "PENDING", priority: "ALL" });
      return;
    }
    onFilter(patch);
  };

  return (
    <div className="lux-hrms-dash__kpi-strip lux-appr-kpi-strip" role="list" aria-busy={loading}>
      <SummaryCard
        label="Pending"
        value={pending}
        hint={pendingActive ? "Showing pending · click to keep" : "Awaiting your decision"}
        tone="amber"
        icon="fe-inbox"
        filterLabel="Show pending approvals"
        active={pendingActive}
        onClick={
          onFilter
            ? () => applyOrClear({ status: "PENDING", priority: "ALL" }, pendingActive)
            : undefined
        }
      />
      <SummaryCard
        label="High priority"
        value={highPriority}
        hint={highPriorityActive ? "Filter on · click again to clear" : "Needs attention first"}
        tone="rose"
        icon="fe-alert-triangle"
        filterLabel="Show high priority pending approvals"
        active={highPriorityActive}
        onClick={
          onFilter
            ? () =>
                applyOrClear({ status: "PENDING", priority: "HIGH" }, highPriorityActive)
            : undefined
        }
      />
      <SummaryCard
        label="Domains"
        value={domainCount}
        hint="Approval types in queue"
        tone="primary"
        icon="fe-layers"
      />
      <SummaryCard
        label="As delegate"
        value={delegateCount}
        hint="Acting for another manager"
        tone="violet"
        icon="fe-shield"
        filterLabel="Show pending approvals"
        onClick={onFilter && delegateCount > 0 ? () => onFilter({ status: "PENDING" }) : undefined}
      />
    </div>
  );
}

export default UniversalApprovalSummary;
