import dateUtils from "_helpers/date.utils";

export const TASKBOARD_COLUMNS = [
  { stage: 1, key: "planned", name: "Planned", icon: "fe-calendar", tone: "slate", hint: "Scheduled, not started" },
  { stage: 2, key: "todo", name: "To do", icon: "fe-flag", tone: "sky", hint: "Ready to pick up" },
  { stage: 3, key: "progress", name: "In progress", icon: "fe-play-circle", tone: "amber", hint: "Actively being worked" },
  { stage: 4, key: "done", name: "Completed", icon: "fe-check-circle", tone: "green", hint: "Logged and closed out" },
];

const STATUS_META = {
  NEW: { label: "New", tone: "sky" },
  ASSIGNED: { label: "Assigned", tone: "indigo" },
  READY_TO_START: { label: "Ready", tone: "sky" },
  INPROGRESS: { label: "In progress", tone: "amber" },
  PAUSED: { label: "Paused", tone: "amber" },
  COMPLETED: { label: "Completed", tone: "green" },
  CLOSED: { label: "Closed", tone: "slate" },
};

const STAGE_BY_STATUS = {
  READY_TO_START: 2,
};

const COMPLETED_STATUSES = ["COMPLETED", "CLOSED"];

export function getTaskBoardStage(workItem) {
  if (!workItem) return 1;
  const st = String(workItem.status || "").toUpperCase();
  if (STAGE_BY_STATUS[st]) return STAGE_BY_STATUS[st];
  const stage = parseInt(workItem.stage, 10);
  return Number.isFinite(stage) ? stage : 1;
}

export function getTaskBoardStatusMeta(status) {
  const key = String(status || "NEW").toUpperCase();
  return STATUS_META[key] || { label: key, tone: "slate" };
}

export function filterItemsByStage(items, column) {
  return (items || []).filter((item) => {
    const stage = getTaskBoardStage(item);
    if (column.stage === 2 && String(item.status || "").toUpperCase() === "READY_TO_START") {
      return true;
    }
    return stage === column.stage;
  });
}

function getItemEndMoment(item) {
  const raw = item.estCompletionTime || item.taskEstCompletionTime || item.estimatedEndTime;
  if (!raw) return null;
  const m = dateUtils.convertDateToMoment(raw);
  return m && m.isValid() ? m : null;
}

function isOverdue(item) {
  const st = String(item.status || "").toUpperCase();
  if (COMPLETED_STATUSES.includes(st)) return false;
  const end = getItemEndMoment(item);
  if (!end) return false;
  return end.isBefore(dateUtils.getCurrentTime(), "day");
}

export function buildTaskBoardSummary(items) {
  const list = items || [];
  const byStage = { 1: 0, 2: 0, 3: 0, 4: 0 };
  const byCategory = {};
  const byType = { PROJECT: 0, NON_PROJECT: 0, OTHER: 0 };
  const statusCounts = {};
  let inProgressMins = 0;
  let completedMins = 0;
  let estimatedMins = 0;
  let overdueCount = 0;
  let billableCount = 0;
  let inTimerCount = 0;

  list.forEach((item) => {
    const stage = getTaskBoardStage(item);
    byStage[stage] = (byStage[stage] || 0) + 1;
    const cat = item.taskActCategory || "Other";
    byCategory[cat] = (byCategory[cat] || 0) + 1;
    const type = String(item.taskType || "").toUpperCase();
    if (type === "PROJECT") {
      byType.PROJECT += 1;
      billableCount += 1;
    } else if (type === "NON_PROJECT" || type === "NONPROJECT") {
      byType.NON_PROJECT += 1;
    } else {
      byType.OTHER += 1;
    }
    const st = String(item.status || "NEW").toUpperCase();
    statusCounts[st] = (statusCounts[st] || 0) + 1;
    const est = item.estDurationInMins || 0;
    estimatedMins += est;
    if (stage === 3) {
      inProgressMins += est;
      inTimerCount += 1;
    }
    if (stage === 4) completedMins += item.durationInMins || est;
    if (isOverdue(item)) overdueCount += 1;
  });

  const total = list.length;
  const active = (byStage[2] || 0) + (byStage[3] || 0);
  const completedCount = byStage[4] || 0;
  const completionRate = total > 0 ? Math.round((completedCount / total) * 100) : 0;
  const billablePct = total > 0 ? Math.round((billableCount / total) * 100) : 0;

  const insights = [];
  if (inTimerCount > 0) {
    insights.push({
      tone: "amber",
      icon: "fe-play-circle",
      title: `${inTimerCount} running now`,
      detail: "Timers active in the In progress column — complete or pause when done.",
    });
  }
  if (overdueCount > 0) {
    insights.push({
      tone: "rose",
      icon: "fe-alert-triangle",
      title: `${overdueCount} past due`,
      detail: "Tasks with an end date before today that are not yet completed.",
    });
  }
  if ((byStage[1] || 0) + (byStage[2] || 0) > (byStage[3] || 0) + completedCount) {
    insights.push({
      tone: "sky",
      icon: "fe-flag",
      title: "Backlog ahead of execution",
      detail: "More work is planned or queued than actively in progress — good day to pull items forward.",
    });
  }
  if (total > 0 && completionRate >= 60) {
    insights.push({
      tone: "green",
      icon: "fe-trending-up",
      title: "Strong completion pace",
      detail: `${completionRate}% of today's board is already in the Done column.`,
    });
  }
  if (insights.length === 0 && total > 0) {
    insights.push({
      tone: "indigo",
      icon: "fe-layers",
      title: "Board is balanced",
      detail: "Drag cards between columns to advance work and keep flow visible to the team.",
    });
  }

  return {
    total,
    active,
    completionRate,
    billablePct,
    overdueCount,
    inTimerCount,
    byStage,
    byCategory,
    byType,
    statusCounts,
    inProgressCount: byStage[3] || 0,
    plannedCount: byStage[1] || 0,
    todoCount: byStage[2] || 0,
    completedCount,
    estimatedHours: Math.round((estimatedMins / 60) * 10) / 10,
    inProgressHours: Math.round((inProgressMins / 60) * 10) / 10,
    completedHours: Math.round((completedMins / 60) * 10) / 10,
    categoryEntries: Object.entries(byCategory)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 8),
    insights: insights.slice(0, 4),
    funnel: TASKBOARD_COLUMNS.map((col) => ({
      key: col.key,
      label: col.name,
      count: byStage[col.stage] || 0,
      tone: col.tone,
    })),
  };
}

export function formatTaskBoardSchedule(item) {
  const raw = item.actualStartTime || item.estStartTime;
  return raw ? dateUtils.convertDateTimeFormat(raw) : "—";
}

export function formatTaskBoardDue(item) {
  const end = getItemEndMoment(item);
  return end ? end.format("ddd DD MMM · HH:mm") : null;
}

export function getTaskBoardCardMeta(workItem, permission) {
  const stage = getTaskBoardStage(workItem);
  const column = TASKBOARD_COLUMNS.find((c) => c.stage === stage) || TASKBOARD_COLUMNS[0];
  const statusMeta = getTaskBoardStatusMeta(workItem.status);
  const durationMins =
    stage === 4
      ? workItem.durationInMins
      : permission && permission.showWorkItemEstimatedHours !== false
        ? workItem.estDurationInMins
        : null;
  const assignee =
    (workItem.ownerDetails && workItem.ownerDetails.name) ||
    workItem.employeeName ||
    (workItem.employee && workItem.employee.name) ||
    null;

  return {
    stage,
    column,
    statusMeta,
    durationLabel: durationMins != null ? dateUtils.minuteToHourString(durationMins) || "0h 0m" : null,
    scheduleLabel: formatTaskBoardSchedule(workItem),
    dueLabel: formatTaskBoardDue(workItem),
    isOverdue: isOverdue(workItem),
    isProject: workItem.taskType === "PROJECT",
    projectName: workItem.projectName || null,
    taskName: workItem.taskName || null,
    projectCode: workItem.projectcode || null,
    assignee,
    itemRef: workItem.itemIdUserTeamPrefix || (workItem.id != null ? `#${workItem.id}` : null),
    isPaused: String(workItem.status || "").toUpperCase() === "PAUSED",
  };
}
