import envconfig from "env.config";
import { shouldUseOrgChart, shouldUseOrgStructureAdmin } from "config/tracopus-pilot.config";

export const ORG_UNIT_TYPES = {
  COMPANY: "COMPANY",
  DIVISION: "DIVISION",
  DEPARTMENT: "DEPARTMENT",
  TEAM: "TEAM",
};

export const ORG_UNIT_TYPE_META = {
  [ORG_UNIT_TYPES.COMPANY]: { label: "Company", icon: "fe fe-briefcase", tone: "primary" },
  [ORG_UNIT_TYPES.DIVISION]: { label: "Division", icon: "fe fe-layers", tone: "violet" },
  [ORG_UNIT_TYPES.DEPARTMENT]: { label: "Department", icon: "fe fe-grid", tone: "blue" },
  [ORG_UNIT_TYPES.TEAM]: { label: "Team", icon: "fe fe-users", tone: "green" },
};

export function isOrgChartEnabled() {
  return shouldUseOrgChart();
}

export function isOrgStructureAdminEnabled() {
  return shouldUseOrgStructureAdmin();
}

export function normalizeOrgUnit(row) {
  if (!row) {
    return null;
  }
  const type = row.type || ORG_UNIT_TYPES.DEPARTMENT;
  return {
    id: row.id,
    name: row.name || "Org unit",
    type,
    parentId: row.parentId || null,
    headEmployeeId: row.headEmployeeId || null,
    headEmployeeName: row.headEmployeeName || row.headName || null,
    headcount: row.headcount != null ? row.headcount : null,
    costCenter: row.costCenter || null,
    location: row.location || null,
    status: row.status || "Active",
    updatedAt: row.updatedAt || null,
    sourceEntityId: row.sourceEntityId || null,
    sourceEntityType: row.sourceEntityType || null,
  };
}

export function normalizeReportingLine(row) {
  if (!row) {
    return null;
  }
  return {
    employeeId: row.employeeId,
    employeeName: row.employeeName || row.name,
    designation: row.designation || null,
    department: row.department || null,
    managerId: row.managerId || null,
    managerName: row.managerName || row.manager || null,
    orgUnitId: row.orgUnitId || null,
    location: row.location || null,
    status: row.status || "Active",
  };
}
