const STORAGE_KEY = "famstack-team-capacity-prefs-v1";

const DEFAULT_PREFS = {
  activeTab: "overview",
  horizonWeeks: 2,
  viewMode: "TASKS",
  teamScope: "myTeams",
  reduceCapacityForHolidays: false,
  ganttAxis: "EMPLOYEE",
  ganttLevel: "WORK_ITEM",
  /** null = all team (Timeline / Gantt); set when focusing one person */
  selectedEmployeeId: null,
  statusFilter: "ALL",
  timeGranularity: "DAY",
  focusDayKey: null,
  showActuals: false,
  assignTrayOpen: true,
  /** Assign work panel — capacity insights summary collapsed vs expanded */
  assignSummaryExpanded: true,
};

export function readPlannerPrefs() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...DEFAULT_PREFS };
    return { ...DEFAULT_PREFS, ...JSON.parse(raw) };
  } catch (e) {
    return { ...DEFAULT_PREFS };
  }
}

export function writePlannerPrefs(partial) {
  try {
    const next = { ...readPlannerPrefs(), ...partial };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
    return next;
  } catch (e) {
    return readPlannerPrefs();
  }
}

export const PLANNER_TABS = [
  { id: "overview", label: "Overview", icon: "fe-pie-chart" },
  { id: "roster", label: "Team roster", icon: "fe-grid" },
  { id: "timeline", label: "Timeline", icon: "fe-calendar" },
  { id: "gantt", label: "Gantt", icon: "fe-bar-chart-2" },
];
