import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import { commonUtils } from "_helpers";
import ProjectAccessChipPicker from "./ProjectAccessChipPicker";

const REFINE_MODES = {
  OPEN: "open",
  SKILLS: "skills",
  PEOPLE: "people",
};

class ProjectTaskAccessRestrictionControlInput extends PureComponent {
  constructor(props) {
    super(props);
    this.state = {
      previouslySelectedRestrictedByEmployeeIds: [],
      refineMode: REFINE_MODES.OPEN,
    };
  }

  componentDidMount() {
    this.setState({
      previouslySelectedRestrictedByEmployeeIds:
        this.props.mappingObject.restrictByEmployeeIds || [],
      refineMode: this.resolveRefineMode(this.props.mappingObject),
    });
  }

  componentDidUpdate(prevProps) {
    const prevPeople = (prevProps.mappingObject.restrictedByEmployeeIds || []).length;
    const prevSkills = (prevProps.mappingObject.restrictedByEmployeeSkills || []).length;
    const nextPeople = (this.props.mappingObject.restrictedByEmployeeIds || []).length;
    const nextSkills = (this.props.mappingObject.restrictedByEmployeeSkills || []).length;

    if (prevPeople !== nextPeople || prevSkills !== nextSkills) {
      const nextMode = this.resolveRefineMode(this.props.mappingObject);
      if (nextMode !== this.state.refineMode) {
        this.setState({ refineMode: nextMode });
      }
    }
  }

  resolveRefineMode = (mappingObject) => {
    if ((mappingObject.restrictedByEmployeeIds || []).length > 0) {
      return REFINE_MODES.PEOPLE;
    }
    if ((mappingObject.restrictedByEmployeeSkills || []).length > 0) {
      return REFINE_MODES.SKILLS;
    }
    return REFINE_MODES.OPEN;
  };

  getAvailableTeams = () => {
    const { userTeams, permission } = this.props;
    if (!userTeams) return [];
    const currentUserTeams = commonUtils.getUserTeamsFromUserItem() || [];
    const selected = this.props.mappingObject.restrictedByUserTeamIds || [];
    return userTeams.filter((team) => {
      const isMine = currentUserTeams.some((t) => t.id === team.id);
      if (permission.showOnlyActiveUserTeamsInCreateWindow) {
        return isMine || (selected && selected.includes(team.id));
      }
      return true;
    });
  };

  getRestrictedEmployees = () => {
    const restrictedUserTeams =
      this.props.mappingObject.restrictedByUserTeamIds ||
      (this.props.projectRestrictedByUserTeamIds &&
      this.props.projectRestrictedByUserTeamIds.length > 0
        ? this.props.projectRestrictedByUserTeamIds
        : undefined) ||
      (this.props.userTeams && this.props.userTeams.map((userTeam) => userTeam.id));
    return this.getRestrictedEmployeesByUserGroupIds(restrictedUserTeams);
  };

  getRestrictedEmployeesByUserGroupIds = (restrictedUserTeams) => {
    let employees =
      this.props.projectRestrictedByEmployeeDetails &&
      this.props.projectRestrictedByEmployeeDetails.length > 0
        ? this.props.projectRestrictedByEmployeeDetails
        : this.props.allEmployees;
    if (employees && restrictedUserTeams && restrictedUserTeams.length > 0) {
      employees = commonUtils.filterEmployeesByTeams(employees, restrictedUserTeams);
    }
    const restrictedBySkills = this.props.projectRestrictedByEmployeeSkills;
    if (restrictedBySkills && employees && employees.length > 0) {
      employees = commonUtils.filterEmployeeBySkills(employees, restrictedBySkills);
    }
    return employees;
  };

  getRestrictedBySkillsOptions = () => {
    const configObject =
      this.props.employeeAppConfig &&
      this.props.employeeAppConfig.find((config) => config.name === "skills");
    let restrictedBySkills =
      this.props.projectRestrictedByEmployeeSkills || (configObject && configObject.value);
    const employees = this.getRestrictedEmployees();

    if (employees && employees.length > 0 && restrictedBySkills) {
      restrictedBySkills = commonUtils.filterSkillsByEmployee(employees, restrictedBySkills);
    } else {
      restrictedBySkills = [];
    }

    return commonUtils.convertConfigListToSelectObject(restrictedBySkills);
  };

  getEmployeePickerOptions = () => {
    const employees = this.getRestrictedEmployees() || [];
    return employees.map((emp) => ({
      value: emp.id,
      label: emp.name,
      meta: emp.email || emp.designation || undefined,
    }));
  };

  onChange = (fieldName, value) => {
    if (fieldName === "restrictedByEmployeeSkills") {
      this.props.onChange("restrictedByEmployeeIds", []);
    } else if (fieldName === "restrictedByEmployeeIds") {
      this.props.onChange("restrictedByEmployeeSkills", []);
      const current = value || [];
      const merged = [
        ...new Set([
          ...current,
          ...(this.state.previouslySelectedRestrictedByEmployeeIds || []),
        ]),
      ];
      this.setState({ previouslySelectedRestrictedByEmployeeIds: merged });
    } else if (fieldName === "restrictedByUserTeamIds") {
      const currentAvailable = this.getRestrictedEmployeesByUserGroupIds(value);
      let previouslySelected = this.state.previouslySelectedRestrictedByEmployeeIds || [];
      if (previouslySelected && currentAvailable) {
        previouslySelected = currentAvailable
          .filter((emp) => previouslySelected.includes(emp.id))
          .map((emp) => emp.id);
      }
      this.props.onChange("restrictedByEmployeeIds", previouslySelected);
      this.props.onChange("restrictedByEmployeeSkills", []);
    }
    this.props.onChange(fieldName, value);
  };

  toggleTeam = (teamId) => {
    const current = this.props.mappingObject.restrictedByUserTeamIds || [];
    const next = current.includes(teamId)
      ? current.filter((id) => id !== teamId)
      : [...current, teamId];
    this.onChange("restrictedByUserTeamIds", next.length ? next : null);
  };

  setRefineMode = (mode) => {
    if (mode === REFINE_MODES.OPEN) {
      this.props.onChange("restrictedByEmployeeSkills", []);
      this.props.onChange("restrictedByEmployeeIds", []);
    } else if (mode === REFINE_MODES.SKILLS) {
      this.props.onChange("restrictedByEmployeeIds", []);
    } else if (mode === REFINE_MODES.PEOPLE) {
      this.props.onChange("restrictedByEmployeeSkills", []);
    }
    this.setState({ refineMode: mode });
  };

  getSummary = () => {
    const teams = (this.props.mappingObject.restrictedByUserTeamIds || []).length;
    const skills = (this.props.mappingObject.restrictedByEmployeeSkills || []).length;
    const people = (this.props.mappingObject.restrictedByEmployeeIds || []).length;
    if (!teams && !skills && !people) {
      return "Open access — all eligible users can view and log work on this project.";
    }
    const parts = [];
    if (teams) parts.push(`${teams} team${teams === 1 ? "" : "s"}`);
    if (skills) parts.push(`${skills} skill${skills === 1 ? "" : "s"}`);
    if (people) parts.push(`${people} named ${people === 1 ? "person" : "people"}`);
    return `Task access limited to ${parts.join(" · ")}.`;
  };

  renderStepBadge = (step, label) => (
    <span className="lux-project-access__step-badge">
      <em>{step}</em>
      {label}
    </span>
  );

  renderTeamGrid = () => {
    const teams = this.getAvailableTeams();
    const selected = this.props.mappingObject.restrictedByUserTeamIds || [];
    const { permission } = this.props;
    const currentUserTeams = commonUtils.getUserTeamsFromUserItem() || [];

    if (!teams.length || teams.length <= 1) return null;

    return (
      <section className="lux-project-access__block">
        <header className="lux-project-access__block-head">
          {this.renderStepBadge(1, "Teams")}
          <i className="fe fe-users" aria-hidden="true" />
          <div>
            <strong>Limit by team</strong>
            <span>Select which teams may access project tasks. Leave empty to include all teams.</span>
          </div>
          {selected.length > 0 && (
            <span className="lux-project-access__count">{selected.length} selected</span>
          )}
        </header>
        <div className="lux-project-access__team-grid" role="group" aria-label="Restrict by team">
          {teams.map((team) => {
            const isOn = selected.includes(team.id);
            const isMine = currentUserTeams.some((t) => t.id === team.id);
            const disabled =
              !isMine && !permission.showAllUserTeamsSelectableInProjectCreateWindow;
            return (
              <button
                key={team.id}
                type="button"
                disabled={disabled}
                className={classNames("lux-project-access__team-chip", {
                  "is-selected": isOn,
                  "is-disabled": disabled,
                })}
                onClick={() => this.toggleTeam(team.id)}
                aria-pressed={isOn}
              >
                <span className="lux-project-access__team-check" aria-hidden="true">
                  <i className={isOn ? "fe fe-check" : "fe fe-circle"} />
                </span>
                <span>{team.name}</span>
              </button>
            );
          })}
        </div>
      </section>
    );
  };

  renderRefinePanel = () => {
    const { refineMode } = this.state;
    const skillOptions = this.getRestrictedBySkillsOptions();
    const peopleOptions = this.getEmployeePickerOptions();
    const selectedSkills = this.props.mappingObject.restrictedByEmployeeSkills || [];
    const selectedPeople = this.props.mappingObject.restrictedByEmployeeIds || [];
    const teamCount = (this.props.mappingObject.restrictedByUserTeamIds || []).length;

    return (
      <section className="lux-project-access__block lux-project-access__block--refine">
        <header className="lux-project-access__block-head">
          {this.renderStepBadge(2, "Refine")}
          <i className="fe fe-filter" aria-hidden="true" />
          <div>
            <strong>Narrow further (optional)</strong>
            <span>
              Choose skills or specific people within the team scope above. Only one refinement
              type applies at a time.
            </span>
          </div>
        </header>

        <div className="lux-project-access__mode-tabs" role="tablist" aria-label="Refine access by">
          <button
            type="button"
            role="tab"
            aria-selected={refineMode === REFINE_MODES.OPEN}
            className={classNames("lux-project-access__mode-tab", {
              "is-active": refineMode === REFINE_MODES.OPEN,
            })}
            onClick={() => this.setRefineMode(REFINE_MODES.OPEN)}
          >
            <i className="fe fe-unlock" aria-hidden="true" />
            All in scope
          </button>
          <button
            type="button"
            role="tab"
            aria-selected={refineMode === REFINE_MODES.SKILLS}
            className={classNames("lux-project-access__mode-tab", {
              "is-active": refineMode === REFINE_MODES.SKILLS,
            })}
            onClick={() => this.setRefineMode(REFINE_MODES.SKILLS)}
          >
            <i className="fe fe-award" aria-hidden="true" />
            By skill
            {selectedSkills.length > 0 && (
              <span className="lux-project-access__mode-count">{selectedSkills.length}</span>
            )}
          </button>
          <button
            type="button"
            role="tab"
            aria-selected={refineMode === REFINE_MODES.PEOPLE}
            className={classNames("lux-project-access__mode-tab", {
              "is-active": refineMode === REFINE_MODES.PEOPLE,
            })}
            onClick={() => this.setRefineMode(REFINE_MODES.PEOPLE)}
          >
            <i className="fe fe-user-check" aria-hidden="true" />
            Specific people
            {selectedPeople.length > 0 && (
              <span className="lux-project-access__mode-count">{selectedPeople.length}</span>
            )}
          </button>
        </div>

        {refineMode === REFINE_MODES.OPEN && (
          <div className="lux-project-access__mode-panel">
            <p className="lux-project-access__mode-hint">
              Everyone in {teamCount ? "the selected teams" : "eligible teams"} can access tasks.
              Switch to <strong>By skill</strong> or <strong>Specific people</strong> to restrict
              further.
            </p>
          </div>
        )}

        {refineMode === REFINE_MODES.SKILLS && (
          <div className="lux-project-access__mode-panel" role="tabpanel">
            <ProjectAccessChipPicker
              variant="skills"
              ariaLabel="Restrict by skill"
              searchPlaceholder="Search skills…"
              options={skillOptions}
              value={selectedSkills}
              onChange={(value) => this.onChange("restrictedByEmployeeSkills", value)}
              emptyMessage="No skills match the current team scope."
              emptyHint="Select teams first, or check employee skill configuration."
            />
          </div>
        )}

        {refineMode === REFINE_MODES.PEOPLE && (
          <div className="lux-project-access__mode-panel" role="tabpanel">
            <ProjectAccessChipPicker
              variant="people"
              ariaLabel="Restrict by employee"
              searchPlaceholder="Search people by name or email…"
              options={peopleOptions}
              value={selectedPeople}
              onChange={(value) => this.onChange("restrictedByEmployeeIds", value)}
              emptyMessage="No employees in the current team scope."
              emptyHint="Adjust team selection above to see more people."
            />
          </div>
        )}
      </section>
    );
  };

  render() {
    return (
      <div className="lux-project-access">
        <div className="lux-project-access__summary">
          <i className="fe fe-shield" aria-hidden="true" />
          <div>
            <strong>Access policy</strong>
            <p>{this.getSummary()}</p>
          </div>
        </div>

        {this.renderTeamGrid()}
        {this.renderRefinePanel()}

        <p className="lux-project-access__hint">
          <i className="fe fe-info" aria-hidden="true" />
          Restrictions apply in order: team scope first, then skills or named people refine who can
          view and log work. Skill and people filters cannot be combined.
        </p>
      </div>
    );
  }
}

export default ProjectTaskAccessRestrictionControlInput;
