import {
  ONBOARDING_TASK_CATEGORIES,
  OFFBOARDING_TASK_CATEGORIES,
} from "config/onboarding.config";

export const ONBOARDING_TEMPLATE_ASSIGNEE_TYPES = [
  { id: "HR", label: "HR team" },
  { id: "candidate", label: "New hire" },
  { id: "manager", label: "Manager" },
];

export const OFFBOARDING_TEMPLATE_ASSIGNEE_TYPES = [
  { id: "HR", label: "HR team" },
  { id: "employee", label: "Departing employee" },
  { id: "manager", label: "Manager" },
  { id: "IT", label: "IT / Ops" },
];

/** @deprecated use getTemplateAssigneeTypes */
export const TEMPLATE_ASSIGNEE_TYPES = ONBOARDING_TEMPLATE_ASSIGNEE_TYPES;

export function getTemplateCategories(lifecycle = "onboarding") {
  return lifecycle === "offboarding" ? OFFBOARDING_TASK_CATEGORIES : ONBOARDING_TASK_CATEGORIES;
}

export function getTemplateAssigneeTypes(lifecycle = "onboarding") {
  return lifecycle === "offboarding"
    ? OFFBOARDING_TEMPLATE_ASSIGNEE_TYPES
    : ONBOARDING_TEMPLATE_ASSIGNEE_TYPES;
}

export function createEmptyTemplateTask(sortOrder = 1, lifecycle = "onboarding") {
  const defaultCategory = lifecycle === "offboarding" ? "Access" : "HR";
  const defaultAssignee = lifecycle === "offboarding" ? "HR" : "HR";
  return {
    category: defaultCategory,
    title: "",
    ownerRole: lifecycle === "offboarding" ? "HR Admin" : "HR Admin",
    assigneeType: defaultAssignee,
    dueOffsetDays: lifecycle === "offboarding" ? 5 : 7,
    required: true,
    selfService: false,
    sortOrder,
  };
}

export function buildTemplateCodeFromName(name) {
  const slug = String(name || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
  const suffix = Date.now().toString(36).slice(-4);
  return slug ? `${slug}-${suffix}` : `template-${suffix}`;
}

export function normalizeTemplateTasks(tasks) {
  return (tasks || [])
    .map((task, index) => {
      const category = task.category || "HR";
      const required = task.required !== false;
      const integrationType =
        task.integrationType ||
        (category === "Documents" ? "DOCUMENT" : undefined);
      return {
        category,
        title: String(task.title || "").trim(),
        ownerRole: String(task.ownerRole || "HR Admin").trim() || "HR Admin",
        assigneeType: task.assigneeType || "HR",
        dueOffsetDays: Number(task.dueOffsetDays) >= 0 ? Number(task.dueOffsetDays) : 7,
        required,
        documentRequired: category === "Documents" && required,
        selfService: task.selfService === true,
        sortOrder: index + 1,
        ...(integrationType ? { integrationType } : {}),
      };
    })
    .filter((task) => task.title);
}

export function validateLifecycleTemplateDraft(draft, lifecycle = "onboarding") {
  const errors = [];
  const name = String(draft.name || "").trim();
  if (!name) {
    errors.push("Template name is required.");
  }
  const tasks = normalizeTemplateTasks(draft.tasks);
  if (!tasks.length) {
    errors.push("Add at least one checklist task with a title.");
  }
  const categories = getTemplateCategories(lifecycle);
  const invalidCategory = tasks.find(
    (task) => !categories.some((category) => category.id === task.category)
  );
  if (invalidCategory) {
    errors.push("Each task needs a valid category.");
  }
  return {
    valid: errors.length === 0,
    errors,
    tasks,
    name,
  };
}

/** @deprecated use validateLifecycleTemplateDraft */
export function validateOnboardingTemplateDraft(draft) {
  return validateLifecycleTemplateDraft(draft, "onboarding");
}

export function buildLifecycleTemplatePayload(draft, lifecycle = "onboarding") {
  const validation = validateLifecycleTemplateDraft(draft, lifecycle);
  if (!validation.valid) {
    throw new Error(validation.errors[0]);
  }
  const code = String(draft.code || "").trim() || buildTemplateCodeFromName(validation.name);
  return {
    code,
    name: validation.name,
    description: String(draft.description || "").trim(),
    department: String(draft.department || "").trim() || null,
    roleFilter: String(draft.roleFilter || "").trim() || null,
    locationFilter: String(draft.locationFilter || "").trim() || null,
    active: true,
    taskCount: validation.tasks.length,
    tasks: validation.tasks,
  };
}

/** @deprecated use buildLifecycleTemplatePayload */
export function buildOnboardingTemplatePayload(draft) {
  return buildLifecycleTemplatePayload(draft, "onboarding");
}
