import React from 'react';
import { connect } from 'react-redux';
import { withRouter } from 'react-router-dom';
import { leavePhase2Service as api } from '_services/leavePhase2.service';
import { getApiErrorMessage } from '_helpers/apiError.utils';
import { AdminActionButton } from 'views/admin/components/AdminLuxShared';
import {
  LeavePhase2AdminBase,
  LeavePhase2Panel,
  LeavePhase2Register,
  mapLeavePhase2State,
  renderLeavePhase2Nav,
  LEAVE_PHASE2_EMPTY_DESCRIPTION,
  cell,
} from './leavePhase2.shared';
import '../leaveLuxForms.css';

const NAV = [
  { path: '/admin/leave/document-rules', label: 'Rules', icon: 'fe fe-shield', exact: true },
  { path: '/admin/leave/document-review', label: 'Review', icon: 'fe fe-eye' },
  { path: '/admin/leave/document-retention', label: 'Retention', icon: 'fe fe-archive' },
];

const EMPTY_RULE = {
  leaveTypeCode: '',
  documentType: 'MEDICAL_CERTIFICATE',
  required: true,
};

function sectionFromPath(pathname) {
  if (pathname.includes('document-review')) return 'review';
  if (pathname.includes('document-retention')) return 'retention';
  return 'rules';
}

class LeaveDocumentWorkflowPage extends LeavePhase2AdminBase {
  state = {
    ...this.state,
    rules: [],
    requests: [],
    retention: [],
    saving: false,
    ruleForm: { ...EMPTY_RULE },
  };

  fetchSectionData = async (teamId) => {
    const section = sectionFromPath(this.props.location.pathname);
    if (section === 'rules') {
      const rules = (await api.listDocumentRules(teamId)) || [];
      this.setState({ rules: Array.isArray(rules) ? rules : [] });
      return;
    }
    if (section === 'review') {
      const requests = (await api.listDocumentRequests(teamId)) || [];
      this.setState({ requests: Array.isArray(requests) ? requests : [] });
      return;
    }
    const retention = (await api.listRetentionPolicies(teamId)) || [];
    this.setState({ retention: Array.isArray(retention) ? retention : [] });
  };

  saveRule = (event) => {
    event.preventDefault();
    const { ruleForm } = this.state;
    const leaveTypeCode = (ruleForm.leaveTypeCode || '').trim().toUpperCase();
    const documentType = (ruleForm.documentType || '').trim();
    if (!leaveTypeCode || !documentType) {
      this.setState({ error: 'Leave type and document type are required.' });
      return;
    }
    const teamId = this.teamId();
    if (!teamId) {
      this.setState({ error: 'Select a team first.' });
      return;
    }
    this.setState({ saving: true, error: null, notice: null });
    api
      .saveDocumentRule({
        userTeamId: teamId,
        actorId: this.actorId(),
        leaveTypeCode,
        documentType,
        required: ruleForm.required !== false,
      })
      .then(() => {
        this.setState({
          saving: false,
          notice: 'Document rule saved. Required proof will block leave submit until linked.',
          ruleForm: { ...EMPTY_RULE },
        });
        return this.loadAll();
      })
      .catch((e) => {
        this.setState({
          saving: false,
          error: getApiErrorMessage(e, 'Could not save rule.'),
        });
      });
  };

  markLinked = (request) => {
    if (!request || !request.id) return;
    const vaultRaw = window.prompt('Document vault ID (optional number). Leave blank to mark LINKED only.');
    if (vaultRaw === null) return;
    const vaultId = vaultRaw.trim() ? Number(vaultRaw.trim()) : null;
    this.setState({ saving: true, error: null, notice: null });
    const actorId = this.actorId();
    const done = () =>
      this.setState({
        saving: false,
        notice: 'Document marked linked — leave submit can proceed when rules are satisfied.',
      });
    const fail = (e) =>
      this.setState({
        saving: false,
        error: getApiErrorMessage(e, 'Could not mark document linked.'),
      });
    if (vaultId) {
      api
        .linkDocumentVault(request.id, {
          actorId,
          documentVaultId: vaultId,
          sourceEntityType: 'LEAVE',
          sourceEntityId: request.sourceId || null,
        })
        .then(() => this.loadAll().then(done))
        .catch(fail);
      return;
    }
    api
      .updateDocumentRequestStatus(request.id, { actorId, status: 'LINKED' })
      .then(() => this.loadAll().then(done))
      .catch(fail);
  };

  render() {
    const { loading, rules, requests, retention, ruleForm, saving } = this.state;
    const section = sectionFromPath(this.props.location.pathname);
    const kpiCards = [
      { id: 'rules', label: 'Rules', value: rules.length, tone: 'primary', icon: 'fe fe-shield' },
      { id: 'req', label: 'In review', value: requests.length, tone: 'amber', icon: 'fe fe-eye' },
      { id: 'ret', label: 'Retention', value: retention.length, tone: 'blue', icon: 'fe fe-archive' },
    ];

    return this.renderChrome({
      testId: 'page-leave-document-workflow',
      kpiCards,
      pageMeta: {
        tone: 'emerald',
        icon: 'fe fe-file-text',
        eyebrow: 'Admin · Leave',
        titleLead: 'Document',
        titleAccent: 'Workflow',
        lede: 'Proof rules that gate leave submit, review queue, and retention — minimal rule form; vault links only.',
      },
      heroNav: renderLeavePhase2Nav(NAV, this.props.location.pathname),
      children: (
        <>
          {section === 'rules' && (
            <>
              <LeavePhase2Panel
                title="Add document rule"
                subtitle="Required rules block leave submit until proof is linked."
                testId="glp22-add-rule"
              >
                <form className="lux-glp-form" onSubmit={this.saveRule} data-testid="glp22-add-rule-form">
                  <label>
                    Leave type code
                    <input
                      required
                      value={ruleForm.leaveTypeCode}
                      onChange={(e) =>
                        this.setState({ ruleForm: { ...ruleForm, leaveTypeCode: e.target.value } })
                      }
                      placeholder="SL"
                    />
                  </label>
                  <label>
                    Document type
                    <input
                      required
                      value={ruleForm.documentType}
                      onChange={(e) =>
                        this.setState({ ruleForm: { ...ruleForm, documentType: e.target.value } })
                      }
                      placeholder="MEDICAL_CERTIFICATE"
                    />
                  </label>
                  <label className="lux-glp-form__check">
                    <span>Required for submit</span>
                    <input
                      type="checkbox"
                      checked={ruleForm.required !== false}
                      onChange={(e) =>
                        this.setState({ ruleForm: { ...ruleForm, required: e.target.checked } })
                      }
                    />
                  </label>
                  <div className="lux-glp-form__actions">
                    <AdminActionButton type="submit" icon="fe fe-plus" disabled={saving || loading}>
                      Save rule
                    </AdminActionButton>
                  </div>
                </form>
              </LeavePhase2Panel>
              <LeavePhase2Panel title="Document type rules" subtitle="Proof and certificate requirements per leave type.">
                <LeavePhase2Register
                  loading={loading}
                  rows={rules}
                  testId="glp22-rules-register"
                  emptyTitle="No document rules"
                  emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
                  columns={[
                    { key: 'id', label: 'ID' },
                    { key: 'documentType', label: 'Type' },
                    { key: 'leaveTypeCode', label: 'Leave type' },
                    { key: 'required', label: 'Required' },
                    { key: 'expiryDays', label: 'Expiry days' },
                  ]}
                />
              </LeavePhase2Panel>
            </>
          )}
          {section === 'review' && (
            <LeavePhase2Panel title="Document review queue" subtitle="Mark proof linked (vault id) so leave submit can proceed.">
              <LeavePhase2Register
                loading={loading}
                rows={requests}
                testId="glp22-review-register"
                emptyTitle="No documents in review"
                emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
                columns={[
                  { key: 'id', label: 'Request' },
                  { key: 'employeeId', label: 'Employee' },
                  { key: 'documentType', label: 'Type' },
                  { key: 'status', label: 'Status' },
                  { key: 'sourceId', label: 'Leave', render: (r) => cell(r.sourceId) },
                  {
                    key: 'actions',
                    label: '',
                    render: (r) =>
                      r.id ? (
                        <AdminActionButton
                          icon="fe fe-link"
                          disabled={saving || loading}
                          onClick={() => this.markLinked(r)}
                          testId={`glp22-mark-linked-${r.id}`}
                        >
                          Mark linked
                        </AdminActionButton>
                      ) : null,
                  },
                ]}
              />
            </LeavePhase2Panel>
          )}
          {section === 'retention' && (
            <LeavePhase2Panel title="Retention & legal hold" subtitle="Retention policies for leave-related documents.">
              <LeavePhase2Register
                loading={loading}
                rows={retention}
                testId="glp22-retention-register"
                emptyTitle="No retention policies"
                emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
                columns={[
                  { key: 'id', label: 'ID' },
                  { key: 'documentType', label: 'Type' },
                  { key: 'retentionDays', label: 'Retention days' },
                  { key: 'legalHold', label: 'Legal hold' },
                ]}
              />
            </LeavePhase2Panel>
          )}
        </>
      ),
    });
  }
}

export default connect(mapLeavePhase2State)(withRouter(LeaveDocumentWorkflowPage));
