import { normalizeFavorite, normalizeSavedView } from "config/workspace-personalization.config";

export function buildPersonalizationMetrics(favorites, savedViews) {
  const favs = (favorites || []).map(normalizeFavorite).filter(Boolean);
  const views = (savedViews || []).map(normalizeSavedView).filter(Boolean);
  const surfaces = new Set(views.map((row) => row.surface));

  return {
    favorites: favs.length,
    savedViews: views.length,
    surfaces: surfaces.size,
    defaultViews: views.filter((row) => row.isDefault).length,
  };
}

export function buildPersonalizationInsights(favorites, savedViews) {
  const metrics = buildPersonalizationMetrics(favorites, savedViews);
  const insights = [];

  if (metrics.savedViews > 0) {
    insights.push({
      id: "saved-views",
      tone: "blue",
      icon: "fe fe-bookmark",
      title: `${metrics.savedViews} saved view(s)`,
      copy: `Across ${metrics.surfaces} workspace surface(s) — apply filters in one click.`,
      path: "/workspace/home",
    });
  }
  if (metrics.favorites > 0) {
    insights.push({
      id: "favorites",
      tone: "amber",
      icon: "fe fe-star",
      title: `${metrics.favorites} favorite shortcut(s)`,
      copy: "Pinned routes for your daily operating rhythm.",
      path: "/workspace/home",
    });
  }
  if (metrics.favorites === 0 && metrics.savedViews === 0) {
    insights.push({
      id: "get-started",
      tone: "green",
      icon: "fe fe-zap",
      title: "Personalize your workspace",
      copy: "Star frequent routes and save filter presets from approvals, my work, or notifications.",
      path: "/workspace/home",
    });
  }

  return insights.slice(0, 2);
}

export function filterSavedViewsBySurface(savedViews, surface) {
  return (savedViews || [])
    .map(normalizeSavedView)
    .filter((row) => row && (!surface || row.surface === surface));
}

export function isFavoritePath(favorites, path) {
  return (favorites || []).some((row) => row.path === path);
}

export function summarizeSavedViewFilters(filters) {
  const parts = [];
  const f = filters || {};
  if (f.status && f.status !== "ALL") {
    parts.push(f.status);
  }
  if (f.domain && f.domain !== "ALL") {
    parts.push(f.domain);
  }
  if (f.priority && f.priority !== "ALL") {
    parts.push(f.priority);
  }
  if (f.category && f.category !== "ALL") {
    parts.push(f.category);
  }
  if (f.type && f.type !== "ALL") {
    parts.push(f.type);
  }
  if (f.query) {
    parts.push(`"${f.query}"`);
  }
  return parts.length > 0 ? parts.join(" · ") : "All items";
}
