import React, { Component } from "react";
import { connect } from "react-redux";
import classNames from "classnames/bind";
import moment from "moment";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import CreateHolidayModel from "views/project/components/modal/CreateHolidayModel";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import { employeeActions } from "_actions";
import { employeeConstants } from "_constants";
import { accessUtils, commonUtils } from "_helpers";
import { store } from "_helpers";
import dateUtils from "_helpers/date.utils";
import { employeeService } from "_services/employee.service";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import PageInnerHeader from "views/common/PageInnerHeader";
import PageCreateButton from "views/common/fragments/PageCreateButton";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import { HolidayActionButton } from "views/people/components/holidays/HolidayLuxShared";
import { HOLIDAYS_PAGE_META } from "config/people-module-nav.config";
import LuxRegisterListSection from "views/common/lux/LuxRegisterListSection";
import { buildShownPulse } from "views/common/lux/registerAtelier.utils";
import {
  ALL_LOCATIONS,
  HOLIDAY_GROUP_BY,
  HOLIDAY_VIEW_MODE,
  NO_LOCATION_KEY,
  collectHolidayLocationKeys,
  filterHolidays,
  getHolidayDateMeta,
  getHolidayLocations,
  groupHolidays,
  parseHolidayImportText,
  summarizeHolidays,
} from "views/people/components/holidays/holiday.utils";
import HolidayMonthCalendar from "views/people/components/holidays/HolidayMonthCalendar";
import "./HolidaysPage.css";

const STATUS_OPTIONS = [
  { name: "ALL", label: "All" },
  { name: "UPCOMING", label: "Upcoming" },
  { name: "THIS_MONTH", label: "This month" },
  { name: "PAST", label: "Past" },
];

const GROUP_OPTIONS = [
  { name: HOLIDAY_GROUP_BY.MONTH, label: "By month" },
  { name: HOLIDAY_GROUP_BY.LOCATION, label: "By location" },
  { name: HOLIDAY_GROUP_BY.YEAR, label: "By year" },
];

const buildDefaultFilterOptions = () => ({
  SHOW: { options: STATUS_OPTIONS, selected: "ALL" },
  LOCATION: { options: [{ name: ALL_LOCATIONS, label: "All locations" }], selected: ALL_LOCATIONS },
  GROUP: { options: GROUP_OPTIONS, selected: HOLIDAY_GROUP_BY.MONTH },
  filterText: "",
});

class HolidayItemRow extends Component {
  state = { confirmDelete: false };

  handleRemove = () => {
    if (this.state.confirmDelete) {
      this.props.onRemove(this.props.item.id);
      this.setState({ confirmDelete: false });
      return;
    }
    this.setState({ confirmDelete: true });
  };

  render() {
    const { item, canRemove, canEdit, onEdit, dense } = this.props;
    const holidayMoment = dateUtils.convertDateToMoment(item.holidayDate);
    const dateMeta = getHolidayDateMeta(item.holidayDate);
    const locations = getHolidayLocations(item);

    return (
      <li className={classNames("lux-activity-holidays__item", { "is-dense": dense })}>
        <div className={classNames("lux-activity-holidays__date", `is-${dateMeta.tone}`)}>
          <span className="lux-activity-holidays__date-day">{holidayMoment.format("DD")}</span>
          <span className="lux-activity-holidays__date-month">{holidayMoment.format("MMM")}</span>
          <span className="lux-activity-holidays__date-week">{holidayMoment.format("ddd")}</span>
        </div>

        <div className="lux-activity-holidays__copy">
          <div className="lux-activity-holidays__item-top">
            <span className="lux-activity-holidays__name">{item.name}</span>
            <span className={classNames("lux-activity-holidays__badge", `is-${dateMeta.tone}`)}>
              {dateMeta.badge}
            </span>
          </div>
          {item.description && item.description !== item.name && (
            <p className="lux-activity-holidays__desc">{item.description}</p>
          )}
          <div className="lux-activity-holidays__meta">
            <span className="lux-activity-holidays__chip is-muted">{dateMeta.relative}</span>
            <span className="lux-activity-holidays__chip is-muted">{holidayMoment.format("D MMM YYYY")}</span>
            {locations.length === 0 ? (
              <span className="lux-activity-holidays__chip is-muted" title="Applies to all locations">
                <i className="fa fa-globe" aria-hidden="true" />
                All locations
              </span>
            ) : (
              locations.map((loc) => (
                <span key={loc} className="lux-activity-holidays__chip is-key" title="Location / calendar key">
                  <i className="fa fa-map-marker" aria-hidden="true" />
                  {loc}
                </span>
              ))
            )}
          </div>
        </div>

        {(canEdit || canRemove) && (
          <div className="lux-activity-holidays__actions">
            {canEdit && (
              <button
                type="button"
                className="lux-project-row__action"
                title="Edit holiday"
                aria-label="Edit holiday"
                onClick={() => onEdit && onEdit(item)}
              >
                <i className="fe fe-edit-2" aria-hidden="true" />
              </button>
            )}
            {canRemove && (
              <button
                type="button"
                className="lux-project-row__action is-danger"
                title={this.state.confirmDelete ? "Confirm remove" : "Remove holiday"}
                aria-label={this.state.confirmDelete ? "Confirm remove holiday" : "Remove holiday"}
                onClick={this.handleRemove}
              >
                {this.state.confirmDelete ? (
                  <i className="fe fe-check blink_text" aria-hidden="true" />
                ) : (
                  <i className="fe fe-trash-2" aria-hidden="true" />
                )}
              </button>
            )}
          </div>
        )}
      </li>
    );
  }
}

class HolidayGroupSection extends Component {
  render() {
    const { group, collapsed, onToggle, canRemove, canEdit, onRemove, onEdit } = this.props;
    const count = group.items.length;

    return (
      <section
        className={classNames("lux-holiday-group", { "is-collapsed": collapsed })}
        data-testid={`holiday-group-${group.id}`}
      >
        <button
          type="button"
          className="lux-holiday-group__head"
          onClick={() => onToggle(group.id)}
          aria-expanded={!collapsed}
        >
          <span className="lux-holiday-group__chevron" aria-hidden="true">
            <i className={collapsed ? "fe fe-chevron-right" : "fe fe-chevron-down"} />
          </span>
          <span className="lux-holiday-group__title">{group.label}</span>
          <span className="lux-holiday-group__count">
            {count} holiday{count === 1 ? "" : "s"}
          </span>
        </button>
        {!collapsed && (
          <ul className="lux-activity-holidays__list lux-activity-holidays__list--grouped">
            {group.items.map((item) => (
              <HolidayItemRow
                key={`${group.id}-${item.id}`}
                item={item}
                dense
                canRemove={canRemove}
                canEdit={canEdit}
                onRemove={onRemove}
                onEdit={onEdit}
              />
            ))}
          </ul>
        )}
      </section>
    );
  }
}

class HolidaysPage extends Component {
  state = {
    importText: "",
    importing: false,
    importError: null,
    importResult: null,
    importOpen: false,
    year: moment().year(),
    editMode: false,
    selectedHoliday: null,
    filterOptions: buildDefaultFilterOptions(),
    collapsedGroups: {},
    viewMode: HOLIDAY_VIEW_MODE.CALENDAR,
    calendarAnchor: moment().startOf("month"),
    selectedDayKey: moment().format("YYYY-MM-DD"),
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Holidays");
    this.loadHolidays();
  }

  getFilterSnapshot = (filterOptions = this.state.filterOptions) => ({
    statusFilter: (filterOptions.SHOW && filterOptions.SHOW.selected) || "ALL",
    locationKey: (filterOptions.LOCATION && filterOptions.LOCATION.selected) || ALL_LOCATIONS,
    groupBy: (filterOptions.GROUP && filterOptions.GROUP.selected) || HOLIDAY_GROUP_BY.MONTH,
    query: filterOptions.filterText || "",
  });

  getLiveFilterOptions = () => {
    const locationKeys = collectHolidayLocationKeys(this.props.items);
    const locationOptions = [
      { name: ALL_LOCATIONS, label: "All locations" },
      ...locationKeys.map((key) => ({
        name: key,
        label: key === NO_LOCATION_KEY ? "No key (all locations)" : key,
      })),
    ];
    const selected = this.state.filterOptions.LOCATION.selected;
    const stillValid = locationOptions.some((option) => option.name === selected);
    return {
      ...this.state.filterOptions,
      LOCATION: {
        ...this.state.filterOptions.LOCATION,
        options: locationOptions,
        selected: stillValid ? selected : ALL_LOCATIONS,
      },
    };
  };

  loadHolidays = () => {
    const { year, viewMode, calendarAnchor, filterOptions } = this.state;
    const { groupBy } = this.getFilterSnapshot(filterOptions);
    const span = groupBy === HOLIDAY_GROUP_BY.YEAR && viewMode === HOLIDAY_VIEW_MODE.LIST ? 2 : 0;
    const focusYear =
      viewMode === HOLIDAY_VIEW_MODE.CALENDAR ? moment(calendarAnchor).year() : year;
    const startDate = moment()
      .year(focusYear - span)
      .startOf("year")
      .format(dateUtils.SERVER_DATE_FORMAT);
    const endDate = moment()
      .year(focusYear + span)
      .endOf("year")
      .format(dateUtils.SERVER_DATE_FORMAT);
    this.props.getHolidays({ startDate, endDate });
  };

  onYearChange = (delta) => {
    this.setState(
      (prev) => {
        const year = prev.year + delta;
        const calendarAnchor = moment(prev.calendarAnchor).year(year).startOf("month");
        return { year, calendarAnchor, collapsedGroups: {} };
      },
      () => this.loadHolidays()
    );
  };

  onViewModeChange = (viewMode) => {
    this.setState(
      (prev) => {
        const snapshot = this.getFilterSnapshot(prev.filterOptions);
        const nextFilters = { ...prev.filterOptions };
        if (
          viewMode === HOLIDAY_VIEW_MODE.CALENDAR &&
          snapshot.statusFilter === "UPCOMING"
        ) {
          nextFilters.SHOW = { ...nextFilters.SHOW, selected: "ALL" };
        }
        return {
          viewMode,
          filterOptions: nextFilters,
          collapsedGroups: {},
        };
      },
      () => this.loadHolidays()
    );
  };

  onGridClick = (event) => {
    event.preventDefault();
    this.onViewModeChange(HOLIDAY_VIEW_MODE.CALENDAR);
  };

  onListClick = (event) => {
    event.preventDefault();
    this.onViewModeChange(HOLIDAY_VIEW_MODE.LIST);
  };

  onFilterChange = (filterOptions) => {
    const prevGroup = this.getFilterSnapshot(this.state.filterOptions).groupBy;
    const nextGroup = this.getFilterSnapshot(filterOptions).groupBy;
    const needsReload =
      nextGroup !== prevGroup &&
      (nextGroup === HOLIDAY_GROUP_BY.YEAR || prevGroup === HOLIDAY_GROUP_BY.YEAR);
    this.setState({ filterOptions, collapsedGroups: {} }, () => {
      if (needsReload) {
        this.loadHolidays();
      }
    });
  };

  onFilterTextChange = (value) => {
    this.setState((prev) => ({
      filterOptions: {
        ...prev.filterOptions,
        filterText: value,
      },
      collapsedGroups: {},
    }));
  };

  onCalendarPrev = () => {
    const next = moment(this.state.calendarAnchor).subtract(1, "month");
    this.setState(
      { calendarAnchor: next, year: next.year(), selectedDayKey: next.format("YYYY-MM-01") },
      () => this.loadHolidays()
    );
  };

  onCalendarNext = () => {
    const next = moment(this.state.calendarAnchor).add(1, "month");
    this.setState(
      { calendarAnchor: next, year: next.year(), selectedDayKey: next.format("YYYY-MM-01") },
      () => this.loadHolidays()
    );
  };

  onCalendarToday = () => {
    const today = moment().startOf("month");
    this.setState(
      (prev) => ({
        calendarAnchor: today,
        year: today.year(),
        selectedDayKey: moment().format("YYYY-MM-DD"),
        filterOptions: {
          ...prev.filterOptions,
          SHOW: { ...prev.filterOptions.SHOW, selected: "ALL" },
        },
      }),
      () => this.loadHolidays()
    );
  };

  onSelectDay = (day) => {
    this.setState({ selectedDayKey: day.key });
  };

  onToggleGroup = (groupId) => {
    this.setState((prev) => ({
      collapsedGroups: {
        ...prev.collapsedGroups,
        [groupId]: !prev.collapsedGroups[groupId],
      },
    }));
  };

  expandAllGroups = () => this.setState({ collapsedGroups: {} });

  collapseAllGroups = (groupIds) => {
    const collapsedGroups = {};
    (groupIds || []).forEach((id) => {
      collapsedGroups[id] = true;
    });
    this.setState({ collapsedGroups });
  };

  onCreateClick = () => {
    this.setState({ editMode: false, selectedHoliday: null });
    store.dispatch(employeeActions.getModuleConfig(commonUtils.getCurrentUserTeamId()));
    store.dispatch({ type: employeeConstants.SHOW_HOLIDAY_CREATE_WINDOW });
  };

  onEditClick = (holiday) => {
    this.setState({ editMode: true, selectedHoliday: holiday || null });
    store.dispatch(employeeActions.getModuleConfig(commonUtils.getCurrentUserTeamId()));
    store.dispatch({ type: employeeConstants.SHOW_HOLIDAY_CREATE_WINDOW });
  };

  onCloseCreate = () => {
    this.setState({ editMode: false, selectedHoliday: null });
    store.dispatch({ type: employeeConstants.CLOSE_HOLIDAY_CREATE_WINDOW });
  };

  handleSubmit = (holidayRequest, isEditMode, isCreateAnotherEnabled, callbackFunction) => {
    if (isEditMode) {
      store.dispatch(this.props.updateHoliday(holidayRequest, callbackFunction));
    } else {
      store.dispatch(this.props.createHoliday(holidayRequest, isCreateAnotherEnabled, callbackFunction));
    }
  };

  onImportTextChange = (event) => {
    this.setState({ importText: event.target.value, importError: null, importResult: null });
  };

  onImportFile = (event) => {
    const file = event.target.files && event.target.files[0];
    if (!file) {
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      this.setState({ importText: String(reader.result || ""), importError: null, importResult: null, importOpen: true });
    };
    reader.readAsText(file);
    event.target.value = "";
  };

  handleImport = async () => {
    try {
      const holidays = parseHolidayImportText(this.state.importText);
      if (holidays.length === 0) {
        this.setState({ importError: "Add at least one holiday row." });
        return;
      }
      this.setState({ importing: true, importError: null, importResult: null });
      const response = await employeeService.importHolidayItems({ holidays });
      const payload = (response && response.payload) || response;
      this.setState({ importing: false, importResult: payload, importText: "" });
      this.loadHolidays();
    } catch (error) {
      this.setState({
        importing: false,
        importError: error.message || "Unable to import holidays.",
      });
    }
  };

  getPermission = () => accessUtils.getHolidayAccessControl();

  getFilteredItems = () => {
    const { viewMode, calendarAnchor, filterOptions, year } = this.state;
    const { statusFilter, locationKey, groupBy, query } = this.getFilterSnapshot(filterOptions);
    const effectiveStatus =
      viewMode === HOLIDAY_VIEW_MODE.CALENDAR && statusFilter === "THIS_MONTH"
        ? "ALL"
        : statusFilter;
    return filterHolidays(this.props.items, {
      statusFilter: effectiveStatus,
      year:
        viewMode === HOLIDAY_VIEW_MODE.CALENDAR
          ? moment(calendarAnchor).year()
          : groupBy === HOLIDAY_GROUP_BY.YEAR
            ? undefined
            : year,
      query,
      locationKey,
    });
  };

  getGroupedItems = () => {
    const { groupBy } = this.getFilterSnapshot();
    return groupHolidays(this.getFilteredItems(), groupBy);
  };

  renderImportPanel = () => {
    if (!this.state.importOpen) {
      return null;
    }

    const { importResult, importError, importText, importing } = this.state;

    return (
      <section className="lux-holiday-import" data-testid="holiday-bulk-import-panel">
        <header className="lux-hrms-dash__panel-head">
          <div>
            <h2 className="lux-hrms-dash__panel-title">Bulk import</h2>
            <p className="lux-hrms-dash__panel-sub">
              Paste CSV rows or upload a file — each line: name, date (YYYY-MM-DD), optional description.
            </p>
          </div>
          <HolidayActionButton variant="ghost" icon="fe fe-x" onClick={() => this.setState({ importOpen: false })}>
            Close
          </HolidayActionButton>
        </header>
        <div className="lux-holiday-import__body">
          {importError && (
            <div className="lux-employee-360__error mb-2" role="alert">
              {importError}
            </div>
          )}
          {importResult && (
            <LuxInlineAlert
              tone="success"
              title="Import complete"
              message={`Imported ${importResult.created || 0} holiday(s)${
                (importResult.failed || 0) > 0 ? ` — ${importResult.failed} failed` : ""
              }.`}
              className="mb-2"
              testId="holiday-import-result"
            />
          )}
          <textarea
            className="lux-holiday-import__textarea"
            rows={5}
            placeholder={"New Year,2026-01-01,New Year Day\nRepublic Day,2026-01-26\nIndependence Day,2026-08-15"}
            value={importText}
            onChange={this.onImportTextChange}
            data-testid="holiday-import-textarea"
          />
          <p className="lux-holiday-import__hint">
            Holidays sync to leave duration, timesheet non-working days, and attendance calendars after save.
          </p>
          <div className="lux-holiday-import__toolbar">
            <label className="lux-onb-action lux-onb-action--secondary lux-holiday-action mb-0">
              <i className="fe fe-upload" aria-hidden="true" />
              <span>Upload CSV</span>
              <input type="file" accept=".csv,text/csv" className="d-none" onChange={this.onImportFile} />
            </label>
            <HolidayActionButton
              icon="fe fe-download-cloud"
              onClick={this.handleImport}
              disabled={importing || !importText.trim()}
              testId="holiday-import-submit"
            >
              {importing ? "Importing…" : "Import holidays"}
            </HolidayActionButton>
          </div>
        </div>
      </section>
    );
  };

  renderHolidayList = () => {
    const { holidayLoading } = this.props;
    const permission = this.getPermission();
    const filtered = this.getFilteredItems();
    const groups = this.getGroupedItems();
    const { collapsedGroups, viewMode, calendarAnchor, selectedDayKey } = this.state;

    if (holidayLoading) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          icon="fe fe-calendar"
          title="Loading holiday calendar"
          description="Fetching organization holidays for the selected period."
        />
      );
    }

    if (viewMode === HOLIDAY_VIEW_MODE.CALENDAR) {
      return (
        <HolidayMonthCalendar
          anchor={calendarAnchor}
          holidays={this.getFilteredItems()}
          selectedDayKey={selectedDayKey}
          onSelectDay={this.onSelectDay}
          onPrevMonth={this.onCalendarPrev}
          onNextMonth={this.onCalendarNext}
          onToday={this.onCalendarToday}
          nextHoliday={summarizeHolidays(this.getFilteredItems()).nextHoliday}
          canRemove={permission.removeEnabled === true}
          canEdit={permission.editEnabled === true}
          onRemove={(id) => store.dispatch(this.props.removeHoliday(id))}
          onEdit={this.onEditClick}
        />
      );
    }

    if (filtered.length === 0) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          icon="fe fe-calendar"
          title="No holidays match your filters"
          description="Try another year, location key, or status — or add holidays to populate the calendar."
          hints={[
            "Use Add holiday for one-off dates",
            "Import a full year from HR spreadsheets",
            "Filter by location key (e.g. IN, IN-KA) to focus one calendar",
          ]}
        />
      );
    }

    return (
      <div className="lux-holiday-groups" data-testid="holiday-grouped-list">
        <div className="lux-holiday-groups__meta">
          <span>
            Showing <strong>{filtered.length}</strong> holiday{filtered.length === 1 ? "" : "s"} in{" "}
            <strong>{groups.length}</strong> group{groups.length === 1 ? "" : "s"}
          </span>
          <div className="lux-holiday-groups__meta-actions">
            <button type="button" className="lux-holiday-link-btn" onClick={this.expandAllGroups}>
              Expand all
            </button>
            <button
              type="button"
              className="lux-holiday-link-btn"
              onClick={() => this.collapseAllGroups(groups.map((g) => g.id))}
            >
              Collapse all
            </button>
          </div>
        </div>
        {groups.map((group) => (
          <HolidayGroupSection
            key={group.id}
            group={group}
            collapsed={collapsedGroups[group.id] === true}
            onToggle={this.onToggleGroup}
            canRemove={permission.removeEnabled === true}
            canEdit={permission.editEnabled === true}
            onRemove={(id) => store.dispatch(this.props.removeHoliday(id))}
            onEdit={this.onEditClick}
          />
        ))}
      </div>
    );
  };

  render() {
    const permission = accessUtils.getAccessControll("hrmsModules") || {};
    if (permission.holidaysEnabled === false) {
      return (
        <PersonaAccessDenied
          moduleName="Holidays"
          reason="Holiday calendar is not enabled for your organization."
        />
      );
    }

    const holidayPermission = this.getPermission();
    const { viewMode, year } = this.state;
    const { holidayLoading } = this.props;
    const filterOptions = this.getLiveFilterOptions();
    const isCalendar = viewMode === HOLIDAY_VIEW_MODE.CALENDAR;
    const registerPulse = buildShownPulse(this.getFilteredItems().length, "Holidays");

    return (
      <div
        className="lux-holiday-page lux-people-page lux-register-page"
        data-testid="page-people-holidays"
      >
        <PageDataSourceReporter dataSource="api" />
        <LuxModuleIntro
          meta={HOLIDAYS_PAGE_META}
          actions={
            <>
              {holidayPermission.createEnabled !== false ? (
                <PageCreateButton testId="holiday-add-button" onClick={this.onCreateClick}>
                  Add holiday
                </PageCreateButton>
              ) : null}
              <HolidayActionButton
                variant="secondary"
                icon="fe fe-upload"
                testId="holiday-bulk-import-toggle"
                onClick={() => this.setState({ importOpen: !this.state.importOpen })}
              >
                {this.state.importOpen ? "Hide import" : "Bulk import"}
              </HolidayActionButton>
            </>
          }
          onRefresh={this.loadHolidays}
          refreshLoading={holidayLoading}
        />

        <PageInnerHeader
          showFilter={true}
          listFilterPlaceholder="Name or location key…"
          showGridListMenu={true}
          showGridDefault={isCalendar}
          gridClickHandler={this.onGridClick}
          listClickHandler={this.onListClick}
          isLoading={holidayLoading}
          filterOptions={filterOptions}
          handleFilterChange={this.onFilterChange}
          onFilterTextChange={this.onFilterTextChange}
          hiddenFilterKeys={isCalendar ? ["GROUP"] : []}
          enableCalendarControl={isCalendar}
          calendarControls={{
            goToBack: this.onCalendarPrev,
            goToCurrent: this.onCalendarToday,
            goToNext: this.onCalendarNext,
          }}
          additionalButtons={
            !isCalendar ? (
              <div className="lux-holiday-year-nav lux-holiday-year-nav--header" aria-label="Calendar year">
                <button
                  type="button"
                  className="lux-holiday-year-nav__btn"
                  onClick={() => this.onYearChange(-1)}
                  aria-label="Previous year"
                >
                  <i className="fe fe-chevron-left" aria-hidden="true" />
                </button>
                <span className="lux-holiday-year-nav__label">{year}</span>
                <button
                  type="button"
                  className="lux-holiday-year-nav__btn"
                  onClick={() => this.onYearChange(1)}
                  aria-label="Next year"
                >
                  <i className="fe fe-chevron-right" aria-hidden="true" />
                </button>
              </div>
            ) : null
          }
        />

        {this.renderImportPanel()}

        <LuxRegisterListSection
          tone="teal"
          kickerIcon="fe fe-calendar"
          kicker="Holiday register"
          title={HOLIDAYS_PAGE_META.title || "Holidays"}
          subtitle={`Organization calendar for ${year}`}
          pulseCards={registerPulse}
          className="lux-holiday-list-section"
        >
          <section className="lux-activity-holidays lux-activity-holidays--page" aria-label="Organization holidays">
            {this.renderHolidayList()}
          </section>
        </LuxRegisterListSection>

        {this.props.showCreateModel && (
          <CreateHolidayModel
            onCloseCreateItem={this.onCloseCreate}
            show={this.props.showCreateModel}
            editMode={this.state.editMode === true}
            selectedHolidayInfo={this.state.selectedHoliday}
            handleSubmit={this.handleSubmit}
          />
        )}
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  items: state.employees.holidayItems,
  holidayLoading: state.employees.holidayLoading,
  showCreateModel: state.employees.showHolidayCreateModel,
});

const mapDispatchToProps = {
  getHolidays: employeeActions.getHolidays,
  createHoliday: employeeActions.createHolidayItem,
  updateHoliday: employeeActions.updateHolidayItem,
  removeHoliday: employeeActions.removeHolidayItem,
};

export default connect(mapStateToProps, mapDispatchToProps)(HolidaysPage);
