import React, { Component } from "react";
import { connect } from "react-redux";
import classNames from "classnames/bind";
import { purchaseOrderActions } from "_actions";
import { projectActions } from "_actions";
import { store } from "_helpers";
import { commonUtils } from "_helpers";
import { validationUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import LuxCreateModeSwitch from "views/common/create/LuxCreateModeSwitch";
import LuxCreateWizardNav from "views/common/create/LuxCreateWizardNav";
import LuxCreateFooter from "views/common/create/LuxCreateFooter";
import LuxCreateSectionCard from "views/common/create/LuxCreateSectionCard";
import {
  CREATE_ENTRY_MODES,
  getWizardStepMandatoryFieldNames,
  isValidRequestForFieldNames,
  resolveWizardStepStatuses,
} from "views/common/create/createPanel.utils";
import { CREATE_PROJECT_WIZARD_STEPS } from "./createProject.wizardSteps";
import { CREATE_PROJECT_SECTION_META, CREATE_PROJECT_SECTION_ORDER } from "./createProject.sections";
import {
  renderCreateProjectFormSection,
  PROJECT_FORM_LEFT_SECTIONS,
  PROJECT_FORM_RIGHT_SECTIONS,
} from "./createProjectFormSections";

class CreateProjectSidebarSection extends Component {
  constructor() {
    super();
    this.state = {
      formErrors: {},
      hasFormError: false,
      entryMode: CREATE_ENTRY_MODES.WIZARD,
      wizardStep: 0,
      visitedWizardSteps: new Set([0]),
    };
  }

  componentDidMount() {
    this.initializeRequest();
  }

  onResetFormError = () => {
    this.setState({
      hasFormError: false,
    });
  };
  initializeRequest = () => {
    let userTeamId = commonUtils.getCurrentUserTeamId();
    let projectRequest = this.props.editMode
      ? this.props.selectedProjectInfo
      : this.props.duplicateMode
      ? {
          ...this.props.selectedProjectInfo,
          id: null,
          createdBy: commonUtils.getCurrentUserId(),
          modifiedBy: null,
        }
      : {
          userTeamId: userTeamId,
          automationEnabled: false,
          code: "PRJ" + Date.now(),
        };
    this.setState({
      projectRequest: projectRequest,
      purchaseOrderServiceLines:
        projectRequest.serviceLines && projectRequest.serviceLines.legnth > 0
          ? projectRequest.serviceLines
          : projectRequest.purchaseOrderDetails &&
            projectRequest.purchaseOrderDetails.serviceLines,
      purchaseOrderServiceLineEstimate:
        projectRequest.purchaseOrderDetails &&
        projectRequest.purchaseOrderDetails.serviceLineEstimate,
      purchaseOrderStartTime:
        projectRequest &&
        projectRequest.purchaseOrderDetails &&
        projectRequest.purchaseOrderDetails
          ? projectRequest.purchaseOrderDetails.estStartTime
          : null,
      purchaseOrderCompletionTime:
        projectRequest &&
        projectRequest.purchaseOrderDetails &&
        projectRequest.purchaseOrderDetails
          ? projectRequest.purchaseOrderDetails.estCompletionTime
          : null,
    });
  };

  onFormError = (fieldName, hasError) => {
    this.setState((prevState) => ({
      formErrors: {
        ...prevState.formErrors,
        [fieldName]: hasError,
      },
    }));
  };
  onPurchaseOrderChange = (fieldName, value) => {
    let newSelectedOptions =
      (this.props.purchaseOrders &&
        this.props.purchaseOrders.find(
          (purchaseOrder) => purchaseOrder.id === value
        )) ||
      {};
    let { id, userTeamId, name, ...newSelectedOptionsCopy } =
      newSelectedOptions;
    this.setState((prevState) => ({
      projectRequest: {
        ...prevState.projectRequest,
        ...newSelectedOptionsCopy,
        [fieldName]: value,
        createdBy: commonUtils.getCurrentUserId(),
        modifiedBy: commonUtils.getCurrentUserId(),
      },
      purchaseOrderServiceLines: newSelectedOptionsCopy.serviceLines,
      purchaseOrderServiceLineEstimate:
        newSelectedOptionsCopy.serviceLineEstimate,
      purchaseOrderStartTime: newSelectedOptionsCopy.estStartTime,
      purchaseOrderCompletionTime: newSelectedOptionsCopy.estCompletionTime,
    }));
  };

  purchaseOrderListCallBack = (purchaseOrders) => {
    let purchaseOrder =
      this.state.projectRequest &&
      purchaseOrders &&
      purchaseOrders.find(
        (purchaseOrder) =>
          purchaseOrder.id === this.state.projectRequest.purchaseOrderId
      );
    if (!purchaseOrder) {
      this.setState((prevState) => ({
        projectRequest: {
          ...prevState.projectRequest,
          purchaseOrderId: null,
          proposalNumber: null,
          purchaseOrderNumber: null,
        },
        purchaseOrderServiceLines: null,
        purchaseOrderServiceLineEstimate: null,
        purchaseOrderStartTime: null,
        purchaseOrderCompletionTime: null,
      }));
    } else {
    }
  };

  onChangeCommaSeparatedValues = (fieldName, value) => {
    var arrayValue = null;
    if (value && value !== "") {
        arrayValue = value.split(',');
    }
    this.onChange(fieldName, arrayValue);
  }

  onChange = (fieldName, value) => {
    this.onResetFormError();
    if (fieldName === "userTeamId") {
      store.dispatch(this.props.initializeCreateProject(value));
      store.dispatch(
        purchaseOrderActions.getActivePurchaseOrderList(
          { userTeamIds: value },
          this.purchaseOrderListCallBack
        )
      );
    }

    this.setState(
      (prevState) => ({
        projectRequest: {
          ...prevState.projectRequest,
          [fieldName]: value,
        },
      }),
      () => {
        if (fieldName === "estStartTime" || fieldName === "estCompletionTime") {
          if (
            this.state.projectRequest.estStartTime &&
            this.state.projectRequest.estCompletionTime
          ) {
            let startDateMoment = dateUtils.convertDateStringToMoment(
              this.state.projectRequest.estStartTime
            );
            let endDateMoment = dateUtils.convertDateStringToMoment(
              this.state.projectRequest.estCompletionTime
            );
            if (
              dateUtils.compareTwoMoments(
                startDateMoment.startOf("day"),
                endDateMoment.endOf("day")
              ) === -1
            ) {
              this.setState((prevState) => ({
                projectRequest: {
                  ...prevState.projectRequest,
                  [fieldName === "estStartTime"
                    ? "estCompletionTime"
                    : fieldName]: undefined,
                },
              }));
            }
          }
        }

        if (fieldName === "isOrderChanged" && value === false) {
          this.setState((prevState) => ({
            projectRequest: {
              ...prevState.projectRequest,
              revisedAdditionalHrs: 0,
              revisedAdditionalCost: 0,
            },
          }));
        }
      }
    );
  };

  /*onNewItemSelected = (isNewItemSelected) => {
    this.setState(prevState => ({
      isNewItemSelected: isNewItemSelected
    }))
  }


  /*onCreateSelectChange = (fieldName, selectedOption) => {
    let newSelectedOptions = { ...selectedOption };
    delete newSelectedOptions.id;
    this.setState(prevState => ({
      projectRequest: {
        ...prevState.projectRequest,
        ...newSelectedOptions,
        [fieldName]: selectedOption.value
      }
    }))
  }*/

  getFieldConfig = () => {
    let fieldConfig =
      commonUtils.getAppConfigValue(
        this.props.createConfig,
        "isPurchaseOrderMandatory"
      ) === true
        ? this.props.fieldConfig.map((field) => {
            if (field.name === "purchaseOrderId") {
              field.mandatory = true;
            }
            return field;
          })
        : this.props.fieldConfig;
    return this.props.permission.enableProjectPurchaseOrderEditable === true &&
      this.props.editMode === true
      ? fieldConfig.map((field) => {
          if (field.name === "purchaseOrderId") {
            field.editable = true;
          }
          return field;
        })
      : fieldConfig;
  };

  handleSubmit = (isCreateAnotherEnabled) => {
    let isValid = validationUtils.isValidRequest(
      this.getFieldConfig(),
      this.state.projectRequest,
      this.state.formErrors
    );
    //console.log("Validating form  request, isValid - " + isValid);
    //console.log(this.state.projectRequest);
    //console.log(this.state.formErrors)
    if (isValid) {
      let defaultNotificationEmails = commonUtils.getAppConfigValue(
        this.props.createConfig,
        "defaultNotificationEmails"
      );
      const defaultNotificationEmailsForFinanceTeam =
        commonUtils.getAppConfigValue(
          this.props.createConfig,
          "defaultNotificationEmailsForFinanceTeam"
        );
      const defaultPIINotificationEmails = commonUtils.getAppConfigValue(
        this.props.createConfig,
        "defaultPIINotificationEmails"
      );
      if (
        this.state.projectRequest.hasPPI &&
        this.state.projectRequest.hasPPI === true
      ) {
        defaultNotificationEmails = [
          ...(defaultNotificationEmails || []),
          ...(defaultPIINotificationEmails || []),
        ];
      }
      let projectRequestToBeSaved = {
        ...this.state.projectRequest,
        watchers: [
          ...(this.state.projectRequest.watchers || []),
          ...(defaultNotificationEmails ? defaultNotificationEmails : []),
        ],
        financeTeamWatchers: [
          ...(defaultNotificationEmailsForFinanceTeam
            ? defaultNotificationEmailsForFinanceTeam
            : []),
        ],
      };
      if (
        projectRequestToBeSaved.serviceLines &&
        projectRequestToBeSaved.serviceLines.length &&
        !projectRequestToBeSaved.category
      ) {
        projectRequestToBeSaved.category = projectRequestToBeSaved.serviceLines[0];
      }
      this.props.handleSubmit(
        projectRequestToBeSaved,
        this.props.editMode,
        isCreateAnotherEnabled,
        !this.props.editMode ? this.initializeRequest : null
      );
    } else {
      this.setState({
        hasFormError: true,
      });
    }
  };

  isWizardMode = () => this.state.entryMode === CREATE_ENTRY_MODES.WIZARD;

  getWizardStep = () => CREATE_PROJECT_WIZARD_STEPS[this.state.wizardStep];

  isSectionVisible = (sectionKey) => {
    if (!this.isWizardMode()) return true;
    const step = this.getWizardStep();
    return step && step.sections.includes(sectionKey);
  };

  markWizardStepVisited = (stepIndex) => {
    this.setState((prev) => {
      const visitedWizardSteps = new Set(prev.visitedWizardSteps);
      visitedWizardSteps.add(stepIndex);
      return { visitedWizardSteps };
    });
  };

  handleEntryModeChange = (entryMode) => {
    this.setState({
      entryMode,
      wizardStep: 0,
      visitedWizardSteps: new Set([0]),
      hasFormError: false,
    });
  };

  handleWizardStepSelect = (wizardStep) => {
    this.markWizardStepVisited(wizardStep);
    this.setState({ wizardStep, hasFormError: false });
  };

  validateWizardStep = (stepIndex) => {
    const step = CREATE_PROJECT_WIZARD_STEPS[stepIndex];
    if (!step) return true;
    const mandatoryNames = getWizardStepMandatoryFieldNames(this.getFieldConfig(), step.fieldNames);
    if (!mandatoryNames.length) return true;
    return isValidRequestForFieldNames(
      this.getFieldConfig(),
      this.state.projectRequest,
      this.state.formErrors,
      mandatoryNames
    );
  };

  handleWizardNext = () => {
    if (!this.validateWizardStep(this.state.wizardStep)) {
      this.setState({ hasFormError: true });
      return;
    }
    const nextStep = Math.min(this.state.wizardStep + 1, CREATE_PROJECT_WIZARD_STEPS.length - 1);
    this.markWizardStepVisited(this.state.wizardStep);
    this.markWizardStepVisited(nextStep);
    this.setState({ wizardStep: nextStep, hasFormError: false });
  };

  handleWizardBack = () => {
    const prevStep = Math.max(this.state.wizardStep - 1, 0);
    this.markWizardStepVisited(prevStep);
    this.setState({ wizardStep: prevStep, hasFormError: false });
  };

  getWizardStepStatuses = () =>
    resolveWizardStepStatuses({
      steps: CREATE_PROJECT_WIZARD_STEPS,
      activeIndex: this.state.wizardStep,
      fieldConfig: this.getFieldConfig(),
      request: this.state.projectRequest,
      formErrors: this.state.formErrors,
      visitedSteps: this.state.visitedWizardSteps,
      hasFormError: this.state.hasFormError,
    });

  getFormContext = () => ({
    projectRequest: this.state.projectRequest,
    props: this.props,
    purchaseOrderServiceLines: this.state.purchaseOrderServiceLines,
    purchaseOrderServiceLineEstimate: this.state.purchaseOrderServiceLineEstimate,
    purchaseOrderStartTime: this.state.purchaseOrderStartTime,
    purchaseOrderCompletionTime: this.state.purchaseOrderCompletionTime,
    onChange: this.onChange,
    onChangeCommaSeparatedValues: this.onChangeCommaSeparatedValues,
    onFormError: this.onFormError,
    onPurchaseOrderChange: this.onPurchaseOrderChange,
    getFieldConfig: this.getFieldConfig,
  });

  renderSectionCard = (sectionKey, children) => {
    if (!this.isSectionVisible(sectionKey)) return null;
    const meta = CREATE_PROJECT_SECTION_META[sectionKey];
    return (
      <LuxCreateSectionCard icon={meta.icon} title={meta.title} hint={meta.hint} description={meta.description}>
        {children}
      </LuxCreateSectionCard>
    );
  };

  render() {
    const wizardMode = this.isWizardMode();
    const stepStatuses = wizardMode ? this.getWizardStepStatuses() : [];
    const isProcessing = this.props.creating || this.props.updating;

    return (
      <>
        {this.state.projectRequest && (
          <div className="lux-create-panel__workflow lux-create-panel__workflow--project">
            <div className="lux-create-panel__chrome">
              <LuxCreateModeSwitch mode={this.state.entryMode} onChange={this.handleEntryModeChange} disabled={isProcessing} />
            </div>

            <div
              className={classNames(
                "lux-create-panel__workspace",
                wizardMode
                  ? "lux-create-panel__workspace--wizard lux-create-panel__workspace--project-wizard"
                  : "lux-create-panel__workspace--project-full"
              )}
            >
              {wizardMode && (
                <LuxCreateWizardNav
                  stepStatuses={stepStatuses}
                  activeIndex={this.state.wizardStep}
                  onSelect={this.handleWizardStepSelect}
                  disabled={isProcessing}
                  layout="rail"
                />
              )}

              <div className="lux-create-panel__canvas">
                <div className="lux-create-panel__scroll">
                  <div
                    className={classNames("lux-project-form lux-po-form", {
                      "lux-po-form--wizard": wizardMode,
                      "lux-po-form--full": !wizardMode,
                    })}
                  >
                    {wizardMode ? (
                      <div className="lux-po-form__pane lux-project-form__pane">
                        {CREATE_PROJECT_SECTION_ORDER.map((sectionKey) =>
                          this.renderSectionCard(
                            sectionKey,
                            renderCreateProjectFormSection(sectionKey, {
                              ...this.getFormContext(),
                              isFullForm: false,
                            })
                          )
                        )}
                      </div>
                    ) : (
                      <div className="lux-project-form__layout lux-project-form__layout--split">
                        <div className="lux-project-form__pane">
                          {PROJECT_FORM_LEFT_SECTIONS.map((sectionKey) =>
                            this.renderSectionCard(
                              sectionKey,
                              renderCreateProjectFormSection(sectionKey, {
                                ...this.getFormContext(),
                                isFullForm: true,
                              })
                            )
                          )}
                        </div>
                        <div className="lux-project-form__pane">
                          {PROJECT_FORM_RIGHT_SECTIONS.map((sectionKey) =>
                            this.renderSectionCard(
                              sectionKey,
                              renderCreateProjectFormSection(sectionKey, {
                                ...this.getFormContext(),
                                isFullForm: true,
                              })
                            )
                          )}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>

            <LuxCreateFooter
              handleSubmit={this.handleSubmit}
              editMode={this.props.editMode}
              duplicateMode={this.props.duplicateMode}
              initializeRequest={this.initializeRequest}
              isProcessing={isProcessing}
              hasFormError={this.state.hasFormError}
              onResetFormError={this.onResetFormError}
              wizardMode={wizardMode}
              wizardStepIndex={this.state.wizardStep}
              wizardStepCount={CREATE_PROJECT_WIZARD_STEPS.length}
              onWizardBack={this.handleWizardBack}
              onWizardNext={this.handleWizardNext}
              canWizardNext={this.getWizardStep() ? this.validateWizardStep(this.state.wizardStep) : true}
              createButtonLabel={
                this.props.editMode
                  ? "Save project"
                  : this.props.duplicateMode
                  ? "Create duplicate"
                  : "Create project"
              }
            />
          </div>
        )}
      </>
    );
  }
}
const mapStateToProps = (state) => ({
  currentUser: state.authentication.user,
  fieldConfig: state.projects.fieldConfig,
  createConfig: state.projects.createConfig,
  allProjectTeamAccounts: state.accounts.allProjectTeamAccounts,
  employeeAppConfig: state.employees.createConfig,
  allUserTeams: state.appconfig.allTeams,
  allEmployees: state.employees.allEmployees,
  creating: state.projects.creating,
  updating: state.projects.updating,
  purchaseOrders: state.purchaseOrders.activeItems,
});

const mapDispatchToProps = (dispatch) => ({
  initializeCreateProject: projectActions.initializeCreateProject,
});

export default connect(
  mapStateToProps,
  mapDispatchToProps
)(CreateProjectSidebarSection);
