import envconfig from 'env.config';
import { commonUtils } from '_helpers';

/**
 * Shift policies admin — role.json `adminModules.shiftPoliciesEnabled`.
 * Missing role key defaults ON (matches backend / org Application Config).
 */
export function isShiftPoliciesEnvEnabled() {
  return false;
}

export function isShiftPoliciesEnabled(adminModules) {
  if (adminModules && typeof adminModules.shiftPoliciesEnabled === 'boolean') {
    return adminModules.shiftPoliciesEnabled;
  }
  // Match BE: missing flag defaults on.
  return true;
}

export function shouldUseShiftPoliciesApi() {
  return envconfig.USE_SHIFT_POLICIES_API === true;
}

export function getShiftPolicyActorContext() {
  return {
    userTeamId: commonUtils.getCurrentUserTeamId(),
    actorId: commonUtils.getCurrentUserId(),
  };
}
