import React, { Component } from "react";
import classNames from "classnames/bind";
import { store } from "_helpers";
import { commonUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import SelectInput from "views/common/fragments/formfields/SelectInput";
import { getRecipientInitials, getRecipientStatusMeta } from "./feedback.utils";

export default class LuxFeedbackRecipientRow extends Component {
  state = {
    confirmDelete: false,
    confirmRetrigger: false,
  };

  handleRemoveFeedbackRequest = (isConfirmDelete) => {
    if (isConfirmDelete) {
      store.dispatch(
        this.props.removeFeedbackRequest(this.props.feedbackId, this.props.item.id)
      );
      this.setState({ confirmDelete: false });
    } else {
      this.setState({ confirmDelete: true });
    }
  };

  handleRetriggerFeedbackRequest = (confirmRetrigger) => {
    if (confirmRetrigger) {
      store.dispatch(this.props.remindFeedbackRequest(this.props.item.id));
      this.setState({ confirmRetrigger: false });
    } else {
      this.setState({ confirmRetrigger: true });
    }
  };

  handleUpdateStatus = (itemId, status) => {
    if (status !== this.props.item.status) {
      store.dispatch(
        this.props.updateFeedbackRequestStatus(
          itemId,
          status,
          commonUtils.getCurrentUserId(),
          this.props.feedbackItem.expiryDate
        )
      );
    }
  };

  getChangeableStatus = (currentStatus) => {
    if (currentStatus === "DRAFT") return ["REQUESTED"];
    if (currentStatus === "RECEIVED") return ["REVIEWED"];
    if (currentStatus === "REVIEWED") return ["CLOSED"];
    return [];
  };

  render() {
    const statusMeta = getRecipientStatusMeta(this.props.item.status);
    const { item, permission, isFeedbackExpired, isRecurring } = this.props;
    const { confirmDelete, confirmRetrigger } = this.state;
    const statusReadOnly =
      isFeedbackExpired ||
      isRecurring === true ||
      permission.updateStatusEnabled === false;
    const initials = getRecipientInitials(item.personName, item.personEmail);

    return (
      <div
        className={classNames(
          "lux-feedback-recipient",
          `is-status-${statusMeta.tone}`,
          { "is-expired": isFeedbackExpired }
        )}
      >
        <div className="lux-feedback-recipient__accent" aria-hidden="true" />
        <div className="lux-feedback-recipient__main">
          <span
            className={classNames(
              "lux-feedback-recipient__avatar",
              `is-${statusMeta.tone}`
            )}
            aria-hidden="true"
          >
            {initials}
          </span>
          <div className="lux-feedback-recipient__copy">
            <div className="lux-feedback-recipient__title-row">
              <span className="lux-feedback-recipient__name" title={item.personName}>
                {item.personName || "Unnamed recipient"}
              </span>
              <span className={`lux-feedback-status-pill is-${statusMeta.tone}`}>
                <i className={`fe ${statusMeta.icon}`} aria-hidden="true" />
                {statusMeta.label}
              </span>
            </div>
            <span className="lux-feedback-recipient__email" title={item.personEmail}>
              {item.personEmail}
            </span>
          </div>
        </div>
        <div className="lux-feedback-recipient__actions">
          <span className="lux-feedback-recipient__date">
            {dateUtils.convertDateFormat(item.lastModifiedDate)}
          </span>
          {!statusReadOnly && (
            <span className="lux-feedback-recipient__select">
              <SelectInput
                options={[
                  { value: "DRAFT", label: "Draft", level: 0 },
                  { value: "REQUESTED", label: "Requested", level: 1 },
                  { value: "RECEIVED", label: "Received", level: 2 },
                  { value: "REVIEWED", label: "Reviewed", level: 3 },
                  { value: "CLOSED", label: "Closed", level: 4 },
                ]}
                value={item.status}
                allowLevelDown={false}
                changeableStatus={this.getChangeableStatus(item.status)}
                isReadOnly={false}
                itemId={item.id}
                onChange={this.handleUpdateStatus}
                className={classNames("badge", {
                  "badge-info": item.status === "DRAFT",
                  "badge-primary": item.status === "REQUESTED",
                  "badge-warning": item.status === "RECEIVED",
                  "badge-success": item.status === "REVIEWED",
                  "badge-dark": item.status === "CLOSED",
                })}
              />
            </span>
          )}
          {(item.status === "RECEIVED" ||
            item.status === "REVIEWED" ||
            item.status === "CLOSED") && (
            <a
              className="lux-feedback-card__icon-btn"
              target="_blank"
              rel="noopener noreferrer"
              href={`/document/feedback/request/${item.id}`}
              title="View response"
              aria-label="View response"
            >
              <i className="fe fe-eye" aria-hidden="true" />
            </a>
          )}
          {item.status === "REQUESTED" &&
            !isFeedbackExpired &&
            permission.resendEnabled === true && (
              <button
                type="button"
                onClick={() => this.handleRetriggerFeedbackRequest(confirmRetrigger)}
                className={classNames("lux-feedback-card__icon-btn", {
                  blink_text: confirmRetrigger,
                })}
                title={confirmRetrigger ? "Confirm reminder" : "Send reminder"}
                aria-label={confirmRetrigger ? "Confirm reminder" : "Send reminder"}
              >
                <i
                  className={classNames("fe", confirmRetrigger ? "fe-check" : "fe-send")}
                  aria-hidden="true"
                />
              </button>
            )}
          {permission.removeEnabled === true && (
            <button
              type="button"
              onClick={() => this.handleRemoveFeedbackRequest(confirmDelete)}
              className={classNames("lux-feedback-card__icon-btn", "is-delete", {
                blink_text: confirmDelete,
              })}
              title={confirmDelete ? "Confirm remove" : "Remove"}
              aria-label={confirmDelete ? "Confirm remove" : "Remove"}
            >
              <i
                className={classNames("fe", confirmDelete ? "fe-check" : "fe-trash-2")}
                aria-hidden="true"
              />
            </button>
          )}
        </div>
      </div>
    );
  }
}
