/**
 * F05-T4: Attendance exception types and default policy.
 */
export const ATTENDANCE_EXCEPTION_TYPES = [
  { code: "MISSING_PUNCH", label: "Missing punch", requiresEvidence: false },
  { code: "LATE_ARRIVAL", label: "Late arrival", requiresEvidence: false },
  { code: "EARLY_DEPARTURE", label: "Early departure", requiresEvidence: false },
  { code: "WRONG_SHIFT", label: "Wrong shift recorded", requiresEvidence: true },
  { code: "WORK_FROM_HOME", label: "Work from home", requiresEvidence: false },
  { code: "ON_DUTY_TRAVEL", label: "On-duty / travel", requiresEvidence: true },
  // CFA-LEAVE-W6 — distinct from WFH / on-duty
  { code: "OUTDOOR", label: "Outdoor", requiresEvidence: true },
];

export const DEFAULT_SWIPE_BANDS = {
  presentMinHours: 7.5,
  halfDayMinHours: 4.5,
};

export const DEFAULT_SEGMENT_UPDATE_WINDOWS = {
  DELIVERY: { allowBackdatedDays: 2, discipline: "NEAR_REAL_TIME" },
  SUPPORT: { allowBackdatedDays: 45, cycleHint: "16th-to-15th", discipline: "FLEXIBLE_BATCH" },
  OPS: { allowBackdatedDays: 45, cycleHint: "16th-to-15th", discipline: "FLEXIBLE_BATCH" },
};

export const DEFAULT_REGULARIZATION_POLICY = {
  maxRequestsPerMonth: 4,
  requireManagerApproval: true,
  allowBackdatedDays: 7,
  payrollLockDayOfMonth: 25,
  blockedExceptionCodes: [],
  defaultEmployeeSegment: "DELIVERY",
  segmentUpdateWindows: DEFAULT_SEGMENT_UPDATE_WINDOWS,
  swipeBands: DEFAULT_SWIPE_BANDS,
};

export function getExceptionTypeLabel(code) {
  const match = ATTENDANCE_EXCEPTION_TYPES.find((item) => item.code === code);
  return match ? match.label : code || "Exception";
}

export function isExceptionAllowed(policy, code) {
  const blocked = (policy && policy.blockedExceptionCodes) || [];
  return !blocked.includes(code);
}
