import React, { Component } from "react";
import classNames from "classnames/bind";
import {
  isWorkspaceFavoritesEnabled,
  getSavedViewSurfaceMeta,
} from "config/workspace-personalization.config";
import { summarizeSavedViewFilters } from "config/workspace-personalization.utils";
import { workspaceService } from "_services/workspace.service";

export default class WorkspaceSavedViewBar extends Component {
  state = {
    savedViews: [],
    loading: true,
    acting: false,
    showSaveForm: false,
    viewName: "",
    error: null,
  };

  componentDidMount() {
    this.loadSavedViews();
    this._listener = () => this.loadSavedViews();
    window.addEventListener("famstack-workspace-personalization-changed", this._listener);
  }

  componentWillUnmount() {
    window.removeEventListener("famstack-workspace-personalization-changed", this._listener);
  }

  componentDidUpdate(prevProps) {
    if (prevProps.surface !== this.props.surface) {
      this.loadSavedViews();
    }
  }

  loadSavedViews = async () => {
    const { surface } = this.props;
    if (!isWorkspaceFavoritesEnabled() || !surface) {
      this.setState({ loading: false, savedViews: [] });
      return;
    }
    this.setState({ loading: true });
    try {
      const result = await workspaceService.listSavedViews(surface);
      this.setState({ savedViews: result.payload || [], loading: false });
    } catch (e) {
      this.setState({ savedViews: [], loading: false });
    }
  };

  handleApply = (view) => {
    const { onApply } = this.props;
    if (onApply && view && view.filters) {
      onApply({ ...view.filters });
    }
  };

  handleSave = async () => {
    const { surface, currentFilters } = this.props;
    const name = String(this.state.viewName || "").trim();
    if (!name) {
      this.setState({ error: "Enter a name for this view." });
      return;
    }
    this.setState({ acting: true, error: null });
    try {
      await workspaceService.createSavedView({
        surface,
        name,
        filters: { ...(currentFilters || {}) },
      });
      this.setState({ acting: false, showSaveForm: false, viewName: "" });
      await this.loadSavedViews();
    } catch (e) {
      this.setState({ acting: false, error: "Unable to save this view." });
    }
  };

  handleDelete = async (viewId) => {
    this.setState({ acting: true });
    try {
      await workspaceService.deleteSavedView(viewId);
      await this.loadSavedViews();
    } finally {
      this.setState({ acting: false });
    }
  };

  render() {
    const { surface } = this.props;
    if (!isWorkspaceFavoritesEnabled() || !surface) {
      return null;
    }

    const { savedViews, loading, acting, showSaveForm, viewName, error } = this.state;
    const surfaceMeta = getSavedViewSurfaceMeta(surface);

    return (
      <div className="lux-workspace-saved-view-bar" aria-label={`${surfaceMeta.label} saved views`}>
        <div className="lux-workspace-saved-view-bar__head">
          <span className="lux-workspace-saved-view-bar__label">
            <i className="fe fe-bookmark" aria-hidden="true" />
            Saved views
          </span>
          <button
            type="button"
            className="lux-onb-action lux-onb-action--ghost lux-workspace-saved-view-bar__save-btn"
            onClick={() => this.setState({ showSaveForm: !showSaveForm, error: null })}
          >
            <i className="fe fe-save" aria-hidden="true" />
            Save current
          </button>
        </div>

        {showSaveForm && (
          <div className="lux-workspace-saved-view-bar__form">
            <input
              type="text"
              className="lux-appr-toolbar__search-input"
              placeholder={`Name this ${surfaceMeta.label.toLowerCase()} view`}
              value={viewName}
              onChange={(e) => this.setState({ viewName: e.target.value, error: null })}
              aria-label="Saved view name"
            />
            <button
              type="button"
              className="lux-onb-action lux-onb-action--primary"
              onClick={this.handleSave}
              disabled={acting}
            >
              Save
            </button>
            <button
              type="button"
              className="lux-onb-action lux-onb-action--ghost"
              onClick={() => this.setState({ showSaveForm: false, viewName: "", error: null })}
            >
              Cancel
            </button>
            {error && <p className="lux-workspace-saved-view-bar__error" role="alert">{error}</p>}
          </div>
        )}

        {!loading && savedViews.length > 0 && (
          <div className="lux-workspace-saved-view-bar__chips" role="list">
            {savedViews.map((view) => (
              <div key={view.id} className="lux-workspace-saved-view-bar__chip-wrap" role="listitem">
                <button
                  type="button"
                  className={classNames("lux-hrms-dash__filter-chip lux-workspace-saved-view-bar__chip", {
                    "is-active": view.isDefault,
                  })}
                  onClick={() => this.handleApply(view)}
                  title={summarizeSavedViewFilters(view.filters)}
                >
                  {view.name}
                </button>
                <button
                  type="button"
                  className="lux-workspace-saved-view-bar__chip-delete"
                  onClick={() => this.handleDelete(view.id)}
                  disabled={acting}
                  aria-label={`Delete saved view ${view.name}`}
                >
                  <i className="fe fe-x" aria-hidden="true" />
                </button>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }
}
