import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isDocumentVaultEnabled } from "config/document-vault.config";
import {
  buildDocumentVaultMetrics,
  buildDocumentComplianceMetrics,
  filterDocuments,
  getDocumentsNeedingVerification,
} from "config/document-vault.utils";
import { documentVaultService } from "_services/documentVault.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import LuxSegmentNav from "views/common/fragments/LuxSegmentNav";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import DocumentUploadDrawer from "views/people/components/documents/DocumentUploadDrawer";
import DocumentVerificationQueue from "views/people/components/documents/DocumentVerificationQueue";
import DocumentCompliancePanel from "views/people/components/documents/DocumentCompliancePanel";
import { PeopleActionButton } from "views/people/components/PeopleLuxShared";
import { DOCUMENT_VAULT_PAGE_META } from "config/people-module-nav.config";

class EmployeeDocumentsPage extends Component {
  state = {
    documents: [],
    policies: [],
    loading: true,
    loadError: null,
    dataSource: null,
    activeView: "vault",
    statusFilter: "ALL",
    query: "",
    uploadOpen: false,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Documents");
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const [docResult, policyResult] = await Promise.all([
        documentVaultService.listDocuments(),
        documentVaultService.listPolicies(),
      ]);
      this.setState({
        documents: docResult.payload || [],
        policies: policyResult.payload || [],
        loading: false,
        dataSource: docResult.source || null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load document vault.",
        documents: [],
        policies: [],
      });
    }
  };

  handleUpload = async (payload) => {
    await documentVaultService.uploadDocument(payload);
    await this.loadData();
  };

  handleVerify = async (document) => {
    await documentVaultService.verifyDocument(document.id, "HR Admin");
    await this.loadData();
  };

  handleReject = async (document) => {
    await documentVaultService.rejectDocument(document.id, "HR Admin");
    await this.loadData();
  };

  getFilteredDocuments = () => {
    const { documents, statusFilter, query } = this.state;
    return filterDocuments(documents, {
      status: statusFilter === "ALL" ? null : statusFilter,
      query,
    });
  };

  renderKpiStrip = () => {
    const { documents, loading } = this.state;
    const metrics = buildDocumentVaultMetrics(documents);
    const cards = [
      { id: "total", label: "Documents", value: metrics.total, hint: "Vault records", tone: "primary" },
      { id: "verified", label: "Verified", value: metrics.verified, hint: "Complete", tone: "green" },
      { id: "pending", label: "Pending review", value: metrics.pending, hint: "HR queue", tone: "amber" },
      { id: "expiring", label: "Expiring soon", value: metrics.expiring, hint: "Next 30 days", tone: "rose" },
    ];

    return (
      <div className="lux-hrms-dash__kpi-strip lux-doc-kpi-strip" role="list" aria-busy={loading}>
        {cards.map((card) => (
          <article
            key={card.id}
            className={classNames("lux-hrms-dash__kpi lux-doc-kpi", card.tone && `is-${card.tone}`)}
            role="listitem"
          >
            <span className="lux-hrms-dash__kpi-label">{card.label}</span>
            <strong className="lux-hrms-dash__kpi-value">{loading ? "—" : card.value}</strong>
            <span className="lux-hrms-dash__kpi-hint">{card.hint}</span>
          </article>
        ))}
      </div>
    );
  };

  renderVaultRegister = () => {
    const { loading } = this.state;
    const rows = this.getFilteredDocuments();

    if (loading) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          title="Loading documents"
          description="Fetching employee document vault."
        />
      );
    }

    if (rows.length === 0) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          icon="fe fe-file-text"
          title="No documents found"
          description="Upload employment, compliance, and payroll documents to the vault."
        />
      );
    }

    return (
      <div className="lux-doc-register-wrap">
        <table className="lux-doc-register">
          <thead>
            <tr>
              <th>Document</th>
              <th>Employee</th>
              <th>Type</th>
              <th>Visibility</th>
              <th>Status</th>
              <th>Uploaded</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row.id}>
                <td>
                  <strong>{row.title}</strong>
                  {row.fileName && <span className="lux-doc-register__meta">{row.fileName}</span>}
                </td>
                <td>
                  {row.employeeName || "—"}
                  {row.employeeId && (
                    <Link className="lux-doc-register__link" to={`/people/employees/${row.employeeId}/360`}>
                      View 360
                    </Link>
                  )}
                </td>
                <td>{row.typeLabel || row.type}</td>
                <td>{String(row.visibility || "").replace(/_/g, " ")}</td>
                <td>
                  <span className={classNames("lux-doc-badge", {
                    "is-success": String(row.status).toLowerCase().includes("verified"),
                    "is-warning": String(row.status).toLowerCase().includes("pending"),
                  })}
                  >
                    {row.status}
                  </span>
                </td>
                <td>{row.uploadedAt || "—"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  };

  render() {
    if (!isDocumentVaultEnabled()) {
      return (
        <PersonaAccessDenied
          moduleName="Documents"
          reason="Document vault is not enabled for your organization."
        />
      );
    }

    const {
      loading,
      loadError,
      dataSource,
      activeView,
      statusFilter,
      query,
      uploadOpen,
      documents,
      policies,
    } = this.state;
    const verificationQueue = getDocumentsNeedingVerification(documents);
    const complianceMetrics = buildDocumentComplianceMetrics(documents, policies);

    return (
      <div className="lux-doc-page lux-people-page lux-register-page" data-testid="page-documents">
        <PageDataSourceReporter dataSource={dataSource} />
        <LuxModuleIntro
                  meta={DOCUMENT_VAULT_PAGE_META}
                  actions={
                    <>
                      <PeopleActionButton
                        variant="primary"
                        icon="fe fe-plus"
                        testId="document-upload-button"
                        onClick={() => this.setState({ uploadOpen: true })}
                      >
                        Upload document
                      </PeopleActionButton>
                      <PeopleActionButton to="/people/policies" variant="ghost" icon="fe fe-book">
                        Policy hub
                      </PeopleActionButton>
                    </>
                  }
                />

        <div className="lux-register-page__body">
        {this.renderKpiStrip()}

        {loadError ? <LuxInlineAlert message={loadError} tone="danger" /> : null}

        <section className="lux-hrms-dash__panel lux-doc-panel">
          <header className="lux-hrms-dash__panel-head lux-appr-toolbar">
            <LuxSegmentNav
              items={[
                { id: "vault", label: "Vault", icon: "fe fe-folder" },
                { id: "verification", label: "Verification", icon: "fe fe-check-square", count: verificationQueue.length },
                { id: "compliance", label: "Compliance", icon: "fe fe-bar-chart-2" },
              ]}
              activeId={activeView}
              onChange={(next) => this.setState({ activeView: next })}
              ariaLabel="Document views"
              tabList
              testId="document-view-nav"
            />
          </header>

          {activeView === "vault" && (
            <>
              <div className="lux-appr-toolbar lux-appr-toolbar__row">
                <div className="lux-appr-toolbar__search">
                  <i className="fe fe-search" aria-hidden="true" />
                  <input
                    type="search"
                    className="lux-appr-toolbar__search-input"
                    placeholder="Search documents or employees"
                    value={query}
                    onChange={(event) => this.setState({ query: event.target.value })}
                  />
                </div>
                <div className="lux-hrms-dash__filter-group">
                  {["ALL", "Pending review", "Verified"].map((value) => (
                    <button
                      key={value}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", {
                        "is-active": statusFilter === value,
                      })}
                      onClick={() => this.setState({ statusFilter: value })}
                    >
                      {value === "ALL" ? "All" : value}
                    </button>
                  ))}
                </div>
              </div>
              <div className="lux-hrms-dash__panel-body">{this.renderVaultRegister()}</div>
            </>
          )}

          {activeView === "verification" && (
            <div className="lux-hrms-dash__panel-body">
              <DocumentVerificationQueue
                documents={verificationQueue}
                loading={loading}
                onVerify={this.handleVerify}
                onReject={this.handleReject}
              />
            </div>
          )}

          {activeView === "compliance" && (
            <div className="lux-hrms-dash__panel-body">
              <DocumentCompliancePanel metrics={complianceMetrics} documents={documents} />
            </div>
          )}
        </section>

        <DocumentUploadDrawer
          open={uploadOpen}
          onClose={() => this.setState({ uploadOpen: false })}
          onSubmit={this.handleUpload}
        />
        </div>
      </div>
    );
  }
}

export default EmployeeDocumentsPage;
