import { commonUtils } from "_helpers/common.utils";
import { normalizeAuditEvent } from "_helpers/audit.utils";
import { AUDIT_WRITE_CHANGED } from "config/audit-write.config";

const STORAGE_PREFIX = "famstack-audit-write-buffer";
const MAX_BUFFER_SIZE = 200;

function storageKey() {
  const teamId = commonUtils.getCurrentUserTeamId();
  const userId = commonUtils.getCurrentUserId();
  return `${STORAGE_PREFIX}:${teamId || "team"}:${userId || "anon"}`;
}

function readBuffer() {
  if (typeof window === "undefined") {
    return [];
  }
  try {
    const raw = localStorage.getItem(storageKey());
    if (!raw) {
      return [];
    }
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return [];
  }
}

function writeBuffer(rows) {
  if (typeof window === "undefined") {
    return rows;
  }
  const trimmed = rows.slice(0, MAX_BUFFER_SIZE);
  localStorage.setItem(storageKey(), JSON.stringify(trimmed));
  window.dispatchEvent(new CustomEvent(AUDIT_WRITE_CHANGED));
  return trimmed;
}

export function appendBufferedAuditEvent(record) {
  if (!record) {
    return [];
  }
  const entry = {
    ...record,
    id: `buf-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    createdAt: new Date().toISOString(),
    createdDate: new Date().toISOString(),
  };
  const next = [entry, ...readBuffer()].slice(0, MAX_BUFFER_SIZE);
  return writeBuffer(next);
}

export function listBufferedAuditEvents() {
  return readBuffer()
    .map((row) => normalizeAuditEvent(row))
    .filter(Boolean);
}

export function listBufferedAuditRecords() {
  return readBuffer();
}

export function clearBufferedAuditEvents() {
  if (typeof window !== "undefined") {
    localStorage.removeItem(storageKey());
    window.dispatchEvent(new CustomEvent(AUDIT_WRITE_CHANGED));
  }
}
