function expenseTeamQuery(extra) {
  const query = {};
  const explicitIds = extra && extra.userTeamIds;
  const currentIds = commonUtils.getCurrentUserTeamIds() || [];
  const currentId = commonUtils.getCurrentUserTeamId();
  if (Array.isArray(explicitIds) && explicitIds.length) {
    query.userTeamIds = explicitIds;
  } else if (currentIds.length > 0) {
    query.userTeamIds = currentIds;
  } else if (currentId != null && currentId !== "") {
    query.userTeamId = currentId;
  }
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (key === "userTeamId" || key === "userTeamIds") return;
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

function expenseMutationTeamQuery(extra) {
  const query = {
    userTeamId: (extra && extra.userTeamId) || commonUtils.getCurrentUserTeamId(),
  };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (key === "userTeamId" || key === "userTeamIds") return;
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

function expenseTeamQueryString(extra) {
  const query = expenseMutationTeamQuery(extra);
  return Object.keys(query)
    .map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(query[key])}`)
    .join("&");
}

function writeExpenseAudit(actionType, headline, entityRef, metadata) {
  recordAuditEvent({
    actionType,
    entityType: AUDIT_ENTITY_TYPES.EMPLOYEE,
    entityRef: entityRef || headline,
    headline,
    metadata: {
      module: "EXPENSE_MANAGEMENT",
      ...metadata,
    },
  });
}

function applyExpenseMasking(payload, viewerContext) {
  const ctx = viewerContext || buildExpenseViewerContext({}, { id: commonUtils.getCurrentUserId() });
  const policy = ctx.maskingPolicy || {};
  if (Array.isArray(payload)) {
    return payload.map((row) => maskExpenseClaimForDisplay(row, policy, ctx));
  }
  return maskExpenseClaimForDisplay(payload, policy, ctx);
}

async function listExpenseClaims(filters = {}, viewerContext) {
  if (!shouldUseExpensesApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.getWithParam(
    `${urlConfig.EXPENSES_API_PATH}/claims`,
    expenseTeamQuery(filters)
  );
  const rows = (response && response.payload) || response || [];
  return { payload: applyExpenseMasking(rows, viewerContext), source: "api" };
}

async function getExpenseClaim(claimId, viewerContext) {
  if (!shouldUseExpensesApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.get(
    `${urlConfig.EXPENSES_API_PATH}/claims/${claimId}?${expenseTeamQueryString()}`
  );
  const row = (response && response.payload) || response;
  return { payload: applyExpenseMasking(row, viewerContext), source: "api" };
}

async function saveExpenseClaim(payload = {}) {
  if (!shouldUseExpensesApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.post(
    `${urlConfig.EXPENSES_API_PATH}/claims?${expenseTeamQueryString({
      actorId: payload.actorId || commonUtils.getCurrentUserId(),
    })}`,
    payload
  );
  const row = (response && response.payload) || response;
  writeExpenseAudit(
    AUDIT_ACTION_TYPES.CREATED,
    "Expense claim created",
    row && (row.claimRef || row.id),
    buildExpenseAuditMetadata(row, EXPENSE_AUDIT_CODES.RECEIPT_UPLOADED ? "CREATED" : "CREATED")
  );
  return { payload: row, source: "api" };
}

