async function attachExpenseReceipt(claimRef, options = {}) {
  if (!claimRef) {
    return apiErrorResult(null);
  }
  const employeeId = options.employeeId || commonUtils.getCurrentUserId();
  const title = options.title || `Receipt for ${claimRef}`;
  const result = await documentVaultService.uploadDocument({
    title,
    type: "RECEIPT",
    category: "Expenses",
    sourceEntityType: "EXPENSE_CLAIM",
    sourceEntityId: String(claimRef),
    employeeId: employeeId != null ? String(employeeId) : undefined,
    employeeName: options.employeeName,
    fileName: options.fileName || `receipt-${claimRef}.pdf`,
    uploadedBy: options.uploadedBy || "Expense claimant",
  });
  if (result && result.payload) {
    writeExpenseAudit(
      AUDIT_ACTION_TYPES.CREATED,
      "Expense receipt attached",
      claimRef,
      { documentId: result.payload.id, sourceEntityType: "EXPENSE_CLAIM", code: EXPENSE_AUDIT_CODES.RECEIPT_UPLOADED }
    );
  }
  return result;
}

async function listExpenseReceipts(claimRef, filters = {}) {
  if (!claimRef) {
    return { payload: [], source: "api" };
  }
  return documentVaultService.listDocuments({
    ...filters,
    sourceEntityType: "EXPENSE_CLAIM",
    sourceEntityId: String(claimRef),
  });
}

