import React, { Component } from "react";
import classNames from "classnames/bind";
import dateUtils from "_helpers/date.utils";
import workItemUtils from "_helpers/workitem.utils";
import LuxListRowMenuPortal from "views/common/fragments/LuxListRowMenuPortal";
import {
  getWorkItemStatusMeta,
  getWorkItemPriorityMeta,
} from "./workItemActivity.utils";
import {
  getWorkItemChecklistMeta,
  getWorkItemHoursMeta,
  formatWorkItemOwner,
  getWorkItemOwnerInitial,
  getWorkItemTypeMeta,
  isWorkItemOverdue,
  getWorkItemPriorityValue,
} from "./workItemList.utils";

class WorkItemListRow extends Component {
  constructor(props) {
    super(props);
    this.state = { menuOpen: false, confirmRemove: false };
    this.rowRef = React.createRef();
    this.menuTriggerRef = React.createRef();
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick);
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
  }

  handleOutsideClick = (event) => {
    if (!this.state.menuOpen) return;
    if (event.target.closest(".lux-list-row-menu-portal")) return;
    if (this.rowRef.current && !this.rowRef.current.contains(event.target)) {
      this.setState({ menuOpen: false, confirmRemove: false });
    }
  };

  toggleMenu = (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.setState((prev) => ({ menuOpen: !prev.menuOpen, confirmRemove: false }));
  };

  closeMenu = () => this.setState({ menuOpen: false, confirmRemove: false });

  runMenuAction = (handler) => (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.closeMenu();
    if (handler) handler();
  };

  stopRowClick = (event) => {
    event.preventDefault();
    event.stopPropagation();
  };

  handleRemove = () => {
    if (this.state.confirmRemove) {
      this.props.handleRemoveWorkItem(this.props.item.id);
      this.setState({ confirmRemove: false, menuOpen: false });
      return;
    }
    this.setState({ confirmRemove: true });
  };

  isDeleteByHoursEnabled = () => {
    const { item, permission } = this.props;
    if (!item) return false;
    const hours = parseInt(permission.enableWorkItemDeleteTillNextDayXHour || 0, 10);
    return workItemUtils.isWorkItemEditActive(item.actualStartTime, hours);
  };

  canEdit = () => {
    const { permission } = this.props;
    return !!permission.editEnabled;
  };

  renderMenuItem = (entry) => (
    <button
      key={entry.key}
      type="button"
      className={classNames("lux-emp-card__menu-item", entry.tone && `is-${entry.tone}`)}
      role="menuitem"
      onClick={this.runMenuAction(entry.onClick)}
    >
      <span className={classNames("lux-emp-card__menu-icon", entry.tone && `is-${entry.tone}`)}>
        <i className={entry.icon} aria-hidden="true" />
      </span>
      <span className="lux-emp-card__menu-copy">
        <strong>{entry.label}</strong>
      </span>
    </button>
  );

  getMenuSections = () => {
    const { item, permission } = this.props;
    const primary = [
      {
        key: "view",
        icon: "fe fe-eye",
        label: "View details",
        onClick: () => this.props.onOpenDetail(item),
      },
    ];
    if (this.canEdit()) {
      primary.push({
        key: "edit",
        icon: "fe fe-edit-2",
        label: "Edit work item",
        onClick: () => this.props.handleEditWorkItem(item.id),
      });
    }
    if (
      permission.checklistEnabled &&
      (item.taskType === "PROJECT" || item.taskType === "NON_PROJECT")
    ) {
      primary.push({
        key: "checklist",
        icon: "fa fa-wpforms",
        label: "Open checklist",
        onClick: () => this.props.onCheklistItemClick && this.props.onCheklistItemClick(item),
      });
    }

    const secondary = [];
    if (permission.deleteEnabled || this.isDeleteByHoursEnabled()) {
      secondary.push({
        key: "delete",
        icon: item.deleted ? "fe fe-rotate-ccw" : "fe fe-trash-2",
        label: item.deleted ? "Undo delete" : "Delete",
        tone: "danger",
        onClick: () => this.props.handleDeleteWorkItem(item.id, !item.deleted),
      });
    }
    if (permission.removeEnabled) {
      secondary.push({
        key: "remove",
        icon: this.state.confirmRemove ? "fe fe-check" : "fe fe-x",
        label: this.state.confirmRemove ? "Confirm remove" : "Remove permanently",
        tone: "danger",
        onClick: this.handleRemove,
      });
    }
    return { primary, secondary };
  };

  handleRowActivate = () => {
    if (this.props.onOpenDetail) {
      this.props.onOpenDetail(this.props.item);
    }
  };

  handleRowKeyDown = (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      this.handleRowActivate();
    }
  };

  render() {
    const { item } = this.props;
    const { menuOpen } = this.state;
    const statusMeta = getWorkItemStatusMeta(item.status);
    const priorityMeta = getWorkItemPriorityMeta(getWorkItemPriorityValue(item));
    const hoursMeta = getWorkItemHoursMeta(item);
    const checklistMeta = getWorkItemChecklistMeta(item.checklistStatus, item.checklistData);
    const typeMeta = getWorkItemTypeMeta(item.taskType);
    const overdue = isWorkItemOverdue(item);
    const { primary, secondary } = this.getMenuSections();
    const ownerName = formatWorkItemOwner(item);
    const workItemLabel = item.name || item.itemIdUserTeamPrefix;
    const startLabel =
      dateUtils.convertDateFormat(item.actualStartTime || item.estStartTime) || "—";
    const dueLabel = item.estCompletionTime
      ? dateUtils.convertDateFormat(item.estCompletionTime)
      : null;
    const showChecklistBadge = checklistMeta.tone !== "muted";

    return (
      <article
        ref={this.rowRef}
        className={classNames("lux-bid-list__item lux-workitem-row", {
          "is-deleted": item.deleted,
          "is-overdue": overdue,
          "is-menu-open": menuOpen,
          [`is-status-${statusMeta.tone}`]: true,
        })}
        role="listitem"
      >
        <span className="lux-bid-list__accent" aria-hidden="true" />

        <div className="lux-bid-list__col lux-bid-list__col--index">
          <span className="lux-workitem-row__index">{this.props.rowIndex}</span>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--id">
          <span className="lux-bid-list__ref lux-workitem-row__ref" title={item.itemIdUserTeamPrefix}>
            {item.itemIdUserTeamPrefix}
          </span>
        </div>

        <div
          className="lux-bid-list__col lux-bid-list__col--name lux-workitem-row__name-col is-clickable"
          role="button"
          tabIndex={0}
          onClick={this.handleRowActivate}
          onKeyDown={this.handleRowKeyDown}
          aria-label={`View ${workItemLabel}`}
        >
          <span className="lux-workitem-row__name" title={workItemLabel}>
            <span className="lux-workitem-row__name-text">{workItemLabel}</span>
            <i className="fe fe-arrow-up-right" aria-hidden="true" />
          </span>
          {item.description && (
            <p className="lux-workitem-row__description" title={item.description}>
              {item.description}
            </p>
          )}
          <div className="lux-workitem-row__tags">
            <span className={classNames("lux-workitem-row__prio", `is-${priorityMeta.tone}`)}>
              {priorityMeta.label}
            </span>
            {typeMeta && (
              <span
                className={classNames("lux-workitem-row__badge", `is-${typeMeta.tone}`)}
                title={typeMeta.label}
              >
                <i className={typeMeta.icon} aria-hidden="true" />
                <span className="lux-workitem-row__badge-text">{typeMeta.label}</span>
              </span>
            )}
            {showChecklistBadge && (
              <span
                className={classNames("lux-workitem-row__checklist", `is-${checklistMeta.tone}`)}
                title={`Checklist · ${checklistMeta.label}`}
              >
                <i className={checklistMeta.icon} aria-hidden="true" />
                <span className="lux-workitem-row__checklist-text">{checklistMeta.label}</span>
              </span>
            )}
            {overdue && (
              <span className="lux-workitem-row__badge is-overdue">
                <i className="fe fe-alert-circle" aria-hidden="true" />
                Past due
              </span>
            )}
            {item.deleted && (
              <span className="lux-bid-list__deleted-badge">
                <i className="fe fe-trash-2" aria-hidden="true" />
                Deleted
              </span>
            )}
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--category">
          <span className="lux-workitem-row__category" title={item.taskActCategory || "Other"}>
            <i className="fe fe-tag" aria-hidden="true" />
            <span>{item.taskActCategory || "Other"}</span>
          </span>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--owner">
          <div className="lux-workitem-row__owner" title={ownerName}>
            <span className="lux-workitem-row__owner-avatar">{getWorkItemOwnerInitial(item)}</span>
            <div className="lux-workitem-row__owner-copy">
              <strong className="lux-workitem-row__owner-name">{ownerName}</strong>
              <em>Assignee</em>
            </div>
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--dates lux-workitem-row__dates-col">
          <div className="lux-workitem-row__dates">
            <span className="lux-workitem-row__date is-start">
              <em>Start</em>
              {startLabel}
            </span>
            {dueLabel && (
              <span className={classNames("lux-workitem-row__date is-due", { "is-late": overdue })}>
                <em>Due</em>
                {dueLabel}
              </span>
            )}
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--hours">
          <div
            className={classNames("lux-workitem-row__hours", `is-${hoursMeta.tone}`)}
            title={
              hoursMeta.secondary
                ? `${hoursMeta.label} ${hoursMeta.value} · ${hoursMeta.secondary}`
                : `${hoursMeta.label} ${hoursMeta.value}`
            }
          >
            <div className="lux-workitem-row__hours-head">
              <span className="lux-workitem-row__hours-label">{hoursMeta.label}</span>
              <strong>{hoursMeta.value}</strong>
            </div>
            <div className="lux-workitem-row__hours-track" aria-hidden="true">
              <span
                className="lux-workitem-row__hours-fill"
                style={{ width: `${hoursMeta.barPct}%` }}
              />
            </div>
          </div>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--status is-center">
          <span
            className={classNames("lux-workitem-row__status", `is-${statusMeta.tone}`)}
            title={statusMeta.label}
          >
            <i
              className={classNames(statusMeta.icon, { spin: statusMeta.spin })}
              aria-hidden="true"
            />
            <span className="lux-workitem-row__status-text">{statusMeta.label}</span>
          </span>
        </div>

        <div className="lux-bid-list__col lux-bid-list__col--actions">
          <div className="lux-workitem-row__actions">
            <button
              type="button"
              className="lux-workitem-row__action"
              title="View details"
              aria-label={`View ${workItemLabel}`}
              onClick={(event) => {
                this.stopRowClick(event);
                this.props.onOpenDetail(item);
              }}
            >
              <i className="fe fe-eye" aria-hidden="true" />
            </button>
            {this.canEdit() && (
              <button
                type="button"
                className="lux-workitem-row__action"
                title="Edit work item"
                aria-label={`Edit ${workItemLabel}`}
                onClick={(event) => {
                  this.stopRowClick(event);
                  this.props.handleEditWorkItem(item.id);
                }}
              >
                <i className="fe fe-edit-2" aria-hidden="true" />
              </button>
            )}
            <button
              ref={this.menuTriggerRef}
              type="button"
              className="lux-workitem-row__action lux-workitem-row__action--menu"
              aria-label={`More actions for ${workItemLabel}`}
              aria-haspopup="menu"
              aria-expanded={menuOpen}
              onClick={this.toggleMenu}
            >
              <i className="fe fe-more-horizontal" aria-hidden="true" />
            </button>
            <LuxListRowMenuPortal
              open={menuOpen}
              anchorRef={this.menuTriggerRef}
              className="lux-bid-list__menu-panel"
            >
              <header className="lux-emp-card__menu-head">
                <span className="lux-emp-card__menu-head-icon" aria-hidden="true">
                  <i className="fe fe-check-square" />
                </span>
                <div>
                  <span className="lux-emp-card__menu-eyebrow">Work item</span>
                  <strong title={workItemLabel}>{workItemLabel}</strong>
                </div>
                <button
                  type="button"
                  className="lux-emp-card__menu-close"
                  onClick={this.runMenuAction(null)}
                  aria-label="Close menu"
                >
                  <i className="fe fe-x" aria-hidden="true" />
                </button>
              </header>
              <div className="lux-emp-card__menu-body">
                {primary.map((entry) => this.renderMenuItem(entry))}
                {secondary.length > 0 && primary.length > 0 && (
                  <div className="lux-emp-card__menu-divider" aria-hidden="true" />
                )}
                {secondary.map((entry) => this.renderMenuItem(entry))}
              </div>
            </LuxListRowMenuPortal>
          </div>
        </div>
      </article>
    );
  }
}

export default WorkItemListRow;
