import React from "react";
import classNames from "classnames/bind";
import FileManagerBreadcrumb from "./FileManagerBreadcrumb";

export default function FileManagerToolbar({
  breadcrumb,
  viewMode,
  onViewModeChange,
  onNavigate,
  onUpload,
  onNewFolder,
}) {
  return (
    <div className="lux-file-toolbar">
      <FileManagerBreadcrumb trail={breadcrumb} onNavigate={onNavigate} />
      <div className="lux-file-toolbar__actions">
        <div className="lux-file-toolbar__view" role="group" aria-label="View mode">
          <button
            type="button"
            className={classNames("lux-file-toolbar__view-btn", {
              "is-active": viewMode === "list",
            })}
            onClick={() => onViewModeChange && onViewModeChange("list")}
            title="List view"
            aria-pressed={viewMode === "list"}
          >
            <i className="fe fe-list" aria-hidden="true" />
          </button>
          <button
            type="button"
            className={classNames("lux-file-toolbar__view-btn", {
              "is-active": viewMode === "grid",
            })}
            onClick={() => onViewModeChange && onViewModeChange("grid")}
            title="Grid view"
            aria-pressed={viewMode === "grid"}
          >
            <i className="fe fe-grid" aria-hidden="true" />
          </button>
        </div>
        <button
          type="button"
          className="lux-file-toolbar__btn lux-file-toolbar__btn--ghost"
          onClick={onNewFolder}
        >
          <i className="fe fe-folder-plus" aria-hidden="true" />
          New folder
        </button>
        <button type="button" className="lux-file-toolbar__btn lux-file-toolbar__btn--primary" onClick={onUpload}>
          <i className="fe fe-upload-cloud" aria-hidden="true" />
          Upload
        </button>
      </div>
    </div>
  );
}
