import React, { Component } from "react";
import { Link } from "react-router-dom";
import ProjectDetailsTabShell from "views/project/components/ProjectDetailsTabShell";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import UniversalApprovalRegister from "views/workspace/components/approvals/UniversalApprovalRegister";
import UniversalApprovalDetailDrawer from "views/workspace/components/approvals/UniversalApprovalDetailDrawer";
import { universalApprovalService } from "_services/universalApproval.service";
import {
  buildEmployeeApprovalsTabStats,
  filterApprovalsForEmployee,
} from "config/employee360Tab.utils";
import { sortApprovalInboxItems } from "config/universal-approval.utils";
import { getEmployeeDisplayName } from "config/employee360.utils";

export default class Employee360ApprovalsTab extends Component {
  state = {
    items: [],
    loading: true,
    loadError: null,
    selectedItem: null,
    drawerOpen: false,
    acting: false,
  };

  componentDidMount() {
    this.loadApprovals();
  }

  componentDidUpdate(prevProps) {
    const prevId = prevProps.employee && prevProps.employee.id;
    const nextId = this.props.employee && this.props.employee.id;
    if (prevId !== nextId) {
      this.loadApprovals();
    }
  }

  loadApprovals = async () => {
    const { employee } = this.props;
    if (!employee || !employee.id) {
      return;
    }

    this.setState({ loading: true, loadError: null });
    try {
      const result = await universalApprovalService.listInbox({ status: "ALL" });
      const allItems = sortApprovalInboxItems(result.payload || []);
      const items = filterApprovalsForEmployee(allItems, employee);
      this.setState({ items, loading: false });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load approval requests for this employee.",
        items: [],
      });
    }
  };

  handleSelectItem = (item) => {
    this.setState({ selectedItem: item, drawerOpen: true });
  };

  handleCloseDrawer = () => {
    this.setState({ drawerOpen: false, selectedItem: null, acting: false });
  };

  handleApprove = async (item, comment) => {
    this.setState({ acting: true });
    try {
      await universalApprovalService.approveItem(item, comment);
      await this.loadApprovals();
      this.setState({ acting: false });
    } catch (error) {
      this.setState({ acting: false });
      throw error;
    }
  };

  handleReject = async (item, comment) => {
    this.setState({ acting: true });
    try {
      await universalApprovalService.rejectItem(item, comment);
      await this.loadApprovals();
      this.setState({ acting: false });
    } catch (error) {
      this.setState({ acting: false });
      throw error;
    }
  };

  render() {
    const { employee, summary } = this.props;
    const { items, loading, loadError, selectedItem, drawerOpen } = this.state;

    if (!employee) {
      return null;
    }

    const displayName = getEmployeeDisplayName(employee);
    const stats = buildEmployeeApprovalsTabStats(items);
    const pendingFromSummary =
      summary && summary.pendingApprovals != null ? summary.pendingApprovals : null;

    return (
      <>
        <ProjectDetailsTabShell
          icon="fe fe-inbox"
          eyebrow="Workflow"
          title="Approvals"
          subtitle={`Leave, timesheet, and attendance requests submitted by ${displayName}.`}
          stats={stats}
          className="lux-employee-360__embed lux-employee-360__embed--approvals"
        >
          <div className="lux-employee-360__embed-toolbar">
            <strong className="lux-employee-360__embed-period">
              {pendingFromSummary != null
                ? `${pendingFromSummary} pending in summary`
                : `${items.filter((row) => row.status === "PENDING").length} pending requests`}
            </strong>
            <Link to="/workspace/approvals" className="lux-employee-360__embed-link">
              Open approval inbox
              <i className="fe fe-external-link" aria-hidden="true" />
            </Link>
          </div>

          {loadError && !loading && (
            <LuxInlineAlert
              tone="warning"
              title="Unable to load approvals"
              className="lux-employee-360__error"
            >
              {loadError}
            </LuxInlineAlert>
          )}

          {!loadError && (loading || items.length > 0) && (
            <UniversalApprovalRegister
              items={items}
              loading={loading}
              onSelect={this.handleSelectItem}
            />
          )}

          {!loading && !loadError && items.length === 0 && (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact lux-employee-360__embed-empty"
              icon="fe fe-inbox"
              title="No approval requests"
              description="Requests submitted by this employee will appear here across leave, timesheet, and attendance domains."
            />
          )}
        </ProjectDetailsTabShell>

        <UniversalApprovalDetailDrawer
          open={drawerOpen}
          item={selectedItem}
          onClose={this.handleCloseDrawer}
          onApprove={this.handleApprove}
          onReject={this.handleReject}
          acting={this.state.acting}
        />
      </>
    );
  }
}
