import dateUtils from "_helpers/date.utils";
import { toDonutChart } from "../dashboard/employeeDashboard.utils";
import {
  convertMinsToDisplay,
  deriveTimesheetEntryStatus,
  getTimesheetStatusMeta,
  readAttributeValue,
} from "./timesheetSummary.utils";
import { isTimesheetCellEditable } from "./timesheet.utils";
import {
  DAILY_TARGET_MINS,
  formatEntryTotalLabel,
  getDayHeaderMeta,
  getDayTotalHighlightLevel,
  getLeaveHolidayKind,
} from "./timesheetBoard.utils";

export function resolveTaskFromRequest(timeSheetRequest, timesheetType, taskGroupId, taskIndex) {
  const section = timeSheetRequest && timeSheetRequest[timesheetType] && timeSheetRequest[timesheetType][taskGroupId];
  const tasks = section && section.tasks;
  if (!tasks || taskIndex == null || !tasks[taskIndex]) return null;
  return { section, task: tasks[taskIndex] };
}

export function buildEntryDetailModel({
  timesheetType,
  taskGroupId,
  timeEntryTaskSection,
  timeSheetTaskItem,
  weekDates,
}) {
  if (!timeSheetTaskItem || !weekDates) return null;

  const timeEntry = timeSheetTaskItem.timeEntry || {};
  const leaveKind = getLeaveHolidayKind(taskGroupId, timeSheetTaskItem.taskActCategory);
  const isProject = timesheetType === "project";

  let title = timeSheetTaskItem.workItemName || "Time entry";
  let subtitle = "";
  let metaChips = [];
  let badge = { label: "Non-billable", tone: "blue" };

  if (isProject) {
    title = timeSheetTaskItem.taskName || title;
    metaChips = [
      timeEntryTaskSection && timeEntryTaskSection.projectCode
        ? { key: "code", label: timeEntryTaskSection.projectCode, tone: "account" }
        : null,
      timeEntryTaskSection && timeEntryTaskSection.projectName
        ? { key: "project", label: timeEntryTaskSection.projectName, tone: "work" }
        : null,
      timeSheetTaskItem.taskActCategory
        ? { key: "category", label: timeSheetTaskItem.taskActCategory, tone: "category" }
        : null,
      timeSheetTaskItem.workItemName
        ? { key: "work", label: timeSheetTaskItem.workItemName, tone: "work" }
        : null,
    ].filter(Boolean);
    subtitle = metaChips.map((chip) => chip.label).join(" · ");
    badge = { label: "Billable", tone: "green" };
  } else if (leaveKind === "leave") {
    badge = { label: "Leave", tone: "amber" };
    metaChips = taskGroupId ? [{ key: "group", label: taskGroupId, tone: "category" }] : [];
    subtitle = taskGroupId;
  } else if (leaveKind === "holiday") {
    badge = { label: "Holiday", tone: "rose" };
    metaChips = taskGroupId ? [{ key: "group", label: taskGroupId, tone: "category" }] : [];
    subtitle = taskGroupId;
  } else {
    metaChips = [
      taskGroupId ? { key: "group", label: taskGroupId, tone: "category" } : null,
      timeSheetTaskItem.division
        ? { key: "division", label: timeSheetTaskItem.division, tone: "division" }
        : null,
      timeSheetTaskItem.account
        ? { key: "account", label: timeSheetTaskItem.account, tone: "account" }
        : null,
      timeSheetTaskItem.clientPartner
        ? { key: "partner", label: timeSheetTaskItem.clientPartner, tone: "partner" }
        : null,
      timeSheetTaskItem.requestingTeamName
        ? { key: "team", label: timeSheetTaskItem.requestingTeamName, tone: "team" }
        : null,
    ].filter(Boolean);
    subtitle = metaChips.map((chip) => chip.label).join(" · ");
  }

  const dayRows = weekDates.map((dateString) => {
    const cell = timeEntry[dateString] || {};
    const mins = parseInt(cell.timesheetTimeMins || 0, 10);
    const statusKey = deriveTimesheetEntryStatus(cell, timeSheetTaskItem.isNew === true);
    const statusMeta = statusKey ? getTimesheetStatusMeta(statusKey) : getTimesheetStatusMeta("NOT_STARTED");
    const dayMeta = getDayHeaderMeta(dateString);
    const momentDate = dateUtils.convertDateStringToMoment(dateString);
    const comments = readAttributeValue(cell.comments);
    const skill = readAttributeValue(cell.skill);
    const quantity = readAttributeValue(cell.quantity);

    return {
      dateString,
      dayLabel: momentDate && momentDate.isValid() ? momentDate.format("ddd D MMM") : dateString,
      dayShort: dayMeta.dayShort,
      mins,
      hoursDisplay: mins > 0 ? dateUtils.minuteToHourString(mins) : "—",
      statusKey,
      statusMeta,
      comments,
      skill,
      quantity,
      isEditable: isTimesheetCellEditable(cell, timeSheetTaskItem.isNew === true),
      hasDetails: !!(comments || skill || quantity),
    };
  });

  const rowTotalMins = dayRows.reduce((sum, row) => sum + row.mins, 0);
  const activeDays = dayRows.filter((row) => row.mins > 0).length;
  const daysWithComments = dayRows.filter((row) => row.comments).length;

  return {
    timesheetType,
    taskGroupId,
    title,
    subtitle,
    metaChips,
    badge,
    leaveKind,
    timeSheetTaskItem,
    timeEntryTaskSection,
    dayRows,
    rowTotalMins,
    rowTotalDisplay: formatEntryTotalLabel(rowTotalMins),
    activeDays,
    daysWithComments,
    avgPerActiveDay:
      activeDays > 0 ? formatEntryTotalLabel(Math.round(rowTotalMins / activeDays)) : "—",
  };
}

export function collectDayEntries(timeSheetRequest, dateString, weekDates) {
  const entries = [];
  if (!timeSheetRequest || !dateString) return entries;

  ["project", "nonProject"].forEach((timesheetType) => {
    const groups = timeSheetRequest[timesheetType];
    if (!groups) return;

    Object.keys(groups).forEach((taskGroupId) => {
      const section = groups[taskGroupId];
      const tasks = section && section.tasks;
      if (!tasks) return;

      tasks.forEach((task) => {
        const cell = task.timeEntry && task.timeEntry[dateString];
        if (!cell) return;
        const mins = parseInt(cell.timesheetTimeMins || 0, 10);
        if (mins <= 0) return;

        const leaveKind = getLeaveHolidayKind(taskGroupId, task.taskActCategory);
        const statusKey = deriveTimesheetEntryStatus(cell, task.isNew === true);
        const statusMeta = statusKey ? getTimesheetStatusMeta(statusKey) : getTimesheetStatusMeta("NOT_STARTED");

        let label = task.workItemName || "Entry";
        let labelTitle = label;
        let metaChips = [];
        let groupLabel = taskGroupId;
        if (timesheetType === "project") {
          label = task.taskName || label;
          labelTitle = [task.taskName, task.taskActCategory, task.workItemName]
            .filter(Boolean)
            .join(" · ");
          metaChips = [
            task.taskActCategory
              ? { key: "category", label: task.taskActCategory, tone: "category" }
              : null,
            task.workItemName ? { key: "work", label: task.workItemName, tone: "work" } : null,
          ].filter(Boolean);
          groupLabel = [section.projectCode, section.projectName].filter(Boolean).join(" · ");
        } else {
          metaChips = [
            task.division ? { key: "division", label: task.division, tone: "division" } : null,
            task.account ? { key: "account", label: task.account, tone: "account" } : null,
            task.requestingTeamName
              ? { key: "team", label: task.requestingTeamName, tone: "team" }
              : null,
          ].filter(Boolean);
          labelTitle = [task.workItemName, task.division, task.account, task.requestingTeamName]
            .filter(Boolean)
            .join(" · ");
        }

        entries.push({
          timesheetType,
          taskGroupId,
          mins,
          hoursDisplay: dateUtils.minuteToHourString(mins),
          label,
          labelTitle,
          metaChips,
          groupLabel,
          leaveKind,
          statusMeta,
          comments: readAttributeValue(cell.comments),
          skill: readAttributeValue(cell.skill),
          quantity: readAttributeValue(cell.quantity),
        });
      });
    });
  });

  entries.sort((a, b) => b.mins - a.mins);
  return entries;
}

export function buildDayDetailModel(timeSheetRequest, dateString, weekDates) {
  if (!dateString) return null;

  const momentDate = dateUtils.convertDateStringToMoment(dateString);
  const dayMeta = getDayHeaderMeta(dateString);
  const entries = collectDayEntries(timeSheetRequest, dateString, weekDates);

  let totalMins = 0;
  let billableMins = 0;
  let nonProjectMins = 0;
  let leaveMins = 0;

  entries.forEach((entry) => {
    totalMins += entry.mins;
    if (entry.timesheetType === "project") billableMins += entry.mins;
    else if (entry.leaveKind) leaveMins += entry.mins;
    else nonProjectMins += entry.mins;
  });

  const targetLevel = getDayTotalHighlightLevel(totalMins);
  const gapMins = DAILY_TARGET_MINS - totalMins;

  return {
    dateString,
    title: momentDate && momentDate.isValid() ? momentDate.format("dddd, D MMMM YYYY") : dateString,
    dayShort: dayMeta.dayShort,
    isToday: dayMeta.isToday,
    isWeekend: dayMeta.isSaturday || dayMeta.isSunday,
    totalMins,
    totalDisplay: convertMinsToDisplay(totalMins),
    billableMins,
    nonProjectMins,
    leaveMins,
    targetLevel,
    gapDisplay:
      targetLevel === "under"
        ? `${convertMinsToDisplay(gapMins)} below 8h`
        : targetLevel === "over"
          ? `${convertMinsToDisplay(Math.abs(gapMins))} over 8h`
          : targetLevel === "target"
            ? "On target"
            : "No hours logged",
    entryCount: entries.length,
    entries,
  };
}

export function buildEntryRowHoursChart(dayRows) {
  const categories = dayRows.map((row) => row.dayShort);
  const hours = dayRows.map((row) => Math.round((row.mins / 60) * 10) / 10);
  const colors = dayRows.map((row) => {
    if (row.mins <= 0) return "#e2e8f0";
    if (row.mins > DAILY_TARGET_MINS) return "#dc2626";
    if (row.mins < DAILY_TARGET_MINS) return "#d97706";
    return "#059669";
  });

  return {
    series: [{ name: "Hours", data: hours }],
    options: {
      chart: { type: "bar", toolbar: { show: false }, sparkline: { enabled: false } },
      plotOptions: {
        bar: { borderRadius: 8, columnWidth: "55%", distributed: true, dataLabels: { position: "top" } },
      },
      colors,
      dataLabels: {
        enabled: true,
        formatter: (val) => (val > 0 ? `${val}h` : ""),
        offsetY: -16,
        style: { fontSize: "11px", fontWeight: 800, colors: ["#334155"] },
      },
      xaxis: {
        categories,
        labels: { style: { fontSize: "11px", fontWeight: 700, colors: "#64748b" } },
      },
      yaxis: {
        max: Math.max(8, ...hours) + 1,
        labels: { style: { fontSize: "10px", colors: "#94a3b8" } },
      },
      grid: { borderColor: "rgba(226,232,240,0.85)", strokeDashArray: 4 },
      legend: { show: false },
      annotations: {
        yaxis: [
          {
            y: 8,
            borderColor: "rgba(5, 150, 105, 0.45)",
            strokeDashArray: 4,
            label: {
              text: "8h",
              style: { fontSize: "10px", fontWeight: 800, color: "#059669", background: "rgba(255,255,255,0.92)" },
            },
          },
        ],
      },
    },
  };
}

export function buildDayMixDonutChart(model) {
  const { billableMins, nonProjectMins, leaveMins } = model;
  const series = [billableMins, nonProjectMins, leaveMins];
  if (series.every((v) => v === 0)) return null;

  const chart = toDonutChart(
    ["Billable", "Non-billable", "Leave / holiday"],
    series,
    ["#059669", "#5b5ff4", "#d97706"]
  );
  chart.options.plotOptions = {
    pie: {
      donut: {
        size: "68%",
        labels: {
          show: true,
          total: {
            show: true,
            label: "Total",
            fontSize: "11px",
            fontWeight: 700,
            color: "#64748b",
            formatter: () => model.totalDisplay,
          },
        },
      },
    },
  };
  chart.options.legend = { position: "bottom", fontSize: "11px", fontWeight: 600 };
  return chart;
}

export function buildDayTargetGaugeChart(model) {
  const hours = Math.round((model.totalMins / 60) * 10) / 10;
  const pct = Math.min(100, Math.round((model.totalMins / DAILY_TARGET_MINS) * 100));

  return {
    series: [pct],
    options: {
      chart: { type: "radialBar", toolbar: { show: false } },
      plotOptions: {
        radialBar: {
          hollow: { size: "62%" },
          track: { background: "rgba(226,232,240,0.85)" },
          dataLabels: {
            name: { fontSize: "11px", fontWeight: 700, color: "#64748b", offsetY: 22 },
            value: {
              fontSize: "22px",
              fontWeight: 900,
              color: "#0f172a",
              formatter: () => `${hours}h`,
            },
          },
        },
      },
      colors:
        model.targetLevel === "over"
          ? ["#dc2626"]
          : model.targetLevel === "under"
            ? ["#d97706"]
            : model.targetLevel === "target"
              ? ["#059669"]
              : ["#94a3b8"],
      labels: ["of 8h target"],
    },
  };
}

export function entryHasAdditionalDetails(timeEntryValues) {
  if (!timeEntryValues) return false;
  return !!(
    readAttributeValue(timeEntryValues.comments) ||
    readAttributeValue(timeEntryValues.skill) ||
    readAttributeValue(timeEntryValues.quantity)
  );
}
