/**
 * W21 — Benefits carrier/EDI FE service. Real API only (no mock fallback).
 * File-based carrier exchange — does not claim live EDI transmission.
 */
import { axiosUtils, commonUtils } from "../../_helpers";
import urlConfig from "url.config";

export const benefitsService = {
  listPlans,
  createPlan,
  updatePlan,
  eligibility,
  listEnrollments,
  getEnrollment,
  createEnrollment,
  submitEnrollment,
  approveEnrollment,
  rejectEnrollment,
  getDeductionMapping,
  putDeductionMapping,
  exportCarrierFile,
  acknowledgeImport,
  listCarrierFiles,
  dashboardReport,
};

const API_ERROR = { payload: null, source: "api-error" };

function resolveUserTeamId() {
  return commonUtils.getCurrentUserTeamId();
}

function resolveActorId() {
  return commonUtils.getCurrentUserId();
}

function resolveEmployeeId() {
  return commonUtils.getCurrentUserId();
}

function withHr(params = {}) {
  return { ...params, userTeamId: resolveUserTeamId(), hrOrPayroll: true };
}

async function listPlans() {
  try {
    const response = await axiosUtils.getWithParam(`${urlConfig.BENEFITS_API_PATH}/plans`, withHr());
    const payload = response && response.payload != null ? response.payload : response;
    return Array.isArray(payload) ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function createPlan(body = {}) {
  try {
    const response = await axiosUtils.post(`${urlConfig.BENEFITS_API_PATH}/plans`, {
      ...body,
      userTeamId: body.userTeamId || resolveUserTeamId(),
      actorId: body.actorId || resolveActorId(),
      hrOrPayroll: true,
      active: body.active !== false,
      planType: (body.planType || "OTHER").toUpperCase(),
    });
    const payload = response && response.payload != null ? response.payload : response;
    return payload ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function updatePlan(planRef, body = {}) {
  try {
    const response = await axiosUtils.put(
      `${urlConfig.BENEFITS_API_PATH}/plans/${encodeURIComponent(planRef)}`,
      {
        ...body,
        userTeamId: body.userTeamId || resolveUserTeamId(),
        actorId: body.actorId || resolveActorId(),
        hrOrPayroll: true,
      }
    );
    const payload = response && response.payload != null ? response.payload : response;
    return payload ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function eligibility(employeeId, planId) {
  try {
    const response = await axiosUtils.getWithParam(`${urlConfig.BENEFITS_API_PATH}/eligibility`, {
      userTeamId: resolveUserTeamId(),
      employeeId: employeeId || resolveEmployeeId(),
      planId,
      hrOrPayroll: true,
    });
    const payload = response && response.payload != null ? response.payload : response;
    return payload ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function listEnrollments(employeeId) {
  try {
    const params = withHr();
    if (employeeId != null) params.employeeId = employeeId;
    const response = await axiosUtils.getWithParam(`${urlConfig.BENEFITS_API_PATH}/enrollments`, params);
    const payload = response && response.payload != null ? response.payload : response;
    return Array.isArray(payload) ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function getEnrollment(enrollmentRef, { hrOrPayroll = true } = {}) {
  try {
    const empId = resolveEmployeeId();
    const response = await axiosUtils.getWithParam(
      `${urlConfig.BENEFITS_API_PATH}/enrollments/${encodeURIComponent(enrollmentRef)}`,
      {
        userTeamId: resolveUserTeamId(),
        actorEmployeeId: empId,
        hrOrPayroll,
      }
    );
    const payload = response && response.payload != null ? response.payload : response;
    return payload ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function createEnrollment(body = {}) {
  try {
    const empId = body.employeeId || resolveEmployeeId();
    const response = await axiosUtils.post(`${urlConfig.BENEFITS_API_PATH}/enrollments`, {
      ...body,
      userTeamId: body.userTeamId || resolveUserTeamId(),
      actorId: body.actorId || resolveActorId(),
      actorEmployeeId: body.actorEmployeeId || empId,
      employeeId: empId,
      hrOrPayroll: body.hrOrPayroll === true,
    });
    const payload = response && response.payload != null ? response.payload : response;
    return payload ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

