export function getFlagGuideById(id) {
  return APP_CONFIG_FLAG_GUIDE.find((entry) => entry.id === id) || null;
}

export function flagGuideKeyPath(entry) {
  if (!entry) return "";
  return `${entry.group}.${entry.key}`;
}
