import React from "react";
import classNames from "classnames/bind";

export default function PolicyAnalyticsBarChart({ title, subtitle, series, suffix = "", maxValue }) {
  const rows = series || [];
  const peak = maxValue || Math.max(...rows.map((row) => row.value), 1);

  return (
    <article className="lux-policy-analytics__chart">
      <header className="lux-policy-analytics__chart-head">
        <div>
          <h4>{title}</h4>
          {subtitle && <span>{subtitle}</span>}
        </div>
      </header>
      {rows.length === 0 ? (
        <p className="lux-policy-analytics__empty">No data for this view.</p>
      ) : (
        <ul className="lux-policy-analytics__chart-list" role="list">
          {rows.map((row) => (
            <li key={row.label} className="lux-policy-analytics__chart-row" role="listitem">
              <span className="lux-policy-analytics__chart-label" title={row.label}>
                {row.label}
              </span>
              <div className="lux-policy-analytics__bar-track" aria-hidden="true">
                <div
                  className={classNames("lux-policy-analytics__bar-fill", row.tone && `is-${row.tone}`)}
                  style={{ width: `${Math.max(8, (row.value / peak) * 100)}%` }}
                />
              </div>
              <span className="lux-policy-analytics__chart-value">
                {row.value}
                {suffix}
                {row.meta ? ` · ${row.meta}` : ""}
              </span>
            </li>
          ))}
        </ul>
      )}
    </article>
  );
}
