import React from "react";
import { Link } from "react-router-dom";
import { history } from "_helpers";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { getPersonaLabel } from "config/persona-navigation.utils";
import ScopeBadge from "components/persona/ScopeBadge";
import { usePersonaContext } from "hooks/usePersonaContext";

/**
 * P00-T8: Access denied when direct URL hits a persona-restricted page.
 */
function PersonaAccessDenied({ denial }) {
  const { activePersona, landingRoute } = usePersonaContext();
  const pageName = (denial && denial.pageName) || "this page";
  const moduleName = (denial && denial.moduleName) || "module";

  const hints = [
    `You are viewing Tracopus as ${getPersonaLabel(activePersona)}.`,
  ];
  if (denial && denial.message) {
    hints.push(denial.message);
  } else if (denial && denial.requiredPersonas) {
    hints.push(`This page is limited to: ${denial.requiredPersonas.map(getPersonaLabel).join(", ")}.`);
  } else {
    hints.push("Try switching persona if you have another role, or contact your administrator.");
  }

  const title = denial && denial.code === "REPLACED_BY_GLOBAL_LEAVE"
    ? "Classic Leave policies are disabled while Global Leave is enabled"
    : `${pageName} is not available for your current view`;

  const description = denial && denial.code === "REPLACED_BY_GLOBAL_LEAVE"
    ? "Global Policy Center is your Leave admin surface. Open Global policies for accrual rules, or Types & fallback for the leave type catalog when that section is enabled."
    : `The ${moduleName} area is hidden or restricted for the ${getPersonaLabel(activePersona)} persona.`;

  return (
    <div className="lux-persona-access-denied" data-testid="persona-access-denied">
      <div className="lux-persona-access-denied__meta">
        <ScopeBadge showPersona />
      </div>
      <LuxRegisterEmptyState
        variant="employees"
        eyebrow={denial && denial.code === "REPLACED_BY_GLOBAL_LEAVE" ? "Feature replaced" : "Access restricted"}
        title={title}
        description={description}
        hints={hints}
        showSecondary
        secondaryLabel={denial && denial.code === "REPLACED_BY_GLOBAL_LEAVE" ? "Open Global policies" : "Go to your home"}
        secondaryIcon={denial && denial.code === "REPLACED_BY_GLOBAL_LEAVE" ? "fe fe-globe" : "fe fe-home"}
        onSecondary={() => {
          history.push(
            denial && denial.code === "REPLACED_BY_GLOBAL_LEAVE"
              ? "/admin/leave/global-policy-center"
              : (landingRoute || "/")
          );
        }}
        showCreate={activePersona !== "EMPLOYEE" && !(denial && denial.code === "REPLACED_BY_GLOBAL_LEAVE")}
        createLabel="Switch persona"
        createIcon="fe fe-repeat"
        onCreate={() => {
          const switcher = document.querySelector(".lux-persona-chip[data-toggle='dropdown']");
          if (switcher) {
            switcher.click();
          }
        }}
      />
      <p className="lux-persona-access-denied__help">
        Need access?{" "}
        <Link to="/people/settings">Contact your administrator</Link>
      </p>
    </div>
  );
}

export default PersonaAccessDenied;
