import React from "react";
import {
  REGISTER_DEFAULT_PAGE_SIZE,
  shouldShowRegisterPagination,
} from "_helpers/registerPagination.utils";
import { buildPageNumbers } from "views/project/searchPage.utils";

export default function LuxRegisterPagination({
  pagination,
  onPageChange,
  onPageSizeChange,
  pageSizeOptions = [10, 25, 50, 100],
  summaryLabel = "results",
  className = "",
  minTotalToShow = REGISTER_DEFAULT_PAGE_SIZE,
}) {
  if (!shouldShowRegisterPagination(pagination, minTotalToShow)) return null;

  const { page, totalPages, total, rangeStart, rangeEnd, pageSize } = pagination;
  const pageNumbers = buildPageNumbers(page, totalPages);

  return (
    <footer className={`lux-search-pagination lux-register-pagination ${className}`.trim()} data-tour="lux-pagination">
      <div className="lux-search-pagination__summary">
        Showing <strong>{rangeStart}–{rangeEnd}</strong> of <strong>{total}</strong> {summaryLabel}
      </div>

      <div className="lux-search-pagination__controls">
        <button
          type="button"
          className="lux-search-pagination__btn"
          disabled={page <= 1}
          onClick={() => onPageChange(page - 1)}
          aria-label="Previous page"
        >
          <i className="fe fe-chevron-left" aria-hidden="true" />
        </button>

        <div className="lux-search-pagination__pages" role="navigation" aria-label="Pagination">
          {pageNumbers.map((item, index) =>
            item === "ellipsis" ? (
              <span key={`ellipsis-${index}`} className="lux-search-pagination__ellipsis">…</span>
            ) : (
              <button
                key={item}
                type="button"
                className={`lux-search-pagination__page${page === item ? " is-active" : ""}`}
                onClick={() => onPageChange(item)}
                aria-current={page === item ? "page" : undefined}
              >
                {item}
              </button>
            )
          )}
        </div>

        <button
          type="button"
          className="lux-search-pagination__btn"
          disabled={page >= totalPages}
          onClick={() => onPageChange(page + 1)}
          aria-label="Next page"
        >
          <i className="fe fe-chevron-right" aria-hidden="true" />
        </button>
      </div>

      {onPageSizeChange && (
        <div className="lux-search-pagination__size">
          <label htmlFor="lux-register-page-size">Per page</label>
          <select
            id="lux-register-page-size"
            value={pageSize}
            onChange={(e) => onPageSizeChange(Number(e.target.value))}
          >
            {pageSizeOptions.map((size) => (
              <option key={size} value={size}>{size}</option>
            ))}
          </select>
        </div>
      )}
    </footer>
  );
}
