import { appConfigService } from '../_services';
import { commonUtils } from './common.utils';
import envconfig from '../env.config';
import { isDevEnvPilotEnabled, resolveDevEnvOrOrg } from './featurePilot.utils';

export const LEAVE_ADDITIONAL_CONFIG_KEY = 'leaveAdditional';
export const LEAVE_MANAGEMENT_ENABLED_KEY = 'leaveManagementEnabled';
export const LEAVE_CONFIG_CHANGED = 'famstack-leave-config-changed';

const HRMS_MODULE = 'HRMS';

let orgLeaveManagementEnabled = false;
let configLoaded = false;
let loadPromise = null;

export function readLeaveAdditionalFlag(configList, flagKey) {
  const group = commonUtils.getAppConfigValue(configList, LEAVE_ADDITIONAL_CONFIG_KEY);
  if (!group || typeof group !== 'object') {
    return false;
  }
  return group[flagKey] === true;
}

export function isLeaveManagementEnabledFromConfig(configList) {
  return readLeaveAdditionalFlag(configList, LEAVE_MANAGEMENT_ENABLED_KEY);
}

export function applyLeaveConfig(configList) {
  orgLeaveManagementEnabled = isLeaveManagementEnabledFromConfig(configList);
  configLoaded = true;
  return orgLeaveManagementEnabled;
}

export function isLeaveManagementOrgEnabled() {
  return orgLeaveManagementEnabled;
}

/** Env pilot ignored — leave management follows Application Config only. */
export function isLeaveManagementEnvEnabled() {
  return isDevEnvPilotEnabled(envconfig.LEAVE_MANAGEMENT_ENABLED);
}

/** Env pilot ignored — leave policy admin follows role RBAC only. */
export function isLeavePolicyAdminEnvEnabled() {
  return isDevEnvPilotEnabled(envconfig.LEAVE_POLICY_ADMIN_ENABLED);
}

/** Env pilot ignored — Global Policy Center follows role RBAC only. */
export function isGlobalLeavePolicyAdminEnvEnabled() {
  return isDevEnvPilotEnabled(envconfig.GLOBAL_LEAVE_POLICY_ADMIN_ENABLED);
}

/** HR leave policy admin — RBAC leavePolicies.* (env pilots disabled). */
export function isLeavePolicyAdminEnabled(leavePolicies) {
  const policies = leavePolicies || {};
  if (policies.createEnabled === true || policies.editEnabled === true) {
    return true;
  }
  return isLeavePolicyAdminEnvEnabled() && shouldUseLeaveManagement();
}

/**
 * Global leave policy admin — role adminModules.globalLeavePoliciesEnabled.
 */
export function isGlobalLeavePolicyAdminEnabled(leavePolicies, roleAdminModules) {
  if (isGlobalLeavePolicyAdminEnvEnabled() && shouldUseLeaveManagement()) {
    return true;
  }
  if (roleAdminModules && roleAdminModules.globalLeavePoliciesEnabled === true) {
    return isLeavePolicyAdminEnabled(leavePolicies);
  }
  // Backward compatible: same gate as classic leave policies when role key absent.
  if (
    !roleAdminModules ||
    !Object.prototype.hasOwnProperty.call(roleAdminModules, "globalLeavePoliciesEnabled")
  ) {
    return isLeavePolicyAdminEnabled(leavePolicies);
  }
  return false;
}

export function isLeaveMenuEnabled(hrmsModules, hrmsModuleActive) {
  if (hrmsModuleActive !== true) {
    return false;
  }
  const modules = hrmsModules || {};
  // Role menu flag is authoritative — org leave pilots must not bypass role.json.
  return modules.leavesEnabled === true;
}

export function isLeaveConfigLoaded() {
  return configLoaded;
}

export function notifyLeaveConfigChanged() {
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent(LEAVE_CONFIG_CHANGED));
  }
}

export function loadLeaveConfig(force, teamIdOverride) {
  if (!force && configLoaded) {
    return Promise.resolve(orgLeaveManagementEnabled);
  }
  if (!force && loadPromise) {
    return loadPromise;
  }

  const teamId = teamIdOverride || commonUtils.getCurrentUserTeamId();
  if (!teamId) {
    orgLeaveManagementEnabled = false;
    configLoaded = true;
    return Promise.resolve(false);
  }

  loadPromise = appConfigService
    .getModuleConfig(teamId, HRMS_MODULE)
    .then((response) => {
      const list = response && response.payload;
      applyLeaveConfig(list);
      notifyLeaveConfigChanged();
      return orgLeaveManagementEnabled;
    })
    .catch(() => {
      orgLeaveManagementEnabled = false;
      configLoaded = true;
      return false;
    })
    .finally(() => {
      loadPromise = null;
    });

  return loadPromise;
}

export function refreshLeaveConfig(teamIdOverride) {
  configLoaded = false;
  return loadLeaveConfig(true, teamIdOverride);
}

/**
 * Org `leaveAdditional.leaveManagementEnabled` from Application Config.
 * Menu visibility still requires role.json `hrmsModules.leavesEnabled`.
 */
export function shouldUseLeaveManagement() {
  return resolveDevEnvOrOrg(envconfig.LEAVE_MANAGEMENT_ENABLED, isLeaveManagementOrgEnabled());
}

/**
 * Leave team scope for multi-team orgs (Tracopus).
 * Selected PageInnerHeader teams → all profile teams → default team.
 * Never returns an empty list when the user has a default team.
 */
export function resolveLeaveUserTeamIds(userTeamsProp) {
  const teams = commonUtils.getUserTeams(userTeamsProp) || [];
  const selected = teams.filter((t) => t && t.isChecked).map((t) => t.id).filter((id) => id != null);
  if (selected.length) {
    return selected;
  }
  const fromMenu = teams.map((t) => t && t.id).filter((id) => id != null);
  if (fromMenu.length) {
    return fromMenu;
  }
  const all = commonUtils.getCurrentUserTeamIds() || [];
  if (all.length) {
    return all;
  }
  const current = commonUtils.getCurrentUserTeamId();
  return current != null ? [current] : [];
}

/**
 * Teams list for leave PageInnerHeader. Defaults every team to checked so
 * leave covers all employees until the user narrows the selection.
 * Call once on page mount / when redux userTeams is empty.
 */
export function buildLeaveUserTeamsAllSelected(userTeamsProp) {
  const base = commonUtils.getUserTeams(userTeamsProp) || [];
  return base.map((team) => ({
    ...team,
    isChecked: true,
  }));
}

/** Primary team for write operations when multiple teams are in scope. */
export function resolveLeaveWriteUserTeamId(userTeamsProp) {
  const ids = resolveLeaveUserTeamIds(userTeamsProp);
  if (ids.length) {
    return ids[0];
  }
  return commonUtils.getCurrentUserTeamId();
}

/** Axios/query params: prefer userTeamIds array; fall back to singular. */
export function leaveTeamQueryParams(userTeamIdsOrId) {
  if (Array.isArray(userTeamIdsOrId)) {
    if (userTeamIdsOrId.length) {
      return { userTeamIds: userTeamIdsOrId };
    }
    return {};
  }
  if (userTeamIdsOrId != null && userTeamIdsOrId !== '') {
    return { userTeamId: userTeamIdsOrId };
  }
  return {};
}

/** Run a per-team list and flatten (for APIs that are still single-team). */
export async function listLeaveAcrossTeams(userTeamIds, listOneFn) {
  const ids = Array.isArray(userTeamIds) ? userTeamIds.filter((id) => id != null) : [];
  if (!ids.length) {
    return [];
  }
  const chunks = await Promise.all(
    ids.map((id) =>
      Promise.resolve(listOneFn(id))
        .then((res) => {
          if (Array.isArray(res)) return res;
          if (res && Array.isArray(res.payload)) return res.payload;
          return [];
        })
        .catch(() => [])
    )
  );
  return chunks.flat();
}
