import React from "react";
import classNames from "classnames/bind";
import { getApprovalDomainMeta } from "config/universal-approval.config";
import {
  getApprovalPolicyStatusTone,
  formatApprovalPolicySla,
} from "config/approval-policy.config";

function formatUpdatedAt(value) {
  if (!value) {
    return null;
  }
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return value;
  }
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

export default function ApprovalPolicyRegister({ policies, onEdit }) {
  return (
    <div className="lux-appr-policy-gallery" role="list" aria-label="Approval policies">
      {(policies || []).map((policy) => {
        const domainMeta = getApprovalDomainMeta(policy.domain);
        const isDraft = String(policy.status).toLowerCase() === "draft";
        const isActive = String(policy.status).toLowerCase() === "active";
        const chain = policy.approverLevels || [];
        const canEdit = typeof onEdit === "function";

        return (
          <article
            key={policy.id}
            role="listitem"
            className={classNames("lux-appr-policy-card", {
              "is-draft": isDraft,
              "is-active": isActive,
            })}
          >
            <header className="lux-appr-policy-card__head">
              <span
                className={classNames(
                  "lux-appr-policy-card__avatar",
                  domainMeta.tone && `is-${domainMeta.tone}`
                )}
                aria-hidden="true"
              >
                <i className={domainMeta.icon || "fe fe-shield"} />
              </span>

              <div className="lux-appr-policy-card__identity">
                <div className="lux-appr-policy-card__title-row">
                  <h3 className="lux-appr-policy-card__title">{policy.name}</h3>
                  <span
                    className={classNames(
                      "lux-appr-policy-card__status",
                      `is-${getApprovalPolicyStatusTone(policy.status)}`
                    )}
                  >
                    {isActive ? "Live" : policy.status}
                  </span>
                </div>
                <div className="lux-appr-policy-card__meta">
                  <span
                    className={classNames(
                      "lux-appr-policy-card__domain",
                      domainMeta.tone && `is-${domainMeta.tone}`
                    )}
                  >
                    <i className={domainMeta.icon} aria-hidden="true" />
                    {domainMeta.label}
                  </span>
                  {domainMeta.module ? (
                    <em className="lux-appr-policy-card__module">{domainMeta.module}</em>
                  ) : null}
                  {policy.updatedAt ? (
                    <span className="lux-appr-policy-card__updated">
                      Updated {formatUpdatedAt(policy.updatedAt)}
                    </span>
                  ) : null}
                </div>
              </div>

              {canEdit ? (
                <button
                  type="button"
                  className="lux-appr-policy-card__edit"
                  onClick={() => onEdit(policy)}
                  data-testid={`approval-policy-edit-${policy.id}`}
                >
                  <i className="fe fe-edit-2" aria-hidden="true" />
                  Edit
                </button>
              ) : null}
            </header>

            {policy.description ? (
              <p className="lux-appr-policy-card__desc">{policy.description}</p>
            ) : null}

            <div className="lux-appr-policy-card__pulse" aria-label="Policy controls">
              <div className="lux-appr-policy-card__metric">
                <span className="lux-appr-policy-card__metric-label">SLA window</span>
                <strong className="lux-appr-policy-card__metric-value">
                  {formatApprovalPolicySla(policy)}
                </strong>
              </div>
              <div className="lux-appr-policy-card__metric">
                <span className="lux-appr-policy-card__metric-label">Escalation</span>
                <strong
                  className={classNames("lux-appr-policy-card__metric-value", {
                    "is-on": policy.autoEscalate,
                    "is-off": !policy.autoEscalate,
                  })}
                >
                  {policy.autoEscalate ? "Auto" : "Manual"}
                </strong>
              </div>
              <div className="lux-appr-policy-card__metric">
                <span className="lux-appr-policy-card__metric-label">Reminders</span>
                <strong
                  className={classNames("lux-appr-policy-card__metric-value", {
                    "is-on": policy.reminderEnabled,
                    "is-off": !policy.reminderEnabled,
                  })}
                >
                  {policy.reminderEnabled ? "On" : "Off"}
                </strong>
              </div>
              <div className="lux-appr-policy-card__metric">
                <span className="lux-appr-policy-card__metric-label">Levels</span>
                <strong className="lux-appr-policy-card__metric-value">{chain.length || 0}</strong>
              </div>
            </div>

            <div className="lux-appr-policy-card__chain" aria-label="Approver chain">
              <span className="lux-appr-policy-card__chain-label">Approver chain</span>
              <div className="lux-appr-policy-card__chain-track">
                {chain.length === 0 ? (
                  <span className="lux-appr-policy-card__chain-empty">No levels configured</span>
                ) : (
                  chain.map((level, index) => (
                    <React.Fragment key={`${policy.id}-${level}-${index}`}>
                      {index > 0 ? (
                        <span className="lux-appr-policy-card__chain-sep" aria-hidden="true">
                          <i className="fe fe-chevron-right" />
                        </span>
                      ) : null}
                      <span className="lux-appr-policy-card__chain-step">
                        <em>{index + 1}</em>
                        {level}
                      </span>
                    </React.Fragment>
                  ))
                )}
              </div>
            </div>
          </article>
        );
      })}
    </div>
  );
}
