import { axiosUtils, commonUtils } from '../_helpers';
import urlConfig from 'url.config';

export const auditService = {
  getEvents,
  getActorTimeline,
  getEntityTimeline,
  getProjectAudit,
  getPurchaseOrderAudit,
  getEmployeeAudit,
  getDeliverableAudit,
  getAttendanceAudit,
  getLeaveAudit,
  getTimesheetWeekAudit,
  exportEvents,
  recordEvent,
};

function withViewer(params = {}) {
  const viewerUserId = commonUtils.getCurrentUserId();
  return viewerUserId ? { ...params, viewerUserId } : params;
}

function buildQuery(params = {}) {
  const parts = [];
  Object.entries(params).forEach(([key, value]) => {
    if (value === undefined || value === null || value === '') return;
    if (Array.isArray(value)) {
      if (value.length) parts.push(`${encodeURIComponent(key)}=${encodeURIComponent(value.join(','))}`);
      return;
    }
    parts.push(`${encodeURIComponent(key)}=${encodeURIComponent(value)}`);
  });
  return parts.length ? `?${parts.join('&')}` : '';
}

async function getEvents(params) {
  return axiosUtils.get(`${urlConfig.AUDIT_API_PATH}/events${buildQuery(withViewer(params))}`);
}

async function exportEvents(params = {}) {
  return axiosUtils.get(`${urlConfig.AUDIT_API_PATH}/events/export${buildQuery(withViewer(params))}`, {
    responseType: 'blob',
  });
}

async function getActorTimeline(actorUserId, params = {}) {
  return getEvents({ ...params, actorUserId });
}

async function getEntityTimeline(entityType, entityId, params = {}) {
  return getEvents({ ...params, entityType, entityId });
}

async function getProjectAudit(projectId, params = {}) {
  return axiosUtils.get(`${urlConfig.PROJECT_GET_INFO}/${projectId}/audit${buildQuery(withViewer(params))}`);
}

async function getPurchaseOrderAudit(purchaseOrderId, params = {}) {
  return axiosUtils.get(`${urlConfig.PURCHASE_ORDER_PATH}/${purchaseOrderId}/audit${buildQuery(withViewer(params))}`);
}

async function getEmployeeAudit(employeeId, params = {}) {
  return axiosUtils.get(`${urlConfig.EMPLOYEE_GET_INFO}/${employeeId}/audit${buildQuery(withViewer(params))}`);
}

async function getDeliverableAudit(deliverableId, params = {}) {
  return getEntityTimeline('DELIVERABLE', deliverableId, params);
}

async function getAttendanceAudit(attendanceId, params = {}) {
  return axiosUtils.get(`${urlConfig.EMPLOYEE_GET_INFO}/attendance/${attendanceId}/audit${buildQuery(withViewer(params))}`);
}

async function getLeaveAudit(leaveId, params = {}) {
  return axiosUtils.get(`${urlConfig.LEAVES_API_PATH}/${leaveId}/audit${buildQuery(withViewer(params))}`);
}

async function getTimesheetWeekAudit(weekId, params = {}) {
  return axiosUtils.get(`${urlConfig.TIMESHEETS_API_PATH}/weeks/${weekId}/audit${buildQuery(withViewer(params))}`);
}

async function recordEvent(request) {
  const actorUserId = commonUtils.getCurrentUserId();
  if (!actorUserId) {
    return null;
  }
  return axiosUtils.post(
    `${urlConfig.AUDIT_API_PATH}/events?actorUserId=${encodeURIComponent(actorUserId)}`,
    request
  );
}
