import { scheduleActions } from "_actions";
import LuxListCountSkeleton from "views/common/fragments/LuxListCountSkeleton";
import { employeeActions } from "_actions";
import { appConfigActions } from "_actions";
import { store } from "_helpers";
import React, { Component } from "react";
import LuxRegisterListSkeletonRows from "views/common/fragments/LuxRegisterListSkeletonRows";
import classNames from "classnames/bind";
import { connect } from "react-redux";
import SettingsTabShell from "../settings/SettingsTabShell";
import ScheduleListRow from "./ScheduleListRow";
import { buildScheduleSummary } from "../settings/settingsTab.utils";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

class ScheduleListSection extends Component {
  componentDidMount() {
    store.dispatch(this.props.getAllScheulers());
    store.dispatch(this.props.getAllEmployees());
    store.dispatch(this.props.getAllTeams());
  }

  isLoading = () => {
    return this.props.allEmployees == null || this.props.allUserTeams == null;
  };

  render() {
    const items = this.props.items || [];
    const summary = buildScheduleSummary(items);
    const loading = this.isLoading();

    return (
      <SettingsTabShell
        icon="fe fe-clock"
        eyebrow="Automation"
        title="Schedulers"
        subtitle="Background jobs that run reports, syncs, and maintenance tasks on a cron schedule."
        stats={summary.stats}
      >
        <div className="lux-schedule-register">
          <header className="lux-schedule-register__bar">
            <span className="lux-schedule-register__label">
              <i className="fe fe-list" aria-hidden="true" />
              Scheduler register
            </span>
            <span className="lux-schedule-register__count">
              {loading ? <LuxListCountSkeleton /> : `${summary.total} job${summary.total === 1 ? "" : "s"}`}
            </span>
          </header>

          <div className="lux-schedule-register__head" role="row">
            <span>#</span>
            <span>Status</span>
            <span>Job</span>
            <span>Runs</span>
            <span className="is-actions">Power</span>
          </div>

          <div
            className={classNames("lux-schedule-register__body", { "is-loading": loading })}
            role="list"
          >
            {loading && <LuxRegisterListSkeletonRows variant="schedule" rowCount={12} />}
            {!loading &&
              items.map((item, index) => (
                <ScheduleListRow
                  key={item.id}
                  item={item}
                  rowIndex={index + 1}
                  onEnable={(isEnabled) =>
                    store.dispatch(
                      this.props.enableSchedule({ itemId: item.id, isEnabled })
                    )
                  }
                  onRemove={() =>
                    store.dispatch(this.props.removeSchedule({ itemId: item.id }))
                  }
                />
              ))}
          </div>

          {!loading && items.length === 0 && (
            <LuxRegisterEmptyState
              variant="pending-tasks"
              eyebrow="Schedulers"
              title="No schedulers configured"
              description="Background jobs will appear here when your administrator adds cron schedules for this workspace."
              hints={[
                "Enable a scheduler to run it on the next cron tick",
                "Pause jobs without removing their configuration",
                "Removed jobs stay listed until cleared from the server",
              ]}
              showCreate={false}
              className="lux-schedule-register__empty"
            />
          )}
        </div>

        <p className="lux-hrms-settings__note">
          <i className="fe fe-info" aria-hidden="true" /> Use <strong>Paused</strong> or <strong>Active</strong> to control each job. Remove requires a second click to confirm.
        </p>
      </SettingsTabShell>
    );
  }
}

const mapStateToProps = (state) => ({
  items: state.schedules.items,
  allEmployees: state.employees.allEmployees,
  allUserTeams: state.appconfig.allTeams,
});

const mapDispatchToProps = () => ({
  getAllTeams: appConfigActions.getAllTeams,
  getAllEmployees: employeeActions.getAllEmployees,
  getAllScheulers: scheduleActions.getAllSchedules,
  enableSchedule: scheduleActions.enableSchedule,
  removeSchedule: scheduleActions.removeSchedule,
});

export default connect(mapStateToProps, mapDispatchToProps)(ScheduleListSection);
