export const BRAND_TAGLINE_TEXT = "Enterprise work intelligence";
export const BRAND_TAGLINE_BASE_FONT_PX = 7;

export function fitBrandTaglineToLogo(logoEl, shellEl, taglineEl, baseFontPx = BRAND_TAGLINE_BASE_FONT_PX) {
  if (!logoEl || !shellEl || !taglineEl) {
    return;
  }

  const img = logoEl.tagName === "IMG" ? logoEl : logoEl.querySelector("img");
  if (!img) {
    return;
  }

  const targetWidth = img.getBoundingClientRect().width;
  if (targetWidth <= 0) {
    return;
  }

  shellEl.style.width = `${targetWidth}px`;

  taglineEl.style.width = "auto";
  taglineEl.style.maxWidth = "none";
  taglineEl.style.overflow = "visible";
  taglineEl.style.transform = "none";
  taglineEl.style.fontSize = `${baseFontPx}px`;

  const naturalWidth = taglineEl.getBoundingClientRect().width;
  if (naturalWidth <= 0) {
    return;
  }

  const scaleX = targetWidth / naturalWidth;
  taglineEl.style.transform = `scaleX(${scaleX})`;
  taglineEl.style.transformOrigin = "center center";
}

export function attachBrandTaglineFit(logoEl, shellEl, taglineEl, baseFontPx = BRAND_TAGLINE_BASE_FONT_PX) {
  if (!logoEl || !shellEl || !taglineEl) {
    return function noopCleanup() {};
  }

  const sync = () => {
    window.requestAnimationFrame(() => {
      fitBrandTaglineToLogo(logoEl, shellEl, taglineEl, baseFontPx);
    });
  };

  const img = logoEl.tagName === "IMG" ? logoEl : logoEl.querySelector("img");

  let observer;
  if (typeof ResizeObserver !== "undefined" && img) {
    observer = new ResizeObserver(sync);
    observer.observe(img);
  }

  if (img) {
    if (img.complete) {
      sync();
    } else {
      img.addEventListener("load", sync);
    }
  } else {
    sync();
  }

  window.addEventListener("resize", sync);
  if (document.fonts && document.fonts.ready) {
    document.fonts.ready.then(sync).catch(() => undefined);
  }

  return function cleanupBrandTaglineFit() {
    if (observer) {
      observer.disconnect();
    }
    if (img) {
      img.removeEventListener("load", sync);
    }
    window.removeEventListener("resize", sync);
  };
}
