import React from 'react';
import { Link } from 'react-router-dom';
import { connect } from 'react-redux';
import { withRouter } from 'react-router-dom';
import { leavePhase2Service as api } from '_services/leavePhase2.service';
import {
  LeavePhase2AdminBase,
  LeavePhase2Panel,
  LeavePhase2Register,
  mapLeavePhase2State,
  cell,
} from './leavePhase2.shared';
import '../leaveLuxForms.css';

function caseIdFromMatch(match) {
  const id = match && match.params && match.params.id;
  return id ? Number(id) : null;
}

class AbsenceCaseDetailPage extends LeavePhase2AdminBase {
  state = {
    ...this.state,
    caseDetail: null,
    blocks: [],
    events: [],
    rtw: null,
  };

  fetchSectionData = async () => {
    const caseId = caseIdFromMatch(this.props.match);
    if (!caseId) {
      this.setState({ caseDetail: null, blocks: [], events: [], rtw: null });
      return;
    }
    const managerView = !this.props.location.pathname.startsWith('/people/');
    const [caseDetail, blocks, events, rtw] = await Promise.all([
      api.getAbsenceCase(caseId, managerView),
      api.listAbsenceBlocks(caseId),
      api.listAbsenceEvents(caseId, managerView),
      api.getReturnToWork(caseId, managerView),
    ]);
    this.setState({
      caseDetail: caseDetail || null,
      blocks: Array.isArray(blocks) ? blocks : [],
      events: Array.isArray(events) ? events : [],
      rtw: rtw || null,
    });
  };

  render() {
    const { loading, caseDetail, blocks, events, rtw } = this.state;
    const backTo = this.props.location.pathname.startsWith('/people/')
      ? '/people/leave/absence-cases'
      : '/admin/leave/absence-cases';

    return this.renderChrome({
      testId: 'page-leave-absence-case-detail',
      pageMeta: {
        tone: 'emerald',
        icon: 'fe fe-briefcase',
        eyebrow: 'Absence case',
        titleLead: caseDetail ? `Case #${caseDetail.id || ''}` : 'Case',
        titleAccent: 'detail',
        lede: 'Timeline, schedule blocks, confidential notes, and return-to-work clearance.',
      },
      heroActions: (
        <>
          <Link to={backTo} className="lux-onb-action lux-admin-action lux-onb-action--ghost">
            <i className="fe fe-arrow-left" aria-hidden="true" />
            <span>Back</span>
          </Link>
        </>
      ),
      children: (
        <>
          {caseDetail ? (
            <div className="lux-glp-resolve-summary" data-testid="glp17-case-summary">
              <dl className="lux-glp-kv">
                <div><dt>Employee</dt><dd>{cell(caseDetail.employeeId)}</dd></div>
                <div><dt>Type</dt><dd>{cell(caseDetail.caseType || caseDetail.absenceType)}</dd></div>
                <div><dt>Status</dt><dd>{cell(caseDetail.status)}</dd></div>
                <div><dt>Start</dt><dd>{cell(caseDetail.startDate)}</dd></div>
                <div><dt>End</dt><dd>{cell(caseDetail.endDate)}</dd></div>
              </dl>
            </div>
          ) : !loading ? (
            <LeavePhase2Panel title="Case not found">
              <p className="lux-leave-subpanel__sub">This absence case is unavailable or outside your scope.</p>
            </LeavePhase2Panel>
          ) : null}

          <LeavePhase2Panel title="Schedule blocks" subtitle="Intermittent and reduced-schedule segments.">
            <LeavePhase2Register
              loading={loading}
              rows={blocks}
              testId="glp17-blocks-register"
              emptyTitle="No schedule blocks"
              columns={[
                { key: 'id', label: 'Block' },
                { key: 'startDate', label: 'Start' },
                { key: 'endDate', label: 'End' },
                { key: 'scheduleType', label: 'Schedule' },
              ]}
            />
          </LeavePhase2Panel>

          <LeavePhase2Panel title="Case timeline" subtitle="Masked events — medical details are not shown in snippets.">
            <LeavePhase2Register
              loading={loading}
              rows={events}
              testId="glp17-events-register"
              emptyTitle="No timeline events"
              columns={[
                { key: 'eventAt', label: 'When', render: (r) => cell(r.eventAt || r.createdAt) },
                { key: 'eventType', label: 'Type' },
                { key: 'summary', label: 'Summary', render: (r) => cell(r.summary || r.maskedSummary) },
              ]}
            />
          </LeavePhase2Panel>

          <LeavePhase2Panel title="Return to work" subtitle="Fit-to-work clearance and documentation status.">
            {rtw ? (
              <div className="lux-glp-resolve-summary" data-testid="glp17-rtw-panel">
                <dl className="lux-glp-kv">
                  <div><dt>Status</dt><dd>{cell(rtw.status)}</dd></div>
                  <div><dt>Cleared</dt><dd>{cell(rtw.cleared)}</dd></div>
                  <div><dt>Target date</dt><dd>{cell(rtw.targetReturnDate || rtw.plannedReturnDate)}</dd></div>
                  <div><dt>Notes</dt><dd>{cell(rtw.maskedNotes || rtw.notes)}</dd></div>
                </dl>
              </div>
            ) : (
              <LeavePhase2Register
                loading={loading}
                rows={[]}
                emptyTitle="No return-to-work record"
                emptyDescription="RTW clearance is created when the case moves to return planning."
              />
            )}
          </LeavePhase2Panel>
        </>
      ),
    });
  }
}

export default connect(mapLeavePhase2State)(withRouter(AbsenceCaseDetailPage));
