import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import { commonUtils } from "_helpers";

class AttendanceEmployeeFilter extends PureComponent {
  constructor() {
    super();
    this.state = {
      open: false,
      filterText: "",
    };
    this.triggerRef = React.createRef();
    this.panelRef = React.createRef();
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick);
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
  }

  handleOutsideClick = (event) => {
    if (!this.state.open) return;
    const panel = this.panelRef.current;
    const trigger = this.triggerRef.current;
    if (
      panel &&
      !panel.contains(event.target) &&
      trigger &&
      !trigger.contains(event.target)
    ) {
      this.closePanel();
    }
  };

  closePanel = () => {
    this.setState({ open: false, filterText: "" });
  };

  togglePanel = () => {
    if (this.props.isLoading) return;
    this.setState((prev) => ({
      open: !prev.open,
      filterText: prev.open ? "" : prev.filterText,
    }));
  };

  selectAll = () => {
    this.props.onChange(null);
    this.closePanel();
  };

  selectEmployee = (employeeId) => {
    this.props.onChange(employeeId);
    this.closePanel();
  };

  getSelectedLabel = () => {
    const { employees, selectedEmployeeId } = this.props;
    if (selectedEmployeeId == null || selectedEmployeeId === "") {
      return "All employees";
    }
    const match =
      employees && employees.find((emp) => String(emp.id) === String(selectedEmployeeId));
    return (match && match.name) || "Employee";
  };

  renderPanel = () => {
    const { employees, selectedEmployeeId, isLoading } = this.props;
    const { filterText } = this.state;
    const filtered =
      employees &&
      employees.filter(
        (employee) =>
          !filterText || commonUtils.stringContainsString(employee.name, filterText)
      );

    return (
      <div className="lux-att-employee-filter__panel" ref={this.panelRef}>
        <header className="lux-att-employee-filter__panel-head">
          <strong>Filter by employee</strong>
          <button
            type="button"
            className="lux-att-employee-filter__panel-close"
            onClick={this.closePanel}
            aria-label="Close employee filter"
          >
            <i className="fe fe-x" aria-hidden="true" />
          </button>
        </header>

        <label className="lux-att-employee-filter__search">
          <i className="fe fe-search" aria-hidden="true" />
          <input
            type="search"
            value={filterText}
            onChange={(e) => this.setState({ filterText: e.target.value })}
            placeholder="Search employees..."
            disabled={isLoading}
          />
        </label>

        <ul className="lux-att-employee-filter__list">
          <li>
            <button
              type="button"
              className={classNames("lux-att-employee-filter__option", {
                "is-selected": selectedEmployeeId == null || selectedEmployeeId === "",
              })}
              onClick={this.selectAll}
            >
              <i className="fe fe-users" aria-hidden="true" />
              <span>All employees</span>
            </button>
          </li>
          {filtered && filtered.length > 0 ? (
            filtered.map((employee) => (
              <li key={employee.id}>
                <button
                  type="button"
                  className={classNames("lux-att-employee-filter__option", {
                    "is-selected": String(employee.id) === String(selectedEmployeeId),
                    "is-self": String(employee.id) === String(commonUtils.getCurrentUserId()),
                  })}
                  onClick={() => this.selectEmployee(employee.id)}
                >
                  <i className="fe fe-user" aria-hidden="true" />
                  <span>{employee.name}</span>
                  {employee.designation && (
                    <em>{employee.designation}</em>
                  )}
                </button>
              </li>
            ))
          ) : (
            <li className="lux-att-employee-filter__empty">No employees match your search.</li>
          )}
        </ul>
      </div>
    );
  };

  render() {
    const { isLoading, variant } = this.props;
    const isMatrix = variant === "matrix";

    return (
      <div
        className={classNames("lux-att-employee-filter", {
          "is-matrix": isMatrix,
          "is-header": !isMatrix,
        })}
        ref={this.triggerRef}
      >
        <button
          type="button"
          className={classNames("lux-att-employee-filter__trigger", {
            "is-open": this.state.open,
          })}
          onClick={this.togglePanel}
          disabled={isLoading}
          aria-expanded={this.state.open}
          aria-haspopup="listbox"
          title="Filter employees"
        >
          <i className="fe fe-filter" aria-hidden="true" />
          <span className="lux-att-employee-filter__label">{this.getSelectedLabel()}</span>
          <i className="fe fe-chevron-down lux-att-employee-filter__chevron" aria-hidden="true" />
        </button>
        {this.state.open && this.renderPanel()}
      </div>
    );
  }
}

export default AttendanceEmployeeFilter;
