/**
 * SEC-VAPT — strip dangerous markup before rendering rich HTML in the DOM.
 */
export function escapeHtml(text) {
  if (text == null) {
    return "";
  }
  return String(text)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

export function sanitizeRichHtml(html) {
  if (html == null || typeof html !== "string" || !html.trim()) {
    return html;
  }

  if (typeof DOMParser === "undefined") {
    return html.replace(/<script[\s\S]*?>[\s\S]*?<\/script>/gi, "");
  }

  const doc = new DOMParser().parseFromString(html, "text/html");
  doc.querySelectorAll("script, iframe, object, embed, form, link, meta, base, style").forEach((node) => {
    node.remove();
  });

  doc.querySelectorAll("*").forEach((element) => {
    [...element.attributes].forEach((attribute) => {
      const name = attribute.name.toLowerCase();
      const value = (attribute.value || "").trim().toLowerCase();
      if (
        name.startsWith("on")
        || (name === "href" && (value.startsWith("javascript:") || value.startsWith("data:")))
        || (name === "src" && value.startsWith("javascript:"))
      ) {
        element.removeAttribute(attribute.name);
      }
    });
  });

  return doc.body.innerHTML;
}
