import React, { useEffect, useMemo, useState } from "react";
import classNames from "classnames/bind";
import moment from "moment";
import TimesheetLuxuryDialog from "./TimesheetLuxuryDialog";
import {
  CONFLICT_RESOLUTION_OPTIONS,
  formatTimesheetWeekRange,
  getConflictTypeLabel,
} from "./timesheetApproval.utils";

function formatConflictDate(value) {
  if (!value) return "—";
  const parsed = moment(value);
  return parsed.isValid() ? parsed.format("D MMM YYYY") : "—";
}

function TimesheetConflictModal({
  show,
  week,
  conflicts,
  loading,
  resolverId,
  onResolve,
  onClose,
  onRefresh,
}) {
  const [selections, setSelections] = useState({});
  const [comments, setComments] = useState({});
  const [resolvingId, setResolvingId] = useState(null);
  const [errors, setErrors] = useState({});

  const openConflicts = useMemo(
    () => (conflicts || []).filter((item) => item.resolutionStatus !== "RESOLVED"),
    [conflicts]
  );

  useEffect(() => {
    if (!show) {
      setSelections({});
      setComments({});
      setResolvingId(null);
      setErrors({});
    }
  }, [show]);

  const handleResolve = async (conflict) => {
    if (!onResolve || !conflict || !resolverId) return;
    const action = selections[conflict.id];
    if (!action) {
      setErrors((prev) => ({
        ...prev,
        [conflict.id]: "Choose how to resolve this conflict.",
      }));
      return;
    }
    setResolvingId(conflict.id);
    setErrors((prev) => ({ ...prev, [conflict.id]: null }));
    try {
      await onResolve(conflict.id, {
        resolverId,
        resolutionAction: action,
        resolutionComment: (comments[conflict.id] || "").trim() || null,
      });
      if (onRefresh) {
        await onRefresh();
      }
    } finally {
      setResolvingId(null);
    }
  };

  const title = week
    ? `${week.employeeName || "Employee"} — ${formatTimesheetWeekRange(week)}`
    : "Timesheet conflicts";

  return (
    <TimesheetLuxuryDialog
      show={show}
      onClose={onClose}
      wide
      ariaLabel="Resolve timesheet conflicts"
      kicker="Manager review"
      kickerIcon="fe-alert-triangle"
      title="Resolve conflicts"
      subtitle={title}
      badge={
        openConflicts.length
          ? { tone: "amber", label: `${openConflicts.length} open` }
          : { tone: "green", label: "All resolved" }
      }
      footer={
        <p className="lux-ts-conflict__foot-note">
          Approval is blocked until all conflicts for this week are resolved.
        </p>
      }
    >
      {loading && !openConflicts.length ? (
        <p className="lux-ts-conflict__empty">Loading conflicts…</p>
      ) : null}

      {!loading && !openConflicts.length ? (
        <p className="lux-ts-conflict__empty">No open conflicts. You can approve this timesheet.</p>
      ) : null}

      <ul className="lux-ts-conflict__list">
        {openConflicts.map((conflict) => (
          <li key={conflict.id} className="lux-ts-conflict__item">
            <div className="lux-ts-conflict__item-head">
              <strong>{getConflictTypeLabel(conflict.conflictType)}</strong>
              <span>{formatConflictDate(conflict.activityDate)}</span>
            </div>

            <div className="lux-ts-conflict__options" role="radiogroup" aria-label="Resolution action">
              {CONFLICT_RESOLUTION_OPTIONS.map((option) => (
                <label
                  key={option.id}
                  className={classNames("lux-ts-conflict__option", {
                    "is-selected": selections[conflict.id] === option.id,
                  })}
                >
                  <input
                    type="radio"
                    name={`conflict-action-${conflict.id}`}
                    value={option.id}
                    checked={selections[conflict.id] === option.id}
                    disabled={resolvingId === conflict.id || loading}
                    onChange={() =>
                      setSelections((prev) => ({ ...prev, [conflict.id]: option.id }))
                    }
                  />
                  <span>
                    <strong>{option.label}</strong>
                    <em>{option.hint}</em>
                  </span>
                </label>
              ))}
            </div>

            <label className="lux-ts-conflict__comment" htmlFor={`conflict-comment-${conflict.id}`}>
              <span>Resolution note (optional)</span>
              <textarea
                id={`conflict-comment-${conflict.id}`}
                rows={2}
                maxLength={512}
                value={comments[conflict.id] || ""}
                disabled={resolvingId === conflict.id || loading}
                onChange={(event) =>
                  setComments((prev) => ({ ...prev, [conflict.id]: event.target.value }))
                }
              />
            </label>

            {errors[conflict.id] && (
              <p className="lux-ts-conflict__error" role="alert">
                {errors[conflict.id]}
              </p>
            )}

            <div className="lux-ts-conflict__item-actions">
              <button
                type="button"
                className={classNames("lux-ts-conflict__resolve-btn", {
                  "is-loading": resolvingId === conflict.id,
                })}
                disabled={resolvingId === conflict.id || loading}
                onClick={() => handleResolve(conflict)}
              >
                Resolve conflict
              </button>
            </div>
          </li>
        ))}
      </ul>
    </TimesheetLuxuryDialog>
  );
}

export default TimesheetConflictModal;
