import React, { Component } from "react";
import { creditNotesService } from "_services/creditNotes.service";
import { commonUtils } from "_helpers";
import FinanceLuxPage, {
  FinanceActionButton,
  FinanceLuxPanel,
} from "views/finance/components/FinanceLuxShared";
import FinanceLoadAlert from "views/finance/components/FinanceLoadAlert";

class CreditNotesPage extends Component {
  state = {
    loading: true,
    loadError: null,
    saving: false,
    rows: [],
    createForm: {
      invoiceId: "",
      amount: "",
      reason: "",
      projectId: "",
      currency: "USD",
    },
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Credit notes");
    }
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await creditNotesService.listCreditNotes();
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ loading: false, rows: result.payload, loadError: null });
    } else {
      this.setState({
        loading: false,
        rows: [],
        loadError: result.error || new Error("Unable to load credit notes"),
      });
    }
  };

  handleFormChange = (patch) => {
    this.setState({ createForm: { ...this.state.createForm, ...patch } });
  };

  handleCreate = async (event) => {
    event.preventDefault();
    const { createForm } = this.state;
    if (!createForm.invoiceId || !createForm.amount || !createForm.reason) {
      return;
    }
    this.setState({ saving: true });
    const result = await creditNotesService.createCreditNote({
      invoiceId: Number(createForm.invoiceId),
      amount: Number(createForm.amount),
      reason: createForm.reason,
      currency: createForm.currency || "USD",
      projectId: createForm.projectId ? Number(createForm.projectId) : null,
    });
    this.setState({ saving: false });
    if (result.source === "api" && result.payload) {
      this.setState({
        createForm: {
          invoiceId: "",
          amount: "",
          reason: "",
          projectId: "",
          currency: "USD",
        },
      });
      this.loadData();
    } else {
      this.setState({ loadError: result.error || new Error("Create failed") });
    }
  };

  handleSubmit = async (ref, userTeamId) => {
    await creditNotesService.submitCreditNote(ref, userTeamId);
    this.loadData();
  };

  handleApprove = async (ref, userTeamId) => {
    await creditNotesService.approveCreditNote(ref, userTeamId);
    this.loadData();
  };

  handleExportPackage = () => {
    const { rows } = this.state;
    if (!Array.isArray(rows) || rows.length === 0) {
      return;
    }
    const header = ["creditNoteRef", "invoiceId", "projectId", "amount", "currency", "status", "reason"];
    const escape = (value) => `"${String(value == null ? "" : value).replace(/"/g, '""')}"`;
    const lines = [
      header.join(","),
      ...rows.map((row) =>
        [
          row.creditNoteRef,
          row.invoiceId,
          row.projectId,
          row.amount,
          row.currency || "USD",
          row.status,
          row.reason,
        ]
          .map(escape)
          .join(",")
      ),
    ];
    const blob = new Blob([lines.join("\n")], { type: "text/csv;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `credit-notes-export-${commonUtils.getCurrentUserTeamId() || "team"}.csv`;
    anchor.click();
    URL.revokeObjectURL(url);
  };

  render() {
    const { loading, loadError, saving, rows, createForm } = this.state;
    return (
      <FinanceLuxPage
        testId="credit-notes-page"
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-file-minus",
          eyebrow: "Finance",
          titleLead: "Credit",
          titleAccent: "notes",
          lede: "Create and approve credit notes against platform invoices (fs_invoice_model).",
        }}
        dataSource="api"
        demoLabel={null}
        loading={loading}
      >
        <FinanceLoadAlert
          error={loadError}
          fallback="Unable to load credit notes."
          onDismiss={() => this.setState({ loadError: null })}
        />
        <FinanceLuxPanel title="Create credit note">
          <form onSubmit={this.handleCreate} className="d-flex flex-wrap gap-2 align-items-end">
            <label className="small mb-0">
              Invoice ID
              <input
                className="form-control form-control-sm"
                value={createForm.invoiceId}
                onChange={(e) => this.handleFormChange({ invoiceId: e.target.value })}
                required
                data-testid="cn-invoice-id"
              />
            </label>
            <label className="small mb-0">
              Amount
              <input
                type="number"
                step="0.01"
                min="0.01"
                className="form-control form-control-sm"
                value={createForm.amount}
                onChange={(e) => this.handleFormChange({ amount: e.target.value })}
                required
                data-testid="cn-amount"
              />
            </label>
            <label className="small mb-0">
              Project ID (optional)
              <input
                className="form-control form-control-sm"
                value={createForm.projectId}
                onChange={(e) => this.handleFormChange({ projectId: e.target.value })}
              />
            </label>
            <label className="small mb-0 flex-grow-1">
              Reason
              <input
                className="form-control form-control-sm"
                value={createForm.reason}
                onChange={(e) => this.handleFormChange({ reason: e.target.value })}
                required
                data-testid="cn-reason"
              />
            </label>
            <FinanceActionButton type="submit" variant="primary" disabled={saving}>
              {saving ? "Saving…" : "Create draft"}
            </FinanceActionButton>
          </form>
        </FinanceLuxPanel>
        <FinanceLuxPanel
          title="Credit notes"
          className="mt-3"
          actions={
            <FinanceActionButton
              type="button"
              variant="secondary"
              onClick={this.handleExportPackage}
              disabled={loading || rows.length === 0}
              data-testid="cn-export-csv"
            >
              Export CSV package
            </FinanceActionButton>
          }
        >
          {loading ? (
            <p className="text-muted small mb-0">Loading…</p>
          ) : rows.length === 0 ? (
            <p className="text-muted small mb-0">No credit notes for team {commonUtils.getCurrentUserTeamId()}.</p>
          ) : (
            <div className="table-responsive">
              <table className="table table-sm" data-testid="credit-notes-table">
                <thead>
                  <tr>
                    <th>Ref</th>
                    <th>Invoice</th>
                    <th>Amount</th>
                    <th>Status</th>
                    <th>Reason</th>
                    <th />
                  </tr>
                </thead>
                <tbody>
                  {rows.map((row) => (
                    <tr key={row.creditNoteRef || row.id}>
                      <td>{row.creditNoteRef}</td>
                      <td>{row.invoiceId}</td>
                      <td>
                        {row.currency || "USD"} {row.amount}
                      </td>
                      <td>{row.status}</td>
                      <td>{row.reason}</td>
                      <td className="text-nowrap">
                        {row.status === "DRAFT" && (
                          <FinanceActionButton
                            type="button"
                            variant="ghost"
                            onClick={() => this.handleSubmit(row.creditNoteRef, row.userTeamId)}
                          >
                            Submit
                          </FinanceActionButton>
                        )}
                        {row.status === "SUBMITTED" && (
                          <FinanceActionButton
                            type="button"
                            variant="ghost"
                            onClick={() => this.handleApprove(row.creditNoteRef, row.userTeamId)}
                          >
                            Approve
                          </FinanceActionButton>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </FinanceLuxPanel>
      </FinanceLuxPage>
    );
  }
}

export default CreditNotesPage;
