import React, { Component } from "react";
import classNames from "classnames/bind";
import { AUDIT_CONFIG_CHANGED, isAuditUiEnabled } from "_helpers/audit.config";
import {
  readAuditPanelExpanded,
  writeAuditPanelPrefs,
} from "_helpers/audit.panel.utils";
import AuditTrailSection from "./AuditTrailSection";

class CollapsibleAuditPanel extends Component {
  constructor(props) {
    super(props);
    const { panelKey, defaultExpanded } = props;
    this.state = {
      expanded: readAuditPanelExpanded(panelKey, defaultExpanded === true),
      uiEnabled: isAuditUiEnabled(),
    };
  }

  componentDidMount() {
    this.handleAuditConfigChanged = () => {
      this.setState({ uiEnabled: isAuditUiEnabled() });
    };
    window.addEventListener(AUDIT_CONFIG_CHANGED, this.handleAuditConfigChanged);
  }

  componentWillUnmount() {
    window.removeEventListener(AUDIT_CONFIG_CHANGED, this.handleAuditConfigChanged);
  }

  toggleExpanded = () => {
    const { panelKey } = this.props;
    this.setState((prev) => {
      const expanded = !prev.expanded;
      writeAuditPanelPrefs(panelKey, { expanded });
      return { expanded };
    });
  };

  render() {
    const { panelKey, title, subtitle, icon, className, auditProps, children } = this.props;
    const { expanded, uiEnabled } = this.state;

    if (!uiEnabled || !panelKey) {
      return null;
    }

    const toggleIcon = icon || "fe-shield";

    return (
      <section
        className={classNames("lux-audit-collapsible", className, {
          "is-expanded": expanded,
        })}
        data-audit-panel={panelKey}
      >
        <button
          type="button"
          className="lux-audit-collapsible__toggle"
          onClick={this.toggleExpanded}
          aria-expanded={expanded}
          aria-controls={`audit-panel-body-${panelKey}`}
        >
          <span className="lux-audit-collapsible__toggle-main">
            <span className="lux-audit-collapsible__icon" aria-hidden="true">
              <i className={`fe ${toggleIcon}`} />
            </span>
            <span className="lux-audit-collapsible__copy">
              <strong className="lux-audit-collapsible__title">{title}</strong>
              {subtitle && <span className="lux-audit-collapsible__subtitle">{subtitle}</span>}
            </span>
          </span>
          <span className="lux-audit-collapsible__chevron" aria-hidden="true">
            <i className={classNames("fe", expanded ? "fe-chevron-up" : "fe-chevron-down")} />
          </span>
        </button>

        {expanded && (
          <div
            id={`audit-panel-body-${panelKey}`}
            className="lux-audit-collapsible__body"
          >
            {auditProps ? (
              <AuditTrailSection
                {...auditProps}
                persistKey={auditProps.persistKey || panelKey}
                hideHeader={auditProps.hideHeader !== false}
              />
            ) : (
              children
            )}
          </div>
        )}
      </section>
    );
  }
}

export default CollapsibleAuditPanel;
