import React, { Component } from "react";
import classNames from "classnames/bind";
import { NavLink } from "react-router-dom";
import originalMoment from "moment";
import { extendMoment } from "moment-range";
import EmployeeImage from "views/common/fragments/EmployeeImage";
import { commonUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import { getEmployeeDetailsPathname } from "views/hrms/profileDetailsNavigation.utils";

const moment = extendMoment(originalMoment);

const EMP_TYPE_TONES = {
  Permanent: "blue",
  Contract: "amber",
  Intern: "teal",
  Consultant: "violet",
};

function parseJoinMoment(val) {
  if (!val) return null;
  let m = moment(val, moment.ISO_8601, true);
  if (m.isValid()) return m;
  m = moment(val, dateUtils.CLIENT_DATE_FORMAT, true);
  if (m.isValid()) return m;
  m = moment(val);
  return m.isValid() ? m : null;
}

function getTenureLabel(dateOfJoin) {
  const join = parseJoinMoment(dateOfJoin);
  if (!join) return null;
  const months = moment().diff(join, "months");
  if (months < 1) return "New joiner";
  if (months < 12) return `${months} mo`;
  const years = Math.floor(months / 12);
  const rem = months % 12;
  if (rem === 0) return `${years} yr${years > 1 ? "s" : ""}`;
  return `${years}y ${rem}m`;
}

class EmployeeInfoLine extends Component {
  constructor(props) {
    super(props);
    this.state = {
      menuOpen: false,
      confirmRemove: false,
    };
    this.rowRef = React.createRef();
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick);
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
  }

  handleOutsideClick = (event) => {
    if (!this.state.menuOpen) return;
    if (this.rowRef.current && !this.rowRef.current.contains(event.target)) {
      this.setState({ menuOpen: false });
    }
  };

  toggleMenu = (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.setState((prev) => ({ menuOpen: !prev.menuOpen }));
  };

  closeMenu = () => {
    this.setState({ menuOpen: false });
  };

  runMenuAction = (handler) => (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.closeMenu();
    if (handler) handler();
  };

  handleRemoveEmployee = () => {
    if (this.state.confirmRemove) {
      this.props.handleRemoveEmployee(this.props.employee.id);
      this.setState({ confirmRemove: false, menuOpen: false });
      return;
    }
    this.setState({ confirmRemove: true });
  };

  getEmpTypeTone = () => {
    const type = this.props.employee.empType;
    return EMP_TYPE_TONES[type] || "slate";
  };

  getStatusMeta = () => {
    const { employee } = this.props;
    if (employee.deleted) {
      return { label: "Deleted", tone: "danger" };
    }
    if (!employee.active) {
      return { label: "Inactive", tone: "muted" };
    }
    return { label: "Active", tone: "success" };
  };

  getMenuSections = () => {
    const { employee, permission } = this.props;
    const sections = [];

    const contactItems = [];
    if (employee.email) {
      contactItems.push({
        key: "email",
        icon: "fe fe-mail",
        label: "Send email",
        hint: employee.email,
        href: `mailto:${employee.email}`,
      });
    }
    if (employee.mobileNumber) {
      contactItems.push({
        key: "phone",
        icon: "fe fe-phone",
        label: "Call mobile",
        hint: employee.mobileNumber,
        href: `tel:${employee.mobileNumber}`,
      });
    }
    if (contactItems.length) {
      sections.push({ id: "contact", title: "Contact", items: contactItems });
    }

    const manageItems = [];
    if (permission.editEnabled) {
      manageItems.push({
        key: "edit",
        icon: "fa fa-edit",
        label: "Edit employee",
        hint: "Update profile details",
        onClick: () =>
          this.props.handleEditEmployee(employee.id, employee.userTeamId),
      });
    }
    if (permission.archiveEnabled && employee.active) {
      manageItems.push({
        key: "deactivate",
        icon: "fe fe-user-x",
        label: "Deactivate",
        hint: "Mark as inactive",
        tone: "danger",
        onClick: () =>
          this.props.handleActivateEmployee(employee.id, false),
      });
    }
    if (permission.archiveEnabled && !employee.active) {
      manageItems.push({
        key: "activate",
        icon: "fe fe-user-check",
        label: "Activate",
        hint: "Restore active status",
        tone: "success",
        onClick: () =>
          this.props.handleActivateEmployee(employee.id, true),
      });
    }
    if (permission.deleteEnabled) {
      manageItems.push({
        key: "delete",
        icon: employee.deleted ? "fa fa-rotate-left" : "fa fa-trash",
        label: employee.deleted ? "Undo delete" : "Delete employee",
        hint: employee.deleted ? "Restore deleted record" : "Remove from list",
        tone: "danger",
        onClick: () =>
          this.props.handleDeleteEmployee(employee.id, !employee.deleted),
      });
    }
    if (permission.removeEnabled) {
      manageItems.push({
        key: "remove",
        icon: this.state.confirmRemove ? "fa fa-check" : "fa fa-times",
        label: this.state.confirmRemove ? "Confirm remove" : "Remove employee",
        hint: this.state.confirmRemove
          ? "Tap again to confirm"
          : "Detach from selected teams",
        tone: "danger",
        onClick: this.handleRemoveEmployee,
      });
    }
    if (manageItems.length) {
      sections.push({ id: "manage", title: "Manage", items: manageItems });
    }

    return sections;
  };

  renderMenuItem = (item) => {
    const content = (
      <>
        <span
          className={classNames("lux-emp-card__menu-icon", item.tone && `is-${item.tone}`)}
          aria-hidden="true"
        >
          <i className={item.icon} />
        </span>
        <span className="lux-emp-card__menu-copy">
          <strong>{item.label}</strong>
          {item.hint && <span>{item.hint}</span>}
        </span>
      </>
    );

    if (item.href) {
      return (
        <a
          key={item.key}
          href={item.href}
          className={classNames("lux-emp-card__menu-item", item.tone && `is-${item.tone}`)}
          onClick={this.runMenuAction(null)}
        >
          {content}
        </a>
      );
    }

    return (
      <button
        key={item.key}
        type="button"
        className={classNames("lux-emp-card__menu-item", item.tone && `is-${item.tone}`)}
        onClick={this.runMenuAction(item.onClick)}
      >
        {content}
      </button>
    );
  };

  renderActionsMenu = (employee, menuSections) => {
    if (!menuSections.length) {
      return <span className="lux-emp-list__no-actions">—</span>;
    }

    return (
      <div className="lux-emp-list__actions">
        <button
          type="button"
          className="lux-emp-list__menu-trigger"
          onClick={this.toggleMenu}
          aria-expanded={this.state.menuOpen}
          aria-haspopup="menu"
          aria-label={`Actions for ${employee.name}`}
        >
          <i className="fe fe-more-horizontal" aria-hidden="true" />
        </button>

        {this.state.menuOpen && (
          <div className="lux-emp-card__menu-panel lux-emp-list__menu-panel" role="menu">
            <header className="lux-emp-card__menu-head">
              <span className="lux-emp-card__menu-head-icon" aria-hidden="true">
                <i className="fe fe-sliders" />
              </span>
              <div>
                <span className="lux-emp-card__menu-eyebrow">Employee actions</span>
                <strong title={employee.name}>{employee.name}</strong>
              </div>
              <button
                type="button"
                className="lux-emp-card__menu-close"
                onClick={this.runMenuAction(null)}
                aria-label="Close menu"
              >
                <i className="fe fe-x" aria-hidden="true" />
              </button>
            </header>

            <div className="lux-emp-card__menu-body">
              {menuSections.map((section, index) => (
                <div key={section.id} className="lux-emp-card__menu-section">
                  {index > 0 && <div className="lux-emp-card__menu-divider" aria-hidden="true" />}
                  <span className="lux-emp-card__menu-section-label">{section.title}</span>
                  {section.items.map((item) => this.renderMenuItem(item))}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  };

  render() {
    const { employee, permission } = this.props;
    const status = this.getStatusMeta();
    const profilePath = getEmployeeDetailsPathname(employee.id);
    const teamName =
      employee.defaultUserTeamDetails && employee.defaultUserTeamDetails.name;
    const joinDate = employee.dateOfJoin
      ? dateUtils.convertDateFormat(employee.dateOfJoin)
      : null;
    const tenure = getTenureLabel(employee.dateOfJoin);
    const menuSections = this.getMenuSections();

    return (
      <article
        ref={this.rowRef}
        role="listitem"
        className={classNames("lux-emp-list__item", {
          "is-inactive": !employee.active && !employee.deleted,
          "is-deleted": employee.deleted,
          "is-menu-open": this.state.menuOpen,
        })}
      >
        <div className="lux-emp-list__col lux-emp-list__col--employee">
          <div className="lux-emp-list__employee">
            <div className="lux-emp-list__avatar-wrap">
              {permission.viewEnabled ? (
                <NavLink to={profilePath} className="lux-emp-list__avatar-link" title="Open profile">
                  <span className="lux-emp-list__avatar-ring" aria-hidden="true" />
                  <EmployeeImage employee={employee} classes="lux-emp-list__avatar" />
                </NavLink>
              ) : (
                <>
                  <span className="lux-emp-list__avatar-ring" aria-hidden="true" />
                  <EmployeeImage employee={employee} classes="lux-emp-list__avatar" />
                </>
              )}
              <span className="lux-emp-list__initials" aria-hidden="true">
                {commonUtils.getNameInitial(employee.name)}
              </span>
            </div>

            <div className="lux-emp-list__employee-copy">
              <div className="lux-emp-list__employee-top">
                {employee.empCode && (
                  <span className="lux-emp-list__code">{employee.empCode}</span>
                )}
                <span className={classNames("lux-emp-list__status-pill", `is-${status.tone}`)}>
                  {status.label}
                </span>
              </div>
              <div className="lux-emp-list__name">
                {permission.viewEnabled ? (
                  <NavLink to={profilePath} title="Open employee profile">
                    {employee.name}
                    <i className="fe fe-arrow-up-right" aria-hidden="true" />
                  </NavLink>
                ) : (
                  employee.name
                )}
              </div>
              {employee.designation && (
                <div className="lux-emp-list__designation">{employee.designation}</div>
              )}
              {teamName && (
                <div className="lux-emp-list__team" title={teamName}>
                  <i className="fe fe-layers" aria-hidden="true" />
                  {teamName}
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="lux-emp-list__col lux-emp-list__col--skill">
          {employee.primarySkill ? (
            <span className="lux-emp-list__skill">
              <i className="fe fe-award" aria-hidden="true" />
              {employee.primarySkill}
            </span>
          ) : (
            <span className="lux-emp-list__empty">—</span>
          )}
        </div>

        <div className="lux-emp-list__col lux-emp-list__col--type is-center">
          {employee.empType ? (
            <span className={classNames("lux-emp-list__type lux-emp-list__type--solo", `is-${this.getEmpTypeTone()}`)}>
              {employee.empType}
            </span>
          ) : (
            <span className="lux-emp-list__empty">—</span>
          )}
        </div>

        <div className="lux-emp-list__col lux-emp-list__col--email">
          {employee.email ? (
            <a
              className="lux-emp-list__chip"
              href={`mailto:${employee.email}`}
              title={employee.email}
            >
              <i className="fe fe-mail" aria-hidden="true" />
              <span>{employee.email}</span>
            </a>
          ) : (
            <span className="lux-emp-list__empty">—</span>
          )}
        </div>

        <div className="lux-emp-list__col lux-emp-list__col--joined">
          {joinDate ? (
            <div className="lux-emp-list__join">
              <strong>{joinDate}</strong>
              {tenure && (
                <span>
                  <i className="fe fe-clock" aria-hidden="true" />
                  {tenure}
                </span>
              )}
            </div>
          ) : (
            <span className="lux-emp-list__empty">—</span>
          )}
        </div>

        <div className="lux-emp-list__col lux-emp-list__col--contact">
          {employee.mobileNumber ? (
            <a
              className="lux-emp-list__chip lux-emp-list__chip--phone"
              href={`tel:${employee.mobileNumber}`}
              title={employee.mobileNumber}
            >
              <i className="fe fe-phone" aria-hidden="true" />
              <span>{employee.mobileNumber}</span>
            </a>
          ) : (
            <span className="lux-emp-list__empty">—</span>
          )}
        </div>

        <div className="lux-emp-list__col lux-emp-list__col--actions is-center">
          {this.renderActionsMenu(employee, menuSections)}
        </div>
      </article>
    );
  }
}

export default EmployeeInfoLine;
