import React from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { RISK_SEVERITIES } from "config/project-governance.config";

const SEVERITY_TONE = {
  [RISK_SEVERITIES.CRITICAL]: "rose",
  [RISK_SEVERITIES.HIGH]: "amber",
  [RISK_SEVERITIES.MEDIUM]: "blue",
  [RISK_SEVERITIES.LOW]: "slate",
};

export default function PortfolioCrossRollupsPanel({ rollups, loading }) {
  if (loading) {
    return <div className="lux-portfolio-rollups__loading">Loading cross-project roll-ups…</div>;
  }

  if (!rollups) {
    return <div className="lux-portfolio-rollups__empty">Cross-project roll-ups will appear when governance data is linked.</div>;
  }

  const { risk, resource, finance } = rollups;
  const heatmap = risk && risk.heatmap ? risk.heatmap : { severities: [], rows: [] };

  return (
    <div className="lux-portfolio-rollups">
      <section className="lux-portfolio-rollups__section">
        <header>
          <h3>Risk exposure</h3>
          <span>{risk ? risk.openCount : 0} open risks</span>
        </header>
        {heatmap.rows && heatmap.rows.length ? (
          <div className="lux-portfolio-rollups__heatmap">
            <div className="lux-portfolio-rollups__heatmap-head">
              <span>Project</span>
              {(heatmap.severities || []).map((severity) => (
                <span key={severity}>{severity}</span>
              ))}
            </div>
            {heatmap.rows.map((row) => (
              <div key={row.projectId} className="lux-portfolio-rollups__heatmap-row">
                <span className="lux-portfolio-rollups__heatmap-label">{row.projectLabel}</span>
                {(heatmap.severities || []).map((severity) => {
                  const count = row.counts ? row.counts[severity] || 0 : 0;
                  return (
                    <span
                      key={`${row.projectId}-${severity}`}
                      className={classNames("lux-portfolio-rollups__cell", count ? `is-${SEVERITY_TONE[severity]}` : "is-empty")}
                    >
                      {count || "·"}
                    </span>
                  );
                })}
              </div>
            ))}
          </div>
        ) : (
          <p className="lux-portfolio-rollups__hint">No open risks on the portfolio register.</p>
        )}
        {(risk && risk.topRisks || []).length ? (
          <ul className="lux-portfolio-rollups__risk-list">
            {risk.topRisks.map((row) => (
              <li key={row.id}>
                <strong>{row.title}</strong>
                <span>{row.projectName}</span>
                <span className={classNames("lux-portfolio-badge", `is-${SEVERITY_TONE[row.severity] || "slate"}`)}>
                  {row.severity}
                </span>
              </li>
            ))}
          </ul>
        ) : null}
      </section>

      <section className="lux-portfolio-rollups__section">
        <header>
          <h3>Resource utilization</h3>
          <span>Avg {resource ? resource.avgUtilization : 0}%</span>
        </header>
        <div className="lux-portfolio-rollups__bars">
          {(resource && resource.rows || []).map((row) => (
            <div key={row.projectId} className="lux-portfolio-rollups__bar-row">
              <span>{row.projectName}</span>
              <div className="lux-portfolio-rollups__track">
                <div className="lux-portfolio-rollups__fill" style={{ width: `${row.utilization || 0}%` }} />
              </div>
              <strong>{row.utilization != null ? `${row.utilization}%` : "—"}</strong>
            </div>
          ))}
        </div>
        <p className="lux-portfolio-rollups__foot">
          Drill into <Link to="/resources/utilization">resource utilization</Link> for staffing detail.
        </p>
      </section>

      <section className="lux-portfolio-rollups__section">
        <header>
          <h3>Finance outlook</h3>
          <span>Avg margin {finance ? finance.avgMargin : 0}%</span>
        </header>
        <table className="lux-portfolio-rollups__finance">
          <thead>
            <tr>
              <th>Project</th>
              <th>Margin</th>
              <th>Forecast variance</th>
            </tr>
          </thead>
          <tbody>
            {(finance && finance.rows || []).map((row) => (
              <tr key={row.projectId}>
                <td>{row.projectName}</td>
                <td>{row.marginPct != null ? `${row.marginPct}%` : "—"}</td>
                <td className={row.forecastVariancePct > 0 ? "is-positive" : row.forecastVariancePct < 0 ? "is-negative" : ""}>
                  {row.forecastVariancePct != null ? `${row.forecastVariancePct > 0 ? "+" : ""}${row.forecastVariancePct}%` : "—"}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </section>
    </div>
  );
}
