/**
 * F09-T8 — Paycheck access guards, persona masking, and audit metadata helpers.
 */
import { resolveMaskedFieldValue, isFieldVisible } from "config/employee360-field.utils";
import { redactAuditMetadata } from "config/audit-write.utils";
import { formatPayrollCurrency } from "config/payroll.utils";
import { PAYCHECK_STATUSES } from "config/payroll.config";
import { PAYROLL_ADMIN_PERSONAS } from "config/payroll-security.utils";

export const PAYCHECK_VIEW_PERSONAS = PAYROLL_ADMIN_PERSONAS.concat(["EMPLOYEE", "MANAGER"]);

export function buildPaycheckViewerContext(personaContext, currentUser) {
  const user = currentUser || {};
  return {
    activePersona: (personaContext && personaContext.activePersona) || "EMPLOYEE",
    viewerEmployeeId: user.id || (personaContext && personaContext.employeeId) || null,
    maskingPolicy: (personaContext && personaContext.maskingPolicy) || {},
  };
}

export function canViewPaycheckDetail(viewerContext, paycheck, options) {
  if (!paycheck) {
    return false;
  }
  const opts = options || {};
  if (opts.employeeSelfService === true) {
    return paycheck.status === PAYCHECK_STATUSES.PUBLISHED;
  }

  const ctx = viewerContext || {};
  const viewerId = ctx.viewerEmployeeId;
  if (viewerId && String(viewerId) === String(paycheck.employeeId)) {
    return paycheck.status === PAYCHECK_STATUSES.PUBLISHED;
  }

  const persona = ctx.activePersona || "EMPLOYEE";
  if (PAYROLL_ADMIN_PERSONAS.indexOf(persona) >= 0) {
    return true;
  }

  return false;
}

export function canManagePaycheck(viewerContext) {
  const persona = (viewerContext && viewerContext.activePersona) || "EMPLOYEE";
  return PAYROLL_ADMIN_PERSONAS.indexOf(persona) >= 0;
}

export function maskPaycheckAmount(value, maskingPolicy, currency) {
  if (value == null) {
    return "—";
  }
  const formatted = formatPayrollCurrency(value, currency);
  return resolveMaskedFieldValue("payrollLines", formatted, maskingPolicy);
}

export function maskPaycheckForDisplay(paycheck, maskingPolicy, viewerContext) {
  if (!paycheck) {
    return null;
  }
  const ctx = viewerContext || {};
  const isOwn =
    ctx.viewerEmployeeId &&
    paycheck.employeeId &&
    String(ctx.viewerEmployeeId) === String(paycheck.employeeId);
  if (isOwn) {
    return paycheck;
  }

  const policy = maskingPolicy || {};
  if (!isFieldVisible("payrollLines", policy)) {
    return {
      ...paycheck,
      gross: "Restricted",
      net: "Restricted",
      deductions: "Restricted",
      ytdGross: "Restricted",
      ytdNet: "Restricted",
      ytdDeductions: "Restricted",
      lines: [],
      bankAccount: "Restricted",
      taxId: "Restricted",
    };
  }

  const currency = paycheck.currency || "USD";
  return {
    ...paycheck,
    gross: maskPaycheckAmount(paycheck.gross, policy, currency),
    net: maskPaycheckAmount(paycheck.net, policy, currency),
    deductions: maskPaycheckAmount(paycheck.deductions, policy, currency),
    ytdGross: maskPaycheckAmount(paycheck.ytdGross, policy, currency),
    ytdNet: maskPaycheckAmount(paycheck.ytdNet, policy, currency),
    ytdDeductions: maskPaycheckAmount(paycheck.ytdDeductions, policy, currency),
    bankAccount: resolveMaskedFieldValue("bankAccount", paycheck.bankAccount, policy),
    taxId: resolveMaskedFieldValue("taxId", paycheck.taxId, policy),
    lines: (paycheck.lines || []).map((line) => ({
      ...line,
      amount: maskPaycheckAmount(line.amount, policy, currency),
    })),
  };
}

export function buildPaycheckAuditMetadata(paycheck, actionType, extras) {
  const base = {
    actionType,
    paycheckId: paycheck && paycheck.id,
    employeeId: paycheck && paycheck.employeeId,
    periodLabel: paycheck && paycheck.periodLabel,
    status: paycheck && paycheck.status,
    runId: paycheck && paycheck.runId,
  };
  const merged = Object.assign(base, extras || {});
  if (merged.bankAccount != null) {
    merged.bankAccount = "[REDACTED]";
  }
  if (merged.taxId != null) {
    merged.taxId = "[REDACTED]";
  }
  return redactAuditMetadata(merged);
}
