import React, { useMemo } from "react";
import dateUtils from "_helpers/date.utils";
import workItemUtils from "_helpers/workitem.utils";
import PlannerAssignWorkPanel from "../planner/components/PlannerAssignWorkPanel";
import { buildPlannerRange, PLANNER_STATUS_FILTER_OPTIONS } from "../planner/planner.utils";
import { buildEmployeeLeaveMap } from "../planner/plannerLeave.utils";
import { readCapacityOverrides } from "../planner/plannerCapacity.utils";
import { readPlannerPrefs } from "../planner/planner.storage";

function derivePlannerHorizonFromDateRange(dateRange) {
  const start = dateRange.startDateMoment.clone();
  const end = dateRange.endDateMoment.clone();
  const weekStartMoment = start.clone().startOf("isoWeek");
  const endWeek = end.clone().endOf("isoWeek");
  const horizonWeeks = Math.max(1, endWeek.diff(weekStartMoment, "weeks") + 1);
  const range = buildPlannerRange(weekStartMoment, horizonWeeks);
  const rangeLabel = start.isSame(end, "day")
    ? start.format("ddd, DD MMM YYYY")
    : `${range.startDateMoment.format("DD MMM")} – ${range.endDateMoment.format("DD MMM YYYY")}`;
  return { weekStartMoment, horizonWeeks, range, rangeLabel };
}

/**
 * Capacity-style assign panel for the Activities page (calendar + register).
 * Uses the same embedded form, insights, and horizon list as Team capacity.
 */
export default function ActivitiesAssignWorkPanel({
  show,
  onClose,
  employees,
  workItems,
  permission,
  holidayItems,
  dateRange,
  assignContext,
  handleReloadWorkItems,
}) {
  const prefs = readPlannerPrefs();
  const reduceForHolidays = !!prefs.reduceCapacityForHolidays;
  const capacityOverrides = useMemo(() => (show ? readCapacityOverrides() : {}), [show]);

  const { weekStartMoment, horizonWeeks, range, rangeLabel } = useMemo(
    () => derivePlannerHorizonFromDateRange(dateRange),
    [dateRange]
  );

  const leaveMap = useMemo(
    () =>
      buildEmployeeLeaveMap({
        workItems,
        holidayItems,
        timesheetByEmployee: {},
        employees,
      }),
    [workItems, holidayItems, employees]
  );

  return (
    <PlannerAssignWorkPanel
      show={show}
      onClose={onClose}
      employees={employees}
      workItems={workItems}
      permission={permission}
      weekStartMoment={weekStartMoment}
      horizonWeeks={horizonWeeks}
      holidayItems={holidayItems}
      reduceForHolidays={reduceForHolidays}
      filterOptions={PLANNER_STATUS_FILTER_OPTIONS}
      leaveMap={leaveMap}
      capacityOverrides={capacityOverrides}
      rangeLabel={rangeLabel}
      handleReloadWorkItems={handleReloadWorkItems}
      assignContext={assignContext}
      minDate={workItemUtils.getWorkItemCreateStartMinDate(weekStartMoment.clone(), permission)}
      maxDate={workItemUtils.getWorkItemCreateEndMaxDate(range.endDateMoment.clone(), permission)}
      shellKicker="Activities"
      shellTitle="Create task"
      shellSubtitle="Review load for the selected person, then schedule work across your calendar range."
    />
  );
}
