import React, { Component } from "react";
import { getQuestionLayoutSpan } from "../../feedbackForm.utils";
import LuxFeedbackQuestionLabel from "./LuxFeedbackQuestionLabel";

class MultiOptionMultiSelectInput extends Component {
  onChange = (isChecked, value) => {
    value = value.trim();
    var answer = this.props.questionConfig.answer || null;
    var answerList = answer ? answer.split(",") : [];
    if (isChecked === true) {
      answerList.push(value);
    } else {
      const index = answerList.indexOf(value);
      if (index > -1) {
        answerList.splice(index, 1);
      }
    }

    if (answerList.length > 0) {
      answer = answerList.join(",");
    } else {
      answer = null;
    }
    this.props.onChange({ ...this.props.questionConfig, answer: answer });
  };

  render() {
    const { questionConfig, readonly } = this.props;
    if (!questionConfig) return null;
    const span = getQuestionLayoutSpan(questionConfig.type);
    const selected =
      questionConfig.answer && questionConfig.answer.split
        ? questionConfig.answer.split(",")
        : [];

    return (
      <div className={`lux-fb-q lux-fb-q--${span}`}>
        <div className="lux-fb-q__card">
          <LuxFeedbackQuestionLabel questionConfig={questionConfig} />
          {questionConfig.questionOptions &&
            questionConfig.questionOptions.split(",").map((value) => {
              const trimmed = value.trim();
              const id = `lux-fb-ms-${questionConfig.id}-${trimmed}`;
              return (
                <div key={trimmed} className="radioField">
                  <input
                    type="checkbox"
                    name="join"
                    id={id}
                    onChange={(e) => this.onChange(e.target.checked, value)}
                    disabled={readonly}
                    checked={selected.indexOf(trimmed) > -1}
                  />
                  <label htmlFor={id}>{trimmed}</label>
                </div>
              );
            })}
        </div>
      </div>
    );
  }
}
export default MultiOptionMultiSelectInput;
