import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import {
  FINANCE_AUDIT_CODES,
  FINANCE_INVOICE_REC_STATUSES,
  normalizeBillingPlan,
  normalizeInvoiceRecommendation,
  normalizeProjectFinancialSnapshot,
  normalizeRevenueForecast,
} from "config/finance-intelligence.config";
import {
  buildBillingPlansOverview,
  buildFinanceDashboardOverview,
  buildRevenueForecastOverview,
  exportBillingPlansCsv,
  exportFinancePackCsv,
  exportRevenueForecastCsv,
} from "config/finance-intelligence.modules.utils";
import { recordAuditEvent } from "config/audit-write.service";
import { AUDIT_ACTION_TYPES, AUDIT_ENTITY_TYPES } from "_constants/audit.constants";
import {
  buildProjectFinancialsOverview,
  exportProjectFinancialsCsv,
} from "config/finance-intelligence.utils";

export const financeIntelligenceService = {
  listProjectFinancialSnapshots,
  getProjectFinancialSnapshot,
  getProjectFinancialsOverview,
  exportProjectFinancials,
  recordProjectFinancialsViewed,
  listBillingPlans,
  getBillingPlan,
  saveBillingPlan,
  listRevenueForecasts,
  getRevenueForecast,
  saveRevenueForecast,
  listRevenueLeakageFlags,
  flagRevenueLeakage,
  listInvoiceRecommendations,
  approveInvoiceRecommendation,
  dismissInvoiceRecommendation,
  getFinanceDashboardOverview,
  exportFinancePack,
};

function financeTeamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.assign(query, extra);
  }
  return query;
}

function financeTeamQueryString(extra) {
  const query = financeTeamQuery(extra);
  return Object.keys(query)
    .filter((key) => query[key] != null && query[key] !== "")
    .map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(query[key])}`)
    .join("&");
}

function writeFinanceAudit(actionType, headline, entityRef, metadata) {
  recordAuditEvent({
    actionType,
    entityType: AUDIT_ENTITY_TYPES.PROJECT,
    entityRef: entityRef || headline,
    headline,
    metadata: {
      module: "FINANCE_INTELLIGENCE",
      ...metadata,
    },
  });
}

function recordProjectFinancialsViewed(filters = {}) {
  writeFinanceAudit(
    AUDIT_ACTION_TYPES.AUDIT_VIEWED,
    "Project financial snapshots viewed",
    "project-financials",
    { filters }
  );
}

async function listProjectFinancialSnapshots(filters = {}, options = {}) {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.FINANCE_INTELLIGENCE_API_PATH}/project-financial-snapshots`,
    financeTeamQuery(filters)
  );
  const rows = (response && response.payload) || response || [];
  const normalized = rows.map((row) => normalizeProjectFinancialSnapshot(row)).filter(Boolean);
  const overview = buildProjectFinancialsOverview(normalized, { ...options, filters });
  return {
    payload: overview.snapshots,
    rollup: overview.rollup,
    source: "api",
  };
}

async function getProjectFinancialSnapshot(projectId, options = {}) {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.FINANCE_INTELLIGENCE_API_PATH}/project-financial-snapshots/${projectId}`,
    financeTeamQuery()
  );
  const row = normalizeProjectFinancialSnapshot((response && response.payload) || response);
  const overview = buildProjectFinancialsOverview(row ? [row] : [], options);
  return {
    payload: overview.snapshots[0] || null,
    source: "api",
  };
}

async function getProjectFinancialsOverview(filters = {}, options = {}) {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.FINANCE_INTELLIGENCE_API_PATH}/project-financial-snapshots/overview`,
    financeTeamQuery(filters)
  );
  const payload = (response && response.payload) || response || {};
  const rows = (payload.snapshots || []).map((row) => normalizeProjectFinancialSnapshot(row)).filter(Boolean);
  const overview = buildProjectFinancialsOverview(rows.length ? rows : [], { ...options, filters });
  return {
    payload: overview,
    source: "api",
  };
}

async function exportProjectFinancials(filters = {}, options = {}) {
  const result = await listProjectFinancialSnapshots(filters, options);
  const csv = exportProjectFinancialsCsv(result.payload || [], options);
  writeFinanceAudit(AUDIT_ACTION_TYPES.EXPORTED, "Project financial snapshots exported", "project-financials-export", {
    filters,
    rowCount: (result.payload || []).length,
  });
  return {
    payload: csv,
    filename: `project-financials-${new Date().toISOString().slice(0, 10)}.csv`,
    source: result.source,
  };
}

