async function saveBillingPlan(payload = {}) {
  const response = await axiosUtils.post(
    `${urlConfig.FINANCE_INTELLIGENCE_API_PATH}/billing-plans?${financeTeamQueryString()}`,
    payload
  );
  const row = normalizeBillingPlan((response && response.payload) || response);
  writeFinanceAudit(AUDIT_ACTION_TYPES.CREATED, "Billing plan saved", row.id, {
    financeAction: FINANCE_AUDIT_CODES.BILLING_PLAN_CREATED,
    projectId: row.projectId,
  });
  return { payload: row, source: "api" };
}

