async function listInvoiceRecommendations(filters = {}) {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.FINANCE_INTELLIGENCE_API_PATH}/invoice-recommendations`,
    financeTeamQuery(filters)
  );
  return { payload: (response && response.payload) || response || [], source: "api" };
}

async function approveInvoiceRecommendation(recommendationId) {
  return updateInvoiceRecommendationStatus(recommendationId, FINANCE_INVOICE_REC_STATUSES.APPROVED);
}

async function dismissInvoiceRecommendation(recommendationId) {
  return updateInvoiceRecommendationStatus(recommendationId, FINANCE_INVOICE_REC_STATUSES.DISMISSED);
}

async function updateInvoiceRecommendationStatus(recommendationId, status) {
  const response = await axiosUtils.post(
    `${urlConfig.FINANCE_INTELLIGENCE_API_PATH}/invoice-recommendations/${recommendationId}?${financeTeamQueryString()}`,
    { status }
  );
  writeFinanceAudit(AUDIT_ACTION_TYPES.STATUS_CHANGED, `Invoice recommendation ${status.toLowerCase()}`, recommendationId, {
    financeAction: FINANCE_AUDIT_CODES.INVOICE_RECOMMENDED,
    status,
  });
  return { payload: normalizeInvoiceRecommendation((response && response.payload) || response), source: "api" };
}

async function getFinanceDashboardOverview() {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.FINANCE_INTELLIGENCE_API_PATH}/dashboard`,
    financeTeamQuery()
  );
  return {
    payload: buildFinanceDashboardOverview((response && response.payload) || response || {}),
    source: "api",
  };
}

async function exportFinancePack() {
  const [snapshotsResult, billingResult, forecastResult] = await Promise.all([
    listProjectFinancialSnapshots({}, { includeSensitive: false }),
    listBillingPlans(),
    listRevenueForecasts(),
  ]);
  const activeForecast =
    (forecastResult.overview && forecastResult.overview.activeForecast) ||
    (forecastResult.payload && forecastResult.payload[0]) ||
    null;
  const csv = exportFinancePackCsv({
    projectFinancialsCsv: exportProjectFinancialsCsv(snapshotsResult.payload || [], { includeSensitive: false }),
    billingPlansCsv: exportBillingPlansCsv(billingResult.payload || []),
    forecastCsv: exportRevenueForecastCsv(activeForecast),
  });
  writeFinanceAudit(AUDIT_ACTION_TYPES.EXPORTED, "Finance intelligence pack exported", "finance-pack-export", {
    sections: ["project-financials", "billing-plans", "revenue-forecast"],
  });
  return {
    payload: csv,
    filename: `finance-intelligence-pack-${new Date().toISOString().slice(0, 10)}.csv`,
    source: snapshotsResult.source,
  };
}
