import React from "react";
import classNames from "classnames/bind";
import { getApprovalPriorityTone } from "config/universal-approval.utils";

const STATUS_META = {
  PENDING: { label: "Pending", tone: "warning" },
  APPROVED: { label: "Approved", tone: "success" },
  REJECTED: { label: "Rejected", tone: "danger" },
};

function UniversalApprovalStatusBadge({ status, priority, variant = "status" }) {
  if (variant === "priority" && priority) {
    return (
      <span
        className={classNames(
          "lux-appr-badge",
          `lux-appr-badge--${getApprovalPriorityTone(priority)}`
        )}
      >
        {priority === "HIGH" ? "High" : priority === "LOW" ? "Low" : "Normal"}
      </span>
    );
  }

  const meta = STATUS_META[String(status || "PENDING").toUpperCase()] || STATUS_META.PENDING;
  return <span className={classNames("lux-appr-badge", `lux-appr-badge--${meta.tone}`)}>{meta.label}</span>;
}

export default UniversalApprovalStatusBadge;
