import React from "react";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

/**
 * Fallback only — planned tabs should be filtered from the tab rail, not shown as "coming next".
 */
export default function Employee360TabPlaceholder({
  tabLabel,
  featureId,
  showProfileLink,
  onOpenProfile,
}) {
  return (
    <LuxRegisterEmptyState
      className="lux-employee-360__placeholder"
      icon="fe fe-layers"
      title={`${tabLabel} unavailable`}
      description={
        featureId
          ? "This section is not enabled for your organization yet. Open linked modules from Overview when you need related actions."
          : "This section is not available for this employee view. Use Overview or linked modules for related context."
      }
      showCreate={!!showProfileLink && typeof onOpenProfile === "function"}
      createLabel="Open HR profile"
      onCreate={onOpenProfile}
    />
  );
}
