import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import Skeleton from "react-loading-skeleton";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";
import { getFeedbackTypeLabel } from "./feedback.utils";
import LuxSummaryPageSkeleton from "views/common/fragments/LuxSummaryPageSkeleton";

const STORAGE_KEY = "famstack-feedback-summary-expanded";

const FEEDBACK_TIPS = [
  { icon: "fe-send", label: "Request feedback", hint: "Launch a campaign with template, recipients, and expiry." },
  { icon: "fe-repeat", label: "Recurring schedules", hint: "Automate weekly or monthly feedback collection." },
  { icon: "fe-sliders", label: "Templates", hint: "Configure question sets from the header action." },
];

class FeedbackPageSummary extends PureComponent {
  constructor(props) {
    super(props);
    this.state = { expanded: readSummaryExpanded(STORAGE_KEY) };
  }

  toggleExpanded = () => {
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => writeSummaryExpanded(STORAGE_KEY, this.state.expanded)
    );
  };

  buildContextLine = () => {
    const { summary, visibleCount, filterText, filterOptions } = this.props;
    const parts = [
      `${summary.total} campaigns`,
      `${summary.active} active`,
      `${summary.responseRate}% response rate`,
    ];
    if (visibleCount !== summary.total) {
      parts.push(`${visibleCount} shown`);
    }
    const showFilter = filterOptions && filterOptions.SHOW && filterOptions.SHOW.selected;
    if (showFilter && showFilter !== "ALL") {
      const opt = (filterOptions.SHOW.options || []).find((o) => o.name === showFilter);
      parts.push(opt ? opt.label : showFilter);
    }
    if (filterText) {
      parts.push(`matching “${filterText}”`);
    }
    return parts.join(" · ");
  };

  renderTypeChips = () => {
    const { summary } = this.props;
    const entries = Object.entries(summary.byType || {}).sort((a, b) => b[1] - a[1]);
    if (!entries.length) return null;
    return entries.slice(0, 4).map(([type, count]) => (
      <span key={type} className="lux-feedback-summary__chip">
        <i className="fe fe-layers" aria-hidden="true" />
        {getFeedbackTypeLabel(type)} · {count}
      </span>
    ));
  };

  renderKpiStrip = () => {
    const { summary, isLoading } = this.props;
    const kpis = [
      {
        key: "campaigns",
        label: "Campaigns",
        value: summary.total,
        tone: "indigo",
        icon: "fe fe-message-square",
        hint: `${summary.oneOff} one-off · ${summary.recurring} recurring`,
      },
      {
        key: "active",
        label: "Active",
        value: summary.active,
        tone: "green",
        icon: "fe fe-zap",
        hint: `${summary.inactive} inactive`,
      },
      {
        key: "recipients",
        label: "Recipients",
        value: summary.recipients,
        tone: "amber",
        icon: "fe fe-users",
        hint: `${summary.awaiting} awaiting response`,
      },
      {
        key: "rate",
        label: "Response rate",
        value: summary.responseRate,
        tone: "teal",
        icon: "fe fe-activity",
        hint: `${summary.responded} responded`,
        suffix: "%",
      },
    ];

    return (
      <div className="lux-bid-summary__kpi-strip" role="list" aria-label="Feedback metrics">
        {kpis.map((kpi) => (
          <article
            key={kpi.key}
            className={classNames("lux-bid-summary__kpi", kpi.tone && `is-${kpi.tone}`)}
            role="listitem"
          >
            <div className="lux-bid-summary__kpi-top">
              <span className="lux-bid-summary__kpi-label">{kpi.label}</span>
              <span className="lux-bid-summary__kpi-icon" aria-hidden="true">
                <i className={kpi.icon} />
              </span>
            </div>
            <strong className="lux-bid-summary__kpi-value">
              {isLoading ? (
                <Skeleton width={40} />
              ) : (
                <>
                  <CountUp end={Number(kpi.value) || 0} duration={0.6} />
                  {kpi.suffix || ""}
                </>
              )}
            </strong>
            {kpi.hint && <span className="lux-bid-summary__kpi-hint">{kpi.hint}</span>}
          </article>
        ))}
      </div>
    );
  };

  renderInsights = () => {
    const { summary } = this.props;
    return (
      <div className="lux-feedback-summary__insights">
        <h3 className="lux-feedback-summary__insights-title">Workspace insights</h3>
        <ul className="lux-feedback-summary__insights-list">
          <li>
            <span>Awaiting response</span>
            <strong>{summary.awaiting}</strong>
          </li>
          <li>
            <span>Expired campaigns</span>
            <strong>{summary.expiredCampaigns}</strong>
          </li>
          <li>
            <span>Recurring schedules</span>
            <strong>{summary.recurring}</strong>
          </li>
          <li>
            <span>Responded</span>
            <strong>{summary.responded}</strong>
          </li>
        </ul>
      </div>
    );
  };

  render() {
    const { summary, isLoading, visibleCount, filterText, isEmpty } = this.props;
    const { expanded } = this.state;

    if (isLoading && (!summary || !summary.total)) {
      return <LuxSummaryPageSkeleton className="lux-feedback-summary" />;
    }

    return (
      <section
        className={classNames("lux-bid-summary lux-po-summary lux-feedback-summary", {
          "is-collapsed": !expanded,
        })}
        aria-label="Feedback overview"
      >
        <div className="lux-bid-summary__header-bar">
          <div className="lux-bid-summary__header-main">
            <LuxSummaryEyebrow variant="feedback" className="lux-bid-summary__eyebrow">
              Feedback intelligence
            </LuxSummaryEyebrow>
            {!expanded ? (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--compact">
                {isLoading ? (
                  <Skeleton width={180} height={20} borderRadius={6} />
                ) : (
                  <>
                    <CountUp end={summary.total || 0} duration={0.6} />{" "}
                    <span>
                      campaigns · {summary.responseRate}% response · {summary.awaiting} pending
                    </span>
                  </>
                )}
              </h2>
            ) : (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--bar">Feedback workspace</h2>
            )}
          </div>
          <button
            type="button"
            className="lux-bid-summary__toggle"
            onClick={this.toggleExpanded}
            aria-expanded={expanded}
            aria-controls="lux-feedback-summary-body"
          >
            <span>{getSummaryToggleLabel(expanded)}</span>
            <i className={classNames("fe", expanded ? "fe-chevron-up" : "fe-chevron-down")} aria-hidden="true" />
          </button>
        </div>

        {!expanded && (
          <div className="lux-bid-summary__collapsed-strip">
            <p className="lux-bid-summary__collapsed-line">{this.buildContextLine()}</p>
          </div>
        )}

        <div id="lux-feedback-summary-body" className="lux-bid-summary__body" aria-hidden={!expanded}>
          <p className="lux-bid-summary__subtitle">
            {this.buildContextLine()}
            {" · "}
            Track campaigns, recipient status, and response rates across your workspace.
          </p>

          <div className="lux-feedback-summary__context">{this.renderTypeChips()}</div>

          <div className="lux-bid-summary__metrics-row lux-po-summary__metrics-row">
            {this.renderKpiStrip()}
            {this.renderInsights()}
          </div>

          {isEmpty && !isLoading && (
            <div className="lux-feedback-summary__tips">
              <h3 className="lux-feedback-summary__tips-title">Getting started</h3>
              <ul className="lux-feedback-summary__tips-list">
                {FEEDBACK_TIPS.map((tip) => (
                  <li key={tip.label}>
                    <i className={`fe ${tip.icon}`} aria-hidden="true" />
                    <div>
                      <strong>{tip.label}</strong>
                      <span>{tip.hint}</span>
                    </div>
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
      </section>
    );
  }
}

export default FeedbackPageSummary;
