import React, { useCallback, useMemo, useRef, useState } from "react";
import classNames from "classnames/bind";
import dateUtils from "_helpers/date.utils";
import DashboardApexChart from "views/hrms/components/dashboard/DashboardApexChart";
import {
  buildTimelineSwimlanes,
  buildTeamHeatmap,
  formatPlannerHours,
  getUtilizationTone,
} from "./plannerAnalytics.utils";
import {
  filterPlannerWorkItems,
  getPlannerFocusEmployeeName,
  getPlannerScheduleEmptyState,
} from "./planner.utils";
import { enrichWorkItemDetail } from "./plannerHourly.utils";
import { buildDailyLoadAreaChart } from "./plannerSummary.charts";
import PlannerViewHero from "./components/PlannerViewHero";
import PlannerLuxPanel from "./components/PlannerLuxPanel";
import PlannerTimelineSegmentPopover from "./components/PlannerTimelineSegmentPopover";
import PlannerScheduleEmptyState from "./components/PlannerScheduleEmptyState";

export default function TeamCapacityTimelineView({
  workItems,
  employees,
  selectedEmployeeId,
  weekStartMoment,
  horizonWeeks,
  viewMode,
  holidayItems,
  reduceForHolidays,
  filterOptions,
  history,
  onViewModeChange,
  canAssign,
  onAssignRequest,
  leaveMap,
  capacityOverrides,
  actualsByEmployee,
  showActuals,
}) {
  const [selectedSegment, setSelectedSegment] = useState(null);
  const [hoveredSegment, setHoveredSegment] = useState(null);
  const [hoverAnchor, setHoverAnchor] = useState(null);
  const [laneFilter, setLaneFilter] = useState("");
  const hoverCloseTimer = useRef(null);

  const clearHoverSoon = useCallback(() => {
    if (hoverCloseTimer.current) clearTimeout(hoverCloseTimer.current);
    hoverCloseTimer.current = setTimeout(() => {
      setHoveredSegment(null);
      setHoverAnchor(null);
    }, 120);
  }, []);

  const showHover = useCallback((seg, el) => {
    if (hoverCloseTimer.current) clearTimeout(hoverCloseTimer.current);
    if (!el) return;
    setHoveredSegment(seg);
    setHoverAnchor(el.getBoundingClientRect());
  }, []);

  const selectSegment = useCallback((seg) => {
    setSelectedSegment(seg);
  }, []);

  const swim = useMemo(
    () =>
      buildTimelineSwimlanes({
        workItems,
        startMoment: weekStartMoment,
        horizonWeeks,
        viewMode,
        selectedEmployeeId,
        filterOptions,
      }),
    [workItems, weekStartMoment, horizonWeeks, viewMode, selectedEmployeeId, filterOptions]
  );

  const heatmap = useMemo(
    () =>
      buildTeamHeatmap({
        employees,
        workItems,
        startMoment: weekStartMoment,
        horizonWeeks,
        holidayItems,
        reduceForHolidays,
        filterOptions,
        leaveMap,
        capacityOverrides,
        actualsByEmployee,
        showActuals,
      }),
    [
      employees,
      workItems,
      weekStartMoment,
      horizonWeeks,
      holidayItems,
      reduceForHolidays,
      filterOptions,
      leaveMap,
      capacityOverrides,
      actualsByEmployee,
      showActuals,
    ]
  );

  const selectedRow = heatmap.rows.find((r) => String(r.employee.id) === String(selectedEmployeeId));
  const filtered = filterPlannerWorkItems(workItems, filterOptions, selectedEmployeeId);
  const totalMinutes = filtered.reduce((s, i) => s + (i.estDurationInMins || 60), 0);

  const lanes = swim.lanes.filter((lane) => {
    const q = laneFilter.trim().toLowerCase();
    if (q.length < 2) return true;
    return lane.title.toLowerCase().includes(q) || (lane.subtitle || "").toLowerCase().includes(q);
  });

  const emptyState = getPlannerScheduleEmptyState({
    workItems,
    filterOptions,
    selectedEmployeeId,
    employees,
    laneFilterText: laneFilter,
    visibleLaneCount: lanes.length,
  });

  const focusLabel =
    selectedEmployeeId != null
      ? getPlannerFocusEmployeeName(employees, selectedEmployeeId)
      : "All team";

  const dayCapacityStrip = swim.days.map((d) => {
    const key = d.format("YYYY-MM-DD");
    let allocated = 0;
    let capacity = 0;
    heatmap.rows.forEach((row) => {
      const cell = row.dayCells.find((c) => c.dayKey === key);
      if (cell) {
        allocated += cell.allocated;
        capacity += cell.capacity;
      }
    });
    const util = capacity > 0 ? Math.round((allocated / capacity) * 100) : 0;
    return { key, util, tone: getUtilizationTone(util), label: d.format("ddd DD"), allocated, capacity };
  });

  const teamLoadChart = useMemo(() => buildDailyLoadAreaChart(dayCapacityStrip), [dayCapacityStrip]);

  const panelProps = selectedSegment
    ? (() => {
        const d = enrichWorkItemDetail(selectedSegment.item, selectedSegment.minutes);
        const actions = [];
        if (d.item.taskId) {
          actions.push({
            key: "task",
            icon: "fe-layers",
            label: "Open deliverable",
            sublabel: d.taskName,
            variant: "primary",
            onClick: () => history.push(`/project/deliverable/${d.item.taskId}`),
          });
        }
        if (d.item.projectId) {
          actions.push({
            key: "project",
            icon: "fe-briefcase",
            label: "Open project",
            sublabel: d.projectName,
            variant: "ghost",
            onClick: () => history.push(`/project/details/${d.item.projectId}`),
          });
        }
        if (canAssign && onAssignRequest && selectedRow) {
          actions.push({
            key: "assign",
            icon: "fe-user-plus",
            label: "Assign related work",
            sublabel: selectedRow.employee.name,
            variant: "accent",
            onClick: () => {
              onAssignRequest({ employee: selectedRow.employee });
              setSelectedSegment(null);
            },
          });
        }
        return {
          open: true,
          onClose: () => setSelectedSegment(null),
          title: d.item.name || d.item.taskActCategory || selectedSegment.label,
          subtitle: `${d.statusMeta.label} · ${d.durationLabel}`,
          statusMeta: d.statusMeta,
          metrics: [
            { label: "Start", value: d.startLabel },
            { label: "End", value: d.endLabel },
            { label: "Planned", value: d.durationLabel },
            { label: "Project", value: d.projectName },
          ],
          assignments: [{ item: d.item, minutes: d.minutes }],
          primaryItem: { item: d.item, minutes: d.minutes },
          actions,
        };
      })()
    : null;

  return (
    <div className="lux-planner-timeline">
      <PlannerViewHero
        eyebrow="Timeline"
        eyebrowVariant="planner-timeline"
        title="Portfolio timeline"
        description="Day-level swimlanes show how work spans the horizon. Use Gantt → By hour for 8am–6pm scheduling. The chart below reflects team-wide daily load."
        meta={`${focusLabel} · ${formatPlannerHours(totalMinutes)} planned in view · Employee menu filters Timeline & Gantt`}
        actions={
          <div className="lux-planner-segment">
            {["WORK_ITEMS", "TASKS", "PROJECTS"].map((mode) => (
              <button
                key={mode}
                type="button"
                className={classNames({ "is-active": viewMode === mode })}
                onClick={() => onViewModeChange && onViewModeChange(mode)}
              >
                {mode === "WORK_ITEMS" ? "Work items" : mode === "TASKS" ? "Tasks" : "Projects"}
              </button>
            ))}
          </div>
        }
      />

      <div className="lux-planner-timeline__chart-card">
        <h3>Team load across horizon</h3>
        <DashboardApexChart {...teamLoadChart} />
      </div>

      <div className="lux-planner-timeline__capacity-strip">
        <span className="lux-planner-timeline__strip-label">Daily utilization</span>
        <div className="lux-planner-timeline__strip-cells">
          {dayCapacityStrip.map((d, idx) => (
            <div
              key={d.key}
              className={classNames("lux-planner-timeline__strip-cell", `is-${d.tone}`, {
                "is-today": swim.days[idx] && swim.days[idx].isSame(dateUtils.getCurrentTime(), "day"),
              })}
              title={`${d.label}: ${d.util}%`}
            >
              <span style={{ height: `${Math.min(d.util, 100)}%` }} />
              <em>{d.util}%</em>
            </div>
          ))}
        </div>
      </div>

      <div className="lux-planner-timeline__lane-search">
        <i className="fe fe-search" />
        <input type="search" placeholder="Filter lanes…" value={laneFilter} onChange={(e) => setLaneFilter(e.target.value)} />
        <span className="text-muted fsize12">{lanes.length} lane(s)</span>
      </div>

      <div
        className="lux-planner-timeline__board lux-planner-timeline__board--fluid"
        style={{ "--timeline-days": swim.days.length }}
      >
          <div className="lux-planner-timeline__axis">
            {swim.days.map((d) => (
              <div
                key={d.format("YYYY-MM-DD")}
                className={classNames("lux-planner-timeline__axis-day", {
                  "is-weekend": d.isoWeekday() >= 6,
                  "is-today": d.isSame(dateUtils.getCurrentTime(), "day"),
                })}
              >
                <span>{d.format("ddd")}</span>
                <strong>{d.format("DD MMM")}</strong>
              </div>
            ))}
            {swim.todayPct != null && (
              <div className="lux-planner-timeline__today" style={{ left: `${swim.todayPct}%` }} />
            )}
          </div>

          <div className="lux-planner-timeline__lanes">
            {emptyState && (
              <PlannerScheduleEmptyState
                title={emptyState.title}
                detail={emptyState.detail}
              />
            )}
            {lanes.map((lane) => (
              <div key={lane.id} className="lux-planner-timeline__lane">
                <div className="lux-planner-timeline__lane-head">
                  <strong>{lane.title}</strong>
                  {lane.subtitle && <span>{lane.subtitle}</span>}
                  <em>{formatPlannerHours(lane.totalMinutes)}</em>
                </div>
                <div className="lux-planner-timeline__lane-track">
                  <div className="lux-planner-timeline__day-grid" aria-hidden>
                    {swim.days.map((d) => (
                      <div
                        key={d.format("YYYY-MM-DD")}
                        className={classNames("lux-planner-timeline__day-cell", {
                          "is-weekend": d.isoWeekday() >= 6,
                          "is-today": d.isSame(dateUtils.getCurrentTime(), "day"),
                        })}
                      />
                    ))}
                  </div>
                  <div className="lux-planner-timeline__segments-layer">
                    {lane.segments.map((seg) => (
                      <button
                        type="button"
                        key={seg.id}
                        className={classNames("lux-planner-timeline__segment", {
                          "is-selected": selectedSegment && selectedSegment.id === seg.id,
                        })}
                        style={{
                          left: `${seg.leftPct}%`,
                          width: `${seg.widthPct}%`,
                          background: seg.color,
                        }}
                        onMouseEnter={(e) => showHover(seg, e.currentTarget)}
                        onMouseLeave={clearHoverSoon}
                        onFocus={(e) => showHover(seg, e.currentTarget)}
                        onBlur={clearHoverSoon}
                        onClick={() => selectSegment(seg)}
                      >
                        <span className="lux-planner-timeline__segment-label">{seg.label}</span>
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            ))}
          </div>
      </div>

      {panelProps && <PlannerLuxPanel {...panelProps} />}

      <PlannerTimelineSegmentPopover
        segment={hoveredSegment}
        anchorRect={hoverAnchor}
        onClose={clearHoverSoon}
      />
    </div>
  );
}
