import React, { Component } from "react";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { AnalyticsActionButton } from "views/analytics/components/AnalyticsLuxShared";

export default class AnalyticsSavedFiltersPanel extends Component {
  state = {
    selectedFilterId: null,
    saving: false,
    saveError: null,
  };

  componentDidUpdate(prevProps) {
    const filters = this.props.savedFilters || [];
    if (!this.state.selectedFilterId && filters.length) {
      const defaultFilter = filters.find((row) => row.isDefault) || filters[0];
      this.setState({ selectedFilterId: defaultFilter.id });
    }
  }

  handleApply = (filter) => {
    if (!filter || !this.props.onApplyFilter) return;
    this.setState({ selectedFilterId: filter.id });
    this.props.onApplyFilter(filter);
  };

  handleSave = async () => {
    const { domain, metricIds, filters, onSaveFilter } = this.props;
    if (!onSaveFilter) return;
    const name = window.prompt("Name for this saved filter:");
    if (!name || !name.trim()) return;

    this.setState({ saving: true, saveError: null });
    try {
      await onSaveFilter({
        name: name.trim(),
        domain: domain || null,
        metricIds: metricIds || [],
        filters: filters || {},
      });
      this.setState({ saving: false });
    } catch (error) {
      this.setState({
        saving: false,
        saveError: (error && error.message) || "Unable to save filter.",
      });
    }
  };

  render() {
    const { savedFilters = [], loading } = this.props;
    const { selectedFilterId, saving, saveError } = this.state;

    if (loading) {
      return <div className="lux-analytics-filters__skeleton" aria-busy="true" />;
    }

    return (
      <div className="lux-analytics-filters">
        <div className="lux-analytics-filters__head">
          <span className="lux-analytics-filters__label">Saved filters</span>
          <AnalyticsActionButton icon="fe fe-bookmark" variant="ghost" onClick={this.handleSave} disabled={saving}>
            {saving ? "Saving…" : "Save current"}
          </AnalyticsActionButton>
        </div>

        {saveError ? <p className="lux-analytics-filters__error">{saveError}</p> : null}

        <div className="lux-analytics-filters__list">
          {savedFilters.length ? (
            savedFilters.map((row) => (
              <button
                key={row.id}
                type="button"
                className={classNames("lux-analytics-filters__chip", selectedFilterId === row.id && "is-active")}
                onClick={() => this.handleApply(row)}
              >
                <strong>{row.name}</strong>
                {row.isDefault ? <span className="lux-analytics-filters__default">Default</span> : null}
                <small>{row.domain || "All domains"} · {(row.metricIds || []).length} metrics</small>
              </button>
            ))
          ) : (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="No saved filters"
              description="Save your current metric view to reuse it across dashboards and the report builder."
            />
          )}
        </div>
      </div>
    );
  }
}
