import React, { useEffect, useState } from "react";
import DashboardTeamScopeBar from "./DashboardTeamScopeBar";
import EmployeeDashboardKpiStrip from "./EmployeeDashboardKpiStrip";
import EmployeeDashboardInsights from "./EmployeeDashboardInsights";
import EmployeeDashboardAnalytics from "./EmployeeDashboardAnalytics";
import EmployeeDashboardHealth from "./EmployeeDashboardHealth";
import EmployeeDashboardRoadmap from "./EmployeeDashboardRoadmap";
import {
  buildRecentJoiners,
  buildWorkforceAlerts,
  mapFeedbackHealthSummary,
} from "./employeeDashboard.utils";
import { feedbackRequestService } from "_services/feedback.service";

function EmployeeManagerDashboard({
  stats,
  loading,
  hasData,
  analytics,
  userTeams,
  teamScopeLabel,
  managerScope,
  showFilter,
  canViewAllEmployees,
  canSwitchTeams,
  onScopeChange,
  onFilterChange,
  onUserTeamsSelection,
}) {
  const [health, setHealth] = useState(analytics && analytics.health);
  const [healthLoading, setHealthLoading] = useState(false);

  useEffect(() => {
    let cancelled = false;
    async function loadHealth() {
      setHealthLoading(true);
      try {
        const result = await feedbackRequestService.getHealthSummary(90);
        if (cancelled) {
          return;
        }
        const payload = (result && result.payload) || result;
        setHealth(
          mapFeedbackHealthSummary(
            payload,
            (analytics && analytics.activeRoster) || [],
            null
          )
        );
      } catch (e) {
        if (!cancelled) {
          setHealth(
            mapFeedbackHealthSummary(null, (analytics && analytics.activeRoster) || [], null)
          );
        }
      } finally {
        if (!cancelled) {
          setHealthLoading(false);
        }
      }
    }
    loadHealth();
    return () => {
      cancelled = true;
    };
  }, [analytics]);

  return (
    <div className="lux-hrms-dash__manager">
      <DashboardTeamScopeBar
        userTeams={userTeams}
        teamScopeLabel={teamScopeLabel}
        managerScope={managerScope}
        showFilter={showFilter}
        canViewAllEmployees={canViewAllEmployees}
        canSwitchTeams={canSwitchTeams}
        loading={loading}
        onScopeChange={onScopeChange}
        onFilterChange={onFilterChange}
        onUserTeamsSelection={onUserTeamsSelection}
      />

      <EmployeeDashboardKpiStrip stats={stats} loading={loading} variant="manager" />

      <EmployeeDashboardInsights
        recentJoiners={buildRecentJoiners(analytics.roster || [])}
        alerts={buildWorkforceAlerts(analytics.roster || [], analytics.activeRoster || [])}
        loading={loading}
      />

      <EmployeeDashboardAnalytics loading={loading} hasData={hasData} analytics={analytics} />

      <EmployeeDashboardHealth
        loading={loading || healthLoading}
        hasData={hasData}
        health={health || analytics.health}
      />

      <EmployeeDashboardRoadmap />
    </div>
  );
}

export default EmployeeManagerDashboard;
