import React, { useEffect } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import { sanitizeUiCopy } from "_helpers/ui-copy.utils";
import { PayrollDrawerLinks } from "views/payroll/components/PayrollLuxDrawerShared";
import "./PayrollLuxDrawer.css";

/**
 * Rich right-rail drawer for payroll workflows (runs, compensation, imports).
 * Reuses luxury onboarding drawer chrome with payroll accent styling.
 */
export default function PayrollLuxDrawerShell({
  open,
  onClose,
  accent = "green",
  wide = false,
  icon = "fe-layers",
  eyebrow,
  title,
  subtitle,
  badges,
  quickLinks,
  ariaLabel,
  footer,
  children,
}) {
  useEffect(() => {
    if (!open) {
      return undefined;
    }

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    const onKeyDown = (event) => {
      if (event.key === "Escape") {
        onClose();
      }
    };
    window.addEventListener("keydown", onKeyDown);

    return () => {
      document.body.style.overflow = previousOverflow;
      window.removeEventListener("keydown", onKeyDown);
    };
  }, [open, onClose]);

  if (!open) {
    return null;
  }

  const iconClass = icon.startsWith("fe-") ? icon : `fe-${icon}`;

  return createPortal(
    <div
      className="lux-onb-drawer-backdrop lux-payroll-drawer-backdrop"
      role="presentation"
      onClick={onClose}
    >
      <aside
        className={classNames(
          "lux-onb-drawer",
          "lux-gov-drawer",
          "lux-payroll-drawer",
          `lux-onb-drawer--${accent}`,
          { "lux-payroll-drawer--wide": wide }
        )}
        role="dialog"
        aria-modal="true"
        aria-label={ariaLabel || title}
        onClick={(event) => event.stopPropagation()}
      >
        <span className="lux-onb-drawer__accent" aria-hidden="true" />

        <header className="lux-onb-drawer__head">
          <div className="lux-onb-drawer__head-main">
            <span className="lux-onb-drawer__category-icon" aria-hidden="true">
              <i className={classNames("fe", iconClass)} />
            </span>
            <div className="lux-onb-drawer__head-copy">
              {eyebrow ? <span className="lux-onb-drawer__eyebrow">{sanitizeUiCopy(eyebrow)}</span> : null}
              <h2>{title}</h2>
              {subtitle ? <p className="lux-gov-drawer__subtitle">{sanitizeUiCopy(subtitle)}</p> : null}
              {badges ? <div className="lux-onb-drawer__badges lux-gov-drawer__badges">{badges}</div> : null}
            </div>
          </div>
          <button type="button" className="lux-onb-drawer__close" onClick={onClose} aria-label="Close">
            <i className="fe fe-x" aria-hidden="true" />
          </button>
        </header>

        <div className="lux-onb-drawer__body lux-gov-drawer__body lux-payroll-drawer__body">
          <PayrollDrawerLinks links={quickLinks} onNavigate={onClose} />
          {children}
        </div>

        {footer ? <footer className="lux-onb-drawer__foot lux-gov-drawer__foot lux-payroll-drawer__foot">{footer}</footer> : null}
      </aside>
    </div>,
    document.body
  );
}
