import { invoiceConstants } from '../_constants';
import { invoiceService } from '../_services';
import { notificationActions } from './notification.actions';
import { commonActions } from './common.actions';
import { userUtils } from '_helpers';
import { getApiErrorMessage } from '_helpers/apiError.utils';

export const invoiceActions = {
    getAllInvoices,
    loadMoreInvoices,
    getInvoiceInfo,
    ensureInvoiceHeader,
    createInvoice,
    updateInvoice,
    updateInvoiceStatus,
    recordPayment,
    removeInvoice
};

function getAllInvoices(limit = 12, options = {}) {
    const safeLimit = Math.max(1, Number(limit) || 12);
    const isLoadMore = options.isLoadMore === true;

    return dispatch => {
        dispatch(request(isLoadMore, safeLimit));
        invoiceService.getAllInvoices(safeLimit)
            .then(
                invoices => dispatch(success(invoices.payload, safeLimit)),
                error => dispatch(failure(getApiErrorMessage(error)))
            );
    };

    function request(isLoadMore, listLimit) {
        return { type: invoiceConstants.GETALL_INVOICES_REQUEST, isLoadMore, listLimit };
    }
    function success(invoices, listLimit) {
        return { type: invoiceConstants.GETALL_INVOICES_SUCCESS, invoices, listLimit };
    }
    function failure(error) { return { type: invoiceConstants.GETALL_INVOICES_FAILURE, error } }
}

function loadMoreInvoices(currentLimit, step = 12) {
    const nextLimit = Math.max(1, Number(currentLimit) || 12) + Math.max(1, Number(step) || 12);
    return getAllInvoices(nextLimit, { isLoadMore: true });
}

function getInvoiceInfo(invoiceId, hasAccess) {
    return dispatch => {
        dispatch(request());
        invoiceService.getInvoiceInfo(invoiceId, hasAccess)
            .then(
                invoice => dispatch(success(invoice.payload)),
                error => dispatch(failure(getApiErrorMessage(error)))
            );
    };

    function request() { return { type: invoiceConstants.GET_INVOICE_REQUEST } }
    function success(invoice) { return { type: invoiceConstants.GET_INVOICE_SUCCESS, invoice } }
    function failure(error) { return { type: invoiceConstants.GET_INVOICE_FAILURE, error } }
}

function ensureInvoiceHeader() {
    return dispatch => {
        return invoiceService.getAllInvoices(1)
            .then((response) => {
                const header = response && response.payload && response.payload.header;
                if (header && header.accessToken) {
                    dispatch({ type: invoiceConstants.SET_INVOICE_HEADER, header });
                }
                return header;
            })
            .catch(() => null);
    };
}


function createInvoice(invoiceRequest, isCreateAnother, callbackFunction) {
    return dispatch => {
        dispatch(request(invoiceRequest));
        dispatch(notificationActions.clear());
        invoiceService.createInvoice(invoiceRequest)
            .then(
                invoiceResponse => {
                    dispatch(success(invoiceResponse.payload, isCreateAnother));
                    dispatch(notificationActions.success('Invoice created successfully'));
                    callbackFunction && callbackFunction();
                },
                error => {
                    dispatch(failure(commonActions.getErrorMessage(error)));
                    dispatch(notificationActions.error(commonActions.getErrorMessage(error)));

                }
            );
    };

    function request(invoice) { return { type: invoiceConstants.CREATE_INVOICE_REQUEST, invoice } }
    function success(invoice, showModel) { return { type: invoiceConstants.CREATE_INVOICE_SUCCESS, invoice, showModel } }
    function failure(error) { return { type: invoiceConstants.CREATE_INVOICE_FAILURE, error } }
}
function updateInvoice(invoiceRequest) {
    return dispatch => {
        dispatch(request(invoiceRequest));
        dispatch(notificationActions.clear());
        invoiceService.updateInvoice(invoiceRequest)
            .then(
                invoiceResponse => {
                    dispatch(success(invoiceResponse.payload, invoiceRequest.id));
                    dispatch(notificationActions.success('Invoice update successful'));
                },
                error => {
                    dispatch(failure(commonActions.getErrorMessage(error)))
                    dispatch(notificationActions.error(commonActions.getErrorMessage(error)));
                }
            );
    };

    function request(invoice) { return { type: invoiceConstants.UPDATE_INVOICE_REQUEST, invoice } }
    function success(invoice, invoiceId) { return { type: invoiceConstants.UPDATE_INVOICE_SUCCESS, invoice, invoiceId } }
    function failure(error) { return { type: invoiceConstants.UPDATE_INVOICE_FAILURE, error } }
}


function updateInvoiceStatus(invoiceId, status, onSuccess) {
    return dispatch => {
        dispatch(request({ id: invoiceId }));
        dispatch(notificationActions.clear());
        var employeeId = userUtils.getCurrentUserId()
        invoiceService.updateInvoiceStatus(invoiceId, status, employeeId)
            .then(
                invoiceResponse => {
                    dispatch(success(invoiceResponse.payload, invoiceId));
                    dispatch(notificationActions.success('Invoice update successful'));
                    try {
                        const { recordAuditEvent } = require("config/audit-write.service");
                        const { AUDIT_ACTION_TYPES } = require("_constants/audit.constants");
                        recordAuditEvent({
                            actionType: AUDIT_ACTION_TYPES.STATUS_CHANGED,
                            headline: `Invoice status → ${status}`,
                            entityType: "invoice",
                            entityRef: String(invoiceId),
                            metadata: { financeAction: "INVOICE_STATUS_UPDATED", status },
                        });
                    } catch (ignored) {
                        // audit is best-effort
                    }
                    if (typeof onSuccess === "function") {
                        onSuccess(invoiceResponse.payload);
                    }
                },
                error => {
                    dispatch(failure(getErrorMessage(error)))
                    dispatch(notificationActions.error(getErrorMessage(error)));
                }
            );
    };

    function request(invoice) { return { type: invoiceConstants.UPDATE_INVOICE_REQUEST, invoice } }
    function success(invoice, invoiceId) { return { type: invoiceConstants.UPDATE_INVOICE_SUCCESS, invoice, invoiceId } }
    function failure(error) { return { type: invoiceConstants.UPDATE_INVOICE_FAILURE, error } }
}

function recordPayment(invoiceId, paidAmount, onSuccess) {
    return dispatch => {
        dispatch(request({ id: invoiceId }));
        dispatch(notificationActions.clear());
        var employeeId = userUtils.getCurrentUserId();
        invoiceService.recordPayment(invoiceId, paidAmount, employeeId)
            .then(
                invoiceResponse => {
                    dispatch(success(invoiceResponse.payload, invoiceId));
                    dispatch(notificationActions.success("Payment recorded"));
                    try {
                        const { recordAuditEvent } = require("config/audit-write.service");
                        const { AUDIT_ACTION_TYPES } = require("_constants/audit.constants");
                        recordAuditEvent({
                            actionType: AUDIT_ACTION_TYPES.UPDATED,
                            headline: "Invoice payment recorded",
                            entityType: "invoice",
                            entityRef: String(invoiceId),
                            metadata: { financeAction: "INVOICE_PAYMENT_RECORDED", paidAmount },
                        });
                    } catch (ignored) {
                        // audit is best-effort
                    }
                    if (typeof onSuccess === "function") {
                        onSuccess(invoiceResponse.payload);
                    }
                },
                error => {
                    dispatch(failure(getErrorMessage(error)));
                    dispatch(notificationActions.error(getErrorMessage(error)));
                }
            );
    };

    function request(invoice) { return { type: invoiceConstants.UPDATE_INVOICE_REQUEST, invoice } }
    function success(invoice, invoiceId) { return { type: invoiceConstants.UPDATE_INVOICE_SUCCESS, invoice, invoiceId } }
    function failure(error) { return { type: invoiceConstants.UPDATE_INVOICE_FAILURE, error } }
}
function getErrorMessage(error) {
    return getApiErrorMessage(error);
}


function removeInvoice(invoiceId) {
    return dispatch => {
        dispatch(request(invoiceId));

        invoiceService.removeInvoice(invoiceId)
            .then(
                invoiceResponse => dispatch(success(invoiceId)),
                error => {
                    dispatch(failure(invoiceId, getApiErrorMessage(error)));
                    dispatch(notificationActions.error(getApiErrorMessage(error)));
                }
            );
    };

    function request(invoiceId) { return { type: invoiceConstants.REMOVE_INVOICE_REQUEST, invoiceId } }
    function success(invoiceId) { return { type: invoiceConstants.REMOVE_INVOICE_SUCCESS, invoiceId } }
    function failure(invoiceId, error) { return { type: invoiceConstants.REMOVE_INVOICE_FAILURE, invoiceId, error } }
}
