import React, { Component } from "react";
import { connect } from "react-redux";
import { accessUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import LuxCreatePanelShell from "views/common/create/LuxCreatePanelShell";
import DeliverableDetailsGeneral from "../DeliverableDetailsGeneral";

class ViewTaskDetailsSidebar extends Component {
  constructor() {
    super();
    this.state = {
      permission: accessUtils.getTaskAccessControl(),
    };
  }

  renderMeta = (taskInfo) => {
    if (!taskInfo) {
      return "Schedule, ownership, checklist, and project context";
    }

    const chips = [];
    if (taskInfo.itemIdUserTeamPrefix) {
      chips.push({ key: "ref", icon: "fe fe-hash", label: taskInfo.itemIdUserTeamPrefix });
    }
    if (taskInfo.projectInfo && taskInfo.projectInfo.name) {
      chips.push({ key: "project", icon: "fe fe-briefcase", label: taskInfo.projectInfo.name });
    }
    if (taskInfo.ownerDetails && taskInfo.ownerDetails.name) {
      chips.push({ key: "owner", icon: "fe fe-user", label: taskInfo.ownerDetails.name });
    }
    if (taskInfo.estCompletionTime) {
      chips.push({
        key: "due",
        icon: "fe fe-calendar",
        label: `Due ${dateUtils.convertDateFormat(taskInfo.estCompletionTime)}`,
      });
    }

    if (!chips.length) {
      return "Schedule, ownership, checklist, and project context";
    }

    return (
      <span className="lux-view-deliverable-panel__meta">
        {chips.map((chip) => (
          <span key={chip.key} className="lux-view-deliverable-panel__meta-chip">
            <i className={chip.icon} aria-hidden="true" />
            {chip.label}
          </span>
        ))}
      </span>
    );
  };

  render() {
    const { show, onCloseViewTask, taskInfo, isLoading } = this.props;

    return (
      <LuxCreatePanelShell
        show={show}
        onClose={onCloseViewTask}
        panelId="viewtaskdetailssidebar"
        className="view_task_right_sidebar lux-view-deliverable-panel lux-overlay-shell--create"
        kicker="Deliverable"
        title={taskInfo && taskInfo.name ? taskInfo.name : "Deliverable details"}
        subtitle={this.renderMeta(taskInfo)}
        size="lg"
      >
        {show && taskInfo && (
          <div className="lux-create-panel__scroll lux-view-deliverable-panel__scroll">
            <DeliverableDetailsGeneral
              item={taskInfo}
              readOnly
              embedded
              showHero
              permission={this.state.permission}
            />
          </div>
        )}
        {show && !taskInfo && isLoading && (
          <div className="lux-view-deliverable__loading" role="status">
            <span className="lux-view-deliverable__loading-orb" aria-hidden="true" />
            <p>Loading deliverable details…</p>
          </div>
        )}
      </LuxCreatePanelShell>
    );
  }
}

const mapStateToProps = (state) => ({
  taskInfo: state.tasks.selectedTaskInfo,
  isLoading: state.tasks.loading || state.tasks.getInfoLoading,
});

export default connect(mapStateToProps)(ViewTaskDetailsSidebar);
