import React from 'react';
import { withRouter } from 'react-router-dom';
import classNames from 'classnames/bind';
import { resolveHowToDocPath } from 'config/page-howto.config';
import './HowToUseLink.css';

/**
 * Icon-only “How to use” link to Tracopus documentation.
 * Resolves href from page-howto.config via current route, or uses explicit href.
 */
function HowToUseLink({
  href,
  pathname,
  location,
  className,
  testId = 'howto-use-link',
  title = 'How to use',
}) {
  const path = pathname || (location && location.pathname) || '';
  const resolved = href || resolveHowToDocPath(path);
  if (!resolved) return null;

  return (
    <a
      href={resolved}
      target="_blank"
      rel="noopener noreferrer"
      className={classNames('lux-howto-link', className)}
      data-testid={testId}
      title={title}
      aria-label={title}
    >
      <i className="fe fe-book-open" aria-hidden="true" />
    </a>
  );
}

export default withRouter(HowToUseLink);
export { HowToUseLink as HowToUseLinkBase };
