import { RAIL_BRAND_DEFAULT, RAIL_BRAND_URL_MATCHES } from "config/brand-rail.config";

export function buildRailBrandUrlHaystack(context = {}) {
  return [context.locationHref, context.locationHostname]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
}

export function getRailBrandUrlContext() {
  if (typeof window === "undefined") {
    return {};
  }

  return {
    locationHref: window.location.href,
    locationHostname: window.location.hostname,
  };
}

export function resolveRailBrandMark(contextOrHaystack = "") {
  const haystack =
    typeof contextOrHaystack === "string"
      ? contextOrHaystack.toLowerCase()
      : buildRailBrandUrlHaystack(contextOrHaystack);

  const match = RAIL_BRAND_URL_MATCHES.find((entry) => {
    const needle = String(entry.urlContains || "").toLowerCase();
    return needle && haystack.includes(needle);
  });

  return match || RAIL_BRAND_DEFAULT;
}
