/**
 * F06-T4 — Billability and leakage analytics.
 */
import dateUtils from "_helpers/date.utils";

export function buildBillabilityLeakageAnalytics(intelligence) {
  if (!intelligence) {
    return null;
  }

  const workMins = Math.max(0, (intelligence.totalMins || 0) - (intelligence.leaveOrHolidayMins || 0));
  const billableMins = intelligence.billableMins || 0;
  const nonProjectMins = intelligence.nonProjectMins || 0;
  const billablePct = workMins > 0 ? Math.round((billableMins / workMins) * 100) : 0;
  const leakagePct = workMins > 0 ? Math.round((nonProjectMins / workMins) * 100) : 0;

  const leaveMins = intelligence.leaveOrHolidayMins || 0;
  const mixTotal = Math.max(workMins + leaveMins, 1);
  const typeChart = [
    {
      code: "Billable",
      mins: billableMins,
      pct: Math.round((billableMins / mixTotal) * 100),
      hoursLabel: `${Math.round((billableMins / 60) * 10) / 10}h`,
    },
    {
      code: "Non-billable",
      mins: nonProjectMins,
      pct: Math.round((nonProjectMins / mixTotal) * 100),
      hoursLabel: `${Math.round((nonProjectMins / 60) * 10) / 10}h`,
    },
    {
      code: "Leave / holiday",
      mins: leaveMins,
      pct: Math.round((leaveMins / mixTotal) * 100),
      hoursLabel: `${Math.round((leaveMins / 60) * 10) / 10}h`,
    },
  ].filter((row) => row.mins > 0);

  const dailyChart = (intelligence.weekDates || []).map((dateString) => {
    const day = (intelligence.dailyMap && intelligence.dailyMap[dateString]) || {};
    const dayWork = Math.max(0, (day.total || 0) - (day.leave || 0));
    const dayBillable = day.billable || 0;
    const momentDate = dateUtils.convertDateStringToMoment(dateString);
    return {
      label: momentDate && momentDate.isValid() ? momentDate.format("ddd") : dateString.slice(5),
      billablePct: dayWork > 0 ? Math.round((dayBillable / dayWork) * 100) : 0,
      leakageMins: day.nonProject || 0,
    };
  });

  return {
    billablePct,
    leakagePct,
    leakageMins: nonProjectMins,
    billableMins,
    workMins,
    typeChart,
    dailyChart,
    leakageHint:
      leakagePct > 35
        ? "Non-billable share is elevated — review internal categories and unassigned project time."
        : "Billability mix is within a typical range for this week.",
  };
}
