import React from "react";
import classNames from "classnames/bind";
import { getCompliancePackSectionMeta } from "config/compliance-pack.config";

export default function CompliancePackDetailPanel({ section, selectedCount, exporting, onExport }) {
  if (!section) {
    return (
      <aside className="lux-compliance-detail lux-compliance-detail--empty">
        <span className="lux-compliance-detail__empty-icon" aria-hidden="true">
          <i className="fe fe-download" />
        </span>
        <strong>Select a pack section</strong>
        <p>Preview record counts and checksums before generating your compliance export.</p>
        <div className="lux-compliance-detail__export-hint">
          <strong>{selectedCount}</strong> section{selectedCount === 1 ? "" : "s"} selected for export
        </div>
        <button type="button" className="lux-onb-action lux-onb-action--primary" disabled={selectedCount === 0 || exporting} onClick={onExport}>
          <i className="fe fe-download" aria-hidden="true" />
          {exporting ? "Generating…" : "Export compliance pack"}
        </button>
      </aside>
    );
  }

  const meta = getCompliancePackSectionMeta(section.id);
  const preview = section.payloadPreview;

  return (
    <aside className="lux-compliance-detail">
      <header className="lux-compliance-detail__head">
        <div className="lux-compliance-detail__identity">
          <span className={classNames("lux-compliance-detail__avatar", meta.tone && `is-${meta.tone}`)} aria-hidden="true">
            <i className={meta.icon} />
          </span>
          <div>
            <h3>{meta.label}</h3>
            <p>{section.recordCount.toLocaleString()} records · {section.checksum || "no checksum"}</p>
          </div>
        </div>
        <span className={classNames("lux-compliance-detail__status", { "is-ready": section.ready, "is-gap": !section.ready })}>
          {section.ready ? "Ready" : "Gap"}
        </span>
      </header>

      <p className="lux-compliance-detail__copy">{meta.description}</p>

      {preview && Array.isArray(preview) && preview.length > 0 && (
        <div className="lux-compliance-detail__preview">
          <h4>Payload preview</h4>
          <pre>{JSON.stringify(preview, null, 2)}</pre>
        </div>
      )}

      <div className="lux-compliance-detail__actions">
        <button type="button" className="lux-onb-action lux-onb-action--primary" disabled={selectedCount === 0 || exporting} onClick={onExport}>
          <i className="fe fe-download" aria-hidden="true" />
          {exporting ? "Generating…" : `Export pack (${selectedCount})`}
        </button>
      </div>
    </aside>
  );
}
