import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import { validationUtils } from "_helpers";

/**
 * Accounts directory toolbar — same lux-page-header layout as projects, employees, etc.
 */
class PageInnerHeaderAccounts extends PureComponent {
  onFilterTextChange = (value) => {
    if (validationUtils.validateAlphaNumbericWithSpecial(value)) {
      this.props.onFilterTextChange(value);
    }
  };

  onSearchChange = (event) => {
    this.onFilterTextChange(event.target.value);
  };

  clearSearch = () => {
    this.onFilterTextChange("");
  };

  renderBreadcrumbs = () => {
    const { breadCrumps, viewByAccounts, onSelectItem } = this.props;
    const crumbs = breadCrumps || [];
    const rootLabel = viewByAccounts ? "All accounts" : "All user teams";

    return (
      <nav className="lux-page-header__breadcrumb" aria-label="Account hierarchy">
        <button
          type="button"
          className={classNames("lux-page-header__crumb", { "is-current": crumbs.length === 0 })}
          onClick={() => onSelectItem(null, viewByAccounts ? "ACCOUNT" : "USERTEAMS", -1)}
        >
          <i className="fe fe-home" aria-hidden="true" />
          {rootLabel}
        </button>
        {crumbs.map((breadCrump, index) => {
          const isLast = index === crumbs.length - 1;
          return (
            <React.Fragment key={breadCrump.currentItem.id}>
              <i className="fe fe-chevron-right lux-page-header__crumb-sep" aria-hidden="true" />
              {isLast ? (
                <span className="lux-page-header__crumb is-current">{breadCrump.currentItem.name}</span>
              ) : (
                <button
                  type="button"
                  className="lux-page-header__crumb"
                  onClick={() => onSelectItem(breadCrump.currentItem, breadCrump.viewName, index)}
                >
                  {breadCrump.currentItem.name}
                </button>
              )}
            </React.Fragment>
          );
        })}
      </nav>
    );
  };

  render() {
    const {
      stickytop,
      embedded,
      showFilter,
      showGridListMenu,
      viewByAccounts,
      filterOptions,
      isLoading,
      gridClickHandler,
      listClickHandler,
      additionalButtons,
    } = this.props;

    const searchValue = (filterOptions && filterOptions.filterText) || "";
    const isSticky = stickytop === undefined || stickytop === true;

    const toolbar = (
        <div className="lux-page-header__toolbar">
          <div className="lux-page-header__group lux-page-header__group--filters">
            {this.renderBreadcrumbs()}
          </div>

          <div className="lux-page-header__spacer" aria-hidden="true" />

          <div className="lux-page-header__group lux-page-header__group--actions">
            {showFilter && (
              <label className="lux-page-header__search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  disabled={isLoading}
                  value={searchValue}
                  onChange={this.onSearchChange}
                  placeholder="Search name or Salesforce ID…"
                  aria-label="Search accounts"
                />
                {searchValue && (
                  <button
                    type="button"
                    className="lux-page-header__search-clear"
                    onClick={this.clearSearch}
                    aria-label="Clear search"
                  >
                    <i className="fe fe-x" aria-hidden="true" />
                  </button>
                )}
              </label>
            )}

            {showGridListMenu && (
              <div
                className="lux-page-header__segment"
                role="group"
                aria-label="Directory scope"
              >
                <button
                  type="button"
                  className={classNames("lux-page-header__segment-btn", {
                    "is-active": !viewByAccounts,
                  })}
                  onClick={gridClickHandler}
                  title="Browse by user team"
                >
                  <i className="fe fe-users" aria-hidden="true" />
                  <span>User teams</span>
                </button>
                <button
                  type="button"
                  className={classNames("lux-page-header__segment-btn", {
                    "is-active": viewByAccounts,
                  })}
                  onClick={listClickHandler}
                  title="Browse all accounts"
                >
                  <i className="fe fe-layers" aria-hidden="true" />
                  <span>All accounts</span>
                </button>
              </div>
            )}

            {additionalButtons && (
              <div className="lux-page-header__extras">{additionalButtons}</div>
            )}
          </div>
        </div>
    );

    if (embedded) {
      return toolbar;
    }

    return (
      <div
        className={classNames("lux-page-header", "lux-page-header--accounts", {
          "is-sticky": isSticky,
        })}
      >
        {toolbar}
      </div>
    );
  }
}

export default PageInnerHeaderAccounts;
