/**
 * EH02 — Requisition master FE service. Fail closed when flag on.
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import { shouldUseRequisitionApi } from "config/offer-requisition.config";

export const requisitionService = {
  listRequisitions,
  createRequisition,
};

const API_ERROR = { payload: null, source: "api-error" };

function resolveUserTeamId() {
  return commonUtils.getCurrentUserTeamId();
}

async function listRequisitions() {
  if (!shouldUseRequisitionApi()) {
    return { ...API_ERROR, reason: "flag-off" };
  }
  try {
    const response = await axiosUtils.getWithParam(urlConfig.REQUISITIONS_API_PATH, {
      userTeamId: resolveUserTeamId(),
    });
    const payload = response && response.payload != null ? response.payload : response;
    if (Array.isArray(payload)) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[Requisition] API unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}

async function createRequisition(body = {}) {
  if (!shouldUseRequisitionApi()) {
    return { ...API_ERROR, reason: "flag-off" };
  }
  try {
    const response = await axiosUtils.post(urlConfig.REQUISITIONS_API_PATH, {
      ...body,
      userTeamId: body.userTeamId || resolveUserTeamId(),
      actorId: body.actorId || commonUtils.getCurrentUserId(),
    });
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[Requisition] create unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}
