import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import LuxBackNavLink from "./LuxBackNavLink";

/**
 * Back row: “Back to &lt;page&gt;” plus optional current-item breadcrumb suffix.
 */
export default function LuxBackNav({
  to,
  destinationLabel,
  currentLabel,
  component = Link,
  className,
  navClassName,
  actions,
  "aria-label": ariaLabel = "Back navigation",
}) {
  return (
    <nav
      className={classNames(
        "lux-back-nav",
        "pd-back-nav",
        { "lux-back-nav--with-actions": !!actions },
        navClassName,
        className
      )}
      aria-label={ariaLabel}
    >
      <div className="lux-back-nav__trail">
        <LuxBackNavLink
          to={to}
          destinationLabel={destinationLabel}
          component={component}
        />
        {currentLabel ? (
          <>
            <span className="lux-back-nav__sep" aria-hidden="true">
              /
            </span>
            <span className="lux-back-nav__current">{currentLabel}</span>
          </>
        ) : null}
      </div>
      {actions ? <div className="lux-back-nav__actions">{actions}</div> : null}
    </nav>
  );
}
