/**
 * EH23 — Admin jobs status + manual run-now FE service. Fail closed when flag on.
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import { shouldUseAdminJobsApi } from "config/admin-jobs.config";

export const adminJobsService = {
  getJobsStatus,
  runJobNow,
};

const API_ERROR = { payload: null, source: "api-error" };

async function getJobsStatus() {
  if (!shouldUseAdminJobsApi()) {
    return { ...API_ERROR, reason: "flag-off" };
  }
  try {
    const response = await axiosUtils.getWithParam(`${urlConfig.ADMIN_JOBS_API_PATH}/status`, {
      userTeamId: commonUtils.getCurrentUserTeamId(),
    });
    const payload = response && response.payload ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[AdminJobs] API unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}

/**
 * Manually run a schedule type for the current team.
 * TIMESHEET_DATA_QUALITY runs the on-demand DQ scan ("Run scan").
 */
async function runJobNow(scheduleType) {
  if (!shouldUseAdminJobsApi()) {
    return { ...API_ERROR, reason: "flag-off" };
  }
  if (!scheduleType) {
    return { ...API_ERROR, reason: "scheduleType-required" };
  }
  try {
    const teamId = commonUtils.getCurrentUserTeamId();
    const response = await axiosUtils.post(
      `${urlConfig.ADMIN_JOBS_API_PATH}/${encodeURIComponent(scheduleType)}/run?userTeamId=${encodeURIComponent(teamId)}`,
      {}
    );
    const payload = response && response.payload ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[AdminJobs] Run now failed.", e);
    return { ...API_ERROR, error: e };
  }
}
