import React from "react";
import classNames from "classnames/bind";
import { countRestrictedPersonas, getMaskingDomainMeta } from "config/masking-policy.utils";
import { MASKING_LEVEL_LABELS } from "config/masking-policy.config";

function formatUpdatedAt(value) {
  if (!value) return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

export default function MaskingPolicyRegister({ rules, selectedId, onSelect }) {
  return (
    <div className="lux-mask-register-wrap">
      <table className="lux-mask-register">
        <thead>
          <tr>
            <th>Field</th>
            <th>Domain</th>
            <th>Restricted</th>
            <th>Export</th>
            <th>Risk</th>
            <th>Updated</th>
          </tr>
        </thead>
        <tbody>
          {rules.map((rule) => {
            const meta = getMaskingDomainMeta(rule.domain);
            const restricted = countRestrictedPersonas(rule);
            return (
              <tr
                key={rule.id}
                className={classNames("lux-mask-register__row", {
                  "is-selected": selectedId === rule.id,
                  "is-attention": rule.risk === "high",
                })}
                onClick={() => onSelect && onSelect(rule)}
              >
                <td>
                  <div className="lux-mask-register__primary">
                    <span className={classNames("lux-mask-register__avatar", meta.tone && `is-${meta.tone}`)} aria-hidden="true">
                      <i className={meta.icon} />
                    </span>
                    <span className="lux-mask-register__primary-copy">
                      <strong className="lux-mask-register__primary-title">{rule.name}</strong>
                      <span className="lux-mask-register__primary-meta">{rule.fieldKey}</span>
                      {rule.description && <span className="lux-mask-register__primary-meta">{rule.description}</span>}
                    </span>
                  </div>
                </td>
                <td>
                  <span className="lux-mask-register__chip">{rule.domain}</span>
                </td>
                <td>
                  <span className="lux-mask-register__count">{restricted} personas</span>
                </td>
                <td>
                  <span className={classNames("lux-doc-badge", { "is-success": rule.exportRestricted, "is-muted": !rule.exportRestricted })}>
                    {rule.exportRestricted ? MASKING_LEVEL_LABELS[rule.exportLevel] || "Restricted" : "Open"}
                  </span>
                </td>
                <td>
                  <span className={classNames("lux-mask-register__risk", `is-${rule.risk}`)}>{rule.risk}</span>
                </td>
                <td>
                  <span className="lux-mask-register__date">{formatUpdatedAt(rule.updatedAt)}</span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
