import React, { Component } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import {
  validateManagerReviewPayload,
  validateSelfReviewPayload,
} from "config/performance-management.utils";
import { PerformanceActionButton } from "views/performance/components/PerformanceLuxShared";

function DrawerShell({ open, title, subtitle, accent, icon, badge, onClose, children, footer }) {
  if (!open) {
    return null;
  }
  return createPortal(
    <div className="lux-perf-drawer-backdrop" role="presentation" onClick={onClose}>
      <aside
        className={classNames("lux-perf-drawer", accent && `lux-perf-drawer--${accent}`)}
        role="dialog"
        aria-modal="true"
        aria-labelledby="lux-perf-review-drawer-title"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="lux-perf-drawer__ambient" aria-hidden="true">
          <span className="lux-perf-drawer__orb lux-perf-drawer__orb--a" />
          <span className="lux-perf-drawer__orb lux-perf-drawer__orb--b" />
        </div>
        <span className="lux-perf-drawer__accent" aria-hidden="true" />
        <header className="lux-perf-drawer__head">
          <div className="lux-perf-drawer__head-main">
            <span className="lux-perf-drawer__category-icon" aria-hidden="true">
              <i className={icon || "fe fe-clipboard"} />
            </span>
            <div className="lux-perf-drawer__head-copy">
              <span className="lux-perf-drawer__eyebrow">{subtitle}</span>
              <h2 id="lux-perf-review-drawer-title">{title}</h2>
              {badge ? <span className="lux-perf-drawer__pill">{badge}</span> : null}
            </div>
          </div>
          <button type="button" className="lux-perf-drawer__close" onClick={onClose} aria-label="Close">
            <i className="fe fe-x" aria-hidden="true" />
          </button>
        </header>
        <div className="lux-perf-drawer__body">{children}</div>
        {footer ? <footer className="lux-perf-drawer__footer">{footer}</footer> : null}
      </aside>
    </div>,
    document.body
  );
}

function Field({ label, children, hint }) {
  return (
    <label className="lux-perf-drawer__field">
      <span>{label}</span>
      {children}
      {hint ? <small className="lux-perf-drawer__hint">{hint}</small> : null}
    </label>
  );
}

function RatingPicker({ value, onChange, label }) {
  return (
    <div className="lux-perf-drawer__field">
      <span>{label}</span>
      <div className="lux-perf-drawer__rating-grid" role="radiogroup" aria-label={label}>
        {[1, 2, 3, 4, 5].map((rating) => (
          <button
            key={rating}
            type="button"
            role="radio"
            aria-checked={Number(value) === rating}
            className={classNames("lux-perf-drawer__rating", Number(value) === rating && "is-selected")}
            onClick={() => onChange(rating)}
          >
            <strong>{rating}</strong>
            <span>{rating === 5 ? "Exceptional" : rating === 4 ? "Strong" : rating === 3 ? "Solid" : rating === 2 ? "Developing" : "Needs focus"}</span>
          </button>
        ))}
      </div>
    </div>
  );
}

function EvidenceBanner({ review }) {
  if (!review) {
    return null;
  }
  return (
    <div className="lux-perf-drawer__banner is-info">
      <i className="fe fe-info" aria-hidden="true" />
      <div>
        <strong>Self-review evidence</strong>
        <p>
          {review.selfSummary || "No self summary yet."}
          {review.selfRating != null ? ` · Self rating: ${review.selfRating}` : ""}
        </p>
        {review.strengths ? <p>Strengths: {review.strengths}</p> : null}
        {review.improvements ? <p>Growth areas: {review.improvements}</p> : null}
      </div>
    </div>
  );
}

export class SelfReviewDrawer extends Component {
  state = { selfRating: "", selfSummary: "", strengths: "", improvements: "", errors: [] };

  componentDidUpdate(prevProps) {
    if (this.props.open && !prevProps.open && this.props.review) {
      this.setState({
        selfRating: this.props.review.selfRating != null ? String(this.props.review.selfRating) : "",
        selfSummary: this.props.review.selfSummary || "",
        strengths: this.props.review.strengths || "",
        improvements: this.props.review.improvements || "",
        errors: [],
      });
    }
  }

  handleSubmit = () => {
    const payload = {
      selfRating: this.state.selfRating !== "" ? Number(this.state.selfRating) : null,
      selfSummary: this.state.selfSummary,
      strengths: this.state.strengths,
      improvements: this.state.improvements,
    };
    const errors = validateSelfReviewPayload(payload);
    if (errors.length) {
      this.setState({ errors });
      return;
    }
    this.props.onSubmit(payload);
  };

  render() {
    const { open, onClose, busy, review } = this.props;
    const { selfRating, selfSummary, strengths, improvements, errors } = this.state;
    if (!review) {
      return null;
    }
    return (
      <DrawerShell
        open={open}
        title="Self review"
        subtitle={`${review.cycleName}`}
        accent="indigo"
        icon="fe fe-edit-3"
        badge={review.employeeName}
        onClose={onClose}
        footer={
          <>
            <PerformanceActionButton onClick={onClose}>Cancel</PerformanceActionButton>
            <PerformanceActionButton variant="primary" icon="fe fe-send" onClick={this.handleSubmit} disabled={busy}>
              Submit to manager
            </PerformanceActionButton>
          </>
        }
      >
        {errors.length ? <div className="lux-perf-drawer__alert">{errors.join(" ")}</div> : null}
        <section className="lux-perf-drawer__section">
          <RatingPicker
            label="Overall self rating"
            value={selfRating}
            onChange={(rating) => this.setState({ selfRating: String(rating) })}
          />
          <Field label="Summary" hint="What you delivered this cycle and impact on team outcomes.">
            <textarea rows={4} value={selfSummary} onChange={(e) => this.setState({ selfSummary: e.target.value })} />
          </Field>
          <Field label="Top strengths">
            <input value={strengths} onChange={(e) => this.setState({ strengths: e.target.value })} />
          </Field>
          <Field label="Growth areas">
            <input value={improvements} onChange={(e) => this.setState({ improvements: e.target.value })} />
          </Field>
        </section>
      </DrawerShell>
    );
  }
}

export class ManagerReviewDrawer extends Component {
  state = { managerRating: "", managerSummary: "", errors: [] };

  componentDidUpdate(prevProps) {
    if (this.props.open && !prevProps.open && this.props.review) {
      this.setState({
        managerRating: this.props.review.managerRating != null ? String(this.props.review.managerRating) : "",
        managerSummary: this.props.review.managerSummary || "",
        errors: [],
      });
    }
  }

  handleSubmit = () => {
    const payload = {
      managerRating: this.state.managerRating !== "" ? Number(this.state.managerRating) : null,
      managerSummary: this.state.managerSummary,
    };
    const errors = validateManagerReviewPayload(payload);
    if (errors.length) {
      this.setState({ errors });
      return;
    }
    this.props.onSubmit(payload);
  };

  render() {
    const { open, onClose, busy, review, readOnly } = this.props;
    const { managerRating, managerSummary, errors } = this.state;
    if (!review) {
      return null;
    }
    const completed = review.status === "completed" || readOnly;
    return (
      <DrawerShell
        open={open}
        title={completed ? "Review record" : "Manager review"}
        subtitle={`${review.cycleName}`}
        accent="violet"
        icon="fe fe-star"
        badge={review.employeeName}
        onClose={onClose}
        footer={
          completed ? (
            <PerformanceActionButton onClick={onClose}>Close</PerformanceActionButton>
          ) : (
            <>
              <PerformanceActionButton onClick={onClose}>Cancel</PerformanceActionButton>
              <PerformanceActionButton variant="primary" icon="fe fe-check" onClick={this.handleSubmit} disabled={busy}>
                Finalize rating
              </PerformanceActionButton>
            </>
          )
        }
      >
        {errors.length ? <div className="lux-perf-drawer__alert">{errors.join(" ")}</div> : null}
        <EvidenceBanner review={review} />
        <section className="lux-perf-drawer__section">
          {completed ? (
            <>
              <Field label="Manager rating">
                <input value={review.managerRating != null ? String(review.managerRating) : "—"} readOnly />
              </Field>
              <Field label="Manager summary">
                <textarea rows={4} value={review.managerSummary || ""} readOnly />
              </Field>
            </>
          ) : (
            <>
              <RatingPicker
                label="Calibrated manager rating"
                value={managerRating}
                onChange={(rating) => this.setState({ managerRating: String(rating) })}
              />
              <Field label="Manager summary" hint="Evidence-based rationale for calibration and growth conversations.">
                <textarea rows={4} value={managerSummary} onChange={(e) => this.setState({ managerSummary: e.target.value })} />
              </Field>
            </>
          )}
        </section>
      </DrawerShell>
    );
  }
}
