import React from "react";
import classNames from "classnames/bind";
import {
  formatPayrollCurrency,
  formatPayrollDate,
} from "config/payroll.utils";
import {
  buildPaycheckYtdSummary,
  getPaycheckStatusTone,
  groupPaycheckLines,
} from "config/paycheck.utils";

export default function PayslipDetailView({ paycheck, employeeView = false }) {
  if (!paycheck) {
    return null;
  }

  const grouped = groupPaycheckLines(paycheck.lines);
  const ytd = buildPaycheckYtdSummary(paycheck);

  return (
    <div className="lux-payslip-detail">
      <header className="lux-payslip-detail__summary">
        <div className="lux-payslip-detail__amounts">
          <article className="lux-payslip-detail__amount-card">
            <span>Gross pay</span>
            <strong>{formatPayrollCurrency(paycheck.gross, paycheck.currency)}</strong>
          </article>
          <article className="lux-payslip-detail__amount-card is-deduction">
            <span>Deductions</span>
            <strong>{formatPayrollCurrency(paycheck.deductions, paycheck.currency)}</strong>
          </article>
          <article className="lux-payslip-detail__amount-card is-net">
            <span>Net pay</span>
            <strong>{formatPayrollCurrency(paycheck.net, paycheck.currency)}</strong>
          </article>
        </div>
        <div className="lux-payslip-detail__meta">
          <span className={classNames("lux-doc-badge", `is-${getPaycheckStatusTone(paycheck.status)}`)}>
            {paycheck.status}
          </span>
          <span className="lux-payslip-detail__meta-item">
            <i className="fe fe-calendar" aria-hidden="true" />
            Pay date {formatPayrollDate(paycheck.payDate)}
          </span>
          <span className="lux-payslip-detail__meta-item">
            <i className="fe fe-credit-card" aria-hidden="true" />
            {paycheck.paymentMethod}
          </span>
          {!employeeView && paycheck.runName && (
            <span className="lux-payslip-detail__meta-item">
              <i className="fe fe-layers" aria-hidden="true" />
              {paycheck.runName}
            </span>
          )}
        </div>
      </header>

      {ytd && (
        <section className="lux-payslip-detail__ytd" aria-label="Year to date summary">
          <header className="lux-hrms-dash__section-head">
            <div>
              <span className="lux-hrms-dash__section-eyebrow">YTD</span>
              <h3 className="lux-hrms-dash__section-title">Year-to-date totals</h3>
            </div>
          </header>
          <div className="lux-payslip-detail__ytd-grid">
            <article className="lux-payslip-detail__ytd-card">
              <span>Gross</span>
              <strong>{formatPayrollCurrency(ytd.gross, ytd.currency)}</strong>
            </article>
            <article className="lux-payslip-detail__ytd-card">
              <span>Deductions</span>
              <strong>{formatPayrollCurrency(ytd.deductions, ytd.currency)}</strong>
            </article>
            <article className="lux-payslip-detail__ytd-card is-net">
              <span>Net</span>
              <strong>{formatPayrollCurrency(ytd.net, ytd.currency)}</strong>
            </article>
          </div>
        </section>
      )}

      <div className="lux-payslip-detail__lines">
        <section className="lux-payslip-detail__lines-panel">
          <h3 className="lux-payslip-detail__lines-title">Earnings</h3>
          <table className="lux-payslip-detail__lines-table">
            <tbody>
              {grouped.earnings.map((line) => (
                <tr key={line.id}>
                  <td>{line.label}</td>
                  <td>{formatPayrollCurrency(line.amount, paycheck.currency)}</td>
                </tr>
              ))}
              {!grouped.earnings.length && (
                <tr><td colSpan={2} className="is-empty">No earnings lines</td></tr>
              )}
            </tbody>
          </table>
        </section>
        <section className="lux-payslip-detail__lines-panel">
          <h3 className="lux-payslip-detail__lines-title">Deductions</h3>
          <table className="lux-payslip-detail__lines-table">
            <tbody>
              {grouped.deductions.map((line) => (
                <tr key={line.id}>
                  <td>{line.label}</td>
                  <td>{formatPayrollCurrency(line.amount, paycheck.currency)}</td>
                </tr>
              ))}
              {!grouped.deductions.length && (
                <tr><td colSpan={2} className="is-empty">No deduction lines</td></tr>
              )}
            </tbody>
          </table>
        </section>
      </div>
    </div>
  );
}
