import React, { Component } from "react";
import Select from "react-select";
import { createPortal } from "react-dom";
import { connect } from "react-redux";
import classNames from "classnames/bind";
import { commonUtils } from "_helpers";
import ProjectEstimateTeam from "./ProjectEstimateTeam";
import {
    getMonthRangeOptions,
    getAllTeamsGrandTotal,
    getTeamGrandTotal,
    countTeamLines,
    countTeamMonths,
    countAllTeams,
    countAllLines,
    buildTeamGroupedDetails,
    formatHours,
    formatHoursLabel,
    getSharePct,
    getTypeTotals,
} from "./projectEstimate.utils";

class ProjectEstimateInput extends Component {
    constructor() {
        super();
        this.state = {
            showEditor: false,
            showAddTeamOption: false,
            selectedTeamOption: null,
            draftEstimateRequest: null,
            expandedTeamIds: null,
        };
    }

    getMonthOptions = () =>
        getMonthRangeOptions(
            this.props.projectInfo.estStartTime,
            this.props.projectInfo.estCompletionTime
        );

    getEstimateData = () =>
        this.state.draftEstimateRequest || this.props.projectEstimateRequest || {};

    /** Expand behavior: rail stays collapsed for scanability; default expands teams with lines. */
    getExpandedMap = (data) => {
        if (this.state.expandedTeamIds) return this.state.expandedTeamIds;
        const map = {};
        if (data && this.props.variant !== "rail") {
            Object.keys(data).forEach((teamId) => {
                map[teamId] = countTeamLines(data[teamId]) > 0;
            });
        }
        return map;
    };

    openEditor = () => {
        this.setState({
            showEditor: true,
            draftEstimateRequest: this.props.projectEstimateRequest
                ? JSON.parse(JSON.stringify(this.props.projectEstimateRequest))
                : {},
        });
    };

    closeEditor = () => {
        this.setState({
            showEditor: false,
            draftEstimateRequest: null,
            showAddTeamOption: false,
            selectedTeamOption: null,
        });
    };

    syncDraft = (draft) => {
        this.setState({ draftEstimateRequest: draft }, () => {
            this.props.onChange(this.props.name, draft);
        });
    };

    onAddTeamsMonthlyEstimate = (teamId, teamEstimate) => {
        const draft = { ...this.getEstimateData(), [teamId]: { ...teamEstimate } };
        this.syncDraft(draft);
    };

    removeTeamFromEstimate = (teamIdToBeDeleted) => {
        const draft = { ...this.getEstimateData() };
        delete draft[teamIdToBeDeleted];
        this.syncDraft(draft);
    };

    handleSave = () => {
        this.props.handleUpdateEstimate();
        this.closeEditor();
    };

    toggleAddTeamOption = (isShow) => {
        this.setState({ showAddTeamOption: isShow, selectedTeamOption: null });
    };

    addTeamForEstimate = () => {
        if (this.state.selectedTeamOption) {
            this.onAddTeamsMonthlyEstimate(this.state.selectedTeamOption.value, {
                teamName: this.state.selectedTeamOption.label,
                estimates: {},
            });
        }
        this.setState({ selectedTeamOption: null, showAddTeamOption: false });
    };

    getAvailableTeams = () => {
        const data = this.getEstimateData();
        const teams = this.props.userTeams || [];
        return teams.filter((userTeam) => !data[userTeam.id]);
    };

    toggleTeamExpand = (teamId) => {
        const data = this.props.projectEstimateRequest;
        const current = this.getExpandedMap(data);
        this.setState({
            expandedTeamIds: {
                ...current,
                [teamId]: !current[teamId],
            },
        });
    };

    expandAllTeams = (expand) => {
        const data = this.props.projectEstimateRequest || {};
        const map = {};
        Object.keys(data).forEach((teamId) => {
            map[teamId] = expand;
        });
        this.setState({ expandedTeamIds: map });
    };

    renderHourFacts = (line, projectItem, stacked) => (
        <div
            className={classNames("lux-estimate-facts", {
                "is-stacked": stacked,
            })}
        >
            <div className="lux-estimate-fact is-primary">
                <span>Base</span>
                <strong>{formatHoursLabel(line.estimate)}</strong>
            </div>
            {projectItem.automationEnabled && (
                <div className="lux-estimate-fact is-muted">
                    <span>With tool</span>
                    <strong>{formatHoursLabel(line.estimateAutomation)}</strong>
                </div>
            )}
            {projectItem.revisedEstEnabled && (
                <div className="lux-estimate-fact is-accent">
                    <span>Revised</span>
                    <strong>{formatHoursLabel(line.estimateRevised)}</strong>
                </div>
            )}
        </div>
    );

    renderTeamDetail = (team, monthOptions, projectItem, teamTotal) => {
        const groups = buildTeamGroupedDetails(team, monthOptions);
        const isRail = this.props.variant === "rail";
        if (!groups.length) {
            return (
                <p className="pd-estimates__team-detail-empty">
                    No estimate lines for this team yet.
                </p>
            );
        }

        const typeTotals = getTypeTotals(team, monthOptions);

        return (
            <div className={classNames("lux-estimate-detail", { "is-rail": isRail })}>
                {typeTotals.length > 0 && (
                    <div className="lux-estimate-detail__type-strip" aria-label="Hours by type">
                        {typeTotals.map((item) => (
                            <span key={item.estimateType} className="lux-estimate-detail__type-chip">
                                <em>{item.estimateType}</em>
                                <strong>{formatHoursLabel(item.total)}</strong>
                            </span>
                        ))}
                    </div>
                )}

                {groups.map((month) => {
                    const monthShare = getSharePct(month.monthTotal, teamTotal);
                    return (
                        <section key={month.monthYear} className="lux-estimate-month">
                            <header className="lux-estimate-month__head">
                                <div className="lux-estimate-month__title">
                                    <i className="fe fe-calendar" aria-hidden="true" />
                                    <strong>{month.monthYear}</strong>
                                </div>
                                <div className="lux-estimate-month__totals">
                                    <strong>{formatHoursLabel(month.monthTotal)}</strong>
                                    <span>{monthShare}% of team</span>
                                </div>
                            </header>

                            {month.types.map((typeGroup) => (
                                <div
                                    key={`${month.monthYear}-${typeGroup.estimateType}`}
                                    className="lux-estimate-month__type"
                                >
                                    <div className="lux-estimate-month__type-bar">
                                        <span className="lux-estimate-month__type-label">
                                            {typeGroup.estimateType}
                                        </span>
                                        <span className="lux-estimate-month__type-total">
                                            {formatHoursLabel(typeGroup.typeTotal)}
                                        </span>
                                    </div>
                                    <ul className="lux-estimate-lines">
                                        {typeGroup.lines.map((line) => (
                                            <li
                                                key={line.estimateName}
                                                className="lux-estimate-lines__item"
                                            >
                                                <div className="lux-estimate-lines__name">
                                                    <i className="fe fe-layers" aria-hidden="true" />
                                                    <span title={line.estimateName}>
                                                        {line.displayName}
                                                    </span>
                                                </div>
                                                {this.renderHourFacts(line, projectItem, isRail)}
                                            </li>
                                        ))}
                                    </ul>
                                </div>
                            ))}
                        </section>
                    );
                })}
            </div>
        );
    };

    renderSummary = () => {
        const data = this.props.projectEstimateRequest;
        const monthOptions = this.getMonthOptions();
        const teamIds = data ? Object.keys(data) : [];
        const grandTotal = getAllTeamsGrandTotal(data, "estimate", monthOptions);
        const autoTotal = getAllTeamsGrandTotal(data, "estimateAutomation", monthOptions);
        const revisedTotal = getAllTeamsGrandTotal(data, "estimateRevised", monthOptions);
        const { projectItem, readOnly, projectInfo, variant } = this.props;
        const isRail = variant === "rail";
        const teamCount = countAllTeams(data);
        const lineCount = countAllLines(data);
        const expandedMap = this.getExpandedMap(data);
        const allExpanded =
            teamIds.length > 0 && teamIds.every((id) => expandedMap[id]);
        const periodLabel =
            projectInfo && projectInfo.estStartTime && projectInfo.estCompletionTime
                ? `${monthOptions.length} months`
                : "No window";

        return (
            <article
                className={classNames("pd-estimates", "lux-estimate-panel", {
                    "lux-estimate-panel--rail": isRail,
                })}
            >
                <header className="pd-estimates__head">
                    <span className="pd-estimates__icon" aria-hidden="true">
                        <i className="fe fe-pie-chart" />
                    </span>
                    <div className="pd-estimates__titles">
                        <h2 className="pd-estimates__title">Team estimates</h2>
                        <p className="pd-estimates__subtitle">
                            {isRail
                                ? `${periodLabel} · open a team for breakdown`
                                : `Monthly resource hours by team · ${periodLabel}`}
                        </p>
                    </div>
                    {!readOnly && (
                        <button
                            type="button"
                            className="lux-estimate-btn lux-estimate-btn--primary lux-estimate-btn--sm"
                            onClick={this.openEditor}
                        >
                            <i className="fe fe-edit-2" /> {isRail ? "Edit" : "Manage"}
                        </button>
                    )}
                </header>

                {isRail ? (
                    <div className="lux-estimate-rail-hero" aria-label="Estimate summary">
                        <div className="lux-estimate-rail-hero__total">
                            <span>Total base hours</span>
                            <strong>{formatHoursLabel(grandTotal)}</strong>
                        </div>
                        <div className="lux-estimate-rail-hero__meta">
                            <span>
                                <strong>{teamCount}</strong> teams
                            </span>
                            <span>
                                <strong>{lineCount}</strong> lines
                            </span>
                            {projectItem.automationEnabled && (
                                <span>
                                    Tool <strong>{formatHoursLabel(autoTotal)}</strong>
                                </span>
                            )}
                            {projectItem.revisedEstEnabled && (
                                <span>
                                    Revised <strong>{formatHoursLabel(revisedTotal)}</strong>
                                </span>
                            )}
                        </div>
                    </div>
                ) : (
                    <div className="lux-estimate-kpi-grid" role="list" aria-label="Estimate summary">
                        <div className="lux-estimate-kpi is-hero" role="listitem">
                            <span className="lux-estimate-kpi__label">Project total</span>
                            <strong className="lux-estimate-kpi__value">
                                {formatHours(grandTotal)}
                            </strong>
                            <em className="lux-estimate-kpi__unit">base hours</em>
                        </div>
                        <div className="lux-estimate-kpi" role="listitem">
                            <span className="lux-estimate-kpi__label">Teams</span>
                            <strong className="lux-estimate-kpi__value">{teamCount}</strong>
                        </div>
                        <div className="lux-estimate-kpi" role="listitem">
                            <span className="lux-estimate-kpi__label">Resource lines</span>
                            <strong className="lux-estimate-kpi__value">{lineCount}</strong>
                        </div>
                        {projectItem.automationEnabled && (
                            <div className="lux-estimate-kpi is-muted" role="listitem">
                                <span className="lux-estimate-kpi__label">With tool</span>
                                <strong className="lux-estimate-kpi__value">
                                    {formatHours(autoTotal)}
                                </strong>
                                <em className="lux-estimate-kpi__unit">hours</em>
                            </div>
                        )}
                        {projectItem.revisedEstEnabled && (
                            <div className="lux-estimate-kpi is-accent" role="listitem">
                                <span className="lux-estimate-kpi__label">Revised</span>
                                <strong className="lux-estimate-kpi__value">
                                    {formatHours(revisedTotal)}
                                </strong>
                                <em className="lux-estimate-kpi__unit">hours</em>
                            </div>
                        )}
                    </div>
                )}

                {!isRail &&
                    (projectItem.automationEnabled || projectItem.revisedEstEnabled) && (
                        <div className="lux-estimate-legend" aria-label="Hours legend">
                            <span className="lux-estimate-legend__item is-primary">
                                <i /> Base hours — planned effort
                            </span>
                            {projectItem.automationEnabled && (
                                <span className="lux-estimate-legend__item is-muted">
                                    <i /> With tool — hours if automation is used
                                </span>
                            )}
                            {projectItem.revisedEstEnabled && (
                                <span className="lux-estimate-legend__item is-accent">
                                    <i /> Revised — latest re-forecast
                                </span>
                            )}
                        </div>
                    )}

                {teamIds.length === 0 && (
                    <div className="pd-estimates__empty">
                        <i className="fe fe-layers" />
                        <p>No team estimates yet</p>
                        <span className="pd-estimates__empty-hint">
                            {isRail
                                ? "Edit to add teams and monthly resource hours."
                                : "Break delivery effort into teams, months, and resource lines."}
                        </span>
                        {!readOnly && (
                            <button
                                type="button"
                                className="lux-estimate-btn lux-estimate-btn--ghost"
                                onClick={this.openEditor}
                            >
                                Add first estimate
                            </button>
                        )}
                    </div>
                )}

                {teamIds.length > 0 && (
                    <div className="pd-estimates__teams">
                        {!isRail && (
                            <div className="pd-estimates__teams-toolbar">
                                <span className="pd-estimates__teams-hint">
                                    Hours by team — expand a row to see month and resource breakdown
                                </span>
                                <button
                                    type="button"
                                    className="lux-estimate-btn lux-estimate-btn--ghost lux-estimate-btn--sm"
                                    onClick={() => this.expandAllTeams(!allExpanded)}
                                >
                                    {allExpanded ? "Collapse all" : "Expand all"}
                                </button>
                            </div>
                        )}

                        {isRail && teamIds.length > 1 && (
                            <div className="pd-estimates__teams-toolbar pd-estimates__teams-toolbar--rail">
                                <span className="pd-estimates__teams-hint">
                                    Grouped by team
                                </span>
                                <button
                                    type="button"
                                    className="lux-estimate-link-btn"
                                    onClick={() => this.expandAllTeams(!allExpanded)}
                                >
                                    {allExpanded ? "Collapse" : "Show all detail"}
                                </button>
                            </div>
                        )}

                        {teamIds.map((teamId) => {
                            const team = data[teamId];
                            const total = getTeamGrandTotal(team, "estimate", monthOptions);
                            const months = countTeamMonths(team);
                            const lines = countTeamLines(team);
                            const expanded = !!expandedMap[teamId];
                            const types = team.estimateTypes || [];
                            const share = getSharePct(total, grandTotal);
                            const typeTotals = getTypeTotals(team, monthOptions);

                            return (
                                <section
                                    key={teamId}
                                    className={classNames("pd-estimates__team-card", {
                                        "is-expanded": expanded,
                                        "is-rail": isRail,
                                    })}
                                >
                                    <button
                                        type="button"
                                        className="pd-estimates__team-row"
                                        onClick={() => this.toggleTeamExpand(teamId)}
                                        aria-expanded={expanded}
                                    >
                                        <span className="pd-estimates__team-chevron" aria-hidden="true">
                                            <i
                                                className={`fe ${
                                                    expanded ? "fe-chevron-down" : "fe-chevron-right"
                                                }`}
                                            />
                                        </span>
                                        {!isRail && (
                                            <span
                                                className="pd-estimates__team-avatar"
                                                aria-hidden="true"
                                            >
                                                <i className="fe fe-users" />
                                            </span>
                                        )}
                                        <div className="pd-estimates__team-info">
                                            <span className="pd-estimates__team-name">
                                                {team.teamName || "Unnamed team"}
                                            </span>
                                            <span className="pd-estimates__team-meta">
                                                {months} mo · {lines} lines · {share}%
                                            </span>
                                            {isRail && typeTotals.length > 0 && !expanded && (
                                                <span className="pd-estimates__team-preview">
                                                    {typeTotals.slice(0, 3).map((item) => (
                                                        <em key={item.estimateType}>
                                                            {item.estimateType}{" "}
                                                            {formatHours(item.total)}h
                                                        </em>
                                                    ))}
                                                </span>
                                            )}
                                            {!isRail && types.length > 0 && (
                                                <span className="pd-estimates__team-types">
                                                    {types.map((t) => (
                                                        <em key={t}>{t}</em>
                                                    ))}
                                                </span>
                                            )}
                                            <div
                                                className="pd-estimates__team-share"
                                                aria-label={`${share}% of project total`}
                                            >
                                                <span
                                                    className="pd-estimates__team-share-bar"
                                                    style={{ width: `${share}%` }}
                                                />
                                            </div>
                                        </div>
                                        <div className="pd-estimates__team-hours-wrap">
                                            <span className="pd-estimates__team-hours">
                                                {formatHours(total)}
                                            </span>
                                            <span className="pd-estimates__team-hours-unit">hours</span>
                                        </div>
                                    </button>

                                    {expanded && (
                                        <div className="pd-estimates__team-detail">
                                            {this.renderTeamDetail(
                                                team,
                                                monthOptions,
                                                projectItem,
                                                total
                                            )}
                                        </div>
                                    )}
                                </section>
                            );
                        })}
                    </div>
                )}
            </article>
        );
    };

    renderEditor = () => {
        if (!this.state.showEditor) return null;

        const draft = this.getEstimateData();
        const teamIds = Object.keys(draft);
        const availableTeams = this.getAvailableTeams();
        const monthOptions = this.getMonthOptions();
        const grandTotal = getAllTeamsGrandTotal(draft, "estimate", monthOptions);
        const { projectItem, projectInfo } = this.props;

        const panel = (
            <>
                <button
                    type="button"
                    className="lux-estimate-sidebar__backdrop"
                    aria-label="Close team estimates"
                    onClick={this.closeEditor}
                />
                <aside
                    className="right_sidebar lux-estimate-sidebar open"
                    role="dialog"
                    aria-modal="true"
                    aria-label="Team estimates editor"
                >
                    <div className="lux-estimate-sidebar__shell">
                        <header className="lux-estimate-sidebar__head">
                            <div className="lux-estimate-sidebar__head-copy">
                                <span className="lux-estimate-sidebar__kicker">
                                    Resource planning
                                </span>
                                <h2 className="lux-estimate-sidebar__title">Team estimates</h2>
                                <p className="lux-estimate-sidebar__subtitle">
                                    Add teams, then month and resource lines. Base hours are the main
                                    plan
                                    {projectItem.automationEnabled
                                        ? "; With tool is optional automation hours"
                                        : ""}
                                    {projectItem.revisedEstEnabled
                                        ? "; Revised is the latest re-forecast"
                                        : ""}
                                    {projectInfo && projectInfo.name
                                        ? ` — ${projectInfo.name}`
                                        : ""}
                                    .
                                </p>
                            </div>
                            <button
                                type="button"
                                className="lux-estimate-sidebar__close"
                                onClick={this.closeEditor}
                                aria-label="Close"
                            >
                                <i className="fe fe-x" />
                            </button>
                        </header>

                        <div className="lux-estimate-sidebar__summary">
                            <div className="lux-estimate-sidebar__summary-kpi">
                                <span>Teams</span>
                                <strong>{teamIds.length}</strong>
                            </div>
                            <div className="lux-estimate-sidebar__summary-kpi">
                                <span>Lines</span>
                                <strong>{countAllLines(draft)}</strong>
                            </div>
                            <div className="lux-estimate-sidebar__summary-kpi is-primary">
                                <span>Base hours</span>
                                <strong>{formatHoursLabel(grandTotal)}</strong>
                            </div>
                            {projectItem.automationEnabled && (
                                <div className="lux-estimate-sidebar__summary-kpi is-muted">
                                    <span>With tool</span>
                                    <strong>
                                        {formatHoursLabel(
                                            getAllTeamsGrandTotal(
                                                draft,
                                                "estimateAutomation",
                                                monthOptions
                                            )
                                        )}
                                    </strong>
                                </div>
                            )}
                        </div>

                        <div className="lux-estimate-sidebar__body">
                            {teamIds.length === 0 && (
                                <div className="pd-estimates__empty pd-estimates__empty--sidebar">
                                    <i className="fe fe-users" />
                                    <p>Add a team to start building monthly estimates</p>
                                    <span className="pd-estimates__empty-hint">
                                        Choose a delivery team, then add month and resource lines.
                                    </span>
                                </div>
                            )}

                            {teamIds.map((teamId) => (
                                <ProjectEstimateTeam
                                    key={teamId}
                                    editable
                                    projectInfo={this.props.projectInfo}
                                    teamProjectEstimate={draft[teamId]}
                                    teamId={teamId}
                                    onAddTeamEstimate={this.onAddTeamsMonthlyEstimate}
                                    removeTeamFromEstimate={this.removeTeamFromEstimate}
                                    projectItem={this.props.projectItem}
                                    userTeams={this.props.userTeams}
                                    projectGrandTotal={grandTotal}
                                />
                            ))}

                            {this.state.showAddTeamOption && availableTeams.length > 0 && (
                                <div className="lux-estimate-add-team">
                                    <div className="lux-estimate-add-team__head">
                                        <i className="fe fe-user-plus" aria-hidden="true" />
                                        <div>
                                            <strong>Add a team</strong>
                                            <p>Teams already in the estimate are hidden from this list.</p>
                                        </div>
                                    </div>
                                    <label className="lux-estimate-field__label">Team</label>
                                    <Select
                                        isSearchable
                                        isClearable
                                        placeholder="Select team"
                                        classNamePrefix="custom-select"
                                        menuPlacement="auto"
                                        value={this.state.selectedTeamOption}
                                        onChange={(opt) =>
                                            this.setState({ selectedTeamOption: opt })
                                        }
                                        options={commonUtils.convertObjectToSelectObject(
                                            availableTeams
                                        )}
                                    />
                                    <div className="lux-estimate-add-team__actions">
                                        <button
                                            type="button"
                                            className="lux-estimate-btn lux-estimate-btn--primary lux-estimate-btn--sm"
                                            onClick={this.addTeamForEstimate}
                                            disabled={!this.state.selectedTeamOption}
                                        >
                                            Add team
                                        </button>
                                        <button
                                            type="button"
                                            className="lux-estimate-btn lux-estimate-btn--ghost lux-estimate-btn--sm"
                                            onClick={() => this.toggleAddTeamOption(false)}
                                        >
                                            Cancel
                                        </button>
                                    </div>
                                </div>
                            )}

                            {!this.state.showAddTeamOption && availableTeams.length > 0 && (
                                <button
                                    type="button"
                                    className="lux-estimate-add-team-btn"
                                    onClick={() => this.toggleAddTeamOption(true)}
                                >
                                    <i className="fe fe-plus-circle" /> Add another team
                                </button>
                            )}
                        </div>

                        <footer className="lux-estimate-sidebar__foot">
                            <p className="lux-estimate-sidebar__foot-hint">
                                Totals update as you add lines. Save to store on the project.
                            </p>
                            <div className="lux-estimate-sidebar__foot-actions">
                                <button
                                    type="button"
                                    className="lux-estimate-btn lux-estimate-btn--ghost"
                                    onClick={this.closeEditor}
                                >
                                    Cancel
                                </button>
                                <button
                                    type="button"
                                    className="lux-estimate-btn lux-estimate-btn--primary"
                                    onClick={this.handleSave}
                                >
                                    <i className="fe fe-check" /> Save estimates
                                </button>
                            </div>
                        </footer>
                    </div>
                </aside>
            </>
        );

        if (typeof document !== "undefined") {
            return createPortal(panel, document.body);
        }
        return panel;
    };

    render() {
        return (
            <>
                {this.renderSummary()}
                {this.renderEditor()}
            </>
        );
    }
}

export default connect()(ProjectEstimateInput);
