import dateUtils from "_helpers/date.utils";
import moment from "moment";
import { accessUtils } from "./access.utils";
import { shouldUseApprovalDelegation } from "_helpers/approvalDelegation.config";

export const APPROVAL_DELEGATION_SCOPES = [
  {
    id: "ATTENDANCE",
    label: "Attendance",
    icon: "fe-calendar",
    hint: "Check-in, checkout, and removal requests",
  },
  {
    id: "TIMESHEET",
    label: "Timesheet",
    icon: "fe-clock",
    hint: "Weekly timesheet submissions and resubmits",
  },
  {
    id: "LEAVE",
    label: "Leave",
    icon: "fe-briefcase",
    hint: "Leave requests and approvals",
  },
];

export const DELEGATION_DATE_PRESETS = [
  { id: "week", label: "1 week", days: 7 },
  { id: "two-weeks", label: "2 weeks", days: 14 },
  { id: "month", label: "1 month", days: 30 },
];

export function getEmployeeInitials(name) {
  if (!name || typeof name !== "string") return "?";
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase();
}

export function summarizeDelegations(delegations) {
  const list = delegations || [];
  let active = 0;
  let upcoming = 0;
  let ended = 0;
  list.forEach((delegation) => {
    const status = getDelegationStatus(delegation);
    if (status === "active") active += 1;
    else if (status === "upcoming") upcoming += 1;
    else ended += 1;
  });
  return { total: list.length, active, upcoming, ended };
}

export function applyDelegationDatePreset(presetId, startDate) {
  const preset = DELEGATION_DATE_PRESETS.find((item) => item.id === presetId);
  if (!preset) return null;
  const start = startDate ? moment(startDate, "YYYY-MM-DD", true) : moment();
  const validStart = start.isValid() ? start : moment();
  return {
    startDate: validStart.format("YYYY-MM-DD"),
    endDate: validStart.clone().add(preset.days, "days").format("YYYY-MM-DD"),
  };
}

export function buildDelegationScopePills(approvalTypes) {
  const types = approvalTypes || [];
  return APPROVAL_DELEGATION_SCOPES.filter((scope) =>
    types.some((type) => String(type).toUpperCase() === scope.id)
  );
}

export function formatApprovalDelegationScope(approvalTypes) {
  const types = approvalTypes || [];
  if (!types.length) return "—";
  const labels = types.map((type) => {
    const normalized = String(type).toUpperCase();
    if (normalized === "ATTENDANCE") return "Attendance";
    if (normalized === "TIMESHEET") return "Timesheet";
    if (normalized === "LEAVE") return "Leave";
    if (normalized === "ALL") return "All approval types";
    if (normalized === "BOTH") return "Attendance & timesheet";
    return type;
  });
  return labels.join(", ");
}

export function parseDelegationDate(value) {
  if (!value) return null;
  if (moment.isMoment(value)) return value;
  if (typeof value === "string") {
    const iso = moment(value);
    if (iso.isValid()) return iso;
    return dateUtils.convertDateToMoment(value);
  }
  return dateUtils.convertDateToMoment(value);
}

export function formatDelegationDateRange(delegation) {
  if (!delegation) return "—";
  const start = parseDelegationDate(delegation.startDate);
  const end = parseDelegationDate(delegation.endDate);
  if (start && end && start.isValid() && end.isValid()) {
    return `${start.format("D MMM YYYY")} – ${end.format("D MMM YYYY")}`;
  }
  if (start && start.isValid()) {
    return `From ${start.format("D MMM YYYY")}`;
  }
  return "—";
}

export function getDelegationStatus(delegation, asOf) {
  if (!delegation) return "unknown";
  if (delegation.active === false) return "revoked";
  const now = asOf || moment();
  const start = parseDelegationDate(delegation.startDate);
  const end = parseDelegationDate(delegation.endDate);
  if (end && end.isValid() && end.isBefore(now, "day")) return "expired";
  if (start && start.isValid() && start.isAfter(now, "day")) return "upcoming";
  return "active";
}

export function getDelegationStatusMeta(status) {
  if (status === "active") {
    return { label: "Active", tone: "active" };
  }
  if (status === "upcoming") {
    return { label: "Upcoming", tone: "upcoming" };
  }
  if (status === "expired") {
    return { label: "Ended", tone: "ended" };
  }
  if (status === "revoked") {
    return { label: "Revoked", tone: "revoked" };
  }
  return { label: "Unknown", tone: "ended" };
}

export function sortDelegationsForDisplay(delegations) {
  const list = (delegations || []).slice();
  const order = { active: 0, upcoming: 1, expired: 2, revoked: 3, unknown: 4 };
  return list.sort((a, b) => {
    const statusA = getDelegationStatus(a);
    const statusB = getDelegationStatus(b);
    if (order[statusA] !== order[statusB]) {
      return order[statusA] - order[statusB];
    }
    const startA = parseDelegationDate(a.startDate);
    const startB = parseDelegationDate(b.startDate);
    if (startA && startB && startA.isValid() && startB.isValid()) {
      return startB.valueOf() - startA.valueOf();
    }
    return 0;
  });
}

export function toDelegationDateTime(value, endOfDay) {
  const parsed = parseDelegationDate(value);
  if (!parsed || !parsed.isValid()) return null;
  const momentValue = endOfDay ? parsed.clone().endOf("day") : parsed.clone().startOf("day");
  return momentValue.format(dateUtils.SERVER_DATE_FORMAT);
}

export function buildDelegationPayload(form) {
  return {
    delegateId: form.delegateId,
    approvalTypes: form.approvalTypes || [],
    startDate: toDelegationDateTime(form.startDate, false),
    endDate: toDelegationDateTime(form.endDate, true),
    note: form.note ? String(form.note).trim() : null,
  };
}

export function canManageApprovalDelegations(readOnly, permission) {
  if (readOnly) return false;
  if (!shouldUseApprovalDelegation()) return false;
  const access = permission || accessUtils.getTimeSheetAccessControl();
  return access.enableTimeSheetApproval === true;
}

export function buildDelegateOptions(employees, delegatorId) {
  const list = employees || [];
  return list
    .filter((employee) => {
      if (!employee || employee.id == null) return false;
      if (String(employee.id) === String(delegatorId)) return false;
      if (employee.active === false) return false;
      return true;
    })
    .sort((a, b) => (a.name || "").localeCompare(b.name || ""));
}
