import React, { Component } from "react";
import classNames from "classnames/bind";
import { connect } from "react-redux";
import { projectActions, purchaseOrderActions } from "_actions";
import { store } from "_helpers";
import { projectConstants } from "_constants";
import dateUtils from "_helpers/date.utils";
import LuxStatusControl, {
  DELIVERABLE_STATUS_OPTIONS,
} from "views/common/fragments/LuxStatusControl";
import LuxListRowMenuPortal from "views/common/fragments/LuxListRowMenuPortal";
import { downloadProjectSummaryCsv } from "./projectList.utils";

class ProjectDetailsHero extends Component {
  state = {
    menuOpen: false,
    confirmRemove: false,
  };

  menuTriggerRef = React.createRef();
  actionsRef = React.createRef();

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick);
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick);
  }

  handleOutsideClick = (event) => {
    if (!this.state.menuOpen) return;
    if (event.target.closest(".lux-list-row-menu-portal")) return;
    if (this.actionsRef.current && !this.actionsRef.current.contains(event.target)) {
      this.setState({ menuOpen: false, confirmRemove: false });
    }
  };

  toggleMenu = (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.setState((prev) => ({
      menuOpen: !prev.menuOpen,
      confirmRemove: false,
    }));
  };

  closeMenu = () => this.setState({ menuOpen: false, confirmRemove: false });

  runMenuAction = (handler) => (event) => {
    event.preventDefault();
    event.stopPropagation();
    this.closeMenu();
    if (handler) handler();
  };

  handleUpdateStatus = (projectId, status) => {
    store.dispatch(this.props.updateProjectStatus(projectId, status));
  };

  handleDownload = () => {
    downloadProjectSummaryCsv(this.props.item);
  };

  handleEdit = () => {
    const { item, onEditProject } = this.props;
    if (!item) return;
    if (typeof onEditProject === "function") {
      onEditProject(item);
      return;
    }
    store.dispatch({ type: projectConstants.SHOW_PROJECT_CREATE_WINDOW });
    store.dispatch(this.props.initializeCreateProject(item.userTeamId));
    store.dispatch(
      this.props.getActivePurchaseOrderList({ userTeamIds: item.userTeamId })
    );
  };

  handleDuplicate = () => {
    const { item, onDuplicateProject } = this.props;
    if (!item) return;
    if (typeof onDuplicateProject === "function") {
      onDuplicateProject(item);
      return;
    }
    store.dispatch({ type: projectConstants.SHOW_PROJECT_CREATE_WINDOW });
    store.dispatch(this.props.initializeCreateProject(item.userTeamId));
    store.dispatch(
      this.props.getActivePurchaseOrderList({ userTeamIds: item.userTeamId })
    );
  };

  handleArchive = () => {
    const { item } = this.props;
    if (!item) return;
    store.dispatch(this.props.archiveProject(item.id, !item.archived));
  };

  handleDelete = () => {
    const { item } = this.props;
    if (!item) return;
    store.dispatch(this.props.deleteProject(item.id, !item.deleted));
  };

  handleRemove = () => {
    if (this.state.confirmRemove) {
      store.dispatch(this.props.removeProject(this.props.item.id));
      this.setState({ confirmRemove: false, menuOpen: false });
      return;
    }
    this.setState({ confirmRemove: true, menuOpen: true });
  };

  canEdit = () => {
    const { item, permission } = this.props;
    return (
      item &&
      !item.archived &&
      permission &&
      permission.editEnabled &&
      item.status !== "COMPLETED" &&
      item.status !== "CLOSED"
    );
  };

  getMenuSections = () => {
    const { item, permission } = this.props;
    const primary = [
      {
        key: "download",
        icon: "fe fe-download",
        label: "Download summary",
        hint: "CSV export",
        onClick: this.handleDownload,
      },
    ];

    if (this.canEdit()) {
      primary.push({
        key: "edit",
        icon: "fe fe-edit-2",
        label: "Edit project",
        hint: "Update details",
        onClick: this.handleEdit,
      });
    }

    if (permission && permission.duplicateEnabled) {
      primary.push({
        key: "duplicate",
        icon: "fe fe-copy",
        label: "Duplicate",
        hint: "Clone as draft",
        onClick: this.handleDuplicate,
      });
    }

    const secondary = [];
    if (permission && permission.archiveEnabled) {
      secondary.push({
        key: "archive",
        icon: item.archived ? "fe fe-inbox" : "fe fe-archive",
        label: item.archived ? "Unarchive" : "Archive",
        hint: item.archived ? "Restore to active" : "Hide from active lists",
        onClick: this.handleArchive,
      });
    }
    if (permission && permission.deleteEnabled) {
      secondary.push({
        key: "delete",
        icon: item.deleted ? "fe fe-rotate-ccw" : "fe fe-trash-2",
        label: item.deleted ? "Undo delete" : "Delete",
        hint: item.deleted ? "Restore project" : "Soft-delete project",
        tone: "danger",
        onClick: this.handleDelete,
      });
    }
    if (permission && permission.removeEnabled) {
      secondary.push({
        key: "remove",
        icon: this.state.confirmRemove ? "fe fe-check" : "fe fe-x",
        label: this.state.confirmRemove ? "Confirm remove" : "Remove permanently",
        hint: this.state.confirmRemove ? "This cannot be undone" : "Permanent removal",
        tone: "danger",
        onClick: this.handleRemove,
      });
    }

    return { primary, secondary };
  };

  renderMenuItem = (entry) => (
    <button
      key={entry.key}
      type="button"
      className={classNames("lux-emp-card__menu-item", entry.tone && `is-${entry.tone}`)}
      role="menuitem"
      onClick={
        entry.key === "remove" && !this.state.confirmRemove
          ? (event) => {
              event.preventDefault();
              event.stopPropagation();
              this.handleRemove();
            }
          : this.runMenuAction(entry.onClick)
      }
    >
      <span className={classNames("lux-emp-card__menu-icon", entry.tone && `is-${entry.tone}`)}>
        <i className={entry.icon} aria-hidden="true" />
      </span>
      <span className="lux-emp-card__menu-copy">
        <strong>{entry.label}</strong>
        {entry.hint ? <span>{entry.hint}</span> : null}
      </span>
    </button>
  );

  renderFact = (icon, label, value) => {
    const display = value == null || value === "" ? "—" : value;
    return (
      <div className="pd-hero__fact">
        <span className="pd-hero__fact-icon" aria-hidden="true">
          <i className={icon} />
        </span>
        <div className="pd-hero__fact-copy">
          <span className="pd-hero__fact-label">{label}</span>
          <strong className="pd-hero__fact-value" title={String(display)}>
            {display}
          </strong>
        </div>
      </div>
    );
  };

  render() {
    const { item, permission, readOnly, compact } = this.props;
    if (!item) return null;

    const { menuOpen } = this.state;
    const teamName =
      (item.ownerUserTeamDetails && item.ownerUserTeamDetails.name) || item.teamName;
    const startLabel = dateUtils.convertDateFormat(item.estStartTime);
    const dueLabel = dateUtils.convertDateFormat(item.estCompletionTime);
    const { primary, secondary } = this.getMenuSections();
    const projectLabel = item.name || item.itemIdUserTeamPrefix || "Project";

    return (
      <header
        className={classNames("pd-hero", "lux-pd-hero", "pd-hero--dense", {
          "pd-hero--compact": compact,
        })}
      >
        <div className="pd-hero__accent" aria-hidden="true" />
        <div className="pd-hero__inner">
          <div className="pd-hero__identity">
            <div className="pd-hero__meta-row">
              <span className="pd-hero__badge">{teamName || "Team"}</span>
              <span className="pd-hero__id">{item.itemIdUserTeamPrefix}</span>
              {item.category && <span className="pd-hero__meta-chip">{item.category}</span>}
              {item.projectType && (
                <span className="pd-hero__meta-chip">{item.projectType}</span>
              )}
            </div>
            <h1 className="pd-hero__title">
              <span className="pd-hero__code">[{item.code}]</span> {item.name}
            </h1>
            <div className="pd-hero__chips">
              {item.ownerDetails && item.ownerDetails.name && (
                <span className="pd-chip pd-chip--soft">
                  <i className="fe fe-user" /> {item.ownerDetails.name}
                </span>
              )}
              {item.accountName && (
                <span className="pd-chip pd-chip--soft">
                  <i className="fe fe-briefcase" /> {item.accountName}
                </span>
              )}
              {item.priority && (
                <span className="pd-chip pd-chip--accent">{item.priority}</span>
              )}
              {item.location && (
                <span className="pd-chip pd-chip--soft">
                  <i className="fe fe-map-pin" /> {item.location}
                </span>
              )}
            </div>
          </div>
          <div className="pd-hero__actions lux-pd-hero__actions" ref={this.actionsRef}>
            <LuxStatusControl
              className="pd-hero__status"
              label="Project status"
              options={DELIVERABLE_STATUS_OPTIONS}
              value={item.status}
              allowLevelDown={permission.allowStatusLevelDown}
              changeableStatus={permission.changeableStatus}
              isReadOnly={!permission.allowStatusChange || readOnly}
              itemId={item.id}
              onChange={this.handleUpdateStatus}
            />
            {!readOnly && (
              <div
                className={classNames("lux-pd-hero__menu", {
                  "is-open": menuOpen,
                })}
              >
                <button
                  ref={this.menuTriggerRef}
                  type="button"
                  className="lux-pd-hero__menu-trigger"
                  onClick={this.toggleMenu}
                  aria-expanded={menuOpen}
                  aria-haspopup="menu"
                  aria-label={`Actions for ${projectLabel}`}
                  data-testid="project-details-hero-menu"
                >
                  <i className="fe fe-more-vertical" aria-hidden="true" />
                </button>
                <LuxListRowMenuPortal
                  open={menuOpen}
                  anchorRef={this.menuTriggerRef}
                  className="lux-bid-list__menu-panel lux-pd-hero__menu-panel"
                >
                  <header className="lux-emp-card__menu-head">
                    <span className="lux-emp-card__menu-head-icon" aria-hidden="true">
                      <i className="fe fe-layers" />
                    </span>
                    <div>
                      <span className="lux-emp-card__menu-eyebrow">Project actions</span>
                      <strong title={projectLabel}>{projectLabel}</strong>
                    </div>
                    <button
                      type="button"
                      className="lux-emp-card__menu-close"
                      onClick={this.runMenuAction(null)}
                      aria-label="Close menu"
                    >
                      <i className="fe fe-x" aria-hidden="true" />
                    </button>
                  </header>
                  <div className="lux-emp-card__menu-body">
                    {primary.map((entry) => this.renderMenuItem(entry))}
                    {secondary.length > 0 && primary.length > 0 && (
                      <div className="lux-emp-card__menu-divider" aria-hidden="true" />
                    )}
                    {secondary.map((entry) => this.renderMenuItem(entry))}
                  </div>
                </LuxListRowMenuPortal>
              </div>
            )}
          </div>
        </div>

        {!compact && (
          <div className="pd-hero__facts" aria-label="Project at a glance">
            {this.renderFact("fe fe-flag", "Start", startLabel)}
            {this.renderFact("fe fe-target", "Due", dueLabel)}
            {this.renderFact("fe fe-clock", "Hours", item.estHours)}
            {this.renderFact("fe fe-dollar-sign", "Budget", item.estCost)}
            {this.renderFact("fe fe-layers", "Complexity", item.complexity)}
            {this.renderFact(
              "fe fe-users",
              "Clients",
              item.clientNames && item.clientNames.length
                ? item.clientNames.join(", ")
                : null
            )}
          </div>
        )}
      </header>
    );
  }
}

const mapDispatchToProps = () => ({
  updateProjectStatus: projectActions.updateProjectStatus,
  initializeCreateProject: projectActions.initializeCreateProject,
  getActivePurchaseOrderList: purchaseOrderActions.getActivePurchaseOrderList,
  archiveProject: projectActions.archiveProject,
  deleteProject: projectActions.deleteProject,
  removeProject: projectActions.removeProject,
});

export default connect(null, mapDispatchToProps)(ProjectDetailsHero);
