import envconfig from "env.config";

/** True when REACT_ENV_NAME is production — mock/template paths must never run. */
export function isProductionEnv() {
  return String(envconfig.ENV_NAME || "").trim().toLowerCase() === "production";
}

/**
 * Mock/pilot data is permanently disabled. The app uses live API data only.
 * REACT_APP_USE_MOCK_DATA is ignored.
 */
export function isMockDataEnabled() {
  return false;
}

export function isTemplateModeEnabled() {
  return envconfig.TEMPLATE_MODE === true || isMockDataEnabled();
}

export function shouldShowPlannedMenuItems() {
  if (isProductionEnv()) {
    return envconfig.SHOW_PLANNED_MENU_ITEMS === true;
  }
  return envconfig.SHOW_PLANNED_MENU_ITEMS === true || isMockDataEnabled();
}

