import React from "react";
import classNames from "classnames/bind";

function scoreTone(score) {
  if (score == null) return "slate";
  if (score >= 80) return "green";
  if (score >= 60) return "amber";
  return "rose";
}

function steerLabel(score, variant) {
  if (score == null) return "Awaiting signals";
  if (score >= 80) return variant === "manager" ? "Stable steering" : "Strong execution";
  if (score >= 60) return variant === "manager" ? "Watch closely" : "Steady with gaps";
  return variant === "manager" ? "Intervention needed" : "Focus required";
}

function normalizeTone(tone) {
  if (!tone) return "slate";
  return String(tone).replace(/^is-/, "");
}

export default function ProjectDashboardCommandStrip({
  variant = "personal",
  loading,
  score,
  kicker,
  title,
  chips,
  meters,
}) {
  if (loading) {
    return (
      <section
        className="lux-proj-dash__command lux-proj-dash__command--loading"
        aria-busy="true"
        aria-label="Command snapshot"
      >
        <span className="lux-proj-dash__command-skeleton" />
        <span className="lux-proj-dash__command-skeleton is-wide" />
      </section>
    );
  }

  const tone = scoreTone(score);
  const chipRows = chips || [];
  const meterRows = meters || [];

  return (
    <section className="lux-proj-dash__command" aria-label="Command snapshot">
      <div className="lux-proj-dash__command-main">
        <span className="lux-proj-dash__command-kicker">
          <i className={variant === "manager" ? "fe fe-shield" : "fe fe-zap"} aria-hidden="true" />
          {kicker}
        </span>
        <div className="lux-proj-dash__command-headline">
          <strong className={classNames("lux-proj-dash__command-score", `is-${tone}`)}>
            {score == null ? "—" : score}
            <small>%</small>
          </strong>
          <div className="lux-proj-dash__command-copy">
            <span className="lux-proj-dash__command-title">{title}</span>
            <span className={classNames("lux-proj-dash__command-steer", `is-${tone}`)}>
              {steerLabel(score, variant)}
            </span>
            <div className="lux-proj-dash__command-meter" aria-hidden="true">
              <span style={{ width: Math.max(0, Math.min(100, score || 0)) + "%" }} />
            </div>
          </div>
        </div>
      </div>

      {chipRows.length > 0 ? (
        <div className="lux-proj-dash__command-chips" role="list">
          {chipRows.map(function (chip) {
            return (
              <article
                key={chip.id || chip.label}
                className={classNames(
                  "lux-proj-dash__command-chip",
                  chip.tone && `is-${normalizeTone(chip.tone)}`
                )}
                role="listitem"
              >
                {chip.icon ? <i className={chip.icon} aria-hidden="true" /> : null}
                <div>
                  <strong>{chip.value}</strong>
                  <span>{chip.label}</span>
                </div>
              </article>
            );
          })}
        </div>
      ) : null}

      {meterRows.length > 0 ? (
        <div className="lux-proj-dash__command-meters" role="list">
          {meterRows.map(function (meter) {
            const meterTone = normalizeTone(meter.tone);
            return (
              <article
                key={meter.title}
                className={classNames("lux-proj-dash__command-meter-card", `is-${meterTone}`)}
                role="listitem"
              >
                <div className="lux-proj-dash__command-meter-top">
                  <span className="lux-proj-dash__command-meter-label">{meter.title}</span>
                  <strong>{meter.value}</strong>
                </div>
                <p className="lux-proj-dash__command-meter-hint">{meter.hint}</p>
                <div className="lux-proj-dash__command-meter-track" aria-hidden="true">
                  <span style={{ width: Math.max(0, Math.min(100, meter.meter || 0)) + "%" }} />
                </div>
                <div className="lux-proj-dash__command-meter-foot">
                  <span>{meter.meterLabel}</span>
                  <span>{meter.meter}%</span>
                </div>
              </article>
            );
          })}
        </div>
      ) : null}
    </section>
  );
}
