import React from "react";
import { Link } from "react-router-dom";
import { buildProfileLinkFrom360 } from "views/people/employee360Navigation.utils";

/**
 * Employee 360 back-nav action — switch to HR profile / employee details.
 */
export default function Employee360DetailsEntryLink({ employeeId, location }) {
  if (!employeeId) {
    return null;
  }

  return (
    <Link
      to={buildProfileLinkFrom360(employeeId, location)}
      className="lux-back-nav__action-link lux-employee-360-entry-link"
    >
      <i className="fe fe-user" aria-hidden="true" />
      <span>Employee details</span>
    </Link>
  );
}
