import React, { Component } from "react";
import moment from "moment";
import classNames from "classnames/bind";
import {
  ATTENDANCE_EXCEPTION_TYPES,
  getExceptionTypeLabel,
} from "config/attendance-regularization.config";
import {
  buildRegularizationSubmitPayload,
  buildRegularizationEligibility,
  detectTimesheetConflict,
  isPayrollPeriodLocked,
} from "config/attendance-regularization.utils";

const INITIAL = {
  markDate: null,
  exceptionType: "MISSING_PUNCH",
  requestedInTime: "09:00",
  requestedOutTime: "18:00",
  reason: "",
  remarks: "",
};

export default class RegularizationSubmitDrawer extends Component {
  state = {
    form: { ...INITIAL },
    error: null,
    submitting: false,
  };

  componentDidUpdate(prevProps) {
    if (this.props.open && !prevProps.open) {
      const markDate = this.props.initialDate || moment();
      this.setState({
        form: { ...INITIAL, markDate: moment.isMoment(markDate) ? markDate : moment(markDate) },
        error: null,
      });
    }
  }

  updateForm = (patch) => {
    this.setState((prev) => ({
      form: { ...prev.form, ...patch },
      error: null,
    }));
  };

  validate = () => {
    const { employee, policy, timesheetWeeks } = this.props;
    const { form } = this.state;
    if (!employee || !form.markDate) {
      return "Select a date to regularize.";
    }
    if (!form.reason || !form.reason.trim()) {
      return "Provide a reason for this regularization.";
    }
    const eligibility = buildRegularizationEligibility(form.markDate, this.props.attendanceItem, policy);
    if (!eligibility.eligible) {
      return eligibility.reasons.join(" ");
    }
    if (isPayrollPeriodLocked(form.markDate, policy)) {
      return "This date falls in a payroll-locked period.";
    }
    if (detectTimesheetConflict(form.markDate, timesheetWeeks)) {
      return "Approved timesheet exists for this week — contact HR if override is required.";
    }
    return null;
  };

  handleSubmit = (e) => {
    e.preventDefault();
    const { employee, actorId, onSubmit } = this.props;
    const error = this.validate();
    if (error) {
      this.setState({ error });
      return;
    }
    const payload = buildRegularizationSubmitPayload(this.state.form, employee, actorId);
    this.setState({ submitting: true, error: null });
    Promise.resolve(onSubmit(payload))
      .then(() => this.setState({ submitting: false }))
      .catch(() => this.setState({ submitting: false, error: "Unable to submit regularization." }));
  };

  render() {
    const { open, onClose, employee, policy, attendanceItem } = this.props;
    const { form, error, submitting } = this.state;
    if (!open) return null;

    const dateLabel = form.markDate ? form.markDate.format("ddd, MMM D YYYY") : "Select date";

    return (
      <>
        <button type="button" className="lux-att-reg__backdrop" aria-label="Close" onClick={onClose} />
        <aside className="lux-att-reg__drawer" aria-label="Submit attendance regularization">
          <div className="lux-att-reg__glow" aria-hidden="true" />

          <header className="lux-att-reg__head">
            <div>
              <span className="lux-att-reg__eyebrow">Regularization request</span>
              <h2>{employee ? employee.name : "Employee"}</h2>
              <p>
                {dateLabel}
                {attendanceItem && attendanceItem.status && (
                  <span className="lux-att-reg__status-pill">{attendanceItem.status}</span>
                )}
              </p>
            </div>
            <button type="button" className="lux-att-reg__close" onClick={onClose} aria-label="Close">
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <form className="lux-att-reg__body" onSubmit={this.handleSubmit}>
            <div className="lux-att-reg__intro">
              <i className="fe fe-edit-2" aria-hidden="true" />
              <p>
                Request a correction for missing punches, late arrivals, or approved exceptions.
                Your manager will review before payroll lock applies.
              </p>
            </div>

            <div className="lux-att-reg__grid">
              <label className="lux-att-reg__field is-highlight is-wide">
                <span>Date to regularize</span>
                <input
                  type="date"
                  className="lux-att-reg__input"
                  value={form.markDate ? form.markDate.format("YYYY-MM-DD") : ""}
                  onChange={(e) => this.updateForm({ markDate: moment(e.target.value) })}
                />
              </label>

              <label className="lux-att-reg__field is-highlight is-wide">
                <span>Exception type</span>
                <select
                  className="lux-att-reg__input"
                  value={form.exceptionType}
                  onChange={(e) => this.updateForm({ exceptionType: e.target.value })}
                >
                  {ATTENDANCE_EXCEPTION_TYPES.map((type) => (
                    <option key={type.code} value={type.code}>
                      {type.label}
                    </option>
                  ))}
                </select>
              </label>

              <label className="lux-att-reg__field is-highlight">
                <span>In time</span>
                <input
                  type="time"
                  className="lux-att-reg__input"
                  value={form.requestedInTime}
                  onChange={(e) => this.updateForm({ requestedInTime: e.target.value })}
                />
              </label>

              <label className="lux-att-reg__field is-highlight">
                <span>Out time</span>
                <input
                  type="time"
                  className="lux-att-reg__input"
                  value={form.requestedOutTime}
                  onChange={(e) => this.updateForm({ requestedOutTime: e.target.value })}
                />
              </label>

              <label className="lux-att-reg__field is-highlight is-wide">
                <span>Reason</span>
                <textarea
                  className="lux-att-reg__textarea"
                  rows={3}
                  value={form.reason}
                  onChange={(e) => this.updateForm({ reason: e.target.value })}
                  placeholder={`Explain ${getExceptionTypeLabel(form.exceptionType).toLowerCase()}…`}
                />
              </label>
            </div>

            {policy && (
              <div className="lux-att-reg__policy-card">
                <i className="fe fe-shield" aria-hidden="true" />
                <div>
                  <strong>Policy limits</strong>
                  <p>
                    Max {policy.maxRequestsPerMonth} requests/month · backdate up to {policy.allowBackdatedDays} days
                    · payroll lock on day {policy.payrollLockDayOfMonth}
                  </p>
                </div>
              </div>
            )}

            {error && (
              <p className="lux-att-reg__error" role="alert">
                <i className="fe fe-alert-circle" aria-hidden="true" />
                {error}
              </p>
            )}

            <footer className="lux-att-reg__foot">
              <button type="button" className="lux-att-reg__btn" onClick={onClose}>
                Cancel
              </button>
              <button
                type="submit"
                className={classNames("lux-att-reg__btn", "is-primary", { "is-loading": submitting })}
                disabled={submitting}
              >
                <i className={submitting ? "fe fe-loader" : "fe fe-send"} aria-hidden="true" />
                {submitting ? "Submitting…" : "Submit for approval"}
              </button>
            </footer>
          </form>
        </aside>
      </>
    );
  }
}
