import React from "react";
import { FINANCE_BILLING_STATUSES, FINANCE_MARGIN_BANDS } from "config/finance-intelligence.config";
import { FinanceActionButton } from "views/finance/components/FinanceLuxShared";
import ProjectFinancialsRegister from "views/finance/components/ProjectFinancialsRegister";

const MARGIN_FILTER_OPTIONS = [
  { value: "ALL", label: "All margin bands" },
  { value: FINANCE_MARGIN_BANDS.HEALTHY, label: "Healthy" },
  { value: FINANCE_MARGIN_BANDS.WATCH, label: "Watch" },
  { value: FINANCE_MARGIN_BANDS.CRITICAL, label: "Critical" },
];

const BILLING_FILTER_OPTIONS = [
  { value: "ALL", label: "All billing statuses" },
  { value: FINANCE_BILLING_STATUSES.CURRENT, label: "Current" },
  { value: FINANCE_BILLING_STATUSES.PARTIAL, label: "Partial" },
  { value: FINANCE_BILLING_STATUSES.OVERDUE, label: "Overdue" },
  { value: FINANCE_BILLING_STATUSES.READY, label: "Ready" },
];

export default function ProjectFinancialsPanel({
  rows = [],
  loading,
  filters = {},
  programOptions = [],
  onFilterChange,
  onExport,
  exporting,
}) {
  return (
    <div className="lux-finance-snapshots">
      <div className="lux-finance-snapshots__toolbar">
        <div className="lux-finance-snapshots__filters">
          <label className="lux-finance-snapshots__field">
            <span>Search</span>
            <input
              type="search"
              placeholder="Project, code, owner…"
              value={filters.search || ""}
              onChange={(event) => onFilterChange({ search: event.target.value })}
            />
          </label>
          <label className="lux-finance-snapshots__field">
            <span>Margin band</span>
            <select
              value={filters.marginBand || "ALL"}
              onChange={(event) => onFilterChange({ marginBand: event.target.value })}
            >
              {MARGIN_FILTER_OPTIONS.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
          </label>
          <label className="lux-finance-snapshots__field">
            <span>Billing status</span>
            <select
              value={filters.billingStatus || "ALL"}
              onChange={(event) => onFilterChange({ billingStatus: event.target.value })}
            >
              {BILLING_FILTER_OPTIONS.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
          </label>
          {programOptions.length ? (
            <label className="lux-finance-snapshots__field">
              <span>Program</span>
              <select
                value={filters.programId || "ALL"}
                onChange={(event) => onFilterChange({ programId: event.target.value })}
              >
                <option value="ALL">All programs</option>
                {programOptions.map((program) => (
                  <option key={program.id} value={program.id}>
                    {program.name}
                  </option>
                ))}
              </select>
            </label>
          ) : null}
        </div>
        <div className="lux-finance-toolbar__actions">
          <FinanceActionButton icon="fe fe-download" variant="ghost" onClick={onExport} disabled={exporting || loading}>
            {exporting ? "Exporting…" : "Export CSV"}
          </FinanceActionButton>
        </div>
      </div>

      <ProjectFinancialsRegister rows={rows} loading={loading} />
    </div>
  );
}
