import React from "react";
import classNames from "classnames/bind";
import { RcaStatusBadge } from "views/knowledge/components/KnowledgeLuxShared";

export default function RcaRegister({ records, loading, selectedId, onSelect }) {
  if (loading) {
    return (
      <div className="lux-krca-register lux-krca-register--loading">
        {[1, 2, 3].map((key) => (
          <div key={key} className="lux-krca-skeleton lux-krca-skeleton--row" />
        ))}
      </div>
    );
  }

  const rows = records || [];
  if (!rows.length) {
    return (
      <div className="lux-krca-empty">
        <i className="fe fe-target" aria-hidden="true" />
        <p>No RCA records yet.</p>
      </div>
    );
  }

  return (
    <div className="lux-krca-register">
      {rows.map((row, index) => (
        <button
          key={row.id}
          type="button"
          className={classNames("lux-krca-register__row lux-krca-register__row--btn", row.tone && `is-${row.tone}`, selectedId === row.id && "is-selected")}
          onClick={() => onSelect && onSelect(row)}
        >
          <span className="lux-krca-register__index" aria-hidden="true">
            {String(index + 1).padStart(2, "0")}
          </span>
          <span className={classNames("lux-krca-register__rail", row.severity === "high" && "is-danger")} aria-hidden="true">
            <i className="fe fe-target" />
          </span>
          <span className="lux-krca-register__content">
            <span className="lux-krca-register__eyebrow">{row.number} · {row.category} · {row.severity}</span>
            <h3>{row.title}</h3>
            <p>{row.summary}</p>
            <div className="lux-krca-register__meta">
              <RcaStatusBadge status={row.status} />
              <span>{row.ownerName}</span>
              {row.ticketNumber ? <span>{row.ticketNumber}</span> : null}
            </div>
          </span>
        </button>
      ))}
    </div>
  );
}
