import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import { shouldUseIntegrationCenterApi } from "config/integration-center.config";
import { exportConnectorsCsv as buildConnectorsCsv } from "config/integration-center.utils";

import { apiErrorResult } from "config/mock-fallback.utils";

export const integrationCenterService = {
  getHubOverview,
  listConnectors,
  getConnector,
  createConnector,
  listSyncJobs,
  retrySyncJob,
  listFieldMappings,
  saveFieldMapping,
  listIntegrationLogs,
  getSyncHealthOverview,
  exportConnectorsCsv,
  listAdapters,
  getAdapter,
  testAdapterConnection,
  triggerAdapterSync,
};

function teamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

async function getHubOverview(filters = {}) {
  if (!shouldUseIntegrationCenterApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.getWithParam(
    `${urlConfig.INTEGRATION_CENTER_API_PATH}/hub/overview`,
    teamQuery(filters)
  );
  return { payload: (response && response.payload) || response, source: "api" };
}

