import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import Skeleton from "react-loading-skeleton";
import { isNotePending } from "./notes.utils";

class LuxNotesRegisterRow extends PureComponent {
  state = {
    confirmDelete: false,
  };

  componentDidUpdate(prevProps) {
    if (prevProps.note && this.props.note && prevProps.note.id !== this.props.note.id) {
      this.setState({ confirmDelete: false });
    }
  }

  handleDeleteClick = () => {
    const { onDelete, note } = this.props;
    if (!onDelete) return;
    if (this.state.confirmDelete) {
      onDelete(note);
      this.setState({ confirmDelete: false });
    } else {
      this.setState({ confirmDelete: true });
    }
  };

  render() {
    const { note, formatWhen, permission, onMarkDone, onEdit, onDelete, onToggleComplete } = this.props;
    const { confirmDelete } = this.state;
    const pending = isNotePending(note);
    const handleDone = onMarkDone || (onToggleComplete ? () => onToggleComplete(note) : null);

    return (
    <article className={classNames("lux-notes-register-row", { "is-done": !pending })}>
      <div>
        <h3 className="lux-notes-register-row__title">{note.name || "Untitled"}</h3>
        <span className={classNames("lux-note-card__status", pending ? "is-open" : "is-done")}>
          {pending ? "Open" : "Done"}
        </span>
      </div>
      <p className="lux-notes-register-row__desc">{note.description || "—"}</p>
      <span className="lux-notes-register-row__when">{formatWhen(note.noteDateTime)}</span>
      <div className="lux-notes-register-row__actions" role="group" aria-label="Note actions">
        {pending && handleDone && (!permission || permission.editEnabled !== false) && (
          <button
            type="button"
            className="lux-note-card__icon-btn is-done"
            title="Mark as done"
            aria-label="Mark as done"
            onClick={() => handleDone(note)}
          >
            <i className="fe fe-check" aria-hidden="true" />
          </button>
        )}
        {!pending && onToggleComplete && (!permission || permission.editEnabled !== false) && (
          <button
            type="button"
            className="lux-note-card__icon-btn"
            title="Reopen note"
            aria-label="Reopen note"
            onClick={() => onToggleComplete(note)}
          >
            <i className="fe fe-rotate-ccw" aria-hidden="true" />
          </button>
        )}
        {(!permission || permission.editEnabled !== false) && onEdit && (
          <button type="button" className="lux-note-card__icon-btn" title="Edit" aria-label="Edit" onClick={() => onEdit(note)}>
            <i className="fe fe-edit-2" aria-hidden="true" />
          </button>
        )}
        {(!permission || permission.removeEnabled !== false) && onDelete && (
          <button
            type="button"
            className={classNames("lux-note-card__icon-btn", "is-delete", {
              blink_text: confirmDelete,
            })}
            title={confirmDelete ? "Confirm delete" : "Delete"}
            aria-label={confirmDelete ? "Confirm delete" : "Delete"}
            onClick={this.handleDeleteClick}
          >
            <i className={classNames("fe", confirmDelete ? "fe-check" : "fe-trash-2")} aria-hidden="true" />
          </button>
        )}
      </div>
    </article>
    );
  }
}

export default function LuxNotesRegister(props) {
  const { items, isLoading, formatWhen } = props;
  if (isLoading) {
    return (
      <div className="lux-notes-page__list">
        {[1, 2, 3, 4].map((k) => (
          <Skeleton key={k} height={72} borderRadius={14} />
        ))}
      </div>
    );
  }
  return (
    <div className="lux-notes-page__list">
      {(items || []).map((note) => (
        <LuxNotesRegisterRow key={note.id} note={note} formatWhen={formatWhen} {...props} />
      ))}
    </div>
  );
}
