import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import CountUp from "react-countup";
import DashboardApexChart from "views/hrms/components/dashboard/DashboardApexChart";
import BidPipelineFunnelDiagram from "views/sales/components/fragments/BidPipelineFunnelDiagram";
import {
  buildProjectStatusDonutChart,
  buildProjectOutcomeDonutChart,
  buildProjectTypeBarChart,
  buildProjectAccountBarChart,
  buildProjectTimelineDonutChart,
  buildProjectPoLinkDonutChart,
  buildProjectCreatedTrendAreaChart,
  buildProjectTeamBarChart,
  buildProjectBillingDonutChart,
  buildProjectPriorityBarChart,
  buildProjectAutomationDonutChart,
  buildProjectCompletionShareChart,
  buildProjectPipelineLoadChart,
  buildProjectSharedDonutChart,
  buildProjectComplexityBarChart,
  buildProjectCapexDonutChart,
  buildProjectHoursEstimateDonutChart,
} from "./projectSummary.charts";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";

const SUMMARY_STORAGE_KEY = "famstack-projects-summary-expanded";

const QUICK_FILTERS = [
  { value: "ALL", label: "All" },
  { value: "ACTIVE", label: "Active" },
  { value: "ARCHIVED", label: "Archived" },
  { value: "MYPROJECTS", label: "My projects" },
  { value: "FAVORITE", label: "Favorite" },
  { value: "NEW", label: "New" },
  { value: "INPROGRESS", label: "In progress" },
  { value: "COMPLETED", label: "Completed" },
];

class ProjectPageSummary extends PureComponent {
  constructor(props) {
    super(props);
    this.state = { expanded: readSummaryExpanded(SUMMARY_STORAGE_KEY) };
  }

  toggleExpanded = () => {
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => {
        writeSummaryExpanded(SUMMARY_STORAGE_KEY, this.state.expanded);
      }
    );
  };

  getShowFilter = () => {
    const options = this.props.filterOptions;
    return (options && options.SHOW && options.SHOW.selected) || "ACTIVE";
  };

  quickFilter = (value) => {
    if (this.props.onQuickFilter) {
      this.props.onQuickFilter(value);
    }
  };

  getCharts = (stat) => ({
    statusDonut: buildProjectStatusDonutChart(stat),
    outcomeDonut: buildProjectOutcomeDonutChart(stat),
    projectTypeBar: buildProjectTypeBarChart(stat),
    accountBar: buildProjectAccountBarChart(stat),
    timelineDonut: buildProjectTimelineDonutChart(stat),
    poLinkDonut: buildProjectPoLinkDonutChart(stat),
    billingDonut: buildProjectBillingDonutChart(stat),
    automationDonut: buildProjectAutomationDonutChart(stat),
    priorityBar: buildProjectPriorityBarChart(stat),
    createdTrend: buildProjectCreatedTrendAreaChart(stat),
    teamBar: buildProjectTeamBarChart(stat),
    completionShare: buildProjectCompletionShareChart(stat),
    pipelineLoad: buildProjectPipelineLoadChart(stat),
    sharedDonut: buildProjectSharedDonutChart(stat),
    complexityBar: buildProjectComplexityBarChart(stat),
    capexDonut: buildProjectCapexDonutChart(stat),
    hoursEstimateDonut: buildProjectHoursEstimateDonutChart(stat),
  });

  buildContextLine = (stat, visibleCount, filterOptions) => {
    const parts = [];
    parts.push(
      stat.selectedTeams > 0
        ? `${stat.selectedTeams} team${stat.selectedTeams === 1 ? "" : "s"} selected`
        : "All teams"
    );
    if (visibleCount !== stat.total) {
      parts.push(`${visibleCount} of ${stat.total} shown`);
    }
    if (filterOptions && filterOptions.filterText) {
      parts.push(`matching “${filterOptions.filterText}”`);
    }
    if (stat.favorites > 0) {
      parts.push(`${stat.favorites} starred`);
    }
    return parts.join(" · ");
  };

  renderFilterChips = (showFilter, compact) => (
    <div
      className={classNames("lux-bid-summary__filters", {
        "lux-bid-summary__filters--compact": compact,
      })}
      role="group"
      aria-label="Filter projects by status"
    >
      {QUICK_FILTERS.map((option) => (
        <button
          key={option.value}
          type="button"
          className={classNames("lux-bid-summary__filter-chip", {
            "is-active": showFilter === option.value,
          })}
          onClick={() => this.quickFilter(option.value)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );

  renderKpiStrip = (stat) => (
    <div className="lux-bid-summary__kpi-strip" role="list" aria-label="Project portfolio metrics">
      {stat.kpis.map((kpi) => (
        <article
          key={kpi.key}
          className={classNames("lux-bid-summary__kpi", kpi.tone && `is-${kpi.tone}`)}
          role="listitem"
        >
          <div className="lux-bid-summary__kpi-top">
            <span className="lux-bid-summary__kpi-label">{kpi.label}</span>
            <span className="lux-bid-summary__kpi-icon" aria-hidden="true">
              <i className={kpi.icon} />
            </span>
          </div>
          <strong className="lux-bid-summary__kpi-value">
            <CountUp end={kpi.value} duration={0.85} />
          </strong>
          {kpi.hint && <span className="lux-bid-summary__kpi-hint">{kpi.hint}</span>}
        </article>
      ))}
    </div>
  );

  renderHighlights = (stat) => (
    <div className="lux-po-summary__highlights" role="list" aria-label="Project highlights">
      {stat.highlights.map((item) => (
        <article key={item.key} className={classNames("lux-po-summary__highlight", item.tone && `is-${item.tone}`)} role="listitem">
          <span className="lux-po-summary__highlight-icon" aria-hidden="true"><i className={item.icon} /></span>
          <div className="lux-po-summary__highlight-copy">
            <span className="lux-po-summary__highlight-label">{item.label}</span>
            <strong>
              <CountUp end={item.value} duration={0.75} />
              {item.suffix || ""}
            </strong>
            <span className="lux-po-summary__highlight-hint">{item.hint}</span>
          </div>
        </article>
      ))}
    </div>
  );

  renderInsightCard = (insight) => (
    <article key={insight.key} className="lux-bid-summary__insight lux-po-summary__insight">
      <header>
        <i className={insight.icon} aria-hidden="true" />
        <div>
          <strong>{insight.title}</strong>
          <span>{insight.subtitle}</span>
        </div>
      </header>
      {!insight.mix || !insight.mix.length ? (
        <div className="lux-bid-summary__bar lux-bid-summary__bar--empty">{insight.emptyLabel}</div>
      ) : (
        <>
          <div className="lux-bid-summary__bar" aria-hidden="true">
            {insight.mix.map((seg) => (
              <span key={seg.key} className={classNames("lux-bid-summary__bar-segment", `is-${seg.tone}`)} style={{ flexGrow: Math.max(seg.count, 0.15) }} title={`${seg.label}: ${seg.count}`} />
            ))}
          </div>
          <ul className="lux-bid-summary__legend">
            {insight.mix.map((seg) => (
              <li key={seg.key}>
                <span className={classNames("lux-bid-summary__legend-dot", `is-${seg.tone}`)} />
                <span>{seg.label}</span>
                <strong>{seg.count}</strong>
                <em>{seg.pct}%</em>
              </li>
            ))}
          </ul>
        </>
      )}
    </article>
  );

  renderEstimateGaps = (stat) => {
    const gaps = stat.estimateGaps;
    if (!gaps) return null;

    const isLineMode = gaps.serviceLineMode;
    const title = isLineMode
      ? "Projects missing service-line estimates"
      : "Projects missing hours & cost estimates";
    const subtitle = isLineMode
      ? "Active pipeline projects without hours or rates on their service lines."
      : "Active pipeline projects without estimated hours, rate, or cost.";
    const emptyCopy =
      gaps.pipelineTotal === 0
        ? "No open pipeline projects in the current filter."
        : "All pipeline projects have estimate details captured.";

    return (
      <section className="lux-project-summary__estimate-gaps" aria-label={title}>
        <header className="lux-project-summary__estimate-gaps-head">
          <div>
            <h3 className="lux-project-summary__estimate-gaps-title">{title}</h3>
            <p className="lux-project-summary__estimate-gaps-sub">{subtitle}</p>
          </div>
          <span
            className={classNames("lux-project-summary__estimate-gaps-badge", {
              "is-clear": gaps.total === 0,
              "is-alert": gaps.total > 0,
            })}
          >
            {gaps.total} missing
            {gaps.pipelineTotal > 0 && ` · ${gaps.pipelineTotal} in pipeline`}
          </span>
        </header>
        {!gaps.items.length ? (
          <p className="lux-project-summary__estimate-gaps-empty">{emptyCopy}</p>
        ) : (
          <ul className="lux-project-summary__estimate-gaps-list">
            {gaps.items.slice(0, 10).map((item) => (
              <li key={item.id}>
                {this.props.onViewProject ? (
                  <button
                    type="button"
                    className="lux-project-summary__estimate-gaps-item"
                    onClick={() => this.props.onViewProject(item.id)}
                  >
                    <span className="lux-project-summary__estimate-gaps-name">{item.name}</span>
                    <span className="lux-project-summary__estimate-gaps-meta">
                      {[item.code, item.teamName, item.accountName].filter(Boolean).join(" · ")}
                    </span>
                  </button>
                ) : (
                  <div className="lux-project-summary__estimate-gaps-item is-static">
                    <span className="lux-project-summary__estimate-gaps-name">{item.name}</span>
                    <span className="lux-project-summary__estimate-gaps-meta">
                      {[item.code, item.teamName, item.accountName].filter(Boolean).join(" · ")}
                    </span>
                  </div>
                )}
              </li>
            ))}
          </ul>
        )}
        {gaps.items.length > 10 && (
          <p className="lux-project-summary__estimate-gaps-more">
            +{gaps.items.length - 10} more projects missing estimates
          </p>
        )}
      </section>
    );
  };

  renderStageFlow = (stat) => (
    <div className="lux-bid-summary__stage-flow" aria-label="Project lifecycle stages">
      {[
        { key: "new", label: "New", count: stat.stageCounts.newCount, tone: "sky" },
        { key: "assigned", label: "Assigned", count: stat.stageCounts.assignedCount, tone: "indigo" },
        { key: "progress", label: "In progress", count: stat.stageCounts.inProgressCount, tone: "amber" },
        { key: "completed", label: "Completed", count: stat.stageCounts.completedCount, tone: "green" },
      ].map((stage, index, arr) => (
        <React.Fragment key={stage.key}>
          <div className={classNames("lux-bid-summary__stage-node", `is-${stage.tone}`)}>
            <span className="lux-bid-summary__stage-node-label">{stage.label}</span>
            <strong><CountUp end={stage.count} duration={0.7} /></strong>
          </div>
          {index < arr.length - 1 && (
            <span className="lux-bid-summary__stage-arrow" aria-hidden="true"><i className="fe fe-arrow-right" /></span>
          )}
        </React.Fragment>
      ))}
    </div>
  );

  renderChartPanel = (title, subtitle, chart, emptyMessage, { height = 168, wide = false, chartType = "donut", compactHead = false } = {}) => (
    <article className={classNames("lux-bid-summary__chart-panel", { "lux-bid-summary__chart-panel--wide": wide, "lux-bid-summary__chart-panel--compact": compactHead })}>
      <div className="lux-bid-summary__panel-head">
        <div>
          <h3 className="lux-bid-summary__panel-title">{title}</h3>
          {!compactHead && subtitle && <p className="lux-bid-summary__panel-sub">{subtitle}</p>}
        </div>
      </div>
      <div className="lux-bid-summary__chart-body">
        {!chart && <p className="lux-bid-summary__chart-empty">{emptyMessage}</p>}
        {chart && <DashboardApexChart type={chartType} series={chart.series} options={chart.options} height={height} />}
      </div>
    </article>
  );

  renderSkeleton = () => (
    <SkeletonTheme baseColor="#f1f5f9" highlightColor="#e2e8f0">
      <div className="lux-bid-summary lux-project-summary is-loading">
        <Skeleton height={88} borderRadius={16} />
        <div className="lux-bid-summary__kpi-strip lux-bid-summary__kpi-strip--skeleton">
          {[1, 2, 3, 4, 5, 6].map((key) => <Skeleton key={key} height={72} borderRadius={14} />)}
        </div>
      </div>
    </SkeletonTheme>
  );

  render() {
    const { stat, isLoading, visibleCount, filterOptions } = this.props;
    const { expanded } = this.state;
    if (isLoading && (!stat || stat.total === 0)) return this.renderSkeleton();

    const showFilter = this.getShowFilter();
    const charts = this.getCharts(stat);

    return (
      <section className={classNames("lux-bid-summary lux-po-summary lux-project-summary", { "is-collapsed": !expanded })} aria-label="Project portfolio overview" data-tour="lux-summary">
        <div className="lux-bid-summary__header-bar">
          <div className="lux-bid-summary__header-main">
            <LuxSummaryEyebrow variant="projects" className="lux-bid-summary__eyebrow">
              Project portfolio intelligence
            </LuxSummaryEyebrow>
            {!expanded ? (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--compact">
                <CountUp end={stat.total} duration={0.9} />{" "}
                <span>projects · {stat.pipelineRate}% in pipeline · {stat.overdueCount} overdue</span>
              </h2>
            ) : (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--bar">Project portfolio overview</h2>
            )}
          </div>
          <button type="button" className="lux-bid-summary__toggle" onClick={this.toggleExpanded} aria-expanded={expanded} aria-controls="lux-project-summary-body">
            <span>{getSummaryToggleLabel(expanded)}</span>
            <i className={classNames("fe", expanded ? "fe-chevron-up" : "fe-chevron-down")} aria-hidden="true" />
          </button>
        </div>

        {!expanded && (
          <div className="lux-bid-summary__collapsed-strip">
            <p className="lux-bid-summary__collapsed-line">{this.buildContextLine(stat, visibleCount, filterOptions)}</p>
            {this.renderFilterChips(showFilter, true)}
          </div>
        )}

        <div id="lux-project-summary-body" className="lux-bid-summary__body" aria-hidden={!expanded}>
          <div className="lux-bid-summary__toolbar">
            <p className="lux-bid-summary__subtitle">{this.buildContextLine(stat, visibleCount, filterOptions)}</p>
            {this.renderFilterChips(showFilter, false)}
          </div>

          <div className="lux-bid-summary__metrics-row lux-po-summary__metrics-row lux-project-summary__metrics-row">
            {this.renderKpiStrip(stat)}
          </div>

          {this.renderHighlights(stat)}

          <div className="lux-bid-summary__insights lux-po-summary__insights">
            {stat.insights.map(this.renderInsightCard)}
          </div>

          {this.renderStageFlow(stat)}

          {this.renderEstimateGaps(stat)}

          <div className="lux-po-summary__analytics lux-po-summary__analytics--primary">
            <article className="lux-bid-summary__chart-panel lux-bid-summary__chart-panel--funnel lux-bid-summary__chart-panel--funnel-compact">
              <div className="lux-bid-summary__panel-head">
                <h3 className="lux-bid-summary__panel-title">Delivery funnel</h3>
                <p className="lux-bid-summary__panel-sub">Stage progression for active projects</p>
              </div>
              <BidPipelineFunnelDiagram funnel={stat.funnel} totalActive={stat.active} layout="horizontal" />
            </article>
            {this.renderChartPanel("By status", "Active projects only", charts.statusDonut, "No status data yet", { height: 168, compactHead: true })}
            {this.renderChartPanel("Portfolio mix", "Pipeline vs completed vs closed", charts.outcomeDonut, "No outcome data yet", { height: 168, compactHead: true })}
            {this.renderChartPanel("Timeline health", "Open projects by due-date risk", charts.timelineDonut, "No open delivery dates", { height: 168, compactHead: true })}
          </div>

          <div className="lux-po-summary__analytics lux-po-summary__analytics--secondary lux-project-summary__analytics--secondary">
            {this.renderChartPanel("Creation trend", "New projects over the last 6 months", charts.createdTrend, "No projects created in this period", { height: 176, chartType: "area", wide: true, compactHead: true })}
            {this.renderChartPanel("Project types", "Distribution by delivery model", charts.projectTypeBar, "No project type data", { height: 168, chartType: "bar", compactHead: true })}
            {this.renderChartPanel("Billing mix", "Billable vs non-billable portfolio", charts.billingDonut, "No billing type data", { height: 168, compactHead: true })}
            {this.renderChartPanel("PO linkage", "Projects under purchase contract", charts.poLinkDonut, "No linkage data", { height: 168, compactHead: true })}
            {this.renderChartPanel(
              "Completed share",
              "Percent of active projects marked Completed; donut splits completed vs in delivery vs other",
              charts.completionShare,
              "No active projects to measure",
              { height: 168, compactHead: true }
            )}
            {this.renderChartPanel(
              "Open pipeline load",
              "Projects in New, Assigned, or In progress; donut shows stage mix, center is % of active",
              charts.pipelineLoad,
              "No projects in the open pipeline",
              { height: 168, compactHead: true }
            )}
            {this.renderChartPanel("Automation", "Manual vs automated delivery", charts.automationDonut, "No automation data", { height: 168, compactHead: true })}
            {this.renderChartPanel("Top accounts", "Most active client accounts", charts.accountBar, "No account data yet", { height: 168, chartType: "bar", compactHead: true })}
            {this.renderChartPanel("By team", "Projects per delivery team", charts.teamBar, "No team breakdown", { height: 168, chartType: "bar", compactHead: true })}
            {this.renderChartPanel("Priority", "Urgency spread across active projects", charts.priorityBar, "No priority data", { height: 168, chartType: "bar", compactHead: true })}
            {this.renderChartPanel("Shared visibility", "Cross-team vs team-only projects", charts.sharedDonut, "No visibility data", { height: 168, compactHead: true })}
            {this.renderChartPanel("Complexity", "Basic, medium, and complex delivery", charts.complexityBar, "No complexity set", { height: 168, chartType: "bar", compactHead: true })}
            {this.renderChartPanel("Capex / Opex", "Capital vs operating spend classification", charts.capexDonut, "No capex/opex data", { height: 168, compactHead: true })}
            {this.renderChartPanel("Hours estimated", "Active projects with estimated hours captured", charts.hoursEstimateDonut, "No estimate coverage data", { height: 168, compactHead: true })}
          </div>
        </div>
      </section>
    );
  }
}

export default ProjectPageSummary;
