import { getProfileDetailsReturnTarget, buildProfileDetailsLink } from "views/hrms/profileDetailsNavigation.utils";

const EMPLOYEE_360_PATH_RE = /^\/(hrms|people)\/employees\/[^/]+\/360/;

export function isEmployee360Path(pathname = "") {
  return EMPLOYEE_360_PATH_RE.test(pathname.split("?")[0]);
}

export function getEmployee360ReturnTarget(location) {
  return getProfileDetailsReturnTarget(location);
}

export function buildEmployee360Link(employeeId, fromLocation, fromLabel) {
  const pathname = `/people/employees/${employeeId}/360`;
  if (!fromLocation) {
    return { pathname };
  }
  const from = (fromLocation.pathname || "") + (fromLocation.search || "");
  return {
    pathname,
    state: {
      from,
      fromLabel: fromLabel || undefined,
    },
  };
}

export function buildProfileLinkFrom360(employeeId, location) {
  return buildProfileDetailsLink(employeeId, location, "Employee 360");
}
