import React from "react";
import classNames from "classnames/bind";
import { formatEventTimeShort } from "./customCalendar.utils";
import { getCalendarEventStatusMeta } from "./userCalendar.utils";

export default function LuxCalendarEventChip({
  event,
  selected,
  compact,
  mini,
  onSelect,
  className,
}) {
  const meta = getCalendarEventStatusMeta(event.status);
  const timeLabel = formatEventTimeShort(event).split(" – ")[0];

  return (
    <button
      type="button"
      className={classNames(
        "lux-cal-event",
        `is-${meta.tone}`,
        {
          "is-allday": event.allDay,
          "is-selected": selected,
          "is-compact": compact,
          "is-mini": mini,
        },
        className
      )}
      onClick={(e) => {
        e.stopPropagation();
        if (onSelect) onSelect(event);
      }}
    >
      <span className="lux-cal-event__glow" aria-hidden="true" />
      <span className="lux-cal-event__rail" aria-hidden="true" />
      <span className="lux-cal-event__content">
        {!mini && (
          <span className="lux-cal-event__top">
            <span className="lux-cal-event__time">{timeLabel}</span>
            {!compact && (
              <span className={classNames("lux-cal-event__status", `is-${meta.tone}`)}>
                {meta.label}
              </span>
            )}
          </span>
        )}
        <span className="lux-cal-event__title">{event.title}</span>
        {!compact && !mini && event.desc && (
          <span className="lux-cal-event__desc">{event.desc}</span>
        )}
      </span>
    </button>
  );
}
