import React, { Component } from "react";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPayrollManagementEnabled, shouldUsePayrollApi } from "config/payroll.config";
import { buildPayrollGroupMetrics, formatPayrollDate } from "config/payroll.utils";
import { validatePayrollGroupPayload } from "config/payroll-schema.utils";
import { payrollService } from "_services/payroll.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import { PayrollGroupsRegister } from "views/payroll/components/PayrollRegister";
import PayrollGroupDrawer from "views/payroll/components/PayrollGroupDrawer";
import {
  PayrollActionButton,
  PayrollLuxPage,
  PayrollPanelHead,
} from "views/payroll/components/PayrollLuxShared";
import { AdminInsightStrip } from "views/admin/components/AdminLuxShared";

const EMPTY_FORM = {
  name: "",
  code: "",
  payFrequency: "Monthly",
  currency: "INR",
  lockDay: "25",
  nextPayDate: "",
  currentPeriod: "",
  status: "Active",
};


class PayrollGroupsPage extends Component {
  state = {
    groups: [],
    loading: true,
    loadError: null,
    dataSource: null,
    showForm: false,
    form: { ...EMPTY_FORM },
    formError: null,
    saving: false,
    editingId: null,
    query: "",
    statusFilter: "ALL",
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Payroll groups");
    this.loadGroups();
  }

  loadGroups = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await payrollService.listPayrollGroups();
      this.setState({
        groups: result.payload || [],
        loading: false,
        dataSource: result.source || null,
      });
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load payroll groups.", groups: [] });
    }
  };

  closeForm = () => {
    this.setState({
      showForm: false,
      formError: null,
      saving: false,
      editingId: null,
      form: { ...EMPTY_FORM },
    });
  };

  openCreateForm = () => {
    if (!shouldUsePayrollApi()) {
      this.setState({
        showForm: true,
        editingId: null,
        form: { ...EMPTY_FORM },
        formError: "Payroll API is disabled. Enable REACT_APP_USE_PAYROLL_API to create groups.",
      });
      return;
    }
    this.setState({ showForm: true, editingId: null, form: { ...EMPTY_FORM }, formError: null });
  };

  openEditForm = (group) => {
    this.setState({
      showForm: true,
      editingId: group.id,
      form: {
        name: group.name || "",
        code: group.code || "",
        payFrequency: group.payFrequency || "Monthly",
        currency: group.currency || "INR",
        lockDay: group.lockDay != null ? String(group.lockDay) : "",
        nextPayDate: group.nextPayDate || "",
        currentPeriod: group.currentPeriod || "",
        status: group.status || "Active",
      },
      formError: shouldUsePayrollApi()
        ? null
        : "Payroll API is disabled. Enable REACT_APP_USE_PAYROLL_API to edit groups.",
    });
  };

  handleFormChange = (field, value) => {
    this.setState((prev) => ({ form: { ...prev.form, [field]: value }, formError: null }));
  };

  handleSave = async (event) => {
    event.preventDefault();
    if (!shouldUsePayrollApi()) {
      this.setState({ formError: "Payroll API is disabled." });
      return;
    }
    const { form, editingId } = this.state;
    const payload = {
      name: form.name,
      code: form.code,
      payFrequency: form.payFrequency,
      currency: form.currency,
      lockDay: form.lockDay === "" ? null : Number(form.lockDay),
      nextPayDate: form.nextPayDate || null,
      currentPeriod: form.currentPeriod || null,
      status: form.status || "Active",
    };
    const validation = validatePayrollGroupPayload(payload);
    if (!validation.valid) {
      this.setState({ formError: validation.errors.join(" ") });
      return;
    }
    this.setState({ saving: true, formError: null });
    try {
      if (editingId) {
        await payrollService.updatePayrollGroup(editingId, payload);
      } else {
        await payrollService.createPayrollGroup(payload);
      }
      this.closeForm();
      await this.loadGroups();
    } catch (e) {
      this.setState({
        saving: false,
        formError: (e && e.message) || "Unable to save payroll group.",
      });
    }
  };

  getFilteredGroups = () => {
    const { groups, query, statusFilter } = this.state;
    const q = (query || "").trim().toLowerCase();
    return groups.filter((row) => {
      const status = String(row.status || "Active");
      if (statusFilter !== "ALL" && status.toLowerCase() !== statusFilter.toLowerCase()) {
        return false;
      }
      if (!q) return true;
      const haystack = [row.name, row.code, row.payFrequency, row.currency, row.currentPeriod]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return haystack.includes(q);
    });
  };

  render() {
    if (!isPayrollManagementEnabled()) {
      return <PersonaAccessDenied moduleName="Payroll groups" reason="Payroll management is not enabled." />;
    }

    const { groups, loading, loadError, dataSource, showForm, form, formError, saving, editingId, query, statusFilter } =
      this.state;
    const filtered = this.getFilteredGroups();
    const metrics = buildPayrollGroupMetrics(groups);
    const activeCount = groups.filter((g) => String(g.status || "Active").toLowerCase() === "active").length;

    const kpiCards = [
      {
        id: "groups",
        label: "Payroll groups",
        value: metrics.total,
        hint: `${activeCount} active`,
        tone: "green",
        icon: "fe fe-users",
      },
      {
        id: "employees",
        label: "Employees",
        value: metrics.employees,
        hint: "In payroll scope",
        tone: "blue",
        icon: "fe fe-user-check",
      },
      {
        id: "frequencies",
        label: "Pay frequencies",
        value: metrics.frequencies,
        hint: "Monthly, bi-weekly, etc.",
        tone: "violet",
        icon: "fe fe-repeat",
      },
      {
        id: "nextpay",
        label: "Next pay date",
        value: metrics.nextPayDate ? formatPayrollDate(metrics.nextPayDate) : "—",
        hint: "Earliest scheduled",
        tone: "amber",
        icon: "fe fe-calendar",
      },
    ];

    const insights = [
      {
        id: "readiness",
        tone: "green",
        icon: "fe fe-shield",
        title: "Check readiness gates",
        copy: "Confirm groups and pay frequency before locking a cycle.",
        path: "/admin/payroll-config",
      },
      {
        id: "structures",
        tone: "violet",
        icon: "fe fe-sliders",
        title: "Map salary structures",
        copy: "Cohorts need earning and deduction templates to calculate.",
        path: "/payroll/salary-structures",
      },
      {
        id: "runs",
        tone: "blue",
        icon: "fe fe-play",
        title: groups.length ? "Ready for a run?" : "Create a group first",
        copy: groups.length
          ? "Open payroll runs once lock day and frequency are set."
          : "Define at least one group before creating a payroll run.",
        path: groups.length ? "/payroll/runs" : null,
      },
    ];

    return (
      <PayrollLuxPage
        testId="page-payroll-groups"
        className="lux-payroll-groups-page"
        dataSource={dataSource}
        pageMeta={{
          tone: "green",
          icon: "fe fe-users",
          eyebrow: "Payroll · Groups",
          titleLead: "Payroll",
          titleAccent: "groups",
          lede: "Pay cohorts, lock days, and currency — the calendar backbone for every payroll run.",
        }}
        loading={loading}
        kpiCards={kpiCards}
        onRefresh={this.loadGroups}
        refreshLoading={loading}
        heroActions={<><PayrollActionButton to="/admin/payroll-config" icon="fe fe-shield" variant="ghost">
              Readiness
            </PayrollActionButton>
            <PayrollActionButton to="/payroll/runs" icon="fe fe-play" variant="ghost">
              Create run
            </PayrollActionButton>
          </>}
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load payroll groups">
            {loadError}{" "}
            <button type="button" className="link" onClick={this.loadGroups}>
              Retry
            </button>
          </LuxInlineAlert>
        ) : null}

        <AdminInsightStrip insights={insights} className="lux-payroll-groups__insights" />

        {!loading && groups.length > 0 ? (
          <div className="lux-payroll-summary-grid lux-payroll-groups__cards">
            {filtered.map((row) => {
              const isActive = String(row.status || "Active").toLowerCase() === "active";
              return (
                <article
                  key={row.id || row.code}
                  className={classNames("lux-payroll-summary-card", "lux-payroll-summary-card--group", {
                    "is-inactive": !isActive,
                  })}
                >
                  <div className="lux-payroll-summary-card__head">
                    <span className={classNames("lux-doc-badge", isActive ? "is-green" : "is-slate")}>
                      {row.status || "Active"}
                    </span>
                    <span className="lux-payroll-summary-card__code">{row.code || "—"}</span>
                  </div>
                  <h3 className="lux-payroll-summary-card__title">{row.name}</h3>
                  <p className="lux-payroll-summary-card__meta">
                    {row.payFrequency || "—"} · {row.currency || "—"}
                  </p>
                  <dl className="lux-payroll-summary-card__stats">
                    <div>
                      <dt>Current period</dt>
                      <dd>{row.currentPeriod || "—"}</dd>
                    </div>
                    <div>
                      <dt>Next pay</dt>
                      <dd>{formatPayrollDate(row.nextPayDate)}</dd>
                    </div>
                    <div>
                      <dt>Lock day</dt>
                      <dd>{row.lockDay != null ? `Day ${row.lockDay}` : "—"}</dd>
                    </div>
                  </dl>
                  <footer className="lux-payroll-summary-card__foot">
                    <span>
                      <i className="fe fe-users" aria-hidden="true" />{" "}
                      {row.employeeCount != null ? row.employeeCount : 0} employees
                    </span>
                    <PayrollActionButton type="button" variant="ghost" onClick={() => this.openEditForm(row)}>
                      Edit
                    </PayrollActionButton>
                  </footer>
                </article>
              );
            })}
          </div>
        ) : null}

        <section className="lux-hrms-dash__panel lux-payroll-panel">
          <PayrollPanelHead
            title="Group register"
            subtitle="Pay calendar, lock rules, and employee counts per cohort"
            actions={
              <PayrollActionButton type="button" icon="fe fe-plus" variant="primary" onClick={this.openCreateForm}>
                Create group
              </PayrollActionButton>
            }
          />
          <div className="lux-payroll-panel__toolbar">
            <div className="lux-appr-toolbar__row">
              <div className="lux-appr-toolbar__search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  className="lux-appr-toolbar__search-input"
                  placeholder="Search group, code, frequency…"
                  value={query}
                  onChange={(e) => this.setState({ query: e.target.value })}
                  aria-label="Search payroll groups"
                />
              </div>
              <div className="lux-appr-toolbar__group">
                <span className="lux-appr-toolbar__label">Status</span>
                <div className="lux-hrms-dash__filter-group">
                  {["ALL", "Active", "Inactive", "Draft"].map((value) => (
                    <button
                      key={value}
                      type="button"
                      className={classNames("lux-hrms-dash__filter-chip", {
                        "is-active": statusFilter === value,
                      })}
                      onClick={() => this.setState({ statusFilter: value })}
                    >
                      {value === "ALL" ? "All" : value}
                    </button>
                  ))}
                </div>
              </div>
              <span className="lux-appr-toolbar__count">
                <strong>{filtered.length}</strong> group{filtered.length === 1 ? "" : "s"}
              </span>
            </div>
          </div>
          <div className="lux-hrms-dash__panel-body">
            {loading ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                title="Loading groups"
                description="Fetching payroll group configuration."
              />
            ) : filtered.length === 0 ? (
              <div className="lux-payroll-groups__empty">
                <LuxRegisterEmptyState
                  className="lux-register-empty--compact"
                  title={groups.length === 0 ? "No payroll groups" : "No matching groups"}
                  description={
                    groups.length === 0
                      ? "Define pay groups before creating runs."
                      : "Try a different search or status filter."
                  }
                />
                {groups.length === 0 ? (
                  <div className="lux-payroll-groups__empty-actions">
                    <PayrollActionButton type="button" icon="fe fe-plus" variant="primary" onClick={this.openCreateForm}>
                      Create group
                    </PayrollActionButton>
                  </div>
                ) : null}
              </div>
            ) : (
              <PayrollGroupsRegister groups={filtered} onEdit={this.openEditForm} />
            )}
          </div>
        </section>

        <PayrollGroupDrawer
          open={showForm}
          onClose={this.closeForm}
          form={form}
          formError={formError}
          saving={saving}
          editingId={editingId}
          onChange={this.handleFormChange}
          onSubmit={this.handleSave}
        />
      </PayrollLuxPage>
    );
  }
}

export default PayrollGroupsPage;
