import React from "react";
import LuxActionButton from "views/common/lux/LuxActionButton";
import { createModuleLuxPage, LuxModulePanel } from "views/common/lux/createModuleLuxPage";

export const LearningLuxPage = createModuleLuxPage({
  rootClass: "lux-learning-lux",
  defaultMeta: {
    tone: "teal",
    icon: "fe fe-book-open",
    eyebrow: "People · Learning",
    titleLead: "Learning",
    titleAccent: "management",
    lede: "Courses, assignments, compliance tracking, and learner progress.",
  },
});

export function LearningActionButton(props) {
  return <LuxActionButton {...props} moduleClass="lux-learning-action" />;
}

export function LearningLuxPanel(props) {
  return <LuxModulePanel {...props} className="lux-learning-lux__panel" />;
}

export function LearningField({ label, hint, children, className = "" }) {
  return (
    <label className={`lux-learning-field ${className}`.trim()}>
      <span className="lux-learning-field__label">{label}</span>
      {children}
      {hint ? <span className="lux-learning-field__hint">{hint}</span> : null}
    </label>
  );
}

export function LearningMetricCard({ label, value, tone = "teal", hint }) {
  return (
    <article className={`lux-learning-metric is-${tone}`}>
      <span className="lux-learning-metric__label">{label}</span>
      <strong className="lux-learning-metric__value">{value}</strong>
      {hint ? <span className="lux-learning-metric__hint">{hint}</span> : null}
    </article>
  );
}

export default LearningLuxPage;
