import React, { Component } from "react";
import { connect } from "react-redux";
import { Link } from "react-router-dom";
import Skeleton from "react-loading-skeleton";
import { dashboardActions, workItemActions } from "_actions";
import { employeeConstants } from "_constants";
import { store } from "_helpers";
import { commonUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import envconfig from "env.config";
import { getEmployeeDetailsPathname } from "views/hrms/profileDetailsNavigation.utils";
import EmployeeImage from "./fragments/EmployeeImage";
import {
  computeWeeklyUtilization,
  getTaskStatusMeta,
  minsToHoursLabel,
  summarizeTaskStatuses,
} from "./userDiv.utils";

const PENDING_PREVIEW_LIMIT = 5;

class UserDiv extends Component {
  toggleUserDivSidebar = () => {
    store.dispatch({ type: employeeConstants.TOGGLE_USER_DIV_WINDOW });
  };

  render() {
    const { show } = this.props;
    const user = commonUtils.getCurrentUser();

    return (
      <>
        {show && (
          <button
            type="button"
            className="lux-user-panel__backdrop"
            aria-label="Close profile panel"
            onClick={this.toggleUserDivSidebar}
          />
        )}
        <aside
          className={`user_div lux-user-panel${show ? " open" : ""}`}
          aria-hidden={!show}
          aria-label="User quick view"
        >
          <header className="lux-user-panel__header">
            <div className="lux-user-panel__brand">
              <img alt="" src="/favicon.ico" width={28} height={28} />
              <span className="lux-user-panel__brand-name">{envconfig.APP_NAME}</span>
            </div>
            <button
              type="button"
              className="lux-user-panel__close"
              onClick={this.toggleUserDivSidebar}
              aria-label="Close"
              data-ga-action="user_div_toggle"
              data-ga-category="navigation"
              data-ga-label="User sidebar"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          {user && (
            <section className="lux-user-panel__profile">
              <EmployeeImage employee={user} classes="avatar lux-user-panel__avatar" />
              <div className="lux-user-panel__profile-copy">
                <h2 className="lux-user-panel__name">{user.name}</h2>
                {user.designation && (
                  <p className="lux-user-panel__meta">{user.designation}</p>
                )}
                {user.defaultUserTeamDetails && user.defaultUserTeamDetails.name && (
                  <span className="lux-user-panel__team-chip">
                    <i className="fe fe-users" aria-hidden="true" />
                    {user.defaultUserTeamDetails.name}
                  </span>
                )}
                <Link
                  to={getEmployeeDetailsPathname(user.id)}
                  className="lux-user-panel__profile-link"
                  onClick={this.toggleUserDivSidebar}
                  data-ga-action="user_div_profile"
                  data-ga-category="navigation"
                  data-ga-label="View profile"
                >
                  View full profile
                  <i className="fe fe-arrow-right" aria-hidden="true" />
                </Link>
              </div>
            </section>
          )}

          {show && <ConnectedUserDivInsights onClose={this.toggleUserDivSidebar} />}
        </aside>
      </>
    );
  }
}

class UserDivInsights extends Component {
  componentDidMount() {
    this.loadInsights();
  }

  loadInsights = () => {
    const employeeId = commonUtils.getCurrentUserId();
    const teamIds = commonUtils.getCurrentUserTeamIds();
    const userTeamIds =
      teamIds && teamIds.length > 0 ? teamIds : [commonUtils.getCurrentUserTeamId()];

    const weekStart = dateUtils
      .getCurrentTime()
      .clone()
      .startOf("week")
      .startOf("day")
      .format(dateUtils.SERVER_DATE_FORMAT);
    const weekEnd = dateUtils
      .getCurrentTime()
      .clone()
      .endOf("week")
      .endOf("day")
      .format(dateUtils.SERVER_DATE_FORMAT);

    store.dispatch(dashboardActions.employeeWeeklyUtilization(employeeId, weekStart, weekEnd));

    const pendingStart = dateUtils
      .substractXFromMoments(dateUtils.getCurrentTime().clone().startOf("day"), "days", 90)
      .format(dateUtils.SERVER_DATE_FORMAT);
    const pendingEnd = dateUtils
      .addXToMoments(dateUtils.getCurrentTime().clone().endOf("day"), "days", 30)
      .format(dateUtils.SERVER_DATE_FORMAT);

    store.dispatch(
      workItemActions.getWorkItemActivitiesPending({
        employeeIds: [employeeId],
        userTeamIds,
        startDate: pendingStart,
        endDate: pendingEnd,
      })
    );

    const todayStart = dateUtils.getCurrentTime().clone().startOf("day").format(dateUtils.SERVER_DATE_FORMAT);
    const todayEnd = dateUtils.getCurrentTime().clone().endOf("day").format(dateUtils.SERVER_DATE_FORMAT);

    store.dispatch(
      workItemActions.getWorkItemBoardActivities({
        employeeIds: [employeeId],
        userTeamIds,
        startDate: todayStart,
        endDate: todayEnd,
      })
    );
  };

  renderUtilization = () => {
    const { employeeWeeklyUtilization, employeeWeeklyUtilizationLoading } = this.props;
    const stats = computeWeeklyUtilization(employeeWeeklyUtilization);

    if (employeeWeeklyUtilizationLoading && !employeeWeeklyUtilization) {
      return <Skeleton height={140} borderRadius={16} />;
    }

    if (!employeeWeeklyUtilization) {
      return (
        <p className="lux-user-panel__empty">Utilization data is not available right now.</p>
      );
    }

    const u = employeeWeeklyUtilization;
    const totalMins = stats.totalMins || 1;
    const rows = [
      {
        key: "billable",
        label: "Billable",
        mins: u.billableMins || 0,
        tone: "billable",
      },
      {
        key: "nonBillable",
        label: "Non-billable",
        mins: u.nonBillableMins || 0,
        tone: "neutral",
      },
      {
        key: "leave",
        label: "Leave / holiday",
        mins: stats.leaveMins,
        tone: "leave",
      },
    ];

    return (
      <section className="lux-user-panel__section">
        <div className="lux-user-panel__section-head">
          <h3 className="lux-user-panel__section-title">This week</h3>
          <span className="lux-user-panel__section-badge">Utilization</span>
        </div>
        <div className="lux-user-panel__stat-grid">
          <article className="lux-user-panel__stat-card lux-user-panel__stat-card--primary">
            <span className="lux-user-panel__stat-label">Utilization</span>
            <strong className="lux-user-panel__stat-value">{stats.utilizationPct}%</strong>
            <span className="lux-user-panel__stat-hint">vs 40h target</span>
          </article>
          <article className="lux-user-panel__stat-card">
            <span className="lux-user-panel__stat-label">Logged</span>
            <strong className="lux-user-panel__stat-value">
              {minsToHoursLabel(stats.totalMins)}
            </strong>
            <span className="lux-user-panel__stat-hint">Total hours</span>
          </article>
        </div>
        <div className="lux-user-panel__bars">
          {rows.map((row) => (
            <div key={row.key} className="lux-user-panel__bar-row">
              <div className="lux-user-panel__bar-head">
                <span>{row.label}</span>
                <span>{minsToHoursLabel(row.mins)}</span>
              </div>
              <div className="lux-user-panel__bar-track">
                <div
                  className={`lux-user-panel__bar-fill lux-user-panel__bar-fill--${row.tone}`}
                  style={{
                    width: `${commonUtils.getPercentageOfCompletion(totalMins, row.mins)}%`,
                  }}
                />
              </div>
            </div>
          ))}
        </div>
      </section>
    );
  };

  renderTasks = () => {
    const { workItemsPending, workItemBoardWorkItems, isLoadingPending, isLoadingBoard } =
      this.props;
    const summary = summarizeTaskStatuses(workItemsPending);
    const preview = (workItemsPending || []).slice(0, PENDING_PREVIEW_LIMIT);

    if (isLoadingPending && (!workItemsPending || workItemsPending.length === 0)) {
      return <Skeleton height={200} borderRadius={16} />;
    }

    return (
      <section className="lux-user-panel__section">
        <div className="lux-user-panel__section-head">
          <h3 className="lux-user-panel__section-title">My tasks</h3>
          <button
            type="button"
            className="lux-user-panel__refresh"
            onClick={this.loadInsights}
            title="Refresh"
            data-ga-action="user_div_refresh"
            data-ga-category="navigation"
            data-ga-label="Refresh tasks"
          >
            <i className="fe fe-refresh-cw" aria-hidden="true" />
          </button>
        </div>

        <div className="lux-user-panel__task-stats">
          <article className="lux-user-panel__task-stat">
            <strong>{isLoadingBoard ? "—" : (workItemBoardWorkItems || []).length}</strong>
            <span>Today&apos;s board</span>
          </article>
          <article className="lux-user-panel__task-stat">
            <strong>{summary.total}</strong>
            <span>Pending</span>
          </article>
          <article className="lux-user-panel__task-stat">
            <strong>{summary.inProgress}</strong>
            <span>In progress</span>
          </article>
        </div>

        <ul className="lux-user-panel__task-list">
          {preview.length === 0 && (
            <li className="lux-user-panel__task-empty">No pending tasks in your queue.</li>
          )}
          {preview.map((item) => {
            const status = getTaskStatusMeta(item.status);
            const due =
              item.taskEstCompletionTime || item.estStartTime
                ? dateUtils.convertDateFormat(
                    item.taskEstCompletionTime || item.estStartTime
                  )
                : null;
            return (
              <li key={item.id} className="lux-user-panel__task-item">
                <div className="lux-user-panel__task-item-head">
                  <span className={`lux-user-panel__status ${status.className}`}>
                    {status.label}
                  </span>
                  {due && <time className="lux-user-panel__task-due">{due}</time>}
                </div>
                <p className="lux-user-panel__task-name">{item.name}</p>
                {item.taskName && (
                  <p className="lux-user-panel__task-project">{item.taskName}</p>
                )}
              </li>
            );
          })}
        </ul>

        <div className="lux-user-panel__links">
          <Link
            to="/project/activites"
            className="lux-user-panel__link-btn"
            onClick={this.props.onClose}
          >
            Task activity
          </Link>
          <Link
            to="/project/taskboard"
            className="lux-user-panel__link-btn lux-user-panel__link-btn--ghost"
            onClick={this.props.onClose}
          >
            Taskboard
          </Link>
        </div>
      </section>
    );
  };

  render() {
    return (
      <div className="lux-user-panel__body">
        {this.renderUtilization()}
        {this.renderTasks()}
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  show: state.employees.showUserDiv,
  employeeWeeklyUtilization: state.dashboard.employeeWeeklyUtilization,
  employeeWeeklyUtilizationLoading: state.dashboard.employeeWeeklyUtilizationLoading,
  workItemsPending: state.workItem.workItemsPending,
  workItemBoardWorkItems: state.workItem.workItemBoardWorkItems,
  isLoadingPending: state.workItem.isLoadingPending,
  isLoadingBoard: state.workItem.isLoadingBoard,
});

const ConnectedUserDivInsights = connect(mapStateToProps)(UserDivInsights);

const ConnectedUserDiv = connect((state) => ({
  show: state.employees.showUserDiv,
}))(UserDiv);

export default ConnectedUserDiv;
