import React from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";

const MODULE_ICONS = {
  delivery: "fe fe-layers",
  people: "fe fe-users",
  service: "fe fe-life-buoy",
  finance: "fe fe-dollar-sign",
  approvals: "fe fe-check-circle",
  ai: "fe fe-cpu",
  project: "fe fe-briefcase",
};

function scoreTone(score) {
  if (score >= 90) {
    return "is-excellent";
  }
  if (score >= 75) {
    return "is-good";
  }
  return "is-fair";
}

export default function GraphSearchResults({ hits, loading, query, onOpenNode }) {
  if (loading) {
    return (
      <div className="lux-wg-search-results lux-wg-search-results--loading">
        {[1, 2, 3].map((key) => (
          <div key={key} className="lux-wg-skeleton lux-wg-skeleton--row" />
        ))}
      </div>
    );
  }

  if (!query) {
    return (
      <div className="lux-wg-search-empty">
        <span className="lux-wg-search-empty__icon" aria-hidden="true">
          <i className="fe fe-search" />
        </span>
        <h3>Enterprise graph search</h3>
        <p>Search across projects, people, tickets, approvals, documents, and risks.</p>
      </div>
    );
  }

  const list = hits || [];
  if (!list.length) {
    return (
      <div className="lux-wg-search-empty">
        <span className="lux-wg-search-empty__icon" aria-hidden="true">
          <i className="fe fe-inbox" />
        </span>
        <h3>No matches</h3>
        <p>No results for &ldquo;{query}&rdquo; in the enterprise graph index.</p>
      </div>
    );
  }

  return (
    <div className="lux-wg-search-results">
      <header className="lux-wg-search-results__head">
        <span>{list.length} result{list.length === 1 ? "" : "s"}</span>
        <span className="lux-wg-search-results__query">&ldquo;{query}&rdquo;</span>
      </header>
      {list.map((hit, index) => (
        <article key={hit.id} className={classNames("lux-wg-search-hit", hit.tone && `is-${hit.tone}`)}>
          <span className="lux-wg-search-hit__index" aria-hidden="true">
            {String(index + 1).padStart(2, "0")}
          </span>
          <span className="lux-wg-search-hit__module-icon" aria-hidden="true">
            <i className={MODULE_ICONS[hit.module] || "fe fe-circle"} />
          </span>
          <div className="lux-wg-search-hit__main">
            <span className="lux-wg-search-hit__module">{hit.module}</span>
            <h3 className="lux-wg-search-hit__title">{hit.title}</h3>
            <p className="lux-wg-search-hit__snippet">{hit.snippet}</p>
          </div>
          <div className="lux-wg-search-hit__actions">
            <span className={classNames("lux-wg-search-hit__score", scoreTone(hit.score))}>
              {hit.score}% match
            </span>
            {hit.route ? (
              <Link to={hit.route} className="lux-onb-action lux-onb-action--ghost lux-wg-action">
                Open
              </Link>
            ) : null}
            {onOpenNode ? (
              <button
                type="button"
                className="lux-onb-action lux-onb-action--primary lux-wg-action"
                onClick={() => onOpenNode(hit.nodeId)}
              >
                Graph
              </button>
            ) : null}
          </div>
        </article>
      ))}
    </div>
  );
}
