import React, { PureComponent } from "react";
import Skeleton from "react-loading-skeleton";
import PageInnerHeader from "views/common/PageInnerHeader";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import PageCreateButton from "views/common/fragments/PageCreateButton";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";
import { accessUtils, commonUtils, store } from "_helpers";
import { taskService } from "_services";
import { notificationActions } from "_actions";
import NotesPageSummary from "./components/NotesPageSummary";
import LuxNoteCard from "./components/LuxNoteCard";
import LuxNotesRegister from "./components/LuxNotesRegister";
import LuxNoteEditorPanel from "./components/modal/LuxNoteEditorPanel";
import {
  buildNotesSummary,
  filterNotesByText,
  formatNoteWhen,
  getNotesLoadRange,
  isNotePending,
} from "./components/notes.utils";

function mergePermission() {
  const projectPerm = accessUtils.getProjectAccessControl();
  return {
    createEnabled: projectPerm.createEnabled,
    editEnabled: projectPerm.editEnabled,
    removeEnabled: projectPerm.removeEnabled,
  };
}

class ToDoListPage extends PureComponent {
  constructor() {
    super();
    const permission = mergePermission();
    this.state = {
      permission,
      items: [],
      isLoading: false,
      filterOptions: {
        filterText: "",
      },
      statusFilter: "ALL",
      showNoteEditor: false,
      editingNote: null,
      isSavingNote: false,
      showGrid: true,
    };
  }

  onGridClick = (e) => {
    e.preventDefault();
    this.setState({ showGrid: true });
  };

  onListClick = (e) => {
    e.preventDefault();
    this.setState({ showGrid: false });
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    this.loadNotes();
  }

  getCurrentEmployeeId = () => commonUtils.getCurrentUserId();

  loadNotes = () => {
    const employeeId = this.getCurrentEmployeeId();
    if (!employeeId) return;
    const { startDate, endDate } = getNotesLoadRange();
    this.setState({ isLoading: true });
    taskService
      .listNotes({
        employeeId,
        currentEmployeeId: employeeId,
        startDate,
        endDate,
      })
      .then((res) => {
        const raw = res && res.payload;
        const items = Array.isArray(raw) ? raw : raw ? [raw] : [];
        this.setState({ items, isLoading: false });
      })
      .catch(() => {
        this.setState({ items: [], isLoading: false });
      });
  };

  onFilterTextChange = (value) => {
    this.setState((prev) => ({
      filterOptions: { ...prev.filterOptions, filterText: value },
    }));
  };

  setStatusFilter = (id) => {
    this.setState({ statusFilter: id });
  };

  onCreateItemClick = () => {
    this.setState({ showNoteEditor: true, editingNote: null });
  };

  closeNoteEditor = () => {
    if (!this.state.isSavingNote) {
      this.setState({ showNoteEditor: false, editingNote: null });
    }
  };

  saveNote = (payload) => {
    const employeeId = this.getCurrentEmployeeId();
    const body = { ...payload, employeeId };
    this.setState({ isSavingNote: true });
    const isEdit = !!(this.state.editingNote && this.state.editingNote.id);
    const req = isEdit ? taskService.updateNote(body) : taskService.createNote(body);
    req
      .then(() => {
        store.dispatch(notificationActions.success(isEdit ? "Note updated" : "Note added"));
        this.setState({ isSavingNote: false, showNoteEditor: false, editingNote: null });
        this.loadNotes();
      })
      .catch((err) => {
        store.dispatch(notificationActions.error(String((err && err.message) || err || "Could not save")));
        this.setState({ isSavingNote: false });
      });
  };

  openEdit = (note) => {
    this.setState({ showNoteEditor: true, editingNote: note });
  };

  markDone = (note) => {
    taskService
      .updateNoteStatus(note.id, "COMPLETED")
      .then(() => this.loadNotes())
      .catch((err) => {
        store.dispatch(notificationActions.error(String((err && err.message) || err || "Update failed")));
      });
  };

  reopenNote = (note) => {
    taskService
      .updateNoteStatus(note.id, "IN_PROGRESS")
      .then(() => this.loadNotes())
      .catch((err) => {
        store.dispatch(notificationActions.error(String((err && err.message) || err || "Update failed")));
      });
  };

  toggleComplete = (note) => {
    if (isNotePending(note)) {
      this.markDone(note);
    } else {
      this.reopenNote(note);
    }
  };

  deleteNote = (note) => {
    taskService
      .removeNote(note.id)
      .then(() => {
        store.dispatch(notificationActions.success("Note deleted"));
        this.loadNotes();
      })
      .catch((err) => {
        store.dispatch(notificationActions.error(String((err && err.message) || err || "Delete failed")));
      });
  };

  filteredItems = () => {
    let rows = filterNotesByText(this.state.items, this.state.filterOptions.filterText);
    const { statusFilter } = this.state;
    if (statusFilter === "OPEN") {
      rows = rows.filter(isNotePending);
    } else if (statusFilter === "DONE") {
      rows = rows.filter((n) => !isNotePending(n));
    }
    return rows;
  };

  renderGrid = (rows) => {
    if (this.state.isLoading) {
      return (
        <div className="lux-notes-page__grid">
          {[1, 2, 3, 4, 5, 6].map((k) => (
            <Skeleton key={k} height={160} borderRadius={16} />
          ))}
        </div>
      );
    }
    return (
      <div className="lux-notes-page__grid">
        {rows.map((note) => (
          <LuxNoteCard
            key={note.id}
            note={note}
            formatWhen={formatNoteWhen}
            permission={this.state.permission}
            stickyVisual
            onMarkDone={this.markDone}
            onToggleComplete={this.toggleComplete}
            onEdit={this.openEdit}
            onDelete={this.deleteNote}
          />
        ))}
      </div>
    );
  };

  render() {
    const rows = this.filteredItems();
    const summary = buildNotesSummary(this.state.items);
    const showContent = rows.length > 0 || this.state.isLoading;
    const filterText = (this.state.filterOptions.filterText || "").trim();

    return (
      <div className="projectlist lux-bid-requests lux-notes-page lux-register-page" data-testid="page-project-notes">
        <PageDataSourceReporter dataSource="api" />
        <LuxModuleIntro
          meta={DENSE_PAGE_META.projectNotes}
          actions={
            this.state.permission.createEnabled ? (
              <PageCreateButton onClick={this.onCreateItemClick}>Add note</PageCreateButton>
            ) : null
          }
        />
        <PageInnerHeader
          showGridListMenu={true}
          showGridDefault={this.state.showGrid}
          gridClickHandler={this.onGridClick}
          listClickHandler={this.onListClick}
          searchViewEnabled={false}
          showFilter={true}
          isLoading={this.state.isLoading}
          onFilterTextChange={this.onFilterTextChange}
          filterOptions={this.state.filterOptions}
          handleFilterChange={() => {}}
          permission={this.state.permission}
        />

        <NotesPageSummary
          summary={summary}
          isLoading={this.state.isLoading}
          statusFilter={this.state.statusFilter}
          onStatusFilter={this.setStatusFilter}
          visibleCount={rows.length}
          filterText={filterText}
        />

        {showContent && (
          <div className="lux-register-list-section">
            {this.state.showGrid && this.renderGrid(rows)}
            {!this.state.showGrid && (
              <LuxNotesRegister
                items={rows}
                isLoading={this.state.isLoading}
                permission={this.state.permission}
                formatWhen={formatNoteWhen}
                onMarkDone={this.markDone}
                onToggleComplete={this.toggleComplete}
                onEdit={this.openEdit}
                onDelete={this.deleteNote}
              />
            )}
          </div>
        )}

        {!showContent && (
          <LuxRegisterEmptyState
            variant="projects"
            eyebrow="Notes"
            title="No notes in this view"
            description="Add a note, change the status filter, or try a different search."
            showCreate={this.state.permission.createEnabled}
            createLabel="Add note"
            onCreate={this.onCreateItemClick}
          />
        )}

        <LuxNoteEditorPanel
          show={this.state.showNoteEditor}
          note={this.state.editingNote}
          onClose={this.closeNoteEditor}
          onSave={this.saveNote}
          isSaving={this.state.isSavingNote}
        />
      </div>
    );
  }
}

export default ToDoListPage;
