import React, { Component } from "react";
import { withRouter } from "react-router-dom";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxActionButton from "views/common/lux/LuxActionButton";

const CHAT_PAGE_META = {
  tone: "violet",
  icon: "fe fe-message-circle",
  eyebrow: "Delivery · Collaboration",
  titleLead: "Project",
  titleAccent: "chat",
  lede: "Real-time chat is deferred until a collaboration domain ships. Use notes and files for durable project communication today.",
};

/**
 * W1-E03 / PROJ-025 — Project chat deferred.
 * Fail-closed lux surface; removed from header rail. No CHAT_DEMO_* in production path.
 */
class ChatPage extends Component {
  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler && this.props.routeProp) {
      this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    }
  }

  goTo = (path) => {
    if (this.props.history) {
      this.props.history.push(path);
    }
  };

  render() {
    return (
      <div
        className="lux-register-page lux-chat-page is-violet"
        data-testid="page-project-chat"
      >
        <LuxModuleIntro
          meta={CHAT_PAGE_META}
          actions={
            <>
              <LuxActionButton to="/project/todolist" icon="fe fe-book-open" variant="ghost">
                Pending notes
              </LuxActionButton>
              <LuxActionButton to="/project/filemanager" icon="fe fe-folder" variant="primary">
                File manager
              </LuxActionButton>
            </>
          }
        />

        <div className="lux-register-page__body">
          <LuxRegisterEmptyState
            variant="default"
            eyebrow="Deferred · PROJ-025"
            title="Project chat unavailable"
            description="Real-time project chat stays fail-closed until conversations, participants, messages, and audit are implemented as a collaboration domain. Demo chat data is not used on the production path."
            hints={[
              "Use pending notes for lightweight team updates",
              "Use File Manager and Document Vault for durable shared artifacts",
              "This route is not advertised in the header rail or primary navigation",
            ]}
            showCreate={false}
            showSecondary
            secondaryLabel="Open project list"
            secondaryIcon="fe fe-folder"
            onSecondary={() => this.goTo("/project/list")}
          />
        </div>
      </div>
    );
  }
}

export default withRouter(ChatPage);
