import React from "react";
import { NavLink } from "react-router-dom";
import classNames from "classnames/bind";

export const DeliverableDetailViewNameConst = Object.freeze({
  GENERAL: Symbol("general"),
});

export default function DeliverableDetailsHeader({ taskInfo }) {
  if (!taskInfo) return null;

  const workItemsEnabled =
    taskInfo.status !== "NEW" && taskInfo.status !== "ASSIGNED";
  const taskRef = taskInfo.itemIdUserTeamPrefix || taskInfo.id;

  return (
    <nav className="pd-nav lux-del-nav lux-del-nav--atelier" aria-label="Deliverable sections">
      <div className="lux-del-nav__rail">
        <span
          className={classNames("pd-nav__item", "is-active")}
          aria-current="page"
        >
          <i className="fe fe-grid" />
          <span>Overview</span>
        </span>
        {workItemsEnabled ? (
          <NavLink
            to={`/project/workitems/${taskRef}`}
            className="pd-nav__item pd-nav__item--link"
          >
            <i className="fe fe-check-square" />
            <span>Work items</span>
          </NavLink>
        ) : (
          <span
            className="pd-nav__item is-disabled"
            title="Available when deliverable is in progress"
          >
            <i className="fe fe-check-square" />
            <span>Work items</span>
          </span>
        )}
      </div>
    </nav>
  );
}
