import React from "react";
import classNames from "classnames/bind";
import { getExpenseStatusTone } from "config/expenses.config";

function ExpenseStatusBadge({ status }) {
  if (!status) {
    return <span className="lux-doc-badge is-slate">—</span>;
  }
  return (
    <span className={classNames("lux-doc-badge", `is-${getExpenseStatusTone(status)}`)}>
      {status.replace(/_/g, " ")}
    </span>
  );
}

export default ExpenseStatusBadge;
