import { shouldUseWorkGraph } from "config/tracopus-pilot.config";
import envconfig from "env.config";
import { isMockDataEnabled } from "mock/mock.config";

/** F26 — Work graph and enterprise search intelligence. */

export function isWorkGraphEnabled() {
  if (shouldUseWorkGraph()) {
    return true;
  }
  if (isMockDataEnabled()) {
    return true;
  }
  return envconfig.ENV_NAME === "development";
}

export function buildWorkGraphModuleAccess() {
  const pilotOn = isWorkGraphEnabled();
  return {
    active: pilotOn,
    workGraphEnabled: pilotOn,
    enterpriseSearchEnabled: pilotOn,
  };
}

export function shouldUseWorkGraphApi() {
  return envconfig.USE_WORK_GRAPH_API === true;
}

