import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isExpenseManagementEnabled } from "config/expenses.config";
import { EXPENSE_PAGE_META } from "config/expenses-nav.config";
import { expensesService } from "_services/expenses.service";
import ExpensesLuxPage, {
  ExpenseActionButton,
  ExpenseInsightPanel,
  ExpenseLuxPanel,
} from "views/expenses/components/ExpensesLuxShared";
import ExpenseRegister from "views/expenses/components/ExpenseRegister";
import ExpenseFormDrawer from "views/expenses/components/ExpenseFormDrawer";

class EmployeeExpensesPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    claims: [],
    kpiCards: [],
    insights: [],
    drawerOpen: false,
    busyId: null,
    statusFilter: "ALL",
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("My expenses");
    }
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const filters = {};
      if (this.state.statusFilter !== "ALL") {
        filters.status = this.state.statusFilter;
      }
      const result = await expensesService.getEmployeeExpensesOverview(filters);
      const overview = result.payload || {};
      this.setState({
        loading: false,
        claims: overview.claims || [],
        kpiCards: overview.kpiCards || [],
        insights: overview.insights || [],
        dataSource: result.source,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load expenses.",
      });
    }
  };

  handleSaveClaim = async (payload, submit) => {
    const saveResult = await expensesService.saveExpenseClaim({
      ...payload,
      status: submit ? "SUBMITTED" : "DRAFT",
      submit,
    });
    if (submit && saveResult.payload && saveResult.payload.id) {
      await expensesService.submitExpenseClaim(saveResult.payload.id);
    }
    await this.loadData();
  };

  handleSubmit = async (claimId) => {
    this.setState({ busyId: claimId });
    try {
      await expensesService.submitExpenseClaim(claimId);
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to submit claim." });
    } finally {
      this.setState({ busyId: null });
    }
  };

  render() {
    if (!isExpenseManagementEnabled()) {
      return <PersonaAccessDenied featureLabel="Employee expenses" />;
    }

    const { loading, loadError, dataSource, claims, kpiCards, insights, drawerOpen, busyId } = this.state;
    const meta = EXPENSE_PAGE_META.employee;

    return (
      <>
      <ExpensesLuxPage
        testId="page-payroll-expenses"
        pageMeta={meta}
        dataSource={dataSource}
        demoLabel="Demo expense claims"
        loading={loading}
        kpiCards={kpiCards}
        onRefresh={this.loadData}
        refreshLoading={loading}
        heroActions={
          <>
            <ExpenseActionButton to="/workspace/approvals" icon="fe fe-inbox" variant="ghost">
              Approvals
            </ExpenseActionButton>
            <ExpenseActionButton icon="fe fe-plus" variant="primary" onClick={() => this.setState({ drawerOpen: true })}>
              New claim
            </ExpenseActionButton>
          </>
        }
      >
        <ExpenseInsightPanel insights={insights} />
        {loadError ? (
          <ExpenseLuxPanel title="Expense load issue" meta={loadError} accent="rose">
            <ExpenseActionButton icon="fe fe-refresh-cw" variant="primary" onClick={this.loadData}>
              Retry
            </ExpenseActionButton>
          </ExpenseLuxPanel>
        ) : null}
        <ExpenseLuxPanel
          title="My expense claims"
          meta="Submit receipts, track approval status, and view reimbursement progress."
          icon="fe fe-credit-card"
          accent="green"
        >
          <ExpenseRegister rows={claims} loading={loading} mode="employee" busyId={busyId} onSubmit={this.handleSubmit} />
        </ExpenseLuxPanel>
      </ExpensesLuxPage>
      <ExpenseFormDrawer
        open={drawerOpen}
        onClose={() => this.setState({ drawerOpen: false })}
        onSave={this.handleSaveClaim}
      />
    </>
    );
  }
}

export default EmployeeExpensesPage;
